window.MF_I18N = {"zh": {"ui": {"homeTitle": "从 Mayflower\n出发探索巴黎", "homeSub": "从酒店出发的环线漫游，每到一处，都有一个故事。", "start": "开始探索", "kicker": "巴黎第八区 · 导览漫游", "step1": "第 1 步，共 3 步", "step2": "第 2 步，共 3 步", "modeQ": "你想怎么探索？", "walk": "步行", "run": "跑步", "bike": "骑行", "scoot": "滑板车", "cont": "继续", "distQ": "想走多远？", "catTitle": "选择你的路线", "mustSee": "必去路线", "moreIdeas": "更多选择", "byDist": "按距离", "allThemes": "全部", "thArt": "艺术", "thLit": "文学", "thBelle": "美好年代与演出", "thNature": "公园与森林", "thSeine": "塞纳河与河岸", "thRoyal": "国王与历史", "thModern": "现代巴黎", "distHint": "预计用时，已包含听故事的停留时间。", "seeLoop": "查看我的路线", "yourLoop": "第 3 步，共 3 步 · 你的路线", "stories": "个故事", "story1": "个故事", "lookLabel": "看哪里：", "steps": "站", "chooseLoop": "选择你的步行路线", "mapAltPre": "从酒店出发的步行环线：", "swipe": "左右滑动", "readStory": "阅读故事", "zoomIn": "放大", "zoomOut": "缩小", "fit": "查看整条路线", "parisAll": "查看整个巴黎", "lessStory": "回到简短版", "locMe": "显示我的位置", "locWait": "正在寻找你的位置…", "locFar": "你不在巴黎：蓝点模拟在酒店位置", "locDenied": "定位被拒绝：蓝点模拟在酒店位置", "locNone": "无法定位：显示模拟位置", "startWalk": "开始漫步", "backMap": "返回地图", "navNext": "下一站", "navGps": "实时定位", "navFar": "偏离路线 · 手动前进", "navManual": "未定位 · 手动前进", "navWait": "正在寻找你的位置…", "navSim": "模拟演示", "navSimFar": "偏离路线 · 演示", "navPause": "暂停", "navPlay": "继续", "navSkip": "下一站", "navEnd": "结束", "navSoon": "马上到", "navHere": "你在这里", "navGoOn": "继续走", "navReadNow": "听这个故事", "navStop": "站", "navRead": "阅读故事", "navLater": "稍后", "navDoneTitle": "回到酒店了", "navDoneText": "漫步结束。谢谢你和我们一起走这一程！", "navRemaining": "剩余", "navRecenter": "回到我的位置", "next": "下一个故事", "foStart": "出发", "byTheme": "按主题", "otherRoutes": "其他路线", "inKm": "按公里", "inTime": "按时间", "allDist": "全部", "catOne": "条路线", "catMany": "条路线", "catEmpty": "这个筛选下没有路线。", "mustTag": "必去", "withAudio": "文字 + 语音", "exLine": "伦敦、都灵、佛罗伦萨：你酒店周围的街道，都以欧洲城市命名。这里告诉你为什么。", "exKicker": "你的酒店", "exTitle": "Mayflower，莫斯科街", "exText": "你走出酒店，来到莫斯科街。看看周围的路牌：伦敦、都灵、佛罗伦萨、圣彼得堡……这些名字可不是随便取的。\n\n19 世纪 20 年代初，两个人在这里构想了一个新街区：一位是住在巴黎的瑞典银行家约纳斯·哈格曼，另一位是西尔万·米尼翁，他原本是国王的锁匠，后来成了地产商。街区中间是一座大广场，四周的街道都以欧洲城市命名。1826 年，计划获得批准，“欧洲街区”就此诞生。\n\n所以，边走边想象这张地图在你周围慢慢展开：每条街都像是一扇通往另一座城市的门。你还在巴黎，但你的街区已经带你去旅行了。\n\nMayflower 于 2015 年在一栋奥斯曼风格的建筑里开业，它就是你漫步这片“想象中的欧洲”的起点，就在巴黎第八区的中心。", "exListen": "听这段故事", "exRead": "阅读你酒店的故事", "exClose": "关闭故事", "startHint": "一站一站为你导航，到达时为你送上每个故事。“显示我的位置”只是在地图上显示你在哪里。", "askKicker": "出发之前", "askTitle": "开启定位？", "askWhy": "漫步时，你的位置用来在地图上显示你，并在你接近某一站时提醒你。之后由你决定是听故事、读故事，还是留到以后。", "askPrivacy": "你的位置只留在你的手机上，绝不会被保存或发送，漫步结束后定位就会停止。", "askYes": "开启并出发", "askNo": "不定位直接出发", "askCancel": "取消", "locBlocked": "手机阻止了定位：请用“下一站”继续前进。", "helpKicker": "定位被阻止", "helpTitle": "你的手机没有共享位置", "helpWhy": "导览无法请求权限：浏览器的定位已关闭。开启方法：", "helpIos1": "设置 › 隐私与安全性 › 定位服务：打开。", "helpIos2": "往下找到 Safari 浏览器网站（或 Chrome）› “使用 App 期间”。", "helpIos3": "回到这里，点地址栏左边的“大小”图标 › 网站设置 › 位置 › 询问。", "helpAnd1": "设置 › 位置信息：打开。", "helpAnd2": "在 Chrome 中，点地址栏左边的锁形图标 › 权限 › 位置信息 › 允许。", "helpRetry": "再试一次", "helpClose": "不定位继续", "navReadIt": "阅读", "cardAudio": "文字 + 语音 · ", "cardText": "仅文字", "listenDur": "收听 · ", "mediaBoth": "可读可听 · ", "mediaLong": "完整版 ", "mediaText": "仅可阅读 · 此设备不支持语音", "readMore": "继续阅读 · ", "listen": "收听", "vPlay": "收听", "vStop": "停止语音", "vc_butler": "管家", "vc_titi": "巴黎小子", "vc_diva": "女歌星", "vAutoOn": "自动语音：开", "vAutoOff": "自动语音：关", "vWho": "谁来讲？", "uMin": "分钟", "uH": "小时"}, "modes": {"bike": {"chooseLoop": "选择你的骑行路线", "startWalk": "开始骑行", "mapAltPre": "从酒店出发的骑行环线：", "navDoneText": "骑行结束。谢谢你和我们一起骑这一程！"}, "run": {"chooseLoop": "选择你的跑步路线", "startWalk": "开始跑步", "mapAltPre": "从酒店出发的跑步路线：", "navDoneText": "跑步结束。好样的，好好休息！"}, "scoot": {"chooseLoop": "选择你的滑板车路线", "startWalk": "开始出发", "mapAltPre": "从酒店出发的滑板车环线：", "navDoneText": "行程结束。谢谢你和我们一起出发！"}}, "intro": {"butler": "我们到了。请坐好，听我慢慢讲。", "titi": "好，停一下！听听这个，超精彩。", "diva": "啊，亲爱的……好好听这个故事。"}, "loops": {"parc-monceau": ["蒙索公园，艺术家之间的漫步", "雕像、沙特尔公爵的奇趣建筑、卡蒙多和普鲁斯特。"], "court-15": ["十五分钟，画家之桥", "欧洲桥：卡耶博特和莫奈在同一年画过它。"], "court-20": ["从克利希广场到艺术家墓地", "一位保卫巴黎的元帅，还有达丽达、德加和特吕弗。"], "court-30": ["铁教堂和画家之桥", "一座假扮成石头的铁教堂，然后是卡耶博特和莫奈的桥。"], "court-45": ["四十五分钟，从克利希到新雅典", "红磨坊、肖邦和乔治·桑的沙龙、一位画家的家，还有约瑟芬·贝克的歌舞厅。"], "court-60": ["不到一小时，从圣三一教堂到圣奥古斯丁教堂", "一架传奇管风琴、春天百货的穹顶、路易十六的小教堂和一座铁教堂。"], "etoile-secrets": ["星形广场的秘密", "巴尔扎克、一位交际花、一场音乐骚乱，还有一架从凯旋门下飞过的飞机。"], "plaine-monceau-divas": ["蒙索平原的女神们", "莎拉·伯恩哈特、三位大仲马，还有一座为舞会而建的城堡。"], "passy-balzac-eiffel": ["从巴尔扎克到埃菲尔铁塔", "一座创造历史的宫殿、一位逃债的作家，还有电影最爱的桥。"], "foch-bois-boulogne": ["福煦大道和布洛涅森林", "巴黎最宽的大道、德彪西最后的家，还有湖中小岛上的瑞士木屋。"], "montmartre-boheme": ["波西米亚的蒙马特", "红磨坊、毕加索、一头会“画画”的驴，还有 311 句“我爱你”。"], "rive-droite-royale": ["皇家右岸", "亚历山大三世桥、巴黎商品交易所、旺多姆圆柱和玛德莲教堂。"], "course-monceau": ["绕蒙索公园跑圈", "两圈跑过镀金铁门、一座金字塔和一尊巨大的雕像。"], "course-cours-la-reine": ["从香榭丽舍到王后林荫道", "一条皇家散步道、丘吉尔、少年普鲁斯特和环法终点。"], "course-champ-de-mars": ["特罗卡德罗和战神广场", "水炮、一座及时被救下的桥，还有 1790 年的盛大节日。"], "course-muette": ["拉米埃特和拉内拉格", "维克多·雨果大道、人类第一次飞行和印象派。"], "course-grande-jatte": ["修拉的大碗岛", "沿着塞纳河，修拉在这里画下他的星期天，埃菲尔在这里造过他的塔。"], "course-berges-tuileries": ["塞纳河岸和杜乐丽花园", "一条变成公园的快速路、巴士底狱的石头和《睡莲》。"], "course-longchamp": ["隆尚和巴加泰勒", "一道假山瀑布、一座消失的修道院，还有一座因打赌而建的城堡。"], "course-allee-des-cygnes": ["天鹅岛和雪铁龙公园", "一座细长的小岛、小自由女神像、阿波利奈尔和圆形的电台大楼。"], "course-auteuil": ["布洛涅森林，从欧特伊到罗兰·加洛斯", "莎士比亚花园、欧特伊的障碍赛、温室和红土球场。"], "course-ile-saint-louis": ["沿河岸跑到圣路易岛", "挂锁桥、最古老的桥、一座“造出来”的岛和旧书摊。"], "course-saint-ouen": ["圣旺码头和巴蒂尼奥勒", "勒瓦卢瓦的塞纳河、跳蚤市场、一座钢铁人民大厅和魏尔伦。"], "course-quartier-latin": ["圣日耳曼、卢森堡和拉丁区", "一家文学咖啡馆、圣叙尔皮斯的子午线、小自由女神像和一座罗马竞技场。"], "course-villette": ["拉维莱特和乌尔克运河", "拿破仑的大水池、钢铁球体、老屠宰场和太阳王的城门。"], "course-saint-cloud": ["圣克卢公园", "“断头者之丘”、王弟的瀑布、一座消失的城堡，还有脚下的巴黎。"], "course-bercy": ["贝西和东边的河岸", "皇家护城河里的港口、一座脚踩在水里的部委、葡萄酒和书。"], "course-montsouris": ["蒙苏里和巴黎南部", "萨特和波伏娃、子午线标记、一座“世界之城”和布拉桑的公园。"], "course-vincennes": ["沿绿荫步道跑到樊尚", "一座变成花园的高架桥、一座冒气泡的泉水、1931 年的宫殿和将军湖。"], "course-iles-ouest": ["西边的岛屿", "星球档案馆、雷诺岛、一面太阳能帆和杜布菲的塔。"], "velo-rive-gauche": ["左岸，从新艺术到帝国", "一面活的墙、一扇大胆的门、拿破仑和百货公司里的宝塔。"], "velo-nouvelle-athenes": ["画家们的新雅典", "卡耶博特、在谢弗尔家的肖邦、“洛雷特”姑娘们和屋顶上的飞机。"], "velo-halles-beaubourg": ["从大堂区到博堡", "占星师的圆柱、莫里哀的洗礼和廷格利的机器。"], "velo-canal-buttes": ["圣马丁运河和肖蒙山丘", "一位元帅、一座埃及神庙、阿尔莱蒂，还有歌剧院下的秘密湖。"], "velo-montparnasse": ["艺术家的蒙帕纳斯", "夏加尔的“蜂巢”、巴斯德的墓室，还有被拒绝的罗丹《巴尔扎克》。"], "velo-la-defense": ["骑到新凯旋门", "为一位王子建的小教堂、一座印度宫殿，还有给拉德芳斯命名的雕像。"], "velo-annees-30": ["从咆哮的二十年代到三十年代", "吉马尔、勒·柯布西耶的家、莫利托泳池的比基尼和王子公园的环法终点。"], "velo-grande-seine": ["塞纳河大环线", "从维克多·雨果到国王的长颈鹿，从贝西到奥赛，沿着河岸骑行。"], "velo-saint-denis": ["圣但尼，从国王到奥运会", "2024 年的比赛场馆、国王们的大教堂和圣但尼运河。"], "velo-vincennes": ["巴士底和樊尚城堡", "伽弗洛什的大象、圣安托万区的家具匠人和国王们的城堡主塔。"], "scooter-faubourg": ["宫殿林立的圣奥诺雷区", "毕加索的婚礼、一座总统府和一座铁教堂。"], "scooter-chaillot": ["夏约，博物馆之丘", "根付、亚洲艺术、一座混凝土宫殿和一间高级定制工作室。"], "scooter-rive-gauche": ["出版人的左岸", "蝴蝶、一家百货公司、一家豪华酒店、一位出版人和法兰西学院院士。"], "scooter-music-halls": ["第九区的歌舞厅", "一座玻璃穹顶、梅西安的管风琴、歌舞秀、蜡像和平价老饭馆。"], "scooter-ouest": ["讷伊和叙雷讷，花园与记忆", "一座皇家公园、一位金融家的奇想，以及一座面向巴黎的美军公墓。"], "scooter-belleville": ["美丽城和梅尼蒙当", "亨利四世的医院、皮雅芙的传奇、拉雪兹神父公墓和一座帝国马戏团。"], "scooter-quartier-latin": ["从拉丁区到戈布兰", "罗马浴场、因王室誓言而建的穹顶、一座清真寺、夏科的医院和挂毯。"], "scooter-asnieres": ["过河去阿涅尔和科隆布", "路易丝·米歇尔、任丁丁、路易威登的箱子和 1924 年奥运会体育场。"], "scooter-sud": ["向南，直到引水渠", "圆顶餐厅、贝尔福之狮、一座温水泳池、比塞特尔和玛丽·德·美第奇的引水渠。"]}, "stops": {"La Rotonde de Chartres": ["沙特尔圆亭", "建筑 · 勒杜，1787 年", "这座带柱子的小圆亭看起来像花园装饰，其实它是一座海关。", "看看公园入口处那座被柱子环绕的圆形建筑。", "你正站在蒙索公园的入口，面前是一座带柱子的圆形小建筑。\n\n它看起来像花园里的装饰，其实是一座收税站。1787 年，巴黎在城市周围修了一道墙，凡是进城的东西都要交税：葡萄酒、肉、木头。建筑师克洛德－尼古拉·勒杜设计了这些收税亭。在这里，税务官在楼下工作；楼上则是一间沙龙，属于这座公园的主人沙特尔公爵。\n\n看看楼上：公爵就是在那里欣赏他的花园的。"], "Le pont de l'Europe": ["欧洲桥", "绘画 · 卡耶博特和莫奈，1877 年", "两位印象派画家在同一年画了这座桥。", "看看桥的铁梁，还有桥下圣拉扎尔车站的铁轨。", "你正站在一座桥上，桥下就是圣拉扎尔火车站的列车。1837 年，第一列客运火车从这里出发，那时火车还是件轰动的新鲜事：它们烧蒸汽，一路轰鸣、冒着浓烟。\n\n几十年后，巴黎画家古斯塔夫·卡耶博特选了这座桥来画。他画下了眼前的一切：巨大的铁梁、来往的行人，还有现代的巴黎。这幅画就叫《欧洲桥》。1877 年，他的朋友克洛德·莫奈也画了这座车站，画里有火车和蒸汽。莫奈，就是画《睡莲》的那位画家。\n\n看看你周围的铁梁：卡耶博特在 150 年前就画过它们。"], "Le maréchal Moncey": ["蒙塞元帅", "纪念碑 · 阿梅代·杜布勒马尔", "一位将近六十岁的元帅，守住了巴黎的这道城门。", "抬头看看克利希广场中央那尊巨大的雕像。", "你正站在克利希广场上。200 年前，巴黎被一道城墙围着，这里就是其中一道城门。\n\n1814 年，拿破仑皇帝在与几乎整个欧洲的战争中节节败退，俄国军队打到了巴黎。守卫这道城门的，是一位老将军——蒙塞元帅，他身边大多是巴黎的志愿者。3 月 30 日，他们坚守了一整天。当晚巴黎还是投降了，但他们的抵抗从未被人遗忘。\n\n看看广场中央那尊大雕像：那就是蒙塞，他保护着的那位女子，代表的是巴黎。"], "Le cimetière de Montmartre": ["蒙马特公墓", "艺术家安息地 · 始于 1825 年", "达丽达、德加和特吕弗长眠在一座旧采石场里，头顶上还有一座桥。", "看看从墓地上方横跨而过的科兰古街桥。", "你来到了蒙马特公墓。从 1825 年起，它就躺在一座旧采石场的底部，地势低到科兰古街要架一座桥，从坟墓上方穿过。\n\n很多艺术家安葬在这里：以画芭蕾舞女闻名的画家埃德加·德加；写《红与黑》的作家司汤达；电影导演弗朗索瓦·特吕弗；还有法国香颂最大的明星之一、歌手达丽达，她的墓前总是摆着新鲜的花。\n\n看看墓地上方的桥：汽车就从坟墓上面开过去。"], "Saint-Augustin, l'église en fer": ["圣奥古斯丁，铁做的教堂", "教堂 · 维克多·巴尔塔，1860–1871 年", "一座伪装成石头的铁教堂。", "看看林荫大道尽头圣奥古斯丁教堂的大穹顶。", "你面前是圣奥古斯丁教堂。它看起来是石头造的，其实里面是铁。\n\n它建于 1860 年到 1871 年，建筑师是维克多·巴尔塔。在此之前，他已经建造了巴黎旧食品市场“大堂”的那些巨大铁亭。在那个年代，铁是最现代的材料。巴尔塔用纤细的金属柱子撑起了穹顶。它是巴黎最早用这种方式建造的大教堂之一。\n\n看看那座大穹顶：它是立在铁架子上的。"], "Le Moulin Rouge": ["红磨坊", "歌舞厅 · 1889 年 10 月 6 日", "它的花园里曾经有一头巨大的大象。", "看看克利希大道上那架红色的风车。", "你面前是红磨坊，世界上最有名的歌舞厅，顶上有一架红色叶片的风车。\n\n它在 1889 年 10 月 6 日开业，和埃菲尔铁塔同一年。它的花园里甚至有一头巨大的大象。法国康康舞就是在这里出名的：舞者把腿踢得高高的，让衬裙翻飞起来。画家亨利·德·图卢兹－罗特列克是这里的常客，他为歌舞厅设计海报，也画这里的舞者。\n\n看看风车的叶片：它们至今还在转。"], "Le salon d'Ary Scheffer": ["阿里·谢弗的沙龙", "浪漫生活博物馆 · 19 世纪 30 年代", "每到星期五，肖邦、乔治·桑和德拉克洛瓦都会来这里做客。", "走到石板小巷的尽头，去看看那座带花园的小房子。", "在这条铺着石块的小巷尽头，藏着一座带花园的房子：今天它是浪漫生活博物馆。\n\n19 世纪 30 年代，它属于画家阿里·谢弗。每个星期五晚上，他都会招待艺术家朋友：钢琴家弗雷德里克·肖邦，以及他的伴侣、住在附近的作家乔治·桑；画家欧仁·德拉克洛瓦；作曲家弗朗茨·李斯特。屋里有钢琴声，大家谈绘画，也谈激情。\n\n看看小巷尽头的房子：肖邦就是来这里弹琴的。"], "La maison de Gustave Moreau": ["古斯塔夫·莫罗的家", "艺术家博物馆 · 1895 年", "一位画家在生前就把自己的家变成了博物馆。", "看看拉罗什富科街上古斯塔夫·莫罗故居的正面。", "你正经过画家古斯塔夫·莫罗的家，现在它是一座博物馆。\n\n19 世纪末，莫罗画的是神话、梦境和奇幻的生物。1895 年，他做了一个不寻常的决定：在自己还活着的时候，就把家变成博物馆。他建了两间大画室，把画从地板一直挂到天花板。他去世时，把这一切都留给了国家：一千多幅油画，还有成千上万张素描。\n\n看看房子顶上的大窗户：那就是他的画室。"], "Le Casino de Paris": ["巴黎赌场歌舞厅", "歌舞厅 · 克利希街", "米斯坦盖特、莫里斯·谢瓦利埃，后来是约瑟芬·贝克和《我有两个爱》。", "看看克利希街上巴黎赌场歌舞厅的正面。", "你正经过克利希街上的“巴黎赌场”。别被名字骗了，这里没有赌博：它是一座歌舞厅，一个有歌曲、舞者和羽毛的剧场。\n\n第一次世界大战之后，当时最大的明星都在这里大获成功，比如米斯坦盖特和莫里斯·谢瓦利埃。1931 年，一位成了巴黎偶像的美国舞者约瑟芬·贝克，在这里第一次唱起《我有两个爱》：“我有两个爱，我的祖国和巴黎。”这首歌后来成了她的代表作。\n\n看看它的正面：那首歌就诞生在这里。"], "La Trinité de Messiaen": ["梅西安的圣三一教堂", "教堂 · 泰奥多尔·巴吕，1861–1867 年", "一位伟大的作曲家在这里弹了六十一年管风琴。", "看看昂坦堤道街尽头的圣三一教堂。", "你面前是圣三一教堂，建于 1861 年到 1867 年。\n\n它的明星是一位音乐家：奥利维耶·梅西安，20 世纪最伟大的作曲家之一，他特别喜欢鸟鸣。从 1931 年直到 1992 年去世，他一直在这座教堂弹管风琴。整整六十一年！每个星期天他都即兴演奏，世界各地的音乐家专程赶来听他弹琴。\n\n看看这座教堂：在它的正面后面，就是梅西安的管风琴。"], "Le Printemps": ["春天百货", "百货公司 · 1865 年", "在屋顶下，藏着一座 1923 年的彩色玻璃穹顶。", "看看奥斯曼大道上春天百货的正面和它的圆顶。", "你面前是春天百货，奥斯曼大道上两家著名百货公司之一，另一家是老佛爷百货。\n\n它在 1865 年开业，很快就成了时尚的殿堂。它的宝贝藏在屋顶下：一座巨大的彩色玻璃穹顶，1923 年装上。第二次世界大战期间，为了躲避轰炸，人们把它拆了下来。1972 年，由当年制作者的孙子把它重新装了回去。\n\n看看屋顶上的圆顶：那座玻璃穹顶就在它们下面。"], "La chapelle expiatoire": ["赎罪小教堂", "小教堂 · 皮埃尔·方丹，1816–1826 年", "路易十六和玛丽·安托瓦内特最早就葬在这里。", "看看路易十六广场深处的小教堂。", "你面前是一座藏在花园里的小教堂。它讲述的是法国历史上黑暗的一章。\n\n1789 年爆发了法国大革命：人民起来反抗国王。1793 年，国王路易十六和他的妻子玛丽·安托瓦内特王后在协和广场被送上断头台。他们的遗体被扔进一座小墓地，就在这里。二十年后，一位国王重新掌权：路易十八，路易十六的弟弟。他让人挖出他们的遗骸，然后建了这座小教堂来“赎罪”，也就是为他们的死请求宽恕。\n\n看看花园尽头的小教堂：国王和王后最早就葬在这里。"], "La dernière maison de Balzac": ["巴尔扎克最后的家", "作家 · 巴尔扎克街和贝里耶街", "巴尔扎克在这里度过了最后的岁月，后来一位男爵夫人拆了他的房子……为了纪念他。", "看看贝里耶街 11 号的宅邸和花园里的圆亭。", "你正站在巴尔扎克街上。这里曾是奥诺雷·德·巴尔扎克最后的家，他是 19 世纪法国最伟大的小说家之一。\n\n整整十六年，巴尔扎克爱着一位波兰伯爵夫人——埃韦利娜·韩斯卡。他们相隔遥远，几乎只能靠书信往来。1846 年，他在这里买下一栋房子，为她布置好。1850 年，他们终于结婚，搬了进来。五个月后，巴尔扎克就在这栋房子里去世了。\n\n看看贝里耶街的街角：巴尔扎克的房子就曾立在那里。"], "L'hôtel de la Païva": ["帕伊瓦公馆", "交际花 · 香榭丽舍大道 25 号", "她在这条大道上被赶下马车，发誓要回来……还要住在这里。", "看看香榭丽舍大道 25 号的那座宅邸。", "你正经过香榭丽舍大道 25 号的一座漂亮房子：帕伊瓦公馆。\n\n19 世纪，一个叫埃丝特·拉赫曼的年轻女子出生在莫斯科一个贫穷的家庭，来到巴黎时一无所有。她成了一名交际花，也就是靠富有情人生活的女人。后来她成了她们当中最富有的一位，人称“帕伊瓦”。据说有一天，一个男人在这条大道上让她下了马车。她发誓要回来，住在这里。经过十年的建造，这就是她的家。\n\n看看它的正面：里面有一座用珍贵黄色石材做成的楼梯。"], "La Flamme de la Liberté": ["自由之火", "纪念碑 · 戴安娜广场", "大家都以为它是为戴安娜王妃做的，其实它早来了八年。", "看看广场中央、隧道上方那团金色的火焰。", "你正站在阿尔玛广场。这团巨大的金色火焰，和纽约自由女神像手中的火炬一模一样。\n\n1989 年，一家美国报纸把它送给巴黎，感谢修复自由女神像的法国工匠。八年后，1997 年，英国查尔斯王子的前妻戴安娜王妃在正下方的隧道里遭遇车祸去世。人们来到这里献花。没有任何人决定，这团火焰就成了她的纪念碑。\n\n看看火焰的底座：那里常常还有献给戴安娜的花和留言。"], "Un avion sous l'Arc": ["凯旋门下的飞机", "纪念碑 · 凯旋门", "1919 年 8 月 7 日，一位飞行员驾驶飞机从这座拱门下穿了过去。", "抬头看看凯旋门的大拱顶，再低头看看地上的火焰。", "你正站在凯旋门前。\n\n1919 年，第一次世界大战刚刚结束。巴黎正在准备在凯旋门下举行盛大的胜利游行。可是那些在天上冒着生命危险打了四年仗的飞行员，却只能步行参加。年轻的飞行员夏尔·戈德弗鲁瓦觉得这不公平。1919 年 8 月 7 日，他驾驶小飞机从拱门中间穿了过去，拱门的宽度还不到他翼展的两倍。他最后只挨了一句警告。\n\n看看凯旋门的拱洞：想象一架飞机从正中间飞过。"], "Le Céramic Hôtel": ["陶瓷酒店", "新艺术风格 · 瓦格拉姆大道 34 号", "在瓦格拉姆大道上，有一整面墙像植物一样“长”了出来。", "抬头看看瓦格拉姆大道 34 号那面棕绿相间的陶瓷外墙。", "你正站在瓦格拉姆大道上，面前的外墙上覆盖着陶瓷做的叶子和花朵。\n\n1904 年，正流行“新艺术”风格，这种风格模仿植物的曲线。建筑师朱尔·拉维罗特建了这栋楼，一位陶瓷艺术家给它覆盖上泥土色和苔藓色的花纹。第二年，它在巴黎最美外墙比赛中获胜。\n\n看看它的入口：这栋楼好像是像植物一样长出来的。"], "Chez Sarah Bernhardt": ["莎拉·伯恩哈特的家", "明星 · 佩雷尔大道", "世界上第一位超级巨星，有时睡在棺材里，还和大型猫科动物住在一起。", "看看佩雷尔大道沿街的楼房，她在这里度过了最后的岁月。", "你正站在佩雷尔大道上，面前是莎拉·伯恩哈特度过晚年的房子。\n\n莎拉·伯恩哈特是 19 世纪末的舞台剧演员。那时连电影都还没有，她就已经红遍全世界，从巴黎到纽约。她喜欢让人震惊：她家里养着野生动物，卧室里放着一具骷髅，还让人拍她躺在棺材里的照片。\n\n看看这些窗户：窗后住过那个时代最大的明星。"], "Les lecteurs de Dumas": ["大仲马的读者", "纪念碑 · 古斯塔夫·多雷，1883 年", "在亚历山大·仲马脚下，三个巴黎人从 1883 年起就在读他的一本小说。", "绕着坐着的仲马雕像走一圈：达达尼昂在底座的背面。", "你正站在卡特鲁将军广场上，面前是一个坐着的人：亚历山大·仲马，也就是大仲马。\n\n大仲马在 19 世纪写了《三个火枪手》和《基督山伯爵》。人人都读他的冒险小说。这尊雕像表现的正是这一点：在他脚下，一位女子、一位工人和一个学生正在读他的书。在他身后，他笔下的火枪手达达尼昂在站岗。\n\n看看底座后面：达达尼昂手握长剑。"], "Le château du banquier": ["银行家的城堡", "新文艺复兴风格 · 加亚尔公馆", "一位银行家给自己造了一座卢瓦尔河城堡的复制品，开幕时请了 2000 位客人。", "看看卡特鲁将军广场上那座砖石结构、尖屋顶的城堡。", "你面前是一座真正的城堡，就在巴黎市中心。\n\n埃米尔·加亚尔是一位非常富有的银行家，他热爱文艺复兴，也就是 16 世纪国王们的时代。他让人仿造了布卢瓦城堡，那是卢瓦尔河谷一座著名的城堡。1885 年开幕时，他举办了一场化装舞会，请了 2000 多位客人，他自己则扮成了国王亨利二世。\n\n看看那些小塔楼和尖屋顶：一座卢瓦尔河城堡，就在蒙索公园旁边。"], "Le Majestic": ["美琪酒店", "豪华酒店 · 克莱贝尔大道 19 号", "在这家酒店里，普鲁斯特和乔伊斯共进过晚餐，越南战争也在这里画上了句号。", "看看克莱贝尔大道 19 号半岛酒店宏伟的正面。", "你正经过克莱贝尔大道上一座宏伟的豪华酒店。今天它是半岛酒店，以前叫“美琪”。\n\n1922 年，这里举办过一场晚宴，席间坐着四位艺术巨人：作家马塞尔·普鲁斯特、爱尔兰作家詹姆斯·乔伊斯、作曲家伊戈尔·斯特拉文斯基和画家巴勃罗·毕加索。第二次世界大战期间，这里是德军的司令部。1973 年，让美国人退出越南战争的和平协定也是在这里签署的。\n\n看看这宏伟的外墙：这栋楼见证了一个世纪的历史。"], "Le parvis des droits de l'homme": ["人权广场", "观景台 · 特罗卡德罗", "在这片平台上，拍下过 20 世纪最糟糕和最美好的照片。", "走到平台中央，面朝埃菲尔铁塔，站在宫殿的两翼之间。", "你正站在特罗卡德罗宽阔的平台上，夏约宫的两翼之间。塞纳河对岸就是埃菲尔铁塔。\n\n1940 年 6 月 23 日，法国刚刚输掉了对德国的战争。希特勒只来过巴黎一次，那天一大早，他就在这里拍了照，身后是埃菲尔铁塔。八年后，1948 年，战争已经结束。联合国就在这座宫殿里开会，通过了《世界人权宣言》：这份文件说，人人生而自由，在尊严和权利上一律平等。\n\n看看你脚下的平台：正是因为这份文件，它被命名为“人权广场”。"], "Le cimetière de Passy": ["帕西公墓", "艺术家安息地 · 始于 1820 年", "马奈、贝尔特·莫里索和德彪西长眠在这里，就在埃菲尔铁塔的影子下。", "找找台阶顶上小小的帕西公墓入口。", "你正经过帕西公墓，一座位于山丘上的小墓地，也是巴黎最高雅的墓地之一。\n\n两位 19 世纪的伟大画家安葬在这里：爱德华·马奈，以及就在他旁边的贝尔特·莫里索。她是马奈的弟媳，也是印象派中为数不多的女画家之一。写过《月光》的作曲家克洛德·德彪西也葬在这里。他生前希望葬在此处，去世一年后被迁葬过来。\n\n看看公墓的入口，就在特罗卡德罗旁边。"], "Le pont de Bir-Hakeim": ["比尔－哈基姆桥", "桥 · 1905 年，电影明星", "马龙·白兰度在《巴黎最后的探戈》里在这里徘徊，迪卡普里奥在《盗梦空间》里看它折叠起来。", "走到桥下的铁柱廊里，面朝埃菲尔铁塔。", "你正站在一座双层桥上：上层跑地铁，下层走行人和汽车。\n\n它的名字来自比尔哈基姆，利比亚沙漠里的一个地方。1942 年，第二次世界大战期间，忠于戴高乐将军的法国士兵在那里抵挡德军，坚守了好多天。这座桥本身建于 1905 年。凭借它的铁柱和埃菲尔铁塔的景色，它成了电影取景地：你能在《巴黎最后的探戈》和莱昂纳多·迪卡普里奥主演的《盗梦空间》里看到它。\n\n看看地铁下面的铁柱：那正是导演们最爱的镜头。"], "L'avenue de l'Impératrice": ["皇后大道", "大道 · 1854 年", "宽 120 米：拿破仑三世想要一条配得上皇后的大道。", "感受一下这条大道的宽度，两边还有宽阔的草坪。", "你正站在福煦大道上。连同草坪在内，它宽 120 米，是巴黎最宽的大道。\n\n1854 年，拿破仑三世皇帝开辟了这条大道，通往布洛涅森林。最初，他用妻子欧仁妮皇后的名字为它命名。这里是世界上最昂贵的地址之一：希腊船王奥纳西斯和歌手普林斯都在这里住过。\n\n看看那些气派的外墙：里面是巴黎最豪华的一些公寓。"], "La dernière maison de Debussy": ["德彪西最后的家", "音乐 · 福煦大道广场 24 号", "德彪西在这里去世时，德国的大炮正在轰击巴黎。", "朝福煦大道广场 24 号那片私人小广场里望一望。", "你正经过福煦大道旁一个安静的小广场。\n\n写《月光》的法国作曲家克洛德·德彪西，从 1905 年起就住在这里。他在这里写下了一些全世界演奏最多的钢琴曲。1918 年 3 月，第一次世界大战期间，他在这里去世，当时德国的大炮正在轰击巴黎。因为战争，只有很少的人为他送葬。\n\n看看这个小广场：德彪西就住在这里。"], "Le lac et le chalet des Îles": ["湖和小岛木屋", "布洛涅森林 · 第二帝国", "这片湖源于一次计算错误，而这座木屋来自瑞士。", "看看湖中的小岛，还有只能坐船去的那座木屋。", "你正沿着布洛涅森林里的一片大湖奔跑。\n\n拿破仑三世皇帝曾流亡伦敦，他很喜欢海德公园和园里的那条河。他也想在这里有一个一样的。可是第一位园林设计师算错了：水流不起来。于是人们把它改成了两个湖，湖里有两座小岛。皇帝在其中一座岛上，搭起了一座真正的瑞士木屋。\n\n看看那座小岛：木屋还在，至今仍要划船才能到达。"], "Le vaisseau de Gehry": ["盖里的船", "建筑 · 路易威登基金会，2014 年", "一朵玻璃云降落在布洛涅森林的边上。", "看看路易威登基金会那些巨大的玻璃帆。", "你来到了一座看起来像巨大玻璃帆船的建筑前：路易威登基金会，一座 2014 年开放的现代艺术博物馆。\n\n它的建筑师是美国人弗兰克·盖里，世界上最有名的建筑师之一。他之前已经建造了西班牙毕尔巴鄂的古根海姆博物馆。在这里，他用十二面弯曲的大玻璃帆把建筑包了起来。\n\n看看这些玻璃帆：就像一艘准备启航的船。"], "Le moulin de la Galette": ["煎饼磨坊", "舞厅 · 雷诺阿，1876 年", "每到星期天，人们就在树下跳舞。雷诺阿把这一幕画成了杰作。", "抬头看看勒皮克街转角那架木头风车。", "你正经过蒙马特中心的一座风车。\n\n蒙马特以前是个到处都是风车的村子。磨坊主们想了个主意：卖给散步的人一块饼干和一杯葡萄酒，后来又开了一家舞厅。1876 年，画家奥古斯特·雷诺阿在这里画下了朋友们在树下跳舞的情景。这幅《煎饼磨坊的舞会》，如今是世界上最有名的画作之一。\n\n看看街道上方的风车：就是画里的那一架。"], "Le Sacré-Cœur": ["圣心大教堂", "大教堂 · 1875–1919 年", "雨下得越多，它就越白。", "抬头看看白色的穹顶，再看看后面那座方形钟楼。", "你来到了圣心大教堂，这座白色的大教堂在巴黎到处都能看到。\n\n它从 1875 年开始建造，花了四十多年，直到 1919 年才完工。它的秘密在于石头：一下雨，它就变得更白。它的钟楼里挂着一口巨大的钟，叫“萨瓦人”，重将近 20 吨。\n\n看看你身后：整个巴黎都在你脚下。"], "Le Bateau-Lavoir": ["洗衣船", "画室 · 埃米尔－古多广场", "在这座没有暖气的破木屋里，毕加索发明了现代艺术。", "看看埃米尔－古多广场上洗衣船那面带玻璃的正面。", "你正站在蒙马特的一个小广场上。这里曾有一栋没有暖气的旧木头画室楼，人们叫它“洗衣船”。\n\n1904 年，一位身无分文的 23 岁西班牙年轻画家搬了进来：巴勃罗·毕加索。1907 年，他在这里画了《亚维农的少女》，这幅画改变了艺术史。他和朋友乔治·布拉克一起发明了立体主义：一种把形状拆成几何碎片来画的画法。\n\n看看广场上那个小小的正面：现代艺术就从这里开始。"], "Le pont Alexandre-III": ["亚历山大三世桥", "桥 · 1896–1900 年", "沙皇奠下了第一块石头，为了不挡住荣军院，这座桥被压得很平。", "看看桥墩顶上的金色雕像，再看看尽头荣军院的穹顶。", "你正站在亚历山大三世桥上，巴黎最金光闪闪的桥。\n\n19 世纪末，法国和俄国结成了盟友。为了庆祝，这座桥以俄国皇帝、沙皇亚历山大三世命名。1896 年，他的儿子沙皇尼古拉二世奠下了第一块石头。船要能从桥下通过，又不能挡住荣军院穹顶的景色。所以工程师们只建了一道非常扁平的钢拱。\n\n朝荣军院方向看：这座桥就是为了不挡住那座金色穹顶而设计的。"], "La Bourse de Commerce": ["巴黎商品交易所", "博物馆 · 1767 年和 2021 年", "先是一位王后，然后是粮食，最后是艺术：这座圆形建筑有过三段人生。", "看看贴着建筑的那根圆柱，再抬头看看穹顶。", "你面前是巴黎商品交易所，就在大堂区旁边的那座大圆楼。两百多年来，人们在这里买卖粮食，后来又交易来自世界各地的商品。\n\n从 2021 年起，它成了一座当代艺术博物馆。这里展出的是弗朗索瓦·皮诺的收藏。他是一位靠奢侈品发家的法国商人，五十年来一直在买在世艺术家的作品。为了建这座博物馆，日本建筑师安藤忠雄在里面放进了一个巨大的混凝土圆筒，却没有破坏老建筑。\n\n看看贴着建筑的那根圆柱：它是一位王后宫殿留下的唯一遗迹，已经有 450 多年了。"], "La colonne Vendôme": ["旺多姆圆柱", "纪念碑 · 1871 年被推倒", "一位画家被判出钱重建这根圆柱。", "抬头看看青铜圆柱和柱顶的拿破仑雕像。", "你正站在旺多姆广场上，这里是顶级珠宝商的大本营。广场中央，是一根高高的青铜圆柱。\n\n它是为了庆祝拿破仑的胜利而建的，用的是从敌人那里缴获的大炮的金属。1871 年，巴黎人起来反抗政府：这就是巴黎公社。他们把这根圆柱当作皇帝的象征推倒了。画家古斯塔夫·库尔贝曾提议拆掉它。起义失败后，他被判出钱重建圆柱。他逃到了瑞士，到死也没付这笔钱。\n\n抬头看：圆柱被重新立了起来，顶上还是拿破仑。"], "La Madeleine": ["玛德莲教堂", "教堂 · 告别肖邦", "肖邦的葬礼上，女歌手们只能躲在帘子后面唱。", "看看玛德莲教堂那些巨大的柱子：它看起来就像一座希腊神庙。", "你面前是玛德莲教堂。它看起来像一座希腊神庙，其实是一座教堂。\n\n拿破仑原本想把它建成一座颂扬他军队荣耀的神庙。他之后，它成了教堂。1849 年，钢琴家弗雷德里克·肖邦在巴黎去世。将近 3000 人来这里参加他的葬礼。按照他的遗愿，演奏了莫扎特的《安魂曲》。可那时女人不准在教堂里唱歌：女歌手们只能躲在一道黑色帘子后面唱。\n\n看看这些巨大的柱子：这就是拿破仑心中的那座神庙。"], "Les grilles dorées": ["镀金铁门", "铁艺 · 加布里埃尔·达维乌，1861 年", "这些黑金相间的大门，是拿破仑三世时代的优雅巴黎在向你说“欢迎”。", "看看公园入口那几扇黑金相间的大铁门。", "你来到了蒙索公园那几扇黑金相间的大铁门前。\n\n1860 年左右，拿破仑三世皇帝和他的省长奥斯曼男爵改造了整个巴黎：宽阔的林荫大道、石头建筑、公园。巴黎市从一个王族家庭手里买下了这片庄园。一半卖给了银行家，他们在这里盖起了豪华宅邸；另一半变成了这座公共公园，于 1861 年开放。\n\n看看这些镀金的大门：它们把你迎进拿破仑三世时代优雅的巴黎。"], "La pyramide": ["金字塔", "奇趣建筑 · 卡蒙泰勒，18 世纪 70 年代", "巴黎市中心有一座埃及金字塔，而且已经 250 岁了。", "在北边的绿树丛中，找找那座半掩着的石头小金字塔。", "你正在蒙索公园里。250 年前，这里是一位王子的私家花园，他就是国王的堂兄沙特尔公爵。\n\n18 世纪 70 年代，艺术家卡蒙泰勒为他设计了一座充满惊喜的花园：一座荷兰风车、一顶帐篷、一座废墟神庙……还有一座小小的埃及金字塔。后来，几乎所有东西都消失了，唯独金字塔留了下来。\n\n在树丛中找找看：那座小金字塔还在。"], "La géante de la rue de Chazelles": ["沙泽勒街的巨人", "加热－戈捷工坊 · 1881–1884 年", "自由女神像最早曾高高耸立在这条小街的屋顶之上。", "看看沙泽勒街 25 号，想象屋顶上方站着一位女巨人。", "你正站在沙泽勒街上，一条安静的小街。可是纽约的象征——自由女神像，就诞生在这里。\n\n她是法国送给美国的礼物。法国雕塑家奥古斯特·巴托尔迪在 25 号的一间工坊里建造了她。她的内部是一副铁骨架，设计者正是建造埃菲尔铁塔的工程师古斯塔夫·埃菲尔。直到 1884 年，这尊雕像都高出周围的屋顶：邻居们从窗户里就能看到她的头。后来她被拆开，装进 200 多个木箱，运往纽约。\n\n看看屋顶上方：想象一颗 5 米高的头从那里冒出来。"], "Le Cours la Reine": ["王后林荫道", "散步道 · 玛丽·德·美第奇，1616 年", "早在有人慢跑之前，人们就来这里坐着马车炫耀了。", "看看塞纳河边那条笔直的长林荫道。", "你正沿着塞纳河边一条宽阔的林荫道跑步。它已经有 400 多年历史了。\n\n1616 年，玛丽·德·美第奇王后——一位嫁到法国当王后的意大利公主，让人在这里种了一条林荫道。她想要一个可以坐马车兜风的地方，就像她的家乡佛罗伦萨那样。这里很快成了宫廷的时髦去处：人们来这里看人，也来让人看。\n\n看看这条笔直的长线：树换过了，但布局还是王后当年的。"], "Churchill en marche": ["前进中的丘吉尔", "青铜像 · 让·卡尔多，1998 年", "这头“老狮子”正大步向前，跟你一样。", "看看那尊手拄拐杖、正在迈步的丘吉尔青铜像。", "你正经过一尊大步向前的男子雕像。他是温斯顿·丘吉尔。\n\n第二次世界大战期间，他是英国首相。1940 年，几乎整个欧洲都落入了希特勒手中，但他拒绝投降。人们叫他“老狮子”。雕塑家让·卡尔多把他塑造成身穿军装、手拄拐杖、走向香榭丽舍大道的样子。\n\n看看底座：上面刻着他 1940 年说的话：“我们绝不投降。”"], "Les jardins de Gilberte": ["吉尔贝特的花园", "马塞尔·普鲁斯特小径 · 香榭丽舍花园", "在这些小路上，一个小男孩遇见了他伟大小说的女主人公。", "沿着草坪找找“马塞尔·普鲁斯特小径”的路牌。", "你正在香榭丽舍花园里。\n\n19 世纪末，一个小男孩常来这里玩：马塞尔·普鲁斯特。他后来成了伟大的作家，写了《追忆似水年华》。在这些花园里，他遇见了一个小女孩玛丽·德·贝纳达基，并爱上了她。多年以后，她成了他小说里男主人公初恋吉尔贝特的原型。\n\n看看草坪边小路的名字：它就叫“马塞尔·普鲁斯特小径”。"], "La ligne d’arrivée du Tour": ["环法自行车赛的终点线", "大道 · 自 1975 年起的终点", "环法车手们要骑三个星期才能到达的这条大道，你正在往上跑。", "看看正前方大道顶端的凯旋门。", "你正在香榭丽舍大道上，巴黎最有名的大道。\n\n环法自行车赛是世界上最著名的自行车赛：在全国各地比赛整整三个星期。从 1975 年起，最后的终点就设在这里。那一年，法国车手贝尔纳·泰弗内击败了伟大的比利时冠军埃迪·默克斯，在巴黎人面前赢得了环法冠军。\n\n看看通往凯旋门的这段上坡：对你和对冠军们来说，都是同一段路。"], "Les canons du Trocadéro": ["特罗卡德罗的水炮", "华沙喷泉 · 1937 年世博会", "巴黎最大的喷泉是横着喷的，直冲埃菲尔铁塔。", "看看大水池里那些面朝埃菲尔铁塔的水炮。", "你正在特罗卡德罗花园里，面朝埃菲尔铁塔。\n\n这些花园是为 1937 年世界博览会建的，那是一场盛大的博览会，每个国家都来展示自己的本领。中间有一排水炮，朝塞纳河方向喷出强劲的水平水柱。这是巴黎最大的喷泉。\n\n看看这个大水池：水炮开火时，水柱会射向埃菲尔铁塔。"], "Le pont qu’on voulait faire sauter": ["差点被炸掉的桥", "耶拿桥 · 1808–1814 年", "这座桥以普鲁士的一次惨败命名，而普鲁士人可没忘记。", "看看耶拿桥桥墩上雕刻的雄鹰。", "你正站在耶拿桥上，在埃菲尔铁塔和特罗卡德罗之间。\n\n拿破仑皇帝建这座桥，是为了庆祝 1806 年在耶拿战胜普鲁士——一个德意志王国。可是 1815 年，拿破仑输掉了滑铁卢战役，敌军开进了巴黎。普鲁士将军布吕歇尔想要报复：他想炸掉这座桥。新登基的法国国王路易十八设法保住了它。\n\n看看桥墩上的雄鹰：那是拿破仑的标志。"], "La tour qui devait disparaître": ["本该消失的铁塔", "埃菲尔铁塔 · 1889 年", "它原本只能存在二十年，是无线电救了它。", "抬头看看埃菲尔铁塔塔顶和上面的天线。", "你正站在埃菲尔铁塔脚下。它是为 1889 年世界博览会建的，那是法国展示自己本领的一场盛会。\n\n当时，很多艺术家觉得它丑得可怕。它只被允许保留二十年。它的建造者、工程师古斯塔夫·埃菲尔想办法让它变得有用：他在上面做风和天气的实验。最重要的是，军队在塔顶装了一根无线电天线。铁塔变得太有价值，没人舍得拆了。\n\n看看最顶上：正是那些天线救了它。"], "La fête de la Fédération": ["联盟节", "战神广场 · 1790 年 7 月 14 日", "法国的 7 月 14 日，也是在纪念在这片草坪上举行的那场盛大节日。", "看看一直延伸到军事学院的战神广场大草坪。", "你正站在战神广场上，埃菲尔铁塔脚下的长条草坪。这个故事发生的时候，铁塔还不存在。\n\n1789 年 7 月 14 日，巴黎人攻占了巴士底狱：法国大革命开始了。一年后，人们想在这里举行一场盛大的庆典。可是准备场地的工人不够。于是成千上万的巴黎人自己来挖土，富人和穷人并肩干活。1790 年 7 月 14 日，冒着雨，一大群人在这里庆祝国家。\n\n看看这片草坪：法国国庆节 7 月 14 日的精神，就诞生在这里。"], "Victor Hugo, en son avenue": ["维克多·雨果，在他自己的大道上", "最后的家 · 维克多－雨果大道 124 号", "寄到这里的信，地址独一无二：“寄给维克多·雨果先生，在他的大道上”。", "找找维克多－雨果大道 124 号的那块牌子。", "你正站在维克多－雨果大道上。\n\n维克多·雨果是法国最有名的作家，写了《悲惨世界》和《巴黎圣母院》。他从 1878 年起住在这里。1881 年他 80 岁生日时，巴黎做了一件前所未有的事：在他还活着的时候，就用他的名字命名了这条大道。几十万巴黎人在他的窗下游行致敬。寄给他的信上写着：“寄给维克多·雨果先生，在他的大道上”。1885 年，他在这里去世。\n\n看看楼前的牌子：这里是他最后的家。"], "Le premier vol humain": ["人类第一次飞行", "拉米埃特城堡 · 1783 年 11 月 21 日", "人类第一次飞上天空，就是从这里出发的。", "看看拉米埃特的花园，想象一只气球正在升空。", "你正在拉米埃特。这里以前有一座城堡，带着大花园。\n\n1783 年 11 月 21 日，在那片花园里，两个人登上了一只热气球。他们是年轻的科学老师皮拉特尔·德·罗齐耶和军官达尔朗德侯爵。气球升空了。他们成了人类历史上第一批飞起来的人。他们在巴黎上空飘了 25 分钟，降落在城市的另一边。\n\n看看你头顶的天空：人类就是在这里第一次离开地面的。"], "Le corbeau et le renard": ["乌鸦和狐狸", "拉内拉格花园 · 1774 年的舞会", "一座以英国舞会命名的花园，里面立着一尊寓言故事的雕像。", "在草坪上找找拉封丹的雕像，还有乌鸦和狐狸。", "你正在拉米埃特附近的拉内拉格花园里。\n\n它的名字听起来像英文，这是有原因的：1774 年，这里开了一个露天舞会，模仿的是伦敦一座时髦的花园。贵族们都来这里跳舞。舞会没了，名字留了下来。在草坪中央，一尊雕像纪念着让·德·拉封丹，一位 17 世纪写动物寓言的作家。每个法国孩子都知道他的一个故事：《乌鸦和狐狸》。\n\n看看这尊雕像：乌鸦叼着奶酪，狐狸正在奉承它。"], "Impression, soleil levant": ["《印象·日出》", "马尔莫坦－莫奈博物馆 · 1872 年作", "给“印象派”起了名字的那幅画，就挂在几米之外。", "找找花园边上的马尔莫坦－莫奈博物馆，那是一座宅邸。", "你正经过马尔莫坦－莫奈博物馆附近。里面挂着一幅小画，它给整个艺术流派起了名字。\n\n1872 年，画家克洛德·莫奈画了日出时分的勒阿弗尔港。他给这幅画取名《印象·日出》。1874 年，一位记者嘲笑他和他的朋友们是“印象派”。这个词本来是用来挖苦的，后来却成了世界上最受喜爱的艺术流派之一的名字。\n\n看看花园边上的博物馆：那幅画就在那几面墙后面。"], "L’avenue des pionniers": ["先驱者大道", "大军团大道 · 美好年代", "在有汽车之前，这条大道卖给巴黎人第一批自行车。", "看看大军团大道一路下坡通往马约门的长街。", "你正沿着大军团大道往下走，它从凯旋门出发。\n\n它以拿破仑的军队命名。但在 1900 年左右的“美好年代”，它成了自行车这项全新发明的大市场，后来又成了汽车的大市场。大道两旁满是商店和制造商的作坊：简直就是一座露天车展。\n\n看看大道两边的橱窗：它们至今还在卖摩托车和汽车。"], "Le pont de Perronet": ["佩罗内的桥", "讷伊桥 · 1772 年和 1942 年", "国王亲自来看这座桥拆掉脚手架。", "看看讷伊桥，还有远处拉德芳斯的新凯旋门。", "你正站在塞纳河上的讷伊桥边。\n\n1772 年，工程师让－鲁道夫·佩罗内在这里建了一座石桥，桥拱非常扁平，在当时是一项壮举。最危险的时刻，是拆掉桥拱下面的木脚手架：要么撑得住，要么整座桥塌下来。国王路易十五亲自来观看。桥撑住了。1942 年，这座石桥被今天的钢桥取代了。\n\n看看桥下的塞纳河：想象国王屏住呼吸等待的样子。"], "Un dimanche à la Grande Jatte": ["大碗岛的星期天", "乔治·修拉 · 1884–1886 年", "塞纳河的这条支流，是世界上最有名的画作之一的场景。", "看看大碗岛的河岸和闪闪发光的水面。", "你正沿着大碗岛奔跑，这是塞纳河上的一座小岛。\n\n19 世纪 80 年代，巴黎人星期天会来这里散步。一位年轻画家乔治·修拉花了两年时间来这里观察他们。然后他画了一幅巨大的画——《大碗岛的星期天下午》，全部用细小的彩色圆点画成。1886 年，这幅画引起了轰动。今天，它是世界上最有名的画作之一，收藏在芝加哥。\n\n看看小岛的河岸：这里就是画中的场景。"], "La tour est née à Levallois": ["铁塔诞生在勒瓦卢瓦", "埃菲尔工坊 · 1887–1889 年", "埃菲尔铁塔的全部 18000 个零件，都是在这个街区做出来的。", "找找附近那块“古斯塔夫·埃菲尔街”的路牌。", "你正在勒瓦卢瓦，就在巴黎西边。\n\n埃菲尔铁塔由 18000 个铁零件组成。每一个都是在这里、在工程师古斯塔夫·埃菲尔的工坊里做出来的。每个零件都经过精确得惊人的绘图、钻孔和加工。然后被运到战神广场的工地上，只需要组装就行。所以铁塔从 1887 年到 1889 年，只用了两年多一点就建成了。\n\n朝远处的埃菲尔铁塔看：它的零件就是从这里出发的。"], "Les berges rendues aux piétons": ["还给行人的河岸", "左岸 · 2013 年起禁车", "你正跑在一条以前汽车飞驰的快速路上。", "看看河边：漂浮花园、游戏设施，一辆车都没有。", "你正沿着河岸奔跑，就在水边。十五年前，汽车还在这里飞驰。\n\n20 世纪 60 年代，塞纳河的这些河岸被改成了快速路。2013 年，巴黎市封闭了其中 2.3 公里，把它还给了行人，还加上了漂浮花园、游戏设施和跑道。\n\n看看你周围：你脚下跑的这条路，以前是一条城市高速公路。"], "Les pierres de la Bastille": ["巴士底狱的石头", "协和桥 · 1787–1791 年", "这座桥的一部分，是用人民拆掉的那座监狱的石头建的。", "看看你脚下协和桥的石头，再看看对面的波旁宫。", "你正站在协和桥上。\n\n巴士底狱是一座监狱兼堡垒，是国王权力的象征。1789 年 7 月 14 日，法国大革命开始时，巴黎人攻占了它。然后他们一块石头一块石头地把它拆了。那时这座桥正在建造，最后用巴士底狱的石头完了工。据说用意是：让巴黎人每天都能从那座旧监狱上踩过去。\n\n看看桥上的石头：其中一些就来自巴士底狱。"], "La pyramide et le chiffre du diable": ["金字塔和魔鬼数字", "卢浮宫金字塔 · 贝聿铭，1989 年", "不，这座金字塔并没有 666 块玻璃。", "看看卢浮宫庭院中央的玻璃金字塔。", "你正站在卢浮宫前。在法国国王们搬去凡尔赛之前，这里是他们的王宫。今天，它是世界上最大的博物馆。\n\n1989 年，一个新入口开放了：一座玻璃金字塔，由美籍华裔建筑师贝聿铭设计。它引起了轩然大波：一座现代金字塔，立在一座古老王宫前面。甚至有传言说它有 666 块玻璃，正好是“魔鬼的数字”。不是真的：一共有 673 块。\n\n看看这座金字塔：试着数数玻璃……或者就相信我们吧。"], "Le bouquet de la paix": ["献给和平的花束", "橘园 · 莫奈的《睡莲》，1927 年", "第一次世界大战刚一结束，莫奈就把他的《睡莲》送给了法国。", "看看杜乐丽花园尽头、靠塞纳河一侧的橘园。", "你正经过橘园，杜乐丽花园尽头的一座小博物馆。\n\n1918 年 11 月 12 日，第一次世界大战刚刚结束。画家克洛德·莫奈那时已是一位老人，他想送法国一份礼物。他把礼物交给了自己的朋友、政府首脑乔治·克列孟梭。这份礼物是八幅巨大的画，画的是他花园池塘里的睡莲。它们被挂在这里的两间椭圆形展厅里。莫奈在 1926 年去世，离开幕只差几个月。\n\n看看这座建筑：里面的睡莲环绕着整个墙面。"], "La Grande Cascade": ["大瀑布", "布洛涅森林 · 19 世纪 50 年代", "这道瀑布是为拿破仑三世新建的森林造的，岩石全是假的。", "看看这道大瀑布和它层层叠叠的水池。", "你正在布洛涅森林里，巴黎西边的大森林。它比纽约的中央公园还大。\n\n1852 年，拿破仑三世皇帝把它送给了巴黎。他想让它和伦敦的海德公园一样美。他的工程师阿道夫·阿尔方挖了湖、修了小路，还建了这道大约十米高的瀑布，那些岩石……全是人造的。一切都是假的，但看起来都像真的。\n\n看看瀑布的岩石：它们都是人做出来的。"], "Le moulin de l’abbaye": ["修道院的风车", "隆尚风车 · 修道院建于 1255 年", "这架风车，是一位圣徒国王的妹妹创立的修道院留下的最后痕迹。", "看看这架老风车，就在赛马场正后面。", "你正经过隆尚赛马场旁的一架老风车。\n\n1255 年，国王圣路易的妹妹、法国的伊莎贝尔，在这里创立了一座女修道院。它存在了五百多年。后来 1789 年法国大革命爆发：修道院被卖掉，然后被拆除。只剩下这架风车。就在它后面，每年秋天，赛马场都会举办欧洲最负盛名的赛马比赛——凯旋门大奖赛。\n\n看看这架风车：它是那座修道院最后的痕迹。"], "Le château du pari": ["打赌建成的城堡", "巴加泰勒 · 1777 年", "这座小城堡只用了两个多月就建成了，为的是赢一场赌。", "看看公园中央那座白色的巴加泰勒小城堡。", "你正经过布洛涅森林里的巴加泰勒公园。\n\n1777 年，国王路易十六的弟弟阿图瓦伯爵，和他的嫂子玛丽·安托瓦内特王后打了个赌。他说自己能在三个月内建成一座小城堡。他的建筑师让几百名工人日夜赶工。城堡用 64 天就建好了。赌赢了。\n\n看看这座公园：今天它最出名的是玫瑰。"], "Castor et Pollux": ["卡斯托尔和波吕克斯", "驯化园 · 1870 年围城", "巴黎被围困期间，这座园子里的大象最后进了肉铺。", "看看驯化园的入口。", "你正经过驯化园，布洛涅森林里的一座儿童乐园。\n\n1860 年开放时，它有点像一座动物园，里面有来自世界各地的动物。最受欢迎的明星是两头大象，卡斯托尔和波吕克斯。1870 年冬天，巴黎被来自德意志的普鲁士军队团团围住。什么东西都运不进城，巴黎人在挨饿。12 月底，卡斯托尔和波吕克斯被宰杀，它们的肉被一家高级肉铺以天价卖出。\n\n看看入口：那两头大象就曾住在里面。"], "L’île aux Cygnes": ["天鹅岛", "人工岛 · 1827 年", "一座长 850 米、宽 11 米的小岛：完美的直道。", "看看塞纳河中央那条唯一的林荫小路。", "你正站在塞纳河中央一座狭长的小岛上。它一点都不天然：19 世纪初，大约 200 年前，它是作为一道堤坝修起来的。\n\n后来，人们在上面种了树，修了一条唯一的小路。没有汽车，没有红绿灯，850 米笔直到底。附近的跑者都把这里当成最爱的跑道。\n\n看看你身后：埃菲尔铁塔一路陪着你。"], "La petite sœur de New York": ["纽约的小妹妹", "自由女神像 · 1889 年", "她高 11.5 米，隔着大西洋望着她的大姐姐。", "看看小岛尖端高举火炬的自由女神像。", "没错，那真的是自由女神像，只是小一些。纽约那尊大的，是法国在 1886 年送给美国的礼物，由法国雕塑家奥古斯特·巴托尔迪创作。\n\n1889 年，法国庆祝大革命一百周年。为了表示感谢，住在巴黎的美国人把这尊小复制品送给了这座城市。她手中的书板上刻着两个日期：美国独立日和攻占巴士底狱的日子。1937 年，人们把她转向西方，让她隔着大洋望着她的大姐姐。\n\n看看她举火炬的方向：朝着纽约。"], "Sous le pont Mirabeau": ["米拉波桥下", "米拉波桥 · 1897 年 · 阿波利奈尔，1912 年", "一首关于失去爱情的诗，让这座桥闻名世界。", "看看米拉波桥桥墩上那四尊巨大的青铜雕像。", "你来到了米拉波桥，一座建于 1897 年的铁桥。\n\n20 世纪初，诗人纪尧姆·阿波利奈尔回欧特伊的家时，经常走过这座桥。他爱上了一位女画家玛丽·洛朗森。可是他们分手了。1912 年，他写了一首诗《米拉波桥》：塞纳河在桥下流淌，就像时光流逝，爱情远去。今天，每个法国学生都要背这首诗。\n\n看看桥下流淌的河水：那正是阿波利奈尔当年看到的。"], "La Maison ronde": ["圆房子", "广播大楼 · 亨利·贝尔纳，1963 年", "一座像唱片一样圆的大楼，属于国家电台。", "看看塞纳河边那座巨大的圆形建筑。", "你正经过塞纳河边一座巨大的圆形建筑。它是广播大楼，巴黎人叫它“圆房子”。\n\n1963 年，时任法国总统的戴高乐将军为它揭幕。建筑师亨利·贝尔纳把它设计得像一张唱片：一圈圈办公室和录音室，围着中央的一座塔楼。这里是法国公共广播电台“法国广播电台”的家。\n\n看看它的大圆圈：法国所有的公共电台都从这栋楼里播出。"], "Le jardin de Shakespeare": ["莎士比亚花园", "卡特兰草坪 · 1953 年", "这座花园里的每一种植物，都在莎士比亚的作品里出现过。", "在卡特兰草坪中心找找莎士比亚花园的入口。", "你正在布洛涅森林里，巴黎西边的大森林，在一座叫卡特兰草坪的公园里。\n\n1953 年，这里建了一座非常特别的花园。里面只种莎士比亚戏剧中提到过的植物。每个角落都像一座舞台布景：《仲夏夜之梦》的森林、《麦克白》的荒原、《暴风雨》的小岛。夏天，这里甚至还有露天戏剧演出。\n\n看看这些树和花：每一种都来自一部莎士比亚的戏。"], "L’hippodrome des sauteurs": ["障碍赛马场", "欧特伊赛马场 · 1873 年", "在这里，马不只是跑：它们还要跳。", "透过栏杆看看欧特伊赛马场上的障碍。", "你正沿着 1873 年开放的欧特伊赛马场奔跑。\n\n在这里，马不只是飞奔：它们要跳过树篱和水沟。这叫障碍赛。从 1874 年起，每年春天，法国最著名的障碍赛——巴黎大障碍赛，都在这里举行。\n\n透过栏杆看看：你也许能看到跑道上的树篱。"], "Un aviateur sur la terre battue": ["红土上的飞行员", "罗兰·加洛斯球场 · 1928 年", "世界上最有名的网球场，名字来自一位飞行员，而不是网球运动员。", "看看罗兰·加洛斯球场那与红土同色的外墙。", "你正经过罗兰·加洛斯球场，每年春天，世界上最有名的红土网球赛都在这里举行。\n\n可罗兰·加洛斯并不是网球运动员，他是一名飞行员。1913 年，他成为第一个飞越地中海的人。1918 年，他在第一次世界大战中牺牲。十年后，1928 年，人们为一场重要的网球比赛建了这座球场，并用这位英雄的名字为它命名。\n\n看看入口上方的名字：它属于一位飞行员，而不是一位球员。"], "Sur les rails de la Petite Ceinture": ["在小环线的铁轨上", "欧特伊线 · 1854 年", "你正跑在一条交还给大自然的旧铁路上。", "看看这条曾经跑火车的绿色路堑，里面长满了蕨类和树木。", "你正在城市中央的一条绿色路堑里。这里以前跑火车。\n\n19 世纪，一条铁路环绕着整个巴黎，叫“小环线”。这一段叫欧特伊线，1854 年开通，乘客一直坐到 1985 年。后来火车停了，大自然接管了这里：树木、蕨类、野花。\n\n看看地面：有些地方你还能看出铁轨曾经的位置。"], "Le pont des cadenas": ["挂锁桥", "艺术桥 · 1804 年", "这座小桥上曾经挂了多达 45 吨的爱情锁。", "看看艺术桥的玻璃栏杆，那里以前挂满了锁。", "你正站在艺术桥上，一座连接卢浮宫和法兰西学会的步行桥。\n\n它在 1804 年开通，是巴黎第一座铁桥。2010 年代初，世界各地的情侣都在桥上挂锁，锁上刻着两人的名字缩写，再把钥匙扔进塞纳河。锁实在太多了，多达 45 吨，栏杆都被压坏了。2015 年，市政府把锁全部拆掉，装上了玻璃板。\n\n看看桥边的玻璃板：它们取代了那些锁。"], "Le Pont-Neuf et le Vert-Galant": ["新桥和“风流老头”", "新桥 · 1578–1607 年", "“新桥”其实是巴黎最古老的桥。", "看看新桥中央亨利四世的骑马像。", "你来到了新桥。它的名字意思是“新的桥”，可它却是巴黎最古老的桥。\n\n它在 1607 年、国王亨利四世在位时完工。在当时它是革命性的：巴黎第一座桥上不建房子、而且有人行道的桥。整个巴黎都来这里散步。就在桥下，有一座小花园，用的是国王的绰号“风流老头”，因为他有非常多的情妇。\n\n看看桥中央那尊国王骑马像：那就是亨利四世。"], "L’île inventée": ["被“发明”出来的岛", "圣路易岛 · 1614–1664 年", "这座岛是 17 世纪一位开发商把两座小岛连起来造出来的。", "看看圣路易岛的河岸和那些宅邸的外墙。", "你正在圣路易岛上，巴黎市中心的两座岛之一。\n\n400 年前，这里只有两座小岛，岛上放着牛。1614 年左右，一位开发商克里斯托夫·马里得到国王的批准，把两座小岛连起来盖房子。五十年里，这里有了河岸、笔直的街道和贵族的漂亮宅邸。这是巴黎第一个全新的街区。\n\n看看河岸边的外墙：几乎全都是那个时代的。"], "Les bouquinistes": ["旧书商", "塞纳河岸 · 始于 16 世纪", "这些绿色箱子组成了世界上最大的露天书店。", "看看固定在河边矮墙上的那些绿色书箱。", "你正沿着塞纳河奔跑。矮墙上有一个个绿色的大箱子：这就是旧书商，卖旧书的人。\n\n他们从 16 世纪就在这里了，将近 500 年。很长时间里，他们被驱赶，后来又被容忍。1859 年，市政府终于给了他们正式的摊位。今天，大约 200 位书商经营着 900 个书箱：这是世界上最大的露天书店。\n\n看看这些绿箱子：到了晚上，它们会像箱子一样合上。"], "Le Grand Parc des Docks": ["码头大公园", "圣旺 · 2013 年开放", "一座 12 公顷的公园，长在了从前的工厂和码头上。", "看看塞纳河边公园里的草地和池塘。", "你已经离开巴黎，来到塞纳河边的圣旺。\n\n一百多年来，这里是码头、工厂和一座发电厂：噪音、浓烟和煤炭。后来一切都关闭了。取而代之的是一个生态街区，围绕着这座 12 公顷的大公园建起来，公园在 2013 年开放。\n\n看看这些草地和池塘：它们取代了工厂的烟囱。"], "Les Puces de Saint-Ouen": ["圣旺跳蚤市场", "跳蚤市场 · 19 世纪末", "世界上最大的古董市场，起源于拾荒者捡来的东西。", "看看圣旺跳蚤市场里的小巷和摊位。", "你正经过圣旺跳蚤市场附近，就在巴黎北边。\n\n19 世纪末，拾荒者翻遍巴黎的垃圾桶，寻找布料、废铁和旧物件。他们被赶出城后，就在城墙外这里落脚，卖他们捡到的东西。慢慢地，这里成了一个市场。今天，每到周末，有一千多个商家聚集在这里：这是世界上最大的古董市场。\n\n看看市场里的小巷：从旧纽扣到城堡里的吊灯，什么都能找到。"], "Verlaine et Breton": ["魏尔伦和布勒东", "巴蒂尼奥勒公墓 · 1833 年", "这堵墙后面，长眠着一位伟大的诗人和超现实主义之父。", "看看紧贴环城大道的小小巴蒂尼奥勒公墓的围墙。", "你正经过巴蒂尼奥勒公墓，一座 1833 年开放的小墓地，如今紧挨着环城大道。\n\n可它安葬着两个响亮的名字。法国最伟大的诗人之一保尔·魏尔伦，1896 年葬在这里。1966 年，安德烈·布勒东也葬到了这里：他创立了超现实主义，一个从梦境中汲取灵感的艺术流派。\n\n看看墓地的围墙：墙后是一片宁静的角落，就在车流轰鸣的旁边。"], "Le parc des voies ferrées": ["铁路上的公园", "马丁·路德·金公园 · 2007 年起", "这座公园取代了一大片铁轨。", "看看马丁·路德·金公园里的池塘和花园。", "你正在巴蒂尼奥勒街区的马丁·路德·金公园里。\n\n这里以前是一眼望不到头的铁轨和仓库，属于离你酒店很近的圣拉扎尔火车站。如果巴黎赢得了 2012 年奥运会，运动员村就会建在这里。结果伦敦赢了。于是从 2007 年起，人们在这里建了一座公园，作为一个新生态街区的中心。\n\n看看公园周围的高楼：整个街区都长在旧铁路的土地上。"], "Le méridien de Saint-Sulpice": ["圣叙尔皮斯的子午线", "圣叙尔皮斯教堂 · 1743 年的日晷", "一条铜线横穿教堂的地面：它是一件天文仪器。", "找找教堂地面上那条通向方尖碑的铜线。", "你正经过圣叙尔皮斯教堂，巴黎最大的教堂之一。\n\n教堂里，一条细细的铜线横穿地面，通向一座小方尖碑。这是 1743 年安装的一件天文仪器。一束阳光从一个小孔照进来，落在铜线上。人们用它来确定季节，从而推算复活节的日期。小说《达·芬奇密码》说它是一条秘密线：其实不是。\n\n看看教堂的两座塔楼：那条铜线就在大门后面。"], "Le palais florentin": ["佛罗伦萨式的宫殿", "卢森堡宫 · 1615–1631 年", "一位思乡的王后建了这座宫殿。", "看看大水池尽头卢森堡宫的正面。", "你面前是卢森堡宫，位于同名大花园的尽头。\n\n17 世纪初，意大利公主玛丽·德·美第奇是法国王后。她的丈夫国王亨利四世刚刚遇刺身亡。她很想家，于是建了这座宫殿，让自己想起童年时在佛罗伦萨住过的宫殿。工程从 1615 年持续到 1631 年。从 1799 年起，参议院就在这里开会，它是为法国投票制定法律的两个议院之一。\n\n看看它的正面：这是巴黎市中心的一小块意大利。"], "Le pendule du Panthéon": ["先贤祠的摆", "先贤祠 · 莱昂·傅科，1851 年", "在这座穹顶下，人们亲眼看到了地球在转动。", "抬头看看先贤祠的大穹顶。", "你面前是先贤祠，那座带大穹顶的建筑。法国把对国家最重要的人安葬在这里：作家维克多·雨果、科学家玛丽·居里，还有歌手兼抵抗运动英雄约瑟芬·贝克。\n\n1851 年，这里做过一个著名的实验。物理学家莱昂·傅科在穹顶下用一根 67 米长的钢索挂了一个沉重的球，让它摆动起来。几个小时过去，摆动的方向慢慢转动。转动的不是球，而是它下面的地球。人们第一次亲眼看到，地球在自转。\n\n看看这座穹顶：那个摆至今仍在它下面摆动。"], "Les arènes de Lutèce": ["吕特斯竞技场", "高卢－罗马圆形剧场 · 1 世纪", "将近两千年前，成千上万的观众坐在这里。", "看看石头看台和圆形的场地。", "你正走进一座古罗马圆形剧场，它藏在楼房后面。\n\n2000 年前，巴黎叫吕特斯，是罗马帝国的一部分。1 世纪时，人们在这里建了一座竞技场，有点像一座小型罗马斗兽场。成千上万的观众来这里看表演和打斗。后来它在地下消失了好几个世纪。1869 年修街道时，它又被挖了出来，作家维克多·雨果为保护它奔走呼吁。\n\n看看这些石头看台：今天，巴黎人在这里玩滚球。"], "Le bassin de Napoléon": ["拿破仑的水池", "拉维莱特水池 · 1808 年", "巴黎最大的人工湖，是为了给巴黎人提供饮用水而挖的。", "看看两岸都是码头的长长的拉维莱特水池。", "你正沿着一条很长的水池奔跑，它叫拉维莱特水池。\n\n19 世纪初，巴黎缺少干净的水。1802 年，拿破仑决定从远处引水，从一条叫乌尔克的河，用运河把水引到这里。这座 1808 年启用的水池，既是蓄水池，也是港口。它长 800 米，是巴黎最大的人工水面。\n\n看看两岸：今天，这里是野餐和露天咖啡座的好地方。"], "La Géode": ["晶球影院", "球幕影院 · 阿德里安·凡西尔贝，1985 年", "一颗 36 米的镜面球，映出天空和跑步的人。", "看看晶球影院的大银球和它在水中的倒影。", "你正经过拉维莱特公园里一颗闪闪发亮的巨球。它就是晶球影院，1985 年开放。\n\n它的直径 36 米，表面覆盖着 6000 多块抛光的钢制三角形，就像一面镜子。里面是一座电影院，有一块巨大的穹顶形银幕：你会感觉自己就在电影里面。\n\n经过时看看这颗球：你会看到自己正在里面跑步。"], "La Philharmonie": ["巴黎爱乐音乐厅", "音乐厅 · 让·努维尔，2015 年", "一艘金属太空船，观众围坐在乐团四周。", "看看爱乐音乐厅那面覆盖着鸟形金属片的外墙。", "你正经过一座灰色的大型金属建筑：巴黎爱乐音乐厅，2015 年开放。\n\n它的建筑师让·努维尔设计了一座音乐厅，观众不是面对乐团，而是围坐在乐团四周，坐在仿佛悬浮在空中的楼座上。外面，外墙上覆盖着成千上万块鸟形的铝片。\n\n仔细看看外墙：那些小金属片组成了一只只鸟的形状。"], "La porte du Roi-Soleil": ["太阳王的城门", "圣但尼门 · 弗朗索瓦·布隆代尔，1672 年", "路易十四建了这座拱门，庆祝他的胜利。", "抬头看看圣但尼门和上面的雕刻。", "你正经过街道中央一座巨大的石拱门：圣但尼门。\n\n17 世纪，被称为“太阳王”的国王路易十四权势极大。他让人拆掉了巴黎的旧城墙：在他看来，这座城市已经不再需要城墙了。在旧城门的位置上，他建起了凯旋门。这一座高 24 米，建于 1672 年，庆祝的是他的军事胜利。\n\n看看拱门上的雕刻：它们讲述的是国王的战役。"], "Face au Mont-Valérien": ["面对瓦莱里安山", "河岸 · 遥望纪念馆", "在对面的山丘上，一千多名抵抗战士和人质被枪杀。", "看看塞纳河对岸的瓦莱里安山。", "你正在塞纳河边。对面的山丘上有一座要塞：瓦莱里安山。\n\n第二次世界大战期间，德军占领了法国。从 1941 年到 1944 年，他们在这座要塞里枪杀了一千多名抵抗战士和人质。1960 年，曾在伦敦领导“自由法国”的戴高乐将军，在这里揭幕了一座纪念馆。每年 6 月 18 日，人们都会在这里纪念他 1940 年通过广播发出的抵抗号召。\n\n看看对面的山丘：它是全法国的纪念之地。"], "Le château disparu": ["消失的城堡", "城堡平台 · 1870 年被毁", "在这片空荡荡的平台上，曾有一座城堡，波拿巴就在这里夺取了政权。", "看看城堡曾经矗立的那片空旷的大平台。", "你正站在圣克卢公园的一片大平台上。这里以前有一座城堡。\n\n1785 年，玛丽·安托瓦内特王后买下了它。1799 年，历史上一个关键时刻在这里发生：年轻的将军拿破仑·波拿巴用武力夺取了政权。这是他统治的开始。后来，他的侄子拿破仑三世皇帝也住在这里。1870 年，与普鲁士的战争期间，城堡被大火烧毁，再也没有重建。\n\n看看你面前这片空地：城堡就曾立在这里，看着同样的风景。"], "L’autre Trocadéro": ["另一个特罗卡德罗", "特罗卡德罗花园 · 巴黎全景", "和巴黎那个一样，这座花园也是以一座西班牙要塞命名的。", "从花园高处转过身来：整个巴黎就在你面前。", "你正在圣克卢公园的最高处，一座也叫“特罗卡德罗”的花园，和埃菲尔铁塔对面的那个广场同名。\n\n两个名字都来自 1823 年法国军队在西班牙打赢的一场战役。但在这里，真正的礼物是风景：整个巴黎在你面前展开。\n\n看看地平线：你能看到埃菲尔铁塔，再往左，是拉德芳斯的高楼。"], "Le port de l’Arsenal": ["阿森纳港", "阿森纳水池 · 1983 年起成为游艇港", "这些船漂浮在巴黎旧城墙的护城河里。", "看看巴士底广场下方阿森纳港里的船。", "你正沿着一座停满小船的水池奔跑，它位于塞纳河和巴士底广场之间。\n\n中世纪时，巴黎被城墙围着，墙前有注满水的护城河保护城市。这座水池就是当年的一段护城河。19 世纪，它成了连接塞纳河和圣马丁运河的港口。从 1983 年起，它成了游艇港，旁边还有一座花园。\n\n看看这些停泊的船：它们漂浮在一条古老的防御护城河里。"], "Le ministère qui enjambe le quai": ["跨过河岸的部委大楼", "财政部 · 舍梅托夫和维多夫罗，1989 年", "这座像桥一样的大楼把脚伸进了塞纳河，部长们有时坐船来上班。", "看看那座伸出河岸、巨大的财政部大楼。", "你正从一座桥形的巨大建筑下经过。它是财政部，负责管理法国国家的钱。\n\n财政部以前设在卢浮宫的一部分里。20 世纪 80 年代，弗朗索瓦·密特朗总统想把整个卢浮宫都留给博物馆。于是在这里盖了这座新楼，1989 年完工。它的一端伸过河岸，一直伸到塞纳河上，还有一个码头：部长们可以坐船来上班。\n\n看看大楼的尽头：它的脚几乎踩在水里。"], "Quatre livres ouverts": ["四本打开的书", "法国国家图书馆密特朗馆 · 多米尼克·佩罗，1996 年", "国家图书馆的四座塔楼，形状就像打开的书。", "看看国家图书馆广场四角那四座 L 形的塔楼。", "你面前是法国国家图书馆。全国出版的每一样东西，它都收藏一份。\n\n这座建筑在 1996 年开放。建筑师多米尼克·佩罗设计了四座 L 形的塔楼，立在一个巨大广场的四个角上，就像四本竖着打开的书。广场中间往下，长着一片真正的高大松树林，你可以看，但不能走进去。\n\n看看这四座塔楼：把它们想象成半开的书。"], "Le musée en plein air": ["露天博物馆", "蒂诺·罗西花园 · 1980 年起", "沿着这段河岸，雕塑就这样展出，不隔玻璃，也不要门票。", "看看蒂诺·罗西花园树丛间摆放的雕塑。", "你正在塞纳河边的蒂诺·罗西花园里。它是一座免费的博物馆，日夜开放。\n\n从 1980 年起，20 世纪艺术家的现代雕塑就立在这里，在树木和河流之间。夏天的晚上，那些小小的石头圆形剧场会变成舞池：探戈、萨尔萨，就在水边。\n\n看看树丛间的雕塑：每一件都是真正的博物馆藏品。"], "Le cimetière du Montparnasse": ["蒙帕纳斯公墓", "公墓 · 1824 年", "这堵墙后面，萨特和波伏娃合葬在一起。", "沿大道跑步时，看看蒙帕纳斯公墓的围墙。", "你正沿着蒙帕纳斯公墓奔跑。\n\n大约从 1920 年到 1950 年，蒙帕纳斯街区吸引了世界各地的艺术家。很多人就安葬在这里。让－保罗·萨特和西蒙娜·德·波伏娃，两位哲学家，也是法国最有名的知识分子伴侣，合葬在一起。诗人夏尔·波德莱尔就在附近。歌手塞尔日·甘斯布也在这里。\n\n看看墓地的围墙：墙后安息着法国文化的很大一部分。"], "La mire du méridien": ["子午线标记", "蒙苏里公园 · 阿尔方，1878 年", "在这座公园里，一块小石碑标出了巴黎子午线。", "在公园里找找那块小石碑——“南方标”。", "你正在蒙苏里公园，巴黎南部的一座大花园，1878 年开放。\n\n它藏着一件小宝贝：一块 1806 年的石碑，叫“南方标”。它正好立在巴黎子午线上，那是一条南北走向的假想线。在全世界选定穿过伦敦格林尼治的那条线之前，法国的一切测量都以这条线为准。巴黎天文台的天文学家们会对准这块石碑，来校准他们的仪器。\n\n看看这根小石柱：它正好立在子午线上。"], "Le parc de Brassens": ["布拉桑公园", "乔治·布拉桑公园 · 1985 年", "入口处的青铜马，让人想起从前的马市。", "看看入口处的青铜马和拍卖塔。", "你正在巴黎南部的乔治·布拉桑公园里。\n\n直到 20 世纪 70 年代，这里还是屠宰场和马市。1985 年，公园取代了它们，但留下了一些纪念：几座亭子、一座以前宣布拍卖结果的塔，还有入口处的马雕像。公园以乔治·布拉桑命名，他是法国人非常喜爱的歌手，曾住在附近。\n\n看看入口处的青铜马：它们让人想起从前的马市。"], "La Petite Ceinture du 15e": ["第十五区的小环线", "旧铁路 · 2013 年起成为步道", "一公里半沉睡的铁路，交给了散步和跑步的人。", "看看小环线的铁轨和开满花的路堤。", "你正走在一条旧铁路上，周围长满了青草。\n\n19 世纪，一条铁路环绕着整个巴黎，叫“小环线”。在左岸，它从 1934 年起就不再载客了。铁轨留了下来，大自然在它周围生长。2013 年，市政府在这里沿着铁轨开放了一条步道。\n\n看看开满花的路堤和老桥：这几乎就是城市中央的乡村。"], "L’opéra du Bicentenaire": ["两百周年的歌剧院", "巴士底歌剧院 · 卡洛斯·奥特，1989 年", "这座玻璃歌剧院在大革命两百周年的前一天开幕。", "看看广场上巴士底歌剧院那面巨大的玻璃正面。", "你正在巴士底广场上。1789 年 7 月 14 日，法国大革命开始时，巴黎人攻占的那座监狱兼堡垒就立在这里。\n\n两百年后，弗朗索瓦·密特朗总统想在这里建一座现代歌剧院，向所有人开放，而不只是富人。这座玻璃和石头的大建筑在 1989 年 7 月 13 日开幕，正好是大革命两百周年的前一天。\n\n看看巴士底歌剧院：它的主厅能坐大约 2700 人。"], "Le jardin sur le viaduc": ["高架桥上的花园", "勒内·迪蒙绿荫步道 · 1993 年", "你正跑在世界上第一座建在高架桥上的空中公园里。", "低头看看你脚下的砖砌高架桥和它的拱洞。", "你正走在一条高出街道的绿化步道上：绿荫步道。\n\n从 1859 年到 1969 年，一列火车沿着这座砖砌高架桥，从巴士底开往樊尚。线路停运后，这一切本可能被拆掉。可在 1993 年，这条铁路变成了一座将近 5 公里长的花园。它是世界上第一条这样的步道，启发了纽约著名的高线公园。\n\n看看你脚下：你正跑在一条旧铁路上。"], "Le palais de 1931": ["1931 年的宫殿", "金门宫 · 阿尔贝·拉普拉德，1931 年", "它的正面是一幅巨大的雕刻壁画，是一场饱受争议的博览会留下的遗迹。", "看看金门宫那面巨大的雕刻正面。", "你正经过一座带柱子的大宫殿：金门宫。\n\n它建于 1931 年，是为殖民地博览会建造的。那时法国拥有庞大的帝国，在非洲和亚洲都有殖民地，这场博览会就是为了颂扬它。整个正面覆盖着一幅巨大的浮雕，表现的是那些遥远的土地。从 2007 年起，宫殿里设立了移民历史博物馆，用另一种眼光来看待这段过去。\n\n看看正面：浮雕环绕着整座建筑。"], "Le lac de la Jambe de bois": ["“木腿将军”的湖", "多梅尼尔湖 · 第二帝国", "这片湖以一位拒绝交出樊尚的将军命名。", "看看湖上的两座小岛，还有岩洞上方的小神庙。", "你来到了樊尚森林里的多梅尼尔湖，樊尚森林是巴黎东边的大森林。\n\n这片湖以多梅尼尔将军命名，他在战斗中失去了一条腿，人们叫他“木腿”。1814 年，拿破仑刚刚输掉战争，敌军已经进了巴黎。多梅尼尔正守卫着樊尚城堡。有人要他投降。据说他回答：“你们把我的腿还给我，我就把樊尚交给你们。”\n\n看看这片湖和湖中的小岛：它们都以他的名字命名。"], "Les archives de la planète": ["星球档案馆", "阿尔贝－卡恩博物馆和花园 · 布洛涅", "1914 年以前，一位银行家派摄影师去拍下全世界，而且是彩色的。", "看看阿尔贝－卡恩博物馆的花园，还有里面的日本角落。", "你正经过布洛涅的阿尔贝－卡恩博物馆和花园。\n\n阿尔贝·卡恩是一位非常富有的银行家，他有一个梦想：在世界改变之前，把整个地球记录下来。从 1909 年起，他出钱让摄影师去了大约五十个国家。他们带回了 72000 张彩色照片，是历史上最早的一批彩色照片。他还在自家房子周围建了来自世界各地的花园：日式、英式、法式。\n\n越过围墙看一看：你能瞥见他日本花园里的树。"], "L’île Renault": ["雷诺岛", "塞甘岛 · 工厂 1929–1992 年", "这整座岛曾是一座汽车工厂，人称“工人的堡垒”。", "看看塞纳河中央的塞甘岛。", "你正沿着塞甘岛奔跑，它位于布洛涅－比扬古的塞纳河中央。\n\n汽车制造商雷诺就诞生在这里。从 1929 年起，公司在整座岛上盖满了厂房。几万名工人在这里工作。这座工厂因为大罢工而出名。1992 年，最后一辆汽车从这里开出。今天，岛上有音乐厅和花园。\n\n看看这座岛：想象它整个被工厂覆盖的样子。"], "La voile qui suit le soleil": ["追着太阳转的帆", "塞纳河音乐厅 · 坂茂，2017 年", "在小岛的尖端，一面太阳能板做成的帆随着太阳转动。", "看看塞纳河音乐厅那面巨大的太阳能帆。", "你来到了塞纳河上一座小岛的尖端。那座大建筑是塞纳河音乐厅，2017 年开放的演出场馆。\n\n它的建筑师是日本的坂茂和法国的让·德·加斯蒂纳，他们设计了一座蛋形的音乐厅，外面包着木头。它的周围，一面覆盖着太阳能板的巨大的帆在白天跟着太阳转动，就像一朵向日葵。\n\n看看这面大帆：一天中不同的时间，它的位置都不一样。"], "La tour aux figures": ["人物塔", "圣日耳曼岛 · 让·杜布菲，1988 年", "一座 24 米高、可以走进去的雕塑，上面布满黑、红、蓝三色线条。", "看看那座画着黑、红、蓝线条的高大白塔。", "你来到了圣日耳曼岛。你面前是一座塔，看起来像一幅巨大的儿童画。\n\n它叫“人物塔”，作者是法国画家兼雕塑家让·杜布菲。他在 20 世纪 60 年代用自己的风格构思了它：用黑线勾勒的白色形状，点缀着红色和蓝色。直到 1988 年他去世后，它才建成。它高 24 米，里面藏着一座螺旋楼梯。\n\n看看它的黑线条：就像一幅站起来的画。"], "La porte de l'avenue Rapp": ["拉普大道的大门", "新艺术风格 · 朱尔·拉维罗特，1901 年", "巴黎最大胆的大门，有亚当、夏娃和蜥蜴。", "站到对面的人行道上，看看拉普大道 29 号的大门。", "你正在埃菲尔铁塔附近的拉普大道上。站到对面的人行道上，才能看到整栋楼。\n\n它建于 1900 年左右，建筑师是朱尔·拉维罗特，一位非常大胆的新艺术风格建筑师，这种风格充满植物般的曲线。外墙上覆盖着陶瓷。大门两边是亚当和夏娃，门板上还有铁铸的蜥蜴。1901 年，它赢得了巴黎最美外墙比赛。\n\n看看这扇门：找找亚当、夏娃和蜥蜴。"], "Le Dôme des Invalides": ["荣军院穹顶", "皇家礼拜堂 · 朱尔·阿杜安－芒萨尔，1677 年", "拿破仑等了二十年，才住进他的墓。", "从沃邦广场抬头看看荣军院的金色穹顶。", "你面前是荣军院的金色穹顶，巴黎到处都能看到它。\n\n荣军院是国王路易十四为受伤士兵建造的医院。1677 年，他把穹顶交给了凡尔赛宫的建筑师朱尔·阿杜安－芒萨尔。拿破仑就葬在这里。战败后，他被流放到圣赫勒拿岛，大西洋中央一座很小的岛，1821 年死在那里。1840 年，他的遗体被运回巴黎。他就安息在这座穹顶下。\n\n从沃邦广场看这座穹顶：那里的视角最好。"], "Rodin à l'hôtel Biron": ["罗丹在比隆公馆", "宅邸 · 18 世纪", "马蒂斯、科克托、伊莎多拉·邓肯和里尔克，都曾是罗丹的邻居。", "看看瓦雷讷街上的比隆公馆和它的雕塑花园。", "你正站在比隆公馆外面，一座带花园的 18 世纪大宅。它就是罗丹博物馆。\n\n奥古斯特·罗丹是《思想者》的作者，那个托着下巴、陷入沉思的坐着的男人。20 世纪初，这座房子被一间一间地租给艺术家。1908 年，罗丹租了几间，后来租下了整栋房子。他把自己的作品捐给了国家，只有一个条件：这里要成为他的博物馆。\n\n往花园里看：《思想者》就在那里。"], "Le Grand Palais": ["大皇宫", "世界博览会 · 1900 年", "在它巨大的玻璃屋顶下，举行过 2024 年奥运会的击剑比赛。", "抬头看看玻璃屋顶，还有四角的青铜战车。", "你面前是大皇宫，有着巨大的玻璃屋顶。\n\n它是为 1900 年世界博览会建的，那是一场盛大的展会，全世界都来展示自己的发明。玻璃屋顶下的主厅有两个足球场那么大。翻修期间，它承办了 2024 年巴黎奥运会的击剑比赛。2025 年，它全面重新开放。\n\n看看屋顶的四个角：那里有马拉着的青铜战车。"], "L'avion des Galeries Lafayette": ["老佛爷百货的飞机", "壮举 · 朱尔·韦德里纳，1919 年", "1919 年 1 月 19 日，一架飞机降落在这家百货公司的屋顶上。", "抬头看看老佛爷百货的屋顶。", "你正站在老佛爷百货外面，奥斯曼大道上的那家百货公司。\n\n1919 年，为了制造话题，百货公司悬赏一大笔奖金，给第一个在它屋顶上降落的飞行员。大胆的飞行员朱尔·韦德里纳接受了挑战。1919 年 1 月 19 日，他驾驶小飞机降落在屋顶上，就停在离边缘只差一点的地方。可是那时禁止飞越巴黎：他被罚了一小笔钱。\n\n看看屋顶：一百多年前，一架飞机曾降落在那里。"], "La tour Saint-Jacques": ["圣雅克塔", "哥特式钟楼 · 1509–1523 年", "一座教堂留下的最后遗迹，朝圣者曾从这里出发前往孔波斯特拉。", "抬头看看圣雅克塔，还有塔脚下的帕斯卡雕像。", "你面前是一座孤零零立在花园里的高大哥特式塔楼：圣雅克塔，高 52 米。\n\n它曾是一座教堂的钟楼，那座教堂在大革命期间被毁。这座教堂接待步行前往西班牙圣地亚哥－德孔波斯特拉的朝圣者，那是一条伟大的基督教朝圣之路。据说 17 世纪时，科学家布莱兹·帕斯卡曾在这里做过关于气压的实验。他的雕像就立在塔底。\n\n看看最顶上：一个小气象站至今还在测量巴黎的天气。"], "La fontaine Stravinsky": ["斯特拉文斯基喷泉", "雕塑 · 廷格利和妮基·德·圣法勒，1983 年", "十六件雕塑，随着斯特拉文斯基的音乐起舞。", "看看水池和里面旋转喷水的彩色雕塑。", "你正在蓬皮杜中心旁边，面前是一个满是会动的雕塑的水池。\n\n1983 年，一对艺术家夫妻把它们安放在这里。让·廷格利做了会旋转的黑色机器。妮基·德·圣法勒做了圆滚滚、色彩鲜艳的人物。他们一起向作曲家伊戈尔·斯特拉文斯基致敬，雕塑的灵感来自他的音乐：一只火鸟、一条美人鱼、一个高音谱号。\n\n看看那些黑色机器正往彩色雕塑上喷水。"], "Saint-Eustache": ["圣厄斯塔什教堂", "教堂 · 1532–1640 年", "黎塞留、莫里哀和蓬巴杜夫人都在这里受洗。", "看看圣厄斯塔什教堂巨大的正面。", "你面前是圣厄斯塔什教堂，大堂区的一座巨大教堂，大堂区曾经是巴黎的大市场。\n\n它建于 1532 年到 1640 年。一些名人在这里受洗：路易十三的首相黎塞留枢机主教，还有剧作家莫里哀。1778 年，当时身在巴黎的作曲家莫扎特在这里为母亲举行了葬礼。它的管风琴有将近 8000 根音管。\n\n看看它的正面，然后进去听听管风琴是否正在演奏。"], "La colonne de Catherine de Médicis": ["凯瑟琳·德·美第奇的圆柱", "商品交易所 · 1574 年和 2021 年", "一根占星师的圆柱，贴在一座大型当代艺术博物馆的圆楼上。", "看看紧贴商品交易所圆楼的那根空心圆柱。", "你正站在商品交易所外面，一座圆形建筑。贴着它立着一根奇怪的圆柱。\n\n这根圆柱建于 1574 年。它是凯瑟琳·德·美第奇宫殿留下的唯一遗迹。她是一位来自意大利的王后，三位法国国王的母亲。据说她的占星师会爬上这根圆柱，从星星里读出未来。从 2021 年起，这座圆楼成了收藏家弗朗索瓦·皮诺的当代艺术博物馆。\n\n看看圆柱的顶端：占星师就是在那里观察天空的。"], "La Rotonde de la Villette": ["拉维莱特圆亭", "收税亭 · 克洛德－尼古拉·勒杜", "蒙索公园圆亭的双胞胎姐妹，就在运河的尽头。", "看看拉维莱特水池尽头那座带柱子的大圆亭。", "你正在斯大林格勒广场上，面前是一座带柱子的圆形建筑：拉维莱特圆亭。\n\n1860 年以前，巴黎被一道墙围着。它不是用来防御的，而是对一切进城的东西收税：葡萄酒、肉、木头。建筑师克洛德－尼古拉·勒杜设计了这些收税亭。巴黎人痛恨这道墙。它的建筑只留下了四座，这就是其中之一。\n\n看看这些柱子：一座真正的神庙，却只是一个简单的收税处。"], "Les Buttes-Chaumont": ["肖蒙山丘公园", "公园 · 阿道夫·阿尔方，1867 年", "一座旧垃圾场，变成了巴黎最壮观的公园。", "看看悬崖、湖，还有岛顶上的小神庙。", "你正站在第十九区的肖蒙山丘公园外面。\n\n这个地方以前很阴森：一座垃圾场、几个采石场，附近还有一个从前绞死犯人的地方。在拿破仑三世皇帝时期，建造了巴黎许多公园的工程师阿道夫·阿尔方，把这一切变成了一座公园。它在 1867 年开放。悬崖、瀑布、岩洞和湖，几乎全是人造的。\n\n看看岛顶上的小神庙。把自行车锁好：这座公园最好步行游览。"], "L'Hôtel du Nord": ["北方旅馆", "电影 · 马塞尔·卡尔内，1938 年", "“气氛，气氛……”：运河边最有名的一句台词。", "看看正对运河人行桥的北方旅馆的正面。", "你正在圣马丁运河边，北方旅馆外面。\n\n它以前是一家朴素的小旅馆。老板的儿子、作家欧仁·达比特写了一部关于它的小说。1938 年，导演马塞尔·卡尔内把它拍成了一部经典电影。女演员阿尔莱蒂在片中说出了法国电影里最有名的一句台词，讲的是“气氛”。可这部电影其实完全是在摄影棚里拍的。\n\n看看这栋楼的正面和运河：这就是他们为电影重建的那个场景。"], "Le lac de l'Opéra": ["歌剧院下的湖", "歌剧院 · 夏尔·加尼叶，1875 年", "舞台下面有一个湖，它可能启发了《歌剧魅影》。", "看看加尼叶歌剧院金光闪闪的正面。", "你面前是加尼叶歌剧院，巴黎的大歌剧院，1875 年完工。\n\n1861 年，工程刚开始时，建筑师夏尔·加尼叶遇到了一个难题：地下全是水。为了保护地基，他在观众厅下面建了一个巨大的防水水箱。这就是歌剧院的“湖”，至今仍注满了水。据说，它启发了作家加斯东·勒鲁，让他想到了“歌剧魅影”的藏身之处。\n\n看看金色的正面：在你脚下，有一个湖。"], "La Ruche": ["蜂巢", "艺术家聚居地 · 阿尔弗雷德·布歇，1902 年", "夏加尔、苏蒂纳和莫迪利亚尼，曾在一座世博会展馆的屋顶下创作。", "从但泽巷看看蜂巢的圆亭和它的大门。", "你正站在“蜂巢”外面，一座藏在花园深处的圆形建筑。\n\n1900 年，巴黎举办了世界博览会。之后，雕塑家阿尔弗雷德·布歇回收了拆下来的展馆部件。他的想法是：几乎免费地给穷艺术家提供住处。来自欧洲各地、身无分文的画家和雕塑家都住在这里，比如马克·夏加尔和阿梅代奥·莫迪利亚尼。他们后来都出了名。\n\n看看这座圆亭：之所以叫“蜂巢”，是因为艺术家们在这里像蜜蜂一样工作。"], "L'atelier de Bourdelle": ["布德尔的工作室", "艺术家博物馆 · 1885–1929 年", "一位雕塑家的工作室原样保留，而且免费参观。", "看看布德尔博物馆花园里的大型青铜像。", "你正站在蒙帕纳斯的布德尔博物馆外面。\n\n安托万·布德尔是一位雕塑家。他起初是《思想者》作者罗丹的助手，后来自己也成了名。从 1885 年直到 1929 年去世，他一直在这些工作室里创作。一切都还在：巨大的石膏像、青铜像、石块。从 1949 年起，这里成了博物馆，而且免费参观。\n\n往花园里看：他的大型青铜雕像正等着你。"], "La tour Montparnasse": ["蒙帕纳斯大楼", "摩天楼 · 1973 年", "巴黎唯一的摩天楼，它让其他摩天楼全都被禁止了。", "抬头看看深色的蒙帕纳斯大楼。", "你正站在蒙帕纳斯大楼脚下，它 1973 年建成，高 210 米。\n\n很长一段时间里，它是法国最高的建筑。可巴黎人讨厌它。它太让人震惊了，不久之后，巴黎市中心就禁止再建高楼。所以它孤零零地立在这里。巴黎人喜欢开玩笑说，看巴黎最好的地方就是这座楼的楼顶：因为那是唯一看不到它的地方。\n\n抬头往最高处看：顶上有一个全景观景台。"], "La Closerie des Lilas": ["丁香园咖啡馆", "咖啡馆 · 1847 年", "海明威每天上午在这里写作，身边守着拿破仑的一位元帅。", "看看丁香园的露天座位，还有门前的内伊元帅雕像。", "你正站在丁香园咖啡馆外面，它在 1847 年开业。\n\n它成了艺术家们的聚会地：画家塞尚、作家埃米尔·左拉，后来还有毕加索。20 世纪 20 年代，一位年轻、没钱的美国记者欧内斯特·海明威，每天上午来这里写作。他在《流动的盛宴》里写到了这里，那是一本关于他巴黎岁月的书。咖啡馆门前有一尊内伊元帅的雕像，他是拿破仑手下最出色的将军之一，1815 年在附近被枪决。\n\n看看露天座位：海明威就在那里写作。"], "Le pavillon des Indes": ["印度馆", "世界博览会 · 1878 年", "一座来自 1878 年世博会的印度宫殿，幸存在郊区的一座公园里。", "看看塞纳河边贝孔公园里那座雕花的木头亭子。", "你正在库尔布瓦，面前是一座雕花的小木亭，看起来像是从很远的地方来的。\n\n1878 年，巴黎举办了世界博览会，那是一场每个国家都展示自己最好东西的盛会。威尔士亲王，也就是后来的英国国王，让人建了两座展馆，用来展示当时还是英国殖民地的印度的艺术。博览会结束后，其中一座被暴风雨摧毁了。另一座最后来到了这里，幸存了下来。\n\n看看这些雕花的木头：郊区里的一小块印度。"], "La Grande Arche": ["新凯旋门", "建筑 · 约翰·奥托·冯·施普雷克尔森，1989 年", "一个边长 110 米的空心立方体，转了 6.33 度。", "抬头看看新凯旋门，然后转身望向远处的凯旋门。", "你正站在新凯旋门脚下，一个巨大的空心立方体。\n\n它在 1989 年落成，纪念法国大革命两百周年。它的建筑师是丹麦人约翰·奥托·冯·施普雷克尔森。每条边都是 110 米：巴黎圣母院都能放进去。它补全了一条大直线：从卢浮宫出发，沿着香榭丽舍大道，穿过凯旋门。它稍微转了一点角度，部分原因是下面有一座车站和一条高速公路。\n\n转过身：在尽头你能看到凯旋门。"], "Le CNIT": ["国家工业与技术中心", "建筑 · 卡默洛、德·马伊、泽尔弗斯，1958 年", "一座混凝土拱顶只靠三个点支撑，点与点相距 218 米。", "看看广场上国家工业与技术中心那巨大的三角形拱顶。", "你面前是国家工业与技术中心（CNIT），一座形状像巨大三角帆的建筑。\n\n它是拉德芳斯的第一座大建筑。1958 年，戴高乐将军为它揭幕。它原本是用来展示法国制造的机器的。它的混凝土屋顶只靠三个点支撑，点与点相距 218 米，中间没有一根柱子。\n\n看看屋顶：一个巨大的混凝土拱顶，立在三只脚上。"], "La Défense de Paris": ["保卫巴黎", "雕像 · 路易－埃内斯特·巴里亚斯，1883 年", "一尊 1883 年的雕像，给欧洲最大的商务区起了名字。", "在广场上找找那尊名为《保卫巴黎》的青铜像。", "你正在商务区拉德芳斯，面前是一尊青铜像。\n\n为什么叫“拉德芳斯”（意为“防御”）？1870 年，法国和普鲁士交战，巴黎被包围。人们在这里战斗，保卫城市。1883 年，人们在这里竖起这尊雕像，纪念保卫者们，它的名字就叫《保卫巴黎》。这个十字路口就以它命名；后来高楼来了，名字也留了下来。\n\n看看高楼之间的这尊雕像：是它给这片街区起了名字。"], "Le Castel Béranger": ["贝朗热城堡", "新艺术风格 · 埃克托尔·吉马尔，1898 年", "设计地铁入口的那位建筑师的早期杰作。", "走近贝朗热城堡那扇满是卷曲铁艺的大门。", "你正在第十六区的拉封丹街上，贝朗热城堡外面。\n\n它的建筑师埃克托尔·吉马尔是新艺术风格的大师，这种风格充满了受植物启发的曲线。巴黎地铁那些著名的入口，就是他设计的。1898 年左右，他在这里建了自己的第一栋大型公寓楼，并且亲手设计了一切：外墙、栏杆、墙纸，连门把手都不放过。\n\n看看这扇大门：它的金属曲线已经预示了后来的地铁入口。"], "La piscine Molitor": ["莫利托泳池", "装饰艺术风格 · 吕西安·波莱，1929 年", "人猿泰山为它开幕，比基尼在这里首次亮相。", "看看莫利托泳池那面黄色的装饰艺术风格外墙。", "你正站在莫利托泳池外面，它在 1929 年开放，设计得像一艘大邮轮，还带着舷窗。\n\n开幕那天，第一个跳下水的是约翰尼·韦斯默勒，奥运游泳冠军，后来在电影里演了人猿泰山。1946 年，设计师路易·雷阿尔在这里展示了一件小小的女式泳衣：比基尼。泳池在 1989 年关闭，涂鸦艺术家画满了它的墙，后来在 2014 年重新开放。\n\n看看这些舷窗和舷梯：感觉就像在一艘船上。"], "Le Corbusier chez lui": ["勒·柯布西耶的家", "莫利托公寓楼 · 1934 年", "勒·柯布西耶在这栋玻璃大楼的顶层住了三十年。", "抬头看看农热塞－科利街上这栋玻璃大楼的最上面两层。", "你面前是一栋玻璃外墙的公寓楼，建于 1934 年。\n\n它的建筑师勒·柯布西耶，是最著名的现代建筑师。他喜欢白墙和大窗户。他和堂兄一起建了这栋楼，正好在巴黎和布洛涅的交界处。他把最上面两层留给了自己。他每天上午在那里画画，一直住到 1965 年去世。\n\n看看楼顶：那就是他的公寓。"], "La mairie de Tony Garnier": ["托尼·加尼耶的市政厅", "装饰艺术风格 · 托尼·加尼耶，1934 年", "一位热爱建设的市长构想的超现代市政厅。", "看看布洛涅市政厅那块线条简洁的混凝土建筑。", "你正在巴黎西边的布洛涅，市政厅外面。\n\n20 世纪 20 和 30 年代，布洛涅发展得很快，有雷诺工厂，也有电影制片厂。市长想要一座现代化的城市。他请来里昂建筑师托尼·加尼耶设计新市政厅，这位建筑师热爱混凝土。它在 1934 年完工：一座线条笔直的简洁建筑，没有柱子，也没有镀金。\n\n看看这面简洁的外墙：一座现代城市的现代市政厅。"], "La place des Vosges": ["孚日广场", "皇家广场 · 1612 年", "维克多·雨果在这些拱廊下住了十六年。", "看看广场四周的红砖外墙和拱廊。", "你正在孚日广场上，巴黎最古老的一次性整体设计的广场。\n\n它在 1612 年落成，当时叫“皇家广场”。每栋房子都一模一样：红砖、白石、底下是拱廊。后来，《悲惨世界》的作者维克多·雨果从 1832 年到 1848 年住在 6 号。他的公寓现在是一座免费的博物馆。\n\n看看这些一模一样的外墙，再找找 6 号。"], "La girafe du roi": ["国王的长颈鹿", "动物园 · 植物园", "法国第一只长颈鹿，是从马赛一路走到这里的。", "看看植物园动物园的入口。", "你正在植物园里，靠近动物园，那是法国最古老的动物园。\n\n1826 年，埃及的统治者送给法国国王查理十世一只长颈鹿。法国从来没有人见过长颈鹿。她坐船到了马赛。她太高了，坐不进马车，于是一路走到了巴黎：900 公里。她的名字叫扎拉法。她在这里安了家，十多万巴黎人来看她。时尚界也为她疯狂：女人们把头发梳成“长颈鹿式”。\n\n看看这些围栏：扎拉法就住在这里。"], "Notre-Dame et le point zéro": ["巴黎圣母院和零点", "大教堂 · 1163–2024 年", "大教堂前，一块小牌子标出了法国所有道路的零点。", "从左岸的河堤上，看看巴黎圣母院的背面、尖塔和飞扶壁。", "你面前是巴黎圣母院，世界上最有名的大教堂，始建于 1163 年。\n\n2019 年 4 月 15 日，一场大火烧毁了它的屋顶，尖塔在电视直播中倒塌。经过五年的修复，它在 2024 年 12 月重新开放，换上了一座一模一样的新尖塔。在它前面的广场上，一块小牌子标出了“零点”：从巴黎出发的公路距离都是从那里算起的。\n\n看看大教堂前的地面：找找那颗小小的青铜星。"], "La fontaine Médicis": ["美第奇喷泉", "喷泉 · 约 1630 年", "一座皇家喷泉，为了给一条街让路，往后挪了三十米。", "看看那座岩洞形状的喷泉，还有偷看恋人的巨人。", "你正在卢森堡公园里，面前是一座岩洞形状的喷泉，位于一条长水池的尽头。\n\n1630 年左右，来自意大利佛罗伦萨的玛丽·德·美第奇王后让人建了它，让自己想起家乡。19 世纪，人们加上了希腊神话里的雕像：顶上，巨人波吕斐摩斯正偷看一对恋人，阿西斯和伽拉忒亚。阿西斯的结局可不太好。\n\n看看岩洞顶上：巨人正在盯着他们。注意，公园里不准骑自行车。"], "L'Arena de la Chapelle": ["拉夏佩尔体育馆", "奥运场馆 · SCAU 和 NP2F，2024 年", "2024 年奥运会在巴黎市内新建的唯一一座场馆。", "看看拉夏佩尔门那座巨大的阿迪达斯体育馆。", "你正站在拉夏佩尔体育馆外面，一座 2024 年开放的体育馆。\n\n它是为 2024 年奥运会在巴黎市内新建的唯一一座大型场馆。奥运那个夏天，这里举办了羽毛球和艺术体操比赛。建它的另一个目的，是给这个地区带来活力，这里长期被环城大道和铁轨与城市其他部分隔开。\n\n看看这座建筑：巴黎奥运会留给这个街区的一份礼物。"], "Le Centre aquatique olympique": ["奥运水上运动中心", "奥运场馆 · 2024 年", "2024 年巴黎奥运会唯一新建的大型永久场馆。", "看看水上运动中心巨大的木结构和弧形屋顶。", "你正站在奥运水上运动中心外面，对面就是法兰西体育场。\n\n它是为 2024 年奥运会建造的，也是那届奥运会唯一新建的大型永久体育场馆。为了减少污染，它的骨架用木头做成，屋顶是一大片弧形。跳水和水球比赛就在这里举行。如今，附近居民和学校的孩子们都来这里游泳。\n\n看看木头屋顶：它从一开始就是为奥运会之后的长久使用而设计的。"], "La basilique des rois": ["国王们的大教堂", "大教堂 · 叙热院长，1144 年", "哥特式建筑在这里诞生，法国国王们也长眠于此。", "看看圣但尼大教堂的正面，再进去看看巨大的彩色玻璃窗。", "你正站在圣但尼大教堂前面，就在巴黎北边。\n\n圣但尼是巴黎的第一位主教。传说大约公元 250 年，他在蒙马特被砍了头，然后双手捧着自己的头一路走到这里。人们在他的墓上建了一座教堂。1140 年左右，叙热院长用纤细的柱子和巨大的彩色玻璃窗重建了它：哥特式风格就这样诞生了。几乎所有法国国王都葬在这里。\n\n看看正面：在它后面，安息着历代国王。"], "Le canal Saint-Denis": ["圣但尼运河", "运河 · 1821 年", "沿水而行六公里，从塞纳河一直到拉维莱特。", "看看运河、船闸，还有通往巴黎的纤道。", "你正站在圣但尼运河边，它 1821 年开通。\n\n它把圣但尼的塞纳河和巴黎的拉维莱特水池连起来，全长六公里多一点。很长一段时间里，河边都是工厂：驳船运着煤、木材和各种货物。马匹在水边的小路上拉着船走。\n\n看看运河边的小路：当年马走过的地方，如今人们在骑自行车。"], "La colonne de Juillet": ["七月柱", "纪念碑 · 1840 年", "在这根柱子之前，这里本该有一头巨大的大象。", "在巴士底广场上，抬头看看柱子和顶上的金色精灵像。", "你正站在巴士底广场上，面前是一根 47 米高的柱子，顶上立着一个金色人像。\n\n它纪念的不是 1789 年的大革命，而是另一场革命。1830 年 7 月，巴黎人连续起义三天，赶走了国王查理十世。这三天被称为“光荣三日”。在战斗中牺牲的人就安葬在柱子下面。在建这根柱子之前，拿破仑曾想在这里建一座巨大的大象喷泉，但最后只做出了一个模型。\n\n看看顶上的金色人像：它歌颂的是自由。"], "Le faubourg des ébénistes": ["木匠们的老城郊", "手工艺 · 15 世纪以来", "在这里，木匠们可以不受行会规矩约束，自由干活。", "推开圣安托万郊区街上的一道门，看看工匠们的院子。", "你正走在圣安托万郊区街上，这是一条从巴士底延伸出去的长街。\n\n中世纪时，想在巴黎当工匠，就必须遵守本行会非常严格的规矩，还要交税。但在 15 世纪，国王路易十一允许住在这里的工匠自由工作。于是木匠和细木工，也就是做精美家具的人，纷纷搬来。几百年来，这一带成了家具之都。\n\n看看那些院子和通道：它们都是当年的作坊。"], "Le donjon de Vincennes": ["万塞讷城堡主塔", "王家城堡 · 1370 年", "欧洲最高的主塔，一位大哲学家曾被关在这里。", "抬头看看万塞讷主塔，也就是城堡那座高高的方塔。", "你正站在巴黎东边的万塞讷城堡外。城堡中央耸立着一座巨大的方塔：主塔。\n\n它大约在 1370 年、国王查理五世时期完工。高约五十米，是欧洲最高的城堡主塔。后来，它变成了监狱。1749 年，哲学家德尼·狄德罗因为思想太自由被关在这里。他的朋友让-雅克·卢梭还步行来探望他。\n\n看看这座主塔：狄德罗就被关在这些墙后面。"], "Le Train Bleu": ["蓝色列车餐厅", "车站餐厅 · 1900 年", "一家挂着 41 幅画的车站餐厅，为 1900 年世博会而建。", "在里昂火车站，顺着楼梯往上看蓝色列车餐厅的大窗户。", "你正站在里昂火车站，蓝色列车餐厅门外。\n\n它是为 1900 年世界博览会开张的。经营巴黎到地中海线路的铁路公司想要一家奢华的餐厅：金饰、水晶吊灯，还有 41 幅画，画的都是它的火车经过的城市，一直到蔚蓝海岸。餐厅的名字来自一列开往尼斯和摩纳哥的著名豪华列车。\n\n看看那些彩绘天花板：哪怕只喝杯咖啡也值得。"], "Le mariage de Picasso": ["毕加索的婚礼", "东正教大教堂 · 1861 年", "毕加索在金色洋葱顶下结婚的那一天。", "在达鲁街上，抬头看看大教堂的金色圆顶。", "你正站在圣亚历山大·涅夫斯基大教堂外面，它有好几个金色的洋葱顶。这是巴黎最大的俄罗斯教堂，1861 年落成。\n\n1918 年，画家巴勃罗·毕加索在这里和奥尔加·霍赫洛娃结婚。她是俄罗斯芭蕾舞团的舞者，那是当时最前卫的舞团。他的证婚人是三位有名的作家和诗人朋友：让·科克托、马克斯·雅各布和纪尧姆·阿波利奈尔。\n\n看看这些金色圆顶：毕加索就是从它们下面走过去结婚的。"], "L'Élysée avant les présidents": ["总统入住之前的爱丽舍宫", "总统府 · 1718–1722 年", "国王的宠姬，退位的皇帝，然后才是总统们。", "看看爱丽舍宫有人把守的大门，但别停下来。", "你正走在圣奥诺雷郊区街上，面前是一道有警察守卫的大门。门后就是爱丽舍宫。\n\n法国总统就在这里生活和工作。宫殿建于 18 世纪初，原本属于一位伯爵。1753 年，国王路易十五的宠姬蓬帕杜夫人买下了它。1815 年，滑铁卢战败后不久，拿破仑在这里签署了退位书：他放弃了权力。从 1873 年起，这里成了总统的住所。\n\n看看大门，但别逗留：警察不喜欢这样。"], "Le musée d'Ennery": ["德内里博物馆", "博物馆 · 克莱芒丝·德内里收藏，1908 年", "七千件亚洲珍品，藏在福煦大街的一座宅邸里。", "看看福煦大街上德内里博物馆的正面。", "你正走在福煦大街上，面前是一座小小的、很少有人知道的博物馆。\n\n1900 年前后，巴黎人对亚洲非常着迷。克莱芒丝·德内里是一位著名剧作家的妻子，她收藏了大约 7000 件来自中国和日本的物品。其中很多是根付，也就是挂在和服上的日本小雕件。她把房子和收藏都捐给了国家。博物馆于 1908 年开放。\n\n看看这面外墙：后面藏着成千上万件来自亚洲的小宝贝。"], "Le palais d'Iéna": ["耶拿宫", "建筑 · 奥古斯特·佩雷，1939 年", "一座混凝土宫殿，原本是用来展示水坝和桥梁的。", "看看耶拿宫的柱子：下面细，上面宽。", "你正站在耶拿宫前面，这是一座 1939 年建成的大型混凝土建筑。\n\n它的建筑师奥古斯特·佩雷证明了混凝土也可以很美，人们称他为“混凝土诗人”。这座楼原本要做一个展示大型工程的博物馆：桥梁、水坝。如今，这里是经济、社会和环境理事会，一个为政府提供建议的议事机构。\n\n看看这些柱子：下面细，上面宽，混凝土里还嵌着绿色和粉色的小石子。"], "Le palais Galliera": ["加列拉宫", "宫殿 · 莱昂·吉南，1878–1894 年", "一座为一批永远没来的收藏而建的宫殿。", "看看现代艺术博物馆对面的加列拉宫和它的花园。", "你正站在加列拉宫外面，这是一座坐落在花园里的石头宫殿。\n\n加列拉公爵夫人是一位极其富有的意大利贵族。1878 年，她建造了这座宫殿，用来展示她的画作，并把它们捐给巴黎。但在 1886 年，一项法律驱逐了法国前王室家族，其中就有她的朋友。她很生气，便把画留在了意大利。宫殿就这样空了下来。从 1977 年起，这里成了巴黎时装博物馆。\n\n看看这座华丽的宫殿：它为画作而建，最后却放满了裙子。"], "La maison Yves Saint Laurent": ["伊夫·圣罗兰之家", "博物馆 · 高级时装屋，1974–2002 年", "近三十年里，高级时装就在这些窗户后面诞生。", "看看马索大街 5 号那座宅邸的窗户。", "你正走在马索大街上，面前是一座优雅的城市宅邸。\n\n伊夫·圣罗兰是 20 世纪最伟大的时装设计师之一。正是他让女性穿上了吸烟装和裤子。1974 年，他把自己的时装屋设在这里。近三十年里，他的系列都在这些墙里诞生。从 2017 年起，这里成了博物馆：你可以看到他的工作室，就好像他刚刚出门一样。\n\n看看楼上的窗户：他就是在那里画设计图的。"], "Deyrolle": ["戴罗勒", "博物商店 · 1831 年以来", "蝴蝶、动物标本和教学挂图，1888 年起就在巴克街。", "看看巴克街 46 号戴罗勒的橱窗。", "你正走在巴克街上，面前是戴罗勒，一家独一无二的商店。\n\n它创立于 1831 年，最初是向博物馆出售动物标本、昆虫和贝壳。它那些画着植物和动物的大幅教学挂图，挂在一代又一代法国小学生的教室里。2008 年，一场大火几乎烧毁了一切。后来商店被重建了。\n\n上楼去看看：一头狮子、一头熊和一匹斑马正在等你。"], "Le Lutetia": ["吕特蒂亚酒店", "豪华酒店 · 1910 年", "为乐蓬马歇的顾客而建的豪华酒店，1945 年成了重逢之地。", "看看拉斯帕伊大道上吕特蒂亚酒店的新艺术风格正面和墙上的牌匾。", "你正走在拉斯帕伊大道上，面前是吕特蒂亚酒店，一家 1910 年开业的大酒店。\n\n它是由隔壁乐蓬马歇百货公司的老板们建造的，用来接待他们的富有顾客。第二次世界大战期间，德军占领巴黎，住进了这家酒店。1945 年战争结束时，吕特蒂亚接待了从纳粹集中营归来的被驱逐者。许多家庭拿着照片来到这里，希望能找到亲人。\n\n看看外墙上的牌匾：它记录着那些重逢。"], "La rue Gaston-Gallimard": ["加斯东-伽利玛街", "出版社 · 1929 年起在此", "一条以出版人名字重新命名的街。", "看看加斯东-伽利玛街的路牌和出版社的大门。", "你正走在加斯东-伽利玛街上，这是巴黎七区的一条小街。\n\n伽利玛是法国最有名的出版社，由加斯东·伽利玛于 1911 年创立。1929 年它搬到这里，后来这条街就以他的名字命名。它出版过马塞尔·普鲁斯特、阿尔贝·加缪、让-保罗·萨特，还有《小王子》的作者安托万·德·圣埃克苏佩里。\n\n看看这扇门：20 世纪一些最伟大的作家都曾从这里走过。"], "L'Institut de France": ["法兰西学会", "四国学院 · 路易·勒沃", "在这座穹顶下，坐着身穿绿袍的“不朽者”。", "面对艺术桥，看看法兰西学会的金色穹顶。", "你正站在塞纳河边，面前是一座带穹顶的建筑：法兰西学会。\n\n1661 年，在路易十四还是个孩子时替他治理法国的马扎然红衣主教，留下遗产建一所学校。从 1805 年起，这里成了法兰西学术院的所在地。它守护法语，并编写法语词典。它的四十位院士被称为“不朽者”。在重大仪式上，他们穿绣花绿袍，还佩剑。\n\n看看穹顶：不朽者们就坐在它下面。"], "Les Folies Bergère": ["女神游乐厅", "歌舞厅 · 1869 年", "马奈画过的吧台，还有刻在正面的舞女。", "看看女神游乐厅金色的装饰艺术风格正面和上面的舞女。", "你正站在女神游乐厅外面，这是巴黎最有名的歌舞厅，1869 年开业。歌舞厅就是表演歌曲、舞蹈和各种杂耍节目的剧场。\n\n画家爱德华·马奈把他最后一幅伟大作品的场景放在了这里：《女神游乐厅的吧台》，画中一个女招待站在柜台后，眼神忧伤。现在的正面建于 1926 年。上面那个金色舞女真有其人：她叫莉拉·尼科尔斯卡，身上几乎什么都没穿。\n\n看看正面那个金色舞女。"], "Le Bouillon Chartier": ["沙尔捷汤馆", "汤馆 · 1896 年", "这里至今还把账单写在纸桌布上。", "看看院子尽头沙尔捷汤馆的招牌。", "你正站在沙尔捷汤馆外面，这家餐厅 1896 年开业。\n\n19 世纪末，“汤馆”是给劳动者吃饭的简单、便宜的餐厅。沙尔捷兄弟开了这一家，餐厅大厅几乎没变过：镜子、吊灯、巨大的玻璃屋顶。熟客们放餐巾的小抽屉也还在。服务员至今仍把账单直接写在纸桌布上。\n\n看看排队的人：130 年过去了，大家还是来这里吃饭。"], "Le Jardin d'acclimatation": ["驯化园", "公园 · 拿破仑三世，1860 年", "巴黎最古老的游乐园，起初是个科学项目。", "看看森林边上驯化园的入口。", "你正站在驯化园外面，它在巴黎西边的布洛涅森林里。\n\n如今这里是儿童游乐园。但 1860 年拿破仑三世开设它时，有一个很严肃的想法。科学家们想看看来自世界各地的动物和植物能不能适应法国的气候，也就是“驯化”。慢慢地，这里成了巴黎家庭最爱的出游地。\n\n看看入口：一座诞生于科学实验的公园。"], "La Folie Saint-James": ["圣詹姆斯游乐园", "游乐建筑 · 弗朗索瓦-约瑟夫·贝朗热，1777 年", "一块十二米高的假山，一位破产金融家的任性之作。", "看看圣詹姆斯游乐园里的大岩石。", "你正在讷伊，圣詹姆斯游乐园里。\n\n18 世纪，非常有钱的人会建造“游乐园”：满是小建筑的花园，纯粹为了好玩。1772 年，王家海军的财务官克洛德·博达尔·德·圣詹姆斯买下了这片庄园。他想要一座奢华的花园。其中最疯狂的是一块巨大的假山，长 43 米，里面有浴室和瀑布。1787 年，他破产了。\n\n看看这块大岩石：正是它让他倾家荡产。"], "Le cimetière américain de Suresnes": ["叙雷讷美军公墓", "军人公墓 · 瓦莱里安山", "近 1600 名美国士兵长眠于此，面朝巴黎。", "看看瓦莱里安山坡上一排排白色十字架和小教堂。", "你正在叙雷讷的瓦莱里安山上，面前是一座美军公墓。\n\n第一次世界大战期间，从 1917 年起，美国士兵来到法国作战。很多人战死，再也没能回家。他们中近 1600 人长眠在这座公墓里，白色十字架排得整整齐齐。1919 年，美国总统伍德罗·威尔逊曾来这里发表演讲。\n\n看看这些白色十字架：它们都面朝巴黎。"], "La légende de Piaf": ["琵雅芙的传说", "纪念牌 · 美丽城街 72 号", "生在这栋房子的台阶上？美丽城最美的传说。", "找找美丽城街 72 号的纪念牌。", "你正走在美丽城街上，站在 72 号门前。这里有一块牌子讲的是艾迪特·琵雅芙。\n\n琵雅芙是法国香颂的伟大歌声，《玫瑰人生》就是她唱的。她的母亲在街头唱歌，父亲是杂技演员。牌子上说，她 1915 年就出生在这里的台阶上。其实她的出生证明上写的是附近的特农医院。可这个故事太适合她了，街坊们就一直留着它。\n\n看看这些台阶：琵雅芙的传说从这里开始。"], "Le Père-Lachaise": ["拉雪兹神父公墓", "公墓 · 1804 年", "得先把莫里哀搬进来，巴黎人才愿意葬在这里。", "看看拉雪兹神父公墓宏伟的大门。", "你正站在拉雪兹神父公墓外面，这是世界上参观人数最多的公墓。\n\n1804 年开放时，没人想要它：离市中心太远了。于是有人想了个主意。1817 年，两位著名作家的遗骸被迁到这里：剧作家莫里哀，和写寓言的拉封丹。从那以后，巴黎人都想葬在他们身边。如今，钢琴家肖邦、歌手艾迪特·琵雅芙，还有大门乐队的吉姆·莫里森都长眠于此。\n\n看看爬上山坡的小路：树荫下，一座由坟墓组成的小城。"], "L'Atelier des Lumières": ["光之工坊", "数字艺术 · 旧铸造厂，1835 年", "一座为海军服务的铸造厂，变成了巨大的投影大厅。", "看看光之工坊的老铸造厂大厅。", "你正站在光之工坊外面，这是巴黎十一区的一座老工厂。\n\n1835 年，两兄弟在这里开了一家铸造厂，为船和火车制造巨大的金属零件。工厂在 20 世纪关闭了。2018 年，它变成了一个数字艺术中心。梵高、克里姆特等大画家的作品被放大投影到墙上和地上，还配着音乐。\n\n看看这座老砖楼：在里面，你就像走进了画里。"], "Le Cirque d'Hiver": ["冬季马戏团", "马戏团 · 雅克·希托夫，1852 年", "空中飞人就是在这座屋顶下发明的。", "看看冬季马戏团那座二十条边的圆形建筑。", "你正站在冬季马戏团外面，这是一座有二十条边的圆形建筑。这是一座真正的马戏团，用石头建成。\n\n拿破仑三世在 1852 年为它揭幕。1859 年，体操运动员朱尔·莱奥塔尔在这里表演了历史上第一个空中飞人节目。他甚至把自己的名字留给了杂技演员穿的紧身衣。从 1934 年起，马戏世家布格里奥纳家族一直经营着这里。\n\n看看正面的马雕像：一眼就知道里面在演什么。"], "Le musée de Cluny": ["克吕尼博物馆", "国立中世纪博物馆", "古罗马浴场和《贵妇与独角兽》在同一个屋檐下。", "看看圣米歇尔大道拐角处的古罗马老墙，再看后面的哥特式宅邸。", "你正站在克吕尼博物馆外面，这是一座中世纪博物馆。\n\n它把两座非常古老的建筑合在了一起。首先是大约公元 200 年修建的古罗马浴场，那时巴黎还叫卢泰西亚。然后是一座 15 世纪的哥特式宅邸，是克吕尼修道院院长们的住所。它的镇馆之宝是一套大约 1500 年织成的六幅挂毯：《贵妇与独角兽》。\n\n看看那些古老的砖墙：它们是古罗马浴场留下的遗迹。"], "Le dôme du Val-de-Grâce": ["圣宠谷穹顶", "教堂 · 弗朗索瓦·芒萨尔，1645 年", "一位等了二十三年才有孩子的王后的穹顶。", "抬头看看圣宠谷的大穹顶。", "你正站在圣宠谷前面，这是一座有大穹顶的教堂。\n\n奥地利的安妮是一位西班牙公主。1615 年，她嫁给了法国国王路易十三。可二十三年里，他们一直没有孩子，这对王后来说是一场灾难。她许下诺言：如果生下儿子，就建一座宏伟的教堂。1638 年，未来的路易十四出生了。1645 年，七岁的他亲手奠下了第一块石头。\n\n看看这座穹顶：它是一位王后兑现的诺言。"], "La Grande Mosquée": ["巴黎大清真寺", "清真寺 · 1926 年", "为纪念为法国牺牲的穆斯林士兵而建。", "看看大清真寺的方形宣礼塔。", "你正站在巴黎大清真寺外面，它有一座 33 米高的方形宣礼塔。\n\n第一次世界大战期间，数万名穆斯林士兵为法国牺牲，他们大多来自北非。这座清真寺就是为了纪念他们而建的，1926 年落成。它的建筑风格借鉴了摩洛哥的清真寺。\n\n看看宣礼塔，然后走进茶室：在马赛克庭院里喝薄荷茶、吃点心。"], "Les Gobelins": ["戈布兰", "王家工场 · 1667 年", "这里至今仍像路易十四时代一样手工织挂毯。", "看看戈布兰大街上戈布兰工场的正面。", "你正站在戈布兰工场外面，在巴黎十三区。\n\n大约 1450 年，一位染匠让·戈布兰把作坊开在这里，旁边是一条如今已被埋在城市下面的小河。1667 年，国王路易十四的大臣柯尔贝尔把它变成了王家工场。人们在这里织出巨大的挂毯，用来装饰国王的宫殿，比如凡尔赛宫。\n\n看看作坊的大窗户：织工们至今仍在这里为国家手工织造，就像 350 年前一样。"], "Le cimetière de Levallois": ["勒瓦卢瓦公墓", "公墓 · 博丹街", "一位革命者、古斯塔夫·埃菲尔和莫里斯·拉威尔，同在一座公墓。", "看看博丹街上勒瓦卢瓦公墓的入口。", "你正站在勒瓦卢瓦公墓外面，这是一座安静的小公墓。\n\n长眠在这里的人彼此非常不同。路易丝·米歇尔是一位小学老师。1871 年，她参加了巴黎公社，也就是巴黎人的起义，后来被流放到新喀里多尼亚的苦役营。她就葬在这里。埃菲尔铁塔的工程师古斯塔夫·埃菲尔，还有《波莱罗》的作曲家莫里斯·拉威尔，也都葬在这里。\n\n看看这些小路：一位革命者、一位工程师和一位作曲家，永远做了邻居。"], "Le cimetière des chiens": ["狗公墓", "宠物公墓 · 1899 年", "任丁丁，还有救过四十人的圣伯纳犬巴里。", "看看入口旁边巴里的纪念碑。", "你正站在狗公墓外面，它位于阿涅尔的一座塞纳河小岛上。\n\n它 1899 年开放，是世界上最早的宠物公墓之一，由一位律师和记者玛格丽特·杜兰创办。入口处有一座纪念碑，纪念来自阿尔卑斯山的圣伯纳犬巴里。传说它救过四十个在雪中迷路的人。再往里走，安葬着任丁丁，美国电影里的明星狗。\n\n看看那些小坟墓：有狗、猫、马，还有主人们留下的深情话语。"], "Le château d'Asnières": ["阿涅尔城堡", "城堡 · 雅克·阿杜安-芒萨尔·德萨贡，1750–1752 年", "一位侯爵的城堡，出自凡尔赛宫建筑师的后人之手。", "看看俯瞰小城的阿涅尔城堡。", "你正在阿涅尔，就在巴黎外面，塞纳河边。你面前是一座 18 世纪的城堡。\n\n它大约建于 1750 年，主人是一位侯爵，国王路易十五一位大臣的儿子。它的建筑师是凡尔赛宫建造者的后人。后来，阿涅尔的河岸吸引了许多画家。乔治·修拉 1883 年在这里画了浴者，文森特·梵高 1887 年画了这里的桥。\n\n看看正面：一点凡尔赛的味道，带着乡间别墅的风格。"], "Le stade olympique de Colombes": ["科隆布奥林匹克体育场", "体育场 · 1924 年奥运会", "《烈火战车》里的体育场，在 2024 年奥运会重新登场。", "看看科隆布伊夫-杜马努瓦体育场的看台。", "你正站在巴黎西边的科隆布体育场外面。\n\n它是 1924 年奥运会的主体育场。两位英国跑者在这里赢得了金牌：哈罗德·亚伯拉罕斯赢了 100 米，埃里克·利德尔赢了 400 米。利德尔信仰非常虔诚，拒绝在星期天比赛。他们的故事被拍成了电影《烈火战车》，主题曲非常有名。体育场经过翻修，在 2024 年巴黎奥运会上再次使用。\n\n看看看台：两届奥运会之间，相隔一百年。"], "La Coupole": ["圆顶餐厅", "啤酒馆 · 1927 年", "整个蒙帕纳斯都来吃饭跳舞的装饰艺术风格啤酒馆。", "看看蒙帕纳斯大道上圆顶餐厅的大招牌。", "你正走在蒙帕纳斯大道上，面前是圆顶餐厅，一家 1927 年开业的巨大啤酒馆。\n\n20 世纪 20 年代，蒙帕纳斯是现代艺术的中心。来自世界各地的画家和作家住在这里。圆顶餐厅成了他们聚会的地方：画家毕加索、舞者约瑟芬·贝克、美国作家海明威。大厅里的柱子是当地艺术家画的。\n\n看看里面那些彩绘柱子：大厅几乎没有变过。"], "Le lion de Denfert": ["当费尔的狮子", "雕塑 · 奥古斯特·巴托尔迪", "广场中央的贝尔福狮子缩小版。", "看看当费尔-罗什罗广场中央那头卧着的青铜狮子。", "你正站在当费尔-罗什罗广场上，面前是一头巨大的青铜狮子。\n\n它是贝尔福一头巨型石狮的复制品。贝尔福是法国东部的一座城市。1870 年普法战争期间，贝尔福抵抗敌军整整 103 天。指挥守城的是当费尔-罗什罗上校，这座广场就以他的名字命名。雕塑家是奥古斯特·巴托尔迪，纽约自由女神像也是他的作品。\n\n看看狮子，再看看旁边的小楼：那里是地下墓穴的入口。"], "La piscine de la Butte-aux-Cailles": ["鹌鹑山泳池", "游泳池 · 路易·博尼耶，1924 年", "一座从 600 米深的井里引来温水的泳池。", "看看泳池的砖砌正面和保罗-魏尔伦广场上的泉水。", "你正在鹌鹑山，这是一个像小村庄一样的街区，有石子路和小酒馆。\n\n1893 年，人们在这里挖了一口非常深的井，大约 600 米深。井水会自己涌上来，而且是温的：25 度。多亏了它，这里建起了一座游泳池，1924 年开放，有一个巨大的弧形混凝土屋顶。在保罗-魏尔伦广场上，有一个泉水龙头流出的也是同样的水。\n\n看看这个泉水：附近居民会来这里灌瓶子。"], "L'aqueduc d'Arcueil": ["阿尔克伊渡槽", "渡槽 · 1613–1623 年与 1860 年代", "两座渡槽叠在一起，下面还有第三座古罗马渡槽的痕迹。", "看看横跨山谷的渡槽大拱门。", "你正在巴黎南边的阿尔克伊，面前是一座渡槽：一座用来运水的桥。\n\n其实这里有两座，一座叠在另一座上面。王后玛丽·德·美第奇想为她卢森堡宫的喷泉引水。她下令建造了第一座渡槽，1623 年完工。到了 1860 年代，人们又在它上面建了第二座更高的渡槽。\n\n看看这些拱门：下面是王后的，上面是 19 世纪的。"], "La Naumachie": ["海战池", "游乐建筑 · 沙特尔公爵的花园", "一圈立柱围着池塘，据说来自一位王后为国王修的小教堂。", "走到池塘边，看看这些半毁的立柱。", "这个被立柱环绕的池塘，是一位公爵花园里留下的最后几处景观之一。他是国王路易十六的表亲，花园里满是纯粹为了好玩而建的假废墟。\n\n最疯狂的是这些立柱：据说它们来自王后凯瑟琳·德·美第奇为丈夫国王亨利二世的陵墓修建的小教堂。\n\n看看这些立柱：它们曾守护一位国王。", "在这里成为公共公园之前，它是沙特尔公爵的私人花园，他是国王路易十六的表亲。18 世纪 70 年代，他想要一座每走一步都让人惊喜的花园。于是这里有了埃及金字塔、荷兰风车和假废墟。人们叫它“沙特尔的游乐园”。\n\n这个池塘是留下来的少数景观之一。但这些立柱比花园古老得多。\n\n两个世纪前，王后凯瑟琳·德·美第奇失去了丈夫国王亨利二世。她在圣但尼大教堂旁边为他修了一座小教堂，法国国王们都葬在那座大教堂里。1719 年，小教堂被拆了。\n\n据说它的立柱最后来到了这里，立在水边。它们原本是为守护一位国王而造的，如今却成了鸭子们的背景。"], "Musée Cernuschi": ["赛努奇博物馆", "收藏 · 委拉斯开兹大街", "一尊巨大的日本铜佛，漂洋过海来到蒙梭公园旁。", "看看栏杆后面的房子，里面有人等了一百多年。", "这些栏杆后面住过亨利·赛努奇，一位热爱亚洲的金融家。\n\n1871 年，他在日本发现了一尊巨大的铜佛，它的寺庙被烧毁，它却幸存了下来。他买下了它，把它一块块拆开，运回巴黎，在自己家里重新组装起来。\n\n看看这座房子：铜佛至今还在里面，而且博物馆免费参观。", "亨利·赛努奇是一位出生在米兰、后来定居巴黎的金融家。他很有钱，更重要的是，他非常好奇。1871 年，他和一位艺术评论家朋友出发去亚洲长途旅行。那时日本闭关几百年，才刚刚向世界打开大门。\n\n在东京的目黑区，他看到了一尊巨大的雕像：一尊铜佛。它的寺庙被烧毁了，佛像却幸存下来，已经在露天淋了一年雨。\n\n赛努奇买下了它。他让人把它一块块拆开、运走，再由巴黎的铜匠在他家里重新组装起来。\n\n这座房子后来变成了博物馆，佛像再也没有动过。它穿越了半个世界，最后落脚在离蒙梭公园几步远的地方。而去跟它打个招呼，是免费的。"], "Proust, 45 rue de Courcelles": ["普鲁斯特，库尔塞勒街 45 号", "作家故居 · 库尔塞勒街", "写出世界名著《追忆似水年华》的人，曾住在这栋楼里。", "找找库尔塞勒街 45 号那栋石头楼。", "《追忆似水年华》是世界上最有名的小说之一，它的作者马塞尔·普鲁斯特从 1900 年起住在这栋楼里。\n\n小时候，他每个星期四都在蒙梭公园里度过。就在附近一位画家的沙龙里，他走进了上流社会，后来又把这些人写进了书里。\n\n看看这栋楼：一部伟大的小说就在这里慢慢成形。", "他叫马塞尔·普鲁斯特。小时候，蒙梭公园就是他的游乐场。每个星期四下午，也就是当时学校放假的那天，他都在那里度过。\n\n1900 年，他们一家搬进了这栋高雅的楼。马塞尔快三十岁了，还没有出名。但他有一种天赋：什么都能注意到。\n\n就在附近，一位女画家玛德莱娜·勒梅尔在家里招待巴黎上流社会的精英：贵族、艺术家、作家。普鲁斯特也常去。他听着、看着，记住每一个手势、每一句话。\n\n多年以后，这些人全都变成了他那部巨著《追忆似水年华》里的人物。蒙梭公园的那个小男孩，就在离这里几条街的地方找到了他要写的东西。\n\n好了，最后一段路：回酒店吧。"]}}, "ar": {"ui": {"homeTitle": "اكتشف باريس\nانطلاقًا من مايفلاور", "homeSub": "جولات دائرية تنطلق من الفندق وتعود إليه، مع حكاية في كل محطة.", "start": "اكتشف", "kicker": "باريس، الدائرة الثامنة · جولات مع دليل", "step1": "الخطوة 1 من 3", "step2": "الخطوة 2 من 3", "modeQ": "كيف تحب أن تستكشف؟", "walk": "مشيًا", "run": "جريًا", "bike": "بالدراجة", "scoot": "بالسكوتر", "cont": "متابعة", "distQ": "ما المسافة التي تريدها؟", "catTitle": "اختر جولتك", "mustSee": "جولات لا تفوّتها", "moreIdeas": "أفكار أخرى", "byDist": "حسب المسافة", "allThemes": "الكل", "thArt": "الفن", "thLit": "الأدب", "thBelle": "الحقبة الجميلة والعروض", "thNature": "الحدائق والغابات", "thSeine": "نهر السين وضفافه", "thRoyal": "الملوك والتاريخ", "thModern": "باريس الحديثة", "distHint": "مدة تقديرية تشمل التوقف للاستماع إلى الحكايات.", "seeLoop": "اعرض جولتي", "yourLoop": "الخطوة 3 من 3 · جولتك", "stories": "حكايات", "story1": "حكاية", "lookLabel": "انظر إلى:", "steps": "محطات", "chooseLoop": "اختر جولتك مشيًا", "mapAltPre": "جولة مشيًا من الفندق: ", "swipe": "اسحب", "readStory": "اقرأ الحكاية", "zoomIn": "تكبير", "zoomOut": "تصغير", "fit": "اعرض الجولة كاملة", "parisAll": "اعرض باريس كلها", "lessStory": "العودة إلى النسخة القصيرة", "locMe": "أظهر موقعي", "locWait": "أبحث عن موقعك…", "locFar": "أنت لست في باريس: النقطة الزرقاء موضوعة عند الفندق", "locDenied": "تم رفض تحديد الموقع: النقطة الزرقاء موضوعة عند الفندق", "locNone": "تحديد الموقع غير متاح: موقع تجريبي", "startWalk": "ابدأ الجولة", "backMap": "العودة إلى الخريطة", "navNext": "المحطة التالية", "navGps": "موقعك المباشر", "navFar": "خارج المسار · تقدّم يدويًا", "navManual": "بدون تحديد الموقع · تقدّم يدويًا", "navWait": "أبحث عن موقعك…", "navSim": "عرض تجريبي", "navSimFar": "خارج المسار · عرض تجريبي", "navPause": "إيقاف مؤقت", "navPlay": "استئناف", "navSkip": "المحطة التالية", "navEnd": "إنهاء", "navSoon": "قريبًا", "navHere": "أنت هنا", "navGoOn": "تابع السير", "navReadNow": "استمع إلى الحكاية", "navStop": "محطة", "navRead": "اقرأ الحكاية", "navLater": "لاحقًا", "navDoneTitle": "عدت إلى الفندق", "navDoneText": "انتهت الجولة. شكرًا لأنك مشيت معنا!", "navRemaining": "متبقٍّ", "navRecenter": "توسيط الخريطة على موقعي", "next": "الحكاية التالية", "foStart": "الانطلاق", "byTheme": "حسب الموضوع", "otherRoutes": "جولات أخرى", "inKm": "بالكيلومتر", "inTime": "بالوقت", "allDist": "الكل", "catOne": "جولة", "catMany": "جولات", "catEmpty": "لا توجد جولة لهذا الاختيار.", "mustTag": "لا تفوّتها", "withAudio": "نص + صوت", "exLine": "لندن، تورينو، فلورنسا: الشوارع حول فندقك تحمل أسماء مدن أوروبية. إليك السبب.", "exKicker": "فندقك", "exTitle": "مايفلاور، شارع موسكو", "exText": "تخرج من الفندق وتمشي في شارع موسكو. انظر إلى لافتات الشوارع من حولك: لندن، تورينو، فلورنسا، سانت بطرسبرغ… هذه الأسماء ليست هنا صدفة.\n\nفي أوائل عشرينيات القرن التاسع عشر، تخيّل رجلان حيًّا جديدًا في هذا المكان: يوناس هاغرمان، مصرفي سويدي يعيش في باريس، وسيلفان مينيون، صانع أقفال الملك الذي صار رجل أعمال. في الوسط ساحة كبيرة، وحولها شوارع تحمل أسماء مدن أوروبية. وافقت السلطات على المشروع سنة 1826، فوُلد «حي أوروبا».\n\nلذلك، وأنت تمشي، تخيّل الخريطة ترتسم من حولك: كل شارع يبدو كبابٍ يفتح على مدينة أخرى. أنت ما زلت في باريس، لكن حيّك يأخذك منذ الآن في رحلة.\n\nفندق مايفلاور، الذي افتُتح سنة 2015 في مبنى على طراز هوسمان، هو نقطة انطلاقك في هذه النزهة عبر أوروبا متخيَّلة في قلب الدائرة الثامنة.", "exListen": "استمع إلى المقتطف", "exRead": "اقرأ حكاية فندقك", "exClose": "أغلق الحكاية", "startHint": "يرشدك محطة بعد محطة ويعرض عليك كل حكاية عند وصولك. زر «أظهر موقعي» يعرض مكانك على الخريطة فقط.", "askKicker": "قبل الانطلاق", "askTitle": "هل تريد تفعيل تحديد الموقع؟", "askWhy": "أثناء الجولة، يُستخدم موقعك لإظهارك على الخريطة ولتنبيهك عندما تقترب من محطة. بعدها تختار أنت: أن تستمع إلى الحكاية، أو تقرأها، أو تؤجّلها.", "askPrivacy": "يبقى موقعك على هاتفك. لا يُحفظ ولا يُرسل أبدًا، ويتوقف التتبّع عند نهاية الجولة.", "askYes": "فعّل وابدأ", "askNo": "ابدأ بدون تحديد الموقع", "askCancel": "إلغاء", "locBlocked": "هاتفك يمنع تحديد الموقع: تقدّم باستخدام «المحطة التالية».", "helpKicker": "تحديد الموقع ممنوع", "helpTitle": "هاتفك لا يشارك موقعك", "helpWhy": "لم يتمكن الدليل من طلب الإذن: تحديد الموقع معطّل لمتصفحك. لتفعيله:", "helpIos1": "الإعدادات › الخصوصية والأمن › خدمات الموقع: تشغيل.", "helpIos2": "في الأسفل، مواقع Safari (أو Chrome) › «أثناء استخدام التطبيق».", "helpIos3": "عد إلى هنا، واضغط «aA» بجانب العنوان › إعدادات الموقع › الموقع › اسأل.", "helpAnd1": "الإعدادات › الموقع: تشغيل.", "helpAnd2": "في Chrome، اضغط على القفل بجانب العنوان › الأذونات › الموقع › السماح.", "helpRetry": "حاول مرة أخرى", "helpClose": "تابع بدون تحديد الموقع", "navReadIt": "اقرأ", "cardAudio": "نص + صوت · ", "cardText": "نص فقط", "listenDur": "استمع · ", "mediaBoth": "للقراءة أو الاستماع · ", "mediaLong": "النسخة الطويلة ", "mediaText": "للقراءة فقط · الصوت غير متاح على هذا الجهاز", "readMore": "اقرأ المزيد · ", "listen": "استمع", "vPlay": "استمع", "vStop": "أوقف الصوت", "vc_butler": "كبير الخدم", "vc_titi": "ابن باريس", "vc_diva": "الديفا", "vAutoOn": "الصوت التلقائي: مفعّل", "vAutoOff": "الصوت التلقائي: متوقف", "vWho": "من يروي؟", "uMin": "دقيقة", "uH": "ساعة"}, "modes": {"bike": {"chooseLoop": "اختر جولتك بالدراجة", "startWalk": "ابدأ الجولة بالدراجة", "mapAltPre": "جولة بالدراجة من الفندق: ", "navDoneText": "انتهت الجولة. شكرًا لأنك ركبت معنا!"}, "run": {"chooseLoop": "اختر مسار الجري", "startWalk": "ابدأ الجري", "mapAltPre": "مسار جري من الفندق: ", "navDoneText": "انتهى الجري. أحسنت، وراحة طيبة!"}, "scoot": {"chooseLoop": "اختر جولتك بالسكوتر", "startWalk": "ابدأ الجولة بالسكوتر", "mapAltPre": "جولة بالسكوتر من الفندق: ", "navDoneText": "انتهت الجولة. شكرًا لأنك ركبت معنا!"}}, "intro": {"butler": "ها قد وصلنا. استرح، وسأحكي لك.", "titi": "هيا، توقّف! اسمع هذه، إنها رائعة.", "diva": "آه يا عزيزي… استمع جيدًا إلى هذه الحكاية."}, "loops": {"parc-monceau": ["حديقة مونسو، نزهة بين الفنانين", "تماثيل، وغرائب دوق شارتر، وكاموندو، وبروست."], "court-15": ["خمس عشرة دقيقة، جسر الرسامين", "جسر أوروبا، رسمه كايبوت ومونيه في السنة نفسها."], "court-20": ["من ساحة كليشي إلى مقبرة الفنانين", "مارشال دافع عن باريس، ثم داليدا وديغا وتروفو."], "court-30": ["الكنيسة الحديدية وجسر الرسامين", "كنيسة من حديد متنكّرة في حجر، ثم جسر كايبوت ومونيه."], "court-45": ["خمس وأربعون دقيقة، من كليشي إلى أثينا الجديدة", "الطاحونة الحمراء، وصالون شوبان وجورج صاند، وبيت رسّام، وقاعة عروض جوزفين بيكر."], "court-60": ["أقل من ساعة، من الترينيتيه إلى سان أوغستان", "أرغن أسطوري، وقبة متجر برانتان، وكنيسة لويس السادس عشر، وكنيسة من حديد."], "etoile-secrets": ["أسرار ساحة النجمة", "بلزاك، ومحظية شهيرة، وشغب موسيقي، وطائرة تحت قوس النصر."], "plaine-monceau-divas": ["نجمات سهل مونسو", "سارة برنار، وآل دوما الثلاثة، وقصر بُني من أجل حفلة راقصة."], "passy-balzac-eiffel": ["من بلزاك إلى برج إيفل", "قصر صنع التاريخ، وكاتب هارب، والجسر المفضّل لدى السينما."], "foch-bois-boulogne": ["جادة فوش وغابة بولونيا", "أعرض جادة في باريس، وآخر بيت لديبوسي، وكوخ سويسري على جزيرة."], "montmartre-boheme": ["مونمارتر البوهيمية", "الطاحونة الحمراء، وبيكاسو، وحمار «رسّام»، و311 «أحبك»."], "rive-droite-royale": ["الضفة اليمنى الملكية", "جسر ألكسندر الثالث، وبورصة التجارة، وعمود فاندوم، وكنيسة المادلين."], "course-monceau": ["لفّات في حديقة مونسو", "لفّتان بين البوابات المذهّبة وهرم وتمثال عملاق."], "course-cours-la-reine": ["من الشانزليزيه إلى كور لا رين", "ممشى ملكي، وتشرشل، وبروست الشاب، وخط نهاية طواف فرنسا."], "course-champ-de-mars": ["تروكاديرو وساحة مارس", "مدافع مائية، وجسر أُنقذ في اللحظة الأخيرة، واحتفال سنة 1790."], "course-muette": ["لا مويت ورانيلاغ", "جادة فيكتور هوغو، وأول طيران للإنسان، والانطباعية."], "course-grande-jatte": ["جزيرة لا غراند جات لسورا", "على طول السين، حيث رسم سورا يوم الأحد، وبنى إيفل برجه."], "course-berges-tuileries": ["ضفاف السين وحديقة التويلري", "طريق سريع صار حديقة، وحجارة الباستيل، ولوحات «زنابق الماء»."], "course-longchamp": ["لونشان وباغاتيل", "شلال من صخور مزيّفة، ودير مفقود، وقصر بُني بسبب رهان."], "course-allee-des-cygnes": ["ممرّ البجع وحديقة أندريه سيتروين", "جزيرة طويلة ونحيلة، وتمثال الحرية الصغير، وأبولينير، والمبنى الدائري."], "course-auteuil": ["الغابة، من أوتوي إلى رولان غاروس", "حديقة شكسبير، وحواجز أوتوي، والدفيئات، والملاعب الترابية."], "course-ile-saint-louis": ["الأرصفة حتى جزيرة سان لويس", "جسر الأقفال، وأقدم جسر، وجزيرة مصنوعة، وباعة الكتب."], "course-saint-ouen": ["أرصفة سانت أوان وباتينيول", "السين عند لوفالوا، وسوق البراغيث، وقاعة شعبية من فولاذ، وفيرلين."], "course-quartier-latin": ["سان جيرمان واللوكسمبورغ والحي اللاتيني", "مقهى أدبي، وخط الطول في سان سولبيس، وتمثال الحرية الصغير، وحلبة رومانية."], "course-villette": ["لا فيليت وقناة أورك", "حوض نابليون الكبير، والكرة الفولاذية، والمسالخ القديمة، وبوابة الملك الشمس."], "course-saint-cloud": ["حديقة سان كلو", "تلة المحكومين، وشلال «السيد»، وقصر اختفى، وباريس عند قدميك."], "course-bercy": ["بيرسي والأرصفة الشرقية", "ميناء في خندق ملكي، ووزارة قدماها في الماء، ونبيذ وكتب."], "course-montsouris": ["مونسوري وجنوب باريس", "سارتر وبوفوار، وعلامة خط الطول، ومدينة للعالم، وحديقة براسنس."], "course-vincennes": ["إلى فانسين عبر الممر الأخضر", "جسر صار حديقة، ونافورة فوّارة، وقصر سنة 1931، وبحيرة الجنرال."], "course-iles-ouest": ["جزر الغرب", "أرشيف الكوكب، وجزيرة رونو، وشراع شمسي، وبرج دوبوفيه."], "velo-rive-gauche": ["الضفة اليسرى، من الفن الحديث إلى الإمبراطورية", "جدار حيّ، وباب جريء، ونابليون، وباغودا متجر كبير."], "velo-nouvelle-athenes": ["أثينا الجديدة، حي الرسامين", "كايبوت، وشوبان عند شيفر، و«اللوريت»، وطائرة على سطح."], "velo-halles-beaubourg": ["من لي هال إلى بوبور", "عمود المنجّم، وتعميد موليير، وآلات تينغلي."], "velo-canal-buttes": ["قناة سان مارتان وتلال شومون", "مارشال، ومعبد مصري، وأرليتي، والبحيرة المخفية تحت الأوبرا."], "velo-montparnasse": ["مونبارناس الفنانين", "«خلية» شاغال، وسرداب باستور، وتمثال بلزاك المرفوض لرودان."], "velo-la-defense": ["حتى القوس الكبير", "كنيسة صغيرة لأمير، وقصر هندي، والتمثال الذي أعطى «لا ديفانس» اسمها."], "velo-annees-30": ["من العشرينيات الصاخبة إلى الثلاثينيات", "غيمار، وبيت لو كوربوزييه، وبيكيني مولِيتور، وطواف فرنسا في حديقة الأمراء."], "velo-grande-seine": ["حلقة السين الكبرى", "من فيكتور هوغو إلى زرافة الملك، ومن بيرسي إلى أورسيه، على طول الأرصفة."], "velo-saint-denis": ["سان دوني، من الملوك إلى الألعاب الأولمبية", "ملاعب 2024، وكاتدرائية الملوك، وقناة سان دوني."], "velo-vincennes": ["الباستيل وقصر فانسين", "فيل غافروش، ونجّارو الأثاث في الضاحية، وبرج الملوك."], "scooter-faubourg": ["ضاحية القصور", "زفاف بيكاسو، وقصر رئاسي، وكنيسة من حديد."], "scooter-chaillot": ["شايو، تلة المتاحف", "منحوتات النتسوكي، وفنون آسيا، وقصر من خرسانة، ومشغل أزياء راقية."], "scooter-rive-gauche": ["الضفة اليسرى للناشرين", "فراشات، ومتجر كبير، وفندق فخم، وناشر، وأعضاء الأكاديمية."], "scooter-music-halls": ["قاعات العروض في الدائرة التاسعة", "قبة زجاجية، وأرغن ميسيان، وعروض، وتماثيل شمعية، ومطعم «بويون»."], "scooter-ouest": ["نويي وسورين، حدائق وذاكرة", "حديقة إمبراطورية، وقصر نزوة لرجل مال، ومقبرة أمريكية تطل على باريس."], "scooter-belleville": ["بيلفيل ومينيلمونتان", "مستشفى هنري الرابع، وأسطورة بياف، ومقبرة بير لاشيز، وسيرك إمبراطوري."], "scooter-quartier-latin": ["من الحي اللاتيني إلى الغوبلان", "حمّامات رومانية، وقبة نذر ملكي، ومسجد، ومستشفى شاركو، وسجّاد جداري."], "scooter-asnieres": ["أنيير وكولومب، على الضفة الأخرى", "لويز ميشيل، ورين تين تين، وصناديق فويتون، والملعب الأولمبي لسنة 1924."], "scooter-sud": ["جنوبًا حتى القناة المائية", "مقهى «لا كوبول»، وأسد بلفور، ومسبح بمياه دافئة، وبيسيتر، وقناة ماري دو ميديسيس."]}, "stops": {"La Rotonde de Chartres": ["روتوندا شارتر", "عمارة · لودو، 1787", "هذا المعبد الصغير ذو الأعمدة يبدو زينةً للحديقة. لكنه كان في الحقيقة مركزًا للجمارك.", "انظر إلى المبنى الدائري المحاط بالأعمدة عند مدخل الحديقة.", "أنت عند مدخل حديقة مونسو، أمام مبنى صغير دائري تحيط به الأعمدة.\n\nيبدو كزينة في حديقة، لكنه كان مكتبًا للضرائب. في سنة 1787 أحاطت باريس نفسها بسور لفرض ضريبة على كل ما يدخل المدينة: النبيذ واللحم والخشب. صمّم المهندس كلود نيكولا لودو أكشاك الجباية هذه. هنا كان موظفو الضرائب يعملون في الطابق السفلي، وفي الأعلى صالون لدوق شارتر، صاحب الحديقة.\n\nانظر إلى الطابق العلوي: من هناك كان الدوق يتأمل حديقته."], "Le pont de l'Europe": ["جسر أوروبا", "رسم · كايبوت ومونيه، 1877", "رسّامان انطباعيان رسما هذا الجسر في السنة نفسها.", "انظر إلى العوارض الحديدية للجسر وإلى سكك محطة سان لازار تحته.", "أنت على جسر، وتحتك مباشرةً تمر قطارات محطة سان لازار. عندما انطلق من هنا أول قطار للركاب سنة 1837، كانت القطارات لا تزال حدثًا مدهشًا: تعمل بالبخار، وسط الضجيج والدخان.\n\nبعد بضعة عقود، اختار رسّام باريسي هو غوستاف كايبوت هذا الجسر موضوعًا للوحته. رسم ما رآه: العوارض الحديدية الكبيرة، والمارّة، وباريس الحديثة. اسم لوحته «جسر أوروبا». وفي سنة 1877 رسم صديقه كلود مونيه المحطة بدوره، بقطاراتها وبخارها. مونيه هو رسّام لوحات «زنابق الماء».\n\nانظر إلى العوارض من حولك: رسمها كايبوت قبل 150 سنة."], "Le maréchal Moncey": ["المارشال مونسي", "نصب تذكاري · أميديه دوبلمار", "مارشال في الستين تقريبًا دافع عن هذه البوابة من بوابات باريس.", "ارفع عينيك نحو التمثال الكبير في وسط ساحة كليشي.", "أنت في ساحة كليشي. قبل 200 سنة كانت باريس محاطة بسور، وكانت إحدى بواباته هنا.\n\nفي سنة 1814 كان الإمبراطور نابليون يخسر الحرب ضد أوروبا كلها تقريبًا، ووصلت الجيوش الروسية إلى باريس. كان يدافع عن هذه البوابة جنرال عجوز، المارشال مونسي، ومعه في الغالب متطوعون من أهل باريس. صمدوا طوال يوم 30 مارس. وفي المساء استسلمت باريس رغم ذلك، لكن صمودهم لم يُنسَ أبدًا.\n\nانظر إلى التمثال الكبير في وسط الساحة: إنه مونسي، والمرأة التي يحميها ترمز إلى باريس."], "Le cimetière de Montmartre": ["مقبرة مونمارتر", "مثوى الفنانين · منذ 1825", "داليدا وديغا وتروفو يرقدون في مقلع قديم، تحت جسر.", "انظر إلى جسر شارع كولانكور الذي يمر فوق القبور.", "وصلت إلى مقبرة مونمارتر. منذ سنة 1825 وهي في قاع مقلع حجارة قديم، منخفضة إلى درجة أن شارع كولانكور يمر فوق القبور على جسر.\n\nيرقد هنا كثير من الفنانين: الرسام إدغار ديغا، المشهور بلوحات راقصات الباليه؛ والكاتب ستاندال، مؤلف رواية «الأحمر والأسود»؛ والمخرج السينمائي فرانسوا تروفو؛ والمغنية داليدا، إحدى أكبر نجمات الأغنية الفرنسية، التي لا يخلو قبرها أبدًا من الزهور الطازجة.\n\nانظر إلى الجسر فوق المقبرة: السيارات تمر فوق القبور مباشرة."], "Saint-Augustin, l'église en fer": ["سان أوغستان، الكنيسة الحديدية", "كنيسة · فيكتور بالتار، 1860–1871", "كنيسة من حديد متنكّرة في حجر.", "انظر إلى القبة الكبيرة لكنيسة سان أوغستان في نهاية الجادة.", "أنت أمام كنيسة سان أوغستان. تبدو مبنية من الحجر، لكنها من الداخل من حديد.\n\nبُنيت بين 1860 و1871 على يد المهندس فيكتور بالتار، الذي كان قد شيّد من قبل الأجنحة الحديدية الكبيرة في «لي هال»، سوق باريس القديم للأغذية. في ذلك الوقت كان الحديد هو المادة الحديثة. استخدمه بالتار ليرفع القبة على أعمدة معدنية نحيلة. كانت من أوائل الكنائس الكبرى في باريس التي بُنيت بهذه الطريقة.\n\nانظر إلى القبة الكبيرة: إنها تقوم على هيكل من حديد."], "Le Moulin Rouge": ["الطاحونة الحمراء", "ملهى · 6 أكتوبر 1889", "كان في حديقته فيل عملاق.", "انظر إلى أذرع الطاحونة الحمراء في جادة كليشي.", "أنت أمام «مولان روج»، أي الطاحونة الحمراء، أشهر ملهى في العالم، بطاحونته ذات الأذرع الحمراء.\n\nافتُتح في 6 أكتوبر 1889، في السنة نفسها التي افتُتح فيها برج إيفل. وكان في حديقته فيل عملاق. هنا اشتهرت رقصة «الكان كان» الفرنسية: ترفع الراقصات أرجلهن عاليًا وتتطاير تنانيرهن الداخلية. الرسام هنري دو تولوز لوتريك، أحد روّاد المكان الدائمين، صمّم ملصقات الملهى ورسم راقصاته.\n\nانظر إلى أذرع الطاحونة: ما زالت تدور."], "Le salon d'Ary Scheffer": ["صالون آري شيفر", "متحف الحياة الرومانسية · ثلاثينيات القرن التاسع عشر", "كل يوم جمعة كان شوبان وجورج صاند ودولاكروا يأتون إلى هنا.", "اذهب إلى آخر الممر المرصوف، نحو البيت الصغير وحديقته.", "في آخر هذا الممر الصغير المرصوف بالحجارة يختبئ بيت له حديقة: إنه اليوم متحف الحياة الرومانسية.\n\nفي ثلاثينيات القرن التاسع عشر كان ملكًا للرسام آري شيفر. في أمسيات الجمعة كان يستقبل أصدقاءه الفنانين: عازف البيانو فريديريك شوبان ورفيقته الكاتبة جورج صاند التي كانت تسكن قريبًا، والرسام أوجين دولاكروا، والمؤلف الموسيقي فرانز ليست. كان هناك عزف على البيانو، وحديث عن الرسم وعن العاطفة.\n\nانظر إلى البيت في آخر الممر: إلى هنا كان شوبان يأتي ليعزف."], "La maison de Gustave Moreau": ["بيت غوستاف مورو", "متحف فنان · 1895", "رسّام حوّل بيته إلى متحف وهو ما زال حيًّا.", "انظر إلى واجهة بيت غوستاف مورو في شارع لا روشفوكو.", "أنت تمر أمام بيت الرسام غوستاف مورو، وهو اليوم متحف.\n\nفي أواخر القرن التاسع عشر كان مورو يرسم الأساطير والأحلام والمخلوقات الخيالية. وفي سنة 1895 اتخذ قرارًا غير مألوف: أن يحوّل بيته إلى متحف وهو ما زال حيًّا. بنى مرسمين كبيرين وعلّق لوحاته من الأرض حتى السقف. وعند وفاته ترك كل شيء للدولة: أكثر من 1000 لوحة وآلاف الرسومات.\n\nانظر إلى النوافذ الكبيرة في أعلى البيت: إنها نوافذ مرسميه."], "Le Casino de Paris": ["كازينو باريس", "قاعة عروض · شارع كليشي", "ميستانغيت وموريس شوفالييه، ثم جوزفين بيكر وأغنية «لي حبّان».", "انظر إلى واجهة كازينو باريس في شارع كليشي.", "أنت تمر أمام «كازينو باريس» في شارع كليشي. رغم اسمه، لا قمار فيه: إنه قاعة عروض، مسرح للأغاني والراقصات والريش.\n\nبعد الحرب العالمية الأولى حققت هنا أكبر نجوم ذلك الزمن نجاحًا كبيرًا، مثل ميستانغيت وموريس شوفالييه. وفي سنة 1931 غنّت هنا لأول مرة راقصة أمريكية صارت معبودة باريس، جوزفين بيكر، أغنية «لي حبّان»: «لي حبّان، بلدي وباريس». صارت الأغنية نشيدها.\n\nانظر إلى الواجهة: هنا وُلدت تلك الأغنية."], "La Trinité de Messiaen": ["كنيسة الترينيتيه، كنيسة ميسيان", "كنيسة · تيودور بالو، 1861–1867", "مؤلف موسيقي كبير عزف على الأرغن هنا واحدًا وستين عامًا.", "انظر إلى كنيسة الترينيتيه في نهاية شارع شوسيه دانتان.", "أنت أمام كنيسة الترينيتيه، أي الثالوث، التي بُنيت بين 1861 و1867.\n\nنجمها موسيقي: أوليفييه ميسيان، أحد أعظم المؤلفين الموسيقيين في القرن العشرين، وكان يعشق تغريد الطيور. عزف على أرغن هذه الكنيسة من 1931 حتى وفاته سنة 1992. واحد وستون عامًا! كل يوم أحد كان يرتجل، وكان موسيقيون يأتون من كل أنحاء العالم ليستمعوا إليه.\n\nانظر إلى الكنيسة: خلف واجهتها يوجد أرغن ميسيان."], "Le Printemps": ["برانتان", "متجر كبير · 1865", "تحت السقف قبة من الزجاج الملوّن تعود إلى سنة 1923.", "انظر إلى واجهة برانتان وقبابها في جادة هوسمان.", "أنت أمام «برانتان»، أحد المتجرين الكبيرين الشهيرين في جادة هوسمان، إلى جانب «غاليري لافاييت».\n\nافتُتح سنة 1865 وسرعان ما صار معبدًا للموضة. كنزه مخبّأ تحت السقف: قبة ضخمة من الزجاج الملوّن رُكّبت سنة 1923. خلال الحرب العالمية الثانية فُكّت لحمايتها من القصف، ثم أعادها إلى مكانها سنة 1972 حفيدُ الرجل الذي صنعها.\n\nانظر إلى القباب على السطح: القبة الزجاجية تحتها مباشرة."], "La chapelle expiatoire": ["كنيسة التكفير", "كنيسة صغيرة · بيير فونتين، 1816–1826", "هنا دُفن لويس السادس عشر وماري أنطوانيت في البداية.", "انظر إلى الكنيسة الصغيرة في عمق ساحة لويس السادس عشر.", "أمامك كنيسة صغيرة مختبئة في حديقة. إنها تروي فصلًا مظلمًا من تاريخ فرنسا.\n\nفي سنة 1789 قامت الثورة الفرنسية: ثار الشعب على الملك. وفي سنة 1793 أُعدم الملك لويس السادس عشر وزوجته الملكة ماري أنطوانيت بالمقصلة في ساحة الكونكورد. ورُميت جثتاهما في مقبرة صغيرة، هنا بالضبط. بعد عشرين سنة عاد ملك إلى الحكم: لويس الثامن عشر، شقيق لويس السادس عشر. فأمر باستخراج رفاتهما، ثم بنى هذه الكنيسة «للتكفير»، أي لطلب الغفران عن موتهما.\n\nانظر إلى الكنيسة في آخر الحديقة: هنا دُفن الملك والملكة أول مرة."], "La dernière maison de Balzac": ["آخر بيت لبلزاك", "كاتب · شارع بلزاك وشارع بيريه", "قضى بلزاك هنا سنواته الأخيرة، ثم هدمت بارونة بيته... تكريمًا له.", "انظر إلى القصر في 11 شارع بيريه والروتوندا في حديقته.", "أنت في شارع بلزاك. هنا كان آخر بيت لأونوريه دو بلزاك، أحد أعظم الروائيين الفرنسيين في القرن التاسع عشر.\n\nستة عشر عامًا أحبّ بلزاك كونتيسة بولندية هي إيفلينا هانسكا. كانا يعيشان بعيدين أحدهما عن الآخر، ولم يكن بينهما تقريبًا إلا الرسائل. في سنة 1846 اشترى بيتًا هنا وجهّزه لها. وفي سنة 1850 تزوّجا أخيرًا وسكنا فيه. وبعد خمسة أشهر مات بلزاك في هذا البيت.\n\nانظر إلى زاوية شارع بيريه: هناك كان بيت بلزاك."], "L'hôtel de la Païva": ["قصر لا بايفا", "محظية · 25 جادة الشانزليزيه", "أُنزلت من عربة في هذه الجادة، فأقسمت أن تعود... وأن تملك المكان.", "انظر إلى القصر في 25 جادة الشانزليزيه.", "أنت تمر أمام بيت جميل في 25 جادة الشانزليزيه: قصر لا بايفا.\n\nفي القرن التاسع عشر وُلدت شابة اسمها إستير لاخمان لعائلة فقيرة في موسكو، ووصلت إلى باريس لا تملك شيئًا. صارت محظية، أي امرأة تعيش من عشّاق أثرياء. وأصبحت أغناهن جميعًا، وعُرفت باسم «لا بايفا». تقول الحكاية إن رجلًا أنزلها يومًا من عربتها في هذه الجادة. فأقسمت أن تعود وتسكن هنا. وبعد عشر سنوات من البناء، ها هو بيتها.\n\nانظر إلى الواجهة: خلفها درج من حجر أصفر ثمين."], "La Flamme de la Liberté": ["شعلة الحرية", "نصب تذكاري · ساحة ديانا", "الجميع يظن أنها صُنعت من أجل الليدي ديانا، لكنها وصلت قبلها بثماني سنوات.", "انظر إلى الشعلة الذهبية في وسط الساحة، فوق النفق.", "أنت في ساحة ألما. هذه الشعلة الذهبية الكبيرة نسخة طبق الأصل من الشعلة التي يحملها تمثال الحرية في نيويورك.\n\nأهدتها صحيفة أمريكية إلى باريس سنة 1989، شكرًا للحرفيين الفرنسيين الذين رمّموا التمثال. وبعد ثماني سنوات، في 1997، توفيت الأميرة ديانا، الزوجة السابقة للأمير تشارلز ولي عهد إنجلترا، في حادث سيارة في النفق تحتها مباشرة. جاء الناس ليضعوا الزهور هنا. ومن دون أن يقرر أحد ذلك، صارت الشعلة نصبًا لذكراها.\n\nانظر إلى قاعدة الشعلة: كثيرًا ما تجد فيها زهورًا ورسائل لديانا."], "Un avion sous l'Arc": ["طائرة تحت القوس", "نصب تذكاري · قوس النصر", "في 7 أغسطس 1919، طار طيّار بطائرته من تحت هذا القوس.", "ارفع عينيك إلى قنطرة القوس الكبيرة، ثم انظر إلى الشعلة على الأرض.", "أنت أمام قوس النصر.\n\nفي سنة 1919 كانت الحرب العالمية الأولى قد انتهت للتو. وكانت باريس تستعد لاستعراض نصر كبير تحت القوس. لكن الطيارين الذين خاطروا بحياتهم في السماء أربع سنوات كان عليهم أن يسيروا على الأقدام. رأى طيار شاب اسمه شارل غودفروا أن هذا ظلم. وفي 7 أغسطس 1919 عبر بطائرته الصغيرة من تحت القوس، الذي لا يزيد عرضه كثيرًا عن ضعف عرض جناحيه. ولم ينل إلا إنذارًا بسيطًا.\n\nانظر إلى فتحة القوس: تخيّل طائرة تعبر من وسطها."], "Le Céramic Hôtel": ["فندق سيراميك", "الفن الحديث · 34 جادة فاغرام", "في جادة فاغرام، واجهة كاملة تبدو وكأنها نمت مثل نبتة.", "ارفع عينيك إلى الواجهة الخزفية البنية والخضراء في 34 جادة فاغرام.", "أنت في جادة فاغرام، أمام واجهة مغطاة بأوراق وزهور من الخزف.\n\nفي سنة 1904 كان «الفن الحديث» على الموضة، وهو أسلوب يقلّد انحناءات النباتات. بنى المهندس جول لافيروت هذا المبنى، وغطّاه فنان خزف بزخارف بلون التراب والطحالب. وفي السنة التالية فاز بمسابقة أجمل واجهة في باريس.\n\nانظر إلى المدخل: يبدو المبنى وكأنه نما مثل نبتة."], "Chez Sarah Bernhardt": ["عند سارة برنار", "نجمة · جادة بيرير", "أول نجمة عالمية كانت تنام أحيانًا في تابوت، وتعيش مع قطط كبيرة.", "انظر إلى المباني على طول جادة بيرير، حيث قضت سنواتها الأخيرة.", "أنت في جادة بيرير، أمام البيت الذي قضت فيه سارة برنار سنواتها الأخيرة.\n\nكانت سارة برنار ممثلة مسرح في أواخر القرن التاسع عشر. وقبل أن توجد السينما أصلًا، كانت نجمة في العالم كله، من باريس إلى نيويورك. كانت تحب أن تصدم الناس: عاشت في بيتها حيوانات برية، واحتفظت بهيكل عظمي في غرفة نومها، والتُقطت لها صور وهي مستلقية في تابوت.\n\nانظر إلى النوافذ: خلفها عاشت أكبر نجمة في زمانها."], "Les lecteurs de Dumas": ["قرّاء دوما", "نصب تذكاري · غوستاف دوريه، 1883", "عند قدمي ألكسندر دوما، ثلاثة باريسيين يقرأون إحدى رواياته منذ 1883.", "دُر حول تمثال دوما الجالس: دارتانيان على ظهر القاعدة.", "أنت في ساحة الجنرال كاترو، أمام رجل جالس: ألكسندر دوما.\n\nكتب دوما في القرن التاسع عشر «الفرسان الثلاثة» و«الكونت دي مونت كريستو». كان الجميع يقرأون رواياته المليئة بالمغامرات. وهذا ما يصوّره التمثال: عند قدميه امرأة وعامل وطالب يقرأون أحد كتبه. وخلفه يقف دارتانيان، فارسه، حارسًا.\n\nانظر خلف القاعدة: دارتانيان وسيفه في يده."], "Le château du banquier": ["قصر المصرفي", "عصر النهضة الجديد · قصر غايار", "مصرفي اشترى لنفسه نسخة من قصر في وادي اللوار، وافتتحه مع 2000 ضيف.", "انظر إلى القصر المبني من الآجر والحجر بسقوفه المدبّبة في ساحة الجنرال كاترو.", "أنت أمام قصر حقيقي، في وسط باريس.\n\nكان إميل غايار مصرفيًا ثريًا جدًا يعشق عصر النهضة، زمن ملوك القرن السادس عشر. فأمر ببناء نسخة من قصر بلوا، وهو قصر شهير في وادي اللوار. وفي الافتتاح سنة 1885 أقام حفلة تنكرية لأكثر من 2000 ضيف، وتنكّر هو نفسه في زيّ الملك هنري الثاني.\n\nانظر إلى الأبراج الصغيرة والسقوف المدبّبة: قصر من وادي اللوار، على بعد خطوات من حديقة مونسو."], "Le Majestic": ["الماجستيك", "فندق فخم · 19 جادة كليبر", "في هذا الفندق تناول بروست العشاء مع جويس، ووُضع حدّ لحرب فيتنام.", "انظر إلى الواجهة الفخمة لفندق «ذا بنينسولا» في 19 جادة كليبر.", "أنت تمر أمام فندق فخم في جادة كليبر. اسمه اليوم «ذا بنينسولا»، وكان اسمه من قبل «الماجستيك».\n\nفي سنة 1922 أقيم هنا عشاء جمع أربعة عمالقة في الفن: الكاتب مارسيل بروست، والكاتب الإيرلندي جيمس جويس، والمؤلف الموسيقي إيغور سترافينسكي، والرسام بابلو بيكاسو. وخلال الحرب العالمية الثانية كان مقرًّا لقيادة الجيش الألماني. وفي سنة 1973 وُقّعت هنا اتفاقيات السلام التي أخرجت الأمريكيين من حرب فيتنام.\n\nانظر إلى الواجهة الكبيرة: هذا المبنى شهد قرنًا من التاريخ."], "Le parvis des droits de l'homme": ["ساحة حقوق الإنسان", "إطلالة · تروكاديرو", "على هذه الشرفة التُقطت أسوأ صورة وأجمل صورة في القرن العشرين.", "امشِ إلى وسط الشرفة، مواجهًا برج إيفل، بين جناحي القصر.", "أنت على ساحة تروكاديرو الواسعة، بين جناحي قصر شايو. وعلى الضفة الأخرى من السين يقف برج إيفل.\n\nفي 23 يونيو 1940 كانت فرنسا قد خسرت للتو الحرب أمام ألمانيا. زار هتلر باريس مرة واحدة فقط، في الصباح الباكر جدًا، والتُقطت له صورة هنا بالضبط، وبرج إيفل خلفه. وبعد ثماني سنوات، في 1948، كانت الحرب قد انتهت. اجتمعت الأمم المتحدة في هذا القصر نفسه واعتمدت الإعلان العالمي لحقوق الإنسان: نصّ يقول إن جميع الناس يولدون أحرارًا ومتساوين.\n\nانظر إلى الساحة تحت قدميك: سُمّيت ساحة حقوق الإنسان بسبب هذا النص."], "Le cimetière de Passy": ["مقبرة باسي", "مثوى الفنانين · منذ 1820", "مانيه وبيرت موريزو وديبوسي يرقدون هنا، في ظل برج إيفل.", "ابحث عن مدخل مقبرة باسي الصغيرة في أعلى الدرج.", "أنت تمر أمام مقبرة باسي، وهي مقبرة صغيرة على تلة، ومن أرقى مقابر باريس.\n\nيرقد هنا رسّامان كبيران من القرن التاسع عشر: إدوار مانيه، وإلى جانبه مباشرة بيرت موريزو، زوجة أخيه، وإحدى النساء القليلات في جماعة الانطباعيين. ويرقد هنا أيضًا المؤلف الموسيقي كلود ديبوسي، صاحب مقطوعة «ضوء القمر». كان يريد أن يُدفن هنا، فنُقل إليها بعد سنة من وفاته.\n\nانظر إلى مدخل المقبرة، بجانب تروكاديرو مباشرة."], "Le pont de Bir-Hakeim": ["جسر بير حكيم", "جسر · 1905، نجم سينمائي", "مارلون براندو تجوّل هنا في «التانغو الأخير»، وديكابريو رآه ينطوي في «إنسبشن».", "امشِ تحت رواق الأعمدة الحديدية للجسر، مواجهًا برج إيفل.", "أنت على جسر من طابقين: المترو في الأعلى، والناس والسيارات في الأسفل.\n\nسُمّي على اسم بير حكيم، وهو موقع في الصحراء الليبية. في سنة 1942، خلال الحرب العالمية الثانية، صمد هناك جنود فرنسيون موالون للجنرال ديغول أيامًا أمام الجيش الألماني. أما الجسر نفسه فيعود إلى سنة 1905. بأعمدته الحديدية وإطلالته على برج إيفل صار موقعًا للتصوير السينمائي: تراه في «التانغو الأخير في باريس» وفي «إنسبشن» مع ليوناردو ديكابريو.\n\nانظر إلى الأعمدة الحديدية تحت المترو: هذه هي اللقطة التي يحبها المخرجون."], "L'avenue de l'Impératrice": ["جادة الإمبراطورة", "جادة · 1854", "عرضها 120 مترًا: أراد نابليون الثالث جادة تليق بإمبراطورة.", "تأمّل عرض الجادة، مع مروجها الواسعة على الجانبين.", "أنت في جادة فوش. بمروجها يبلغ عرضها 120 مترًا: إنها أعرض جادة في باريس.\n\nافتتحها الإمبراطور نابليون الثالث سنة 1854 لتقود إلى غابة بولونيا. وسمّاها أولًا باسم زوجته الإمبراطورة أوجيني. إنها من أغلى العناوين في العالم: سكن فيها قطب الملاحة اليوناني أوناسيس والمغني برنس.\n\nانظر إلى الواجهات الفخمة: خلفها بعض أفخم الشقق في باريس."], "La dernière maison de Debussy": ["آخر بيت لديبوسي", "موسيقى · 24 ساحة جادة فوش", "مات ديبوسي هنا بينما كانت المدافع الألمانية تقصف باريس.", "ألقِ نظرة على الساحة الخاصة في 24 ساحة جادة فوش.", "أنت تمر أمام ساحة صغيرة هادئة بجانب جادة فوش.\n\nعاش هنا منذ سنة 1905 كلود ديبوسي، المؤلف الموسيقي الفرنسي صاحب مقطوعة «ضوء القمر». هنا كتب بعضًا من أكثر مقطوعات البيانو عزفًا في العالم. ومات هنا في مارس 1918، خلال الحرب العالمية الأولى، بينما كانت المدافع الألمانية تقصف باريس. وبسبب الحرب، لم يمشِ خلف نعشه إلا قليلون.\n\nانظر إلى الساحة: هنا عاش ديبوسي."], "Le lac et le chalet des Îles": ["البحيرة وكوخ الجزر", "غابة بولونيا · الإمبراطورية الثانية", "وُلدت هذه البحيرة من خطأ في الحساب، وجاء هذا الكوخ من سويسرا.", "انظر إلى الجزيرة في البحيرة والكوخ الخشبي الذي تصل إليه بالقارب.", "أنت تجري بجانب بحيرة كبيرة في غابة بولونيا.\n\nعاش الإمبراطور نابليون الثالث في المنفى في لندن، وأحب حديقة هايد بارك ونهرها. فأراد الشيء نفسه هنا. لكن مصمم الحدائق الأول أخطأ في حساباته: لم تكن المياه تجري. فحُوّلت إلى بحيرتين فيهما جزيرتان. وعلى إحداهما أقام الإمبراطور كوخًا سويسريًا حقيقيًا.\n\nانظر إلى الجزيرة: الكوخ ما زال هناك، وما زلت تصل إليه بقارب التجديف."], "Le vaisseau de Gehry": ["سفينة غيري", "عمارة · مؤسسة لويس فويتون، 2014", "سحابة من زجاج حطّت على طرف غابة بولونيا.", "انظر إلى الأشرعة الزجاجية الكبيرة لمؤسسة لويس فويتون.", "وصلت إلى مبنى يشبه سفينة شراعية كبيرة من زجاج: مؤسسة لويس فويتون، متحف للفن الحديث افتُتح سنة 2014.\n\nمهندسه الأمريكي فرانك غيري من أشهر المهندسين في العالم. كان قد بنى من قبل متحف غوغنهايم في بلباو بإسبانيا. وهنا لفّ المبنى باثني عشر شراعًا كبيرًا من الزجاج المنحني.\n\nانظر إلى الأشرعة الزجاجية: كأنها سفينة مستعدة للإبحار."], "Le moulin de la Galette": ["طاحونة لا غاليت", "قاعة رقص · رونوار، 1876", "كل أحد كان الناس يرقصون هنا تحت الأشجار. وحوّل رونوار المشهد إلى تحفة.", "ارفع عينيك إلى الطاحونة الخشبية عند زاوية شارع لوبيك.", "أنت تمر أمام طاحونة هواء في قلب مونمارتر.\n\nكانت مونمارتر في الماضي قرية تغطيها طواحين الهواء. وخطرت للطحّانين فكرة: أن يبيعوا المتنزهين قطعة بسكويت وكأس نبيذ، ثم أن يفتحوا قاعة رقص. في سنة 1876 رسم هنا الرسام أوغست رونوار أصدقاءه وهم يرقصون تحت الأشجار. هذه اللوحة، «حفلة راقصة في طاحونة لا غاليت»، هي اليوم من أشهر اللوحات في العالم.\n\nانظر إلى الطاحونة فوق الشارع: إنها نفسها التي في اللوحة."], "Le Sacré-Cœur": ["الساكريه كور", "كاتدرائية · 1875–1919", "كلما أمطرت، ازدادت بياضًا.", "ارفع عينيك إلى القباب البيضاء، ثم إلى برج الأجراس المربع في الخلف.", "وصلت إلى «الساكريه كور»، أي القلب المقدس، الكاتدرائية البيضاء الكبيرة التي تراها من كل أنحاء باريس.\n\nبدأ بناؤها سنة 1875 واستغرق أكثر من أربعين عامًا، ولم تكتمل إلا سنة 1919. سرّها في حجارتها: عندما تمطر، تصبح أكثر بياضًا. وفي برجها جرس ضخم اسمه «لا سافويارد»، يزن قرابة 20 طنًّا.\n\nانظر خلفك: باريس كلها عند قدميك."], "Le Bateau-Lavoir": ["الباتو لافوار", "مراسم · ساحة إميل غودو", "في هذا الكوخ بلا تدفئة، اخترع بيكاسو الفن الحديث.", "انظر إلى الواجهة الزجاجية للباتو لافوار في ساحة إميل غودو.", "أنت في ساحة صغيرة في مونمارتر. هنا كان يقوم مبنى خشبي قديم من المراسم بلا تدفئة، يسمّونه «الباتو لافوار»، أي قارب الغسيل.\n\nفي سنة 1904 سكنه رسّام إسباني شاب مفلس في الثالثة والعشرين: بابلو بيكاسو. وهنا رسم سنة 1907 لوحة «آنسات أفينيون»، اللوحة التي غيّرت تاريخ الفن. ومع صديقه جورج براك اخترع التكعيبية: رسم يكسر الأشكال إلى قطع هندسية.\n\nانظر إلى الواجهة الصغيرة على الساحة: من هنا بدأ الفن الحديث."], "Le pont Alexandre-III": ["جسر ألكسندر الثالث", "جسر · 1896–1900", "وضع القيصر الحجر الأول، وجُعل الجسر منبسطًا حتى لا يحجب الإنفاليد.", "انظر إلى التماثيل الذهبية فوق الأعمدة، ثم إلى قبة الإنفاليد في الطرف الآخر.", "أنت على جسر ألكسندر الثالث، أكثر جسور باريس ذهبًا.\n\nفي أواخر القرن التاسع عشر صارت فرنسا وروسيا حليفتين. وللاحتفال بذلك سُمّي الجسر باسم القيصر ألكسندر الثالث، إمبراطور روسيا. وفي سنة 1896 وضع ابنه القيصر نيقولا الثاني الحجر الأول. كان على القوارب أن تمر تحته، من دون أن يحجب الجسر منظر قبة الإنفاليد. لذلك بنى المهندسون قوسًا واحدًا من الفولاذ، منبسطًا جدًا.\n\nانظر نحو الإنفاليد: صُمّم الجسر حتى لا يخفي تلك القبة الذهبية."], "La Bourse de Commerce": ["بورصة التجارة", "متحف · 1767 و2021", "ملكة، ثم قمح، ثم فن: هذا المبنى الدائري عاش ثلاث حيوات.", "انظر إلى العمود الملتصق بالمبنى، ثم ارفع عينيك إلى القبة.", "أنت أمام بورصة التجارة، المبنى الدائري الكبير بجوار «لي هال». أكثر من قرنين كان الناس يتاجرون هنا بالقمح، ثم بسلع من العالم كله.\n\nمنذ سنة 2021 صار متحفًا لفن اليوم. يعرض مجموعة فرانسوا بينو، رجل الأعمال الفرنسي الذي جمع ثروته من الماركات الفاخرة، ويشتري منذ خمسين عامًا أعمال فنانين أحياء. ولإنشاء المتحف أدخل المهندس الياباني تاداو أندو أسطوانة ضخمة من الخرسانة إلى الداخل، من دون أن يمسّ المبنى القديم.\n\nانظر إلى العمود الملتصق بالمبنى: إنه كل ما بقي من قصر ملكة بُني قبل أكثر من 450 سنة."], "La colonne Vendôme": ["عمود فاندوم", "نصب تذكاري · أُسقط سنة 1871", "حُكم على رسّام بأن يدفع تكاليف إعادة بناء هذا العمود.", "ارفع عينيك إلى العمود البرونزي وتمثال نابليون في أعلاه.", "أنت في ساحة فاندوم، موطن كبار صائغي المجوهرات. في وسطها عمود برونزي شاهق.\n\nأُقيم احتفالًا بانتصارات نابليون، من معدن مدافع غُنمت من العدو. وفي سنة 1871 ثار الباريسيون على الحكومة: إنها «الكومونة». فأسقطوا العمود باعتباره رمزًا للإمبراطور. وكان الرسام غوستاف كوربيه قد اقترح تفكيكه. وبعد فشل الثورة حُكم عليه بدفع تكاليف إعادة بنائه. فهرب إلى سويسرا ومات من دون أن يدفع.\n\nارفع عينيك: أُعيد العمود إلى مكانه، ونابليون في أعلاه."], "La Madeleine": ["كنيسة المادلين", "كنيسة · وداع شوبان", "في جنازة شوبان، اضطرت المغنيات إلى الاختباء خلف ستارة.", "انظر إلى أعمدة المادلين الضخمة: إنها تشبه معبدًا يونانيًا تمامًا.", "أنت أمام المادلين. تبدو كمعبد يوناني، لكنها كنيسة.\n\nأرادها نابليون معبدًا لمجد جيشه. وبعده صارت كنيسة. في سنة 1849 مات عازف البيانو فريديريك شوبان في باريس. وجاء قرابة 3000 شخص إلى هنا لحضور جنازته. وعُزف «قدّاس الموتى» لموزارت، كما طلب. لكن في ذلك الوقت لم يكن مسموحًا للنساء بالغناء في الكنيسة: فغنّت المغنيات مختبئات خلف ستارة سوداء.\n\nانظر إلى الأعمدة الضخمة: هذا هو المعبد الذي كان نابليون يتخيّله."], "Les grilles dorées": ["البوابات المذهّبة", "أعمال حديدية · غابرييل دافيو، 1861", "هذه البوابات السوداء والذهبية هي ترحيب باريس الأنيقة في عهد نابليون الثالث.", "انظر إلى البوابات الكبيرة السوداء والذهبية عند مدخل الحديقة.", "وصلت إلى بوابات حديقة مونسو الكبيرة، السوداء والذهبية.\n\nنحو سنة 1860 غيّر الإمبراطور نابليون الثالث وحاكمه البارون هوسمان باريس كلها: جادات واسعة، ومبانٍ من الحجر، وحدائق. اشترت المدينة هذه الأرض من عائلة أمراء. بيع نصفها لمصرفيين بنوا فيه قصورًا فاخرة. وصار النصف الآخر هذه الحديقة العامة التي افتُتحت سنة 1861.\n\nانظر إلى البوابات المذهّبة: إنها ترحّب بك في باريس نابليون الثالث الأنيقة."], "La pyramide": ["الهرم", "قصر نزوة · كارمونتيل، سبعينيات القرن الثامن عشر", "هرم مصري في وسط باريس، وعمره 250 سنة.", "ابحث عن الهرم الحجري الصغير المختبئ نصفه بين الخضرة في الجهة الشمالية.", "أنت في حديقة مونسو. قبل 250 سنة كانت الحديقة الخاصة لأمير، دوق شارتر، ابن عم الملك.\n\nفي سبعينيات القرن الثامن عشر صمّم له الفنان كارمونتيل حديقة مليئة بالمفاجآت: طاحونة هولندية، وخيمة، ومعبد مهدّم… وهرم مصري صغير. اختفى كل ذلك تقريبًا منذ ذلك الحين. إلا الهرم.\n\nانظر بين الأشجار: الهرم الصغير ما زال هناك."], "La géante de la rue de Chazelles": ["عملاقة شارع شازيل", "مشغل غاجيه غوتييه · 1881–1884", "تمثال الحرية ارتفع أولًا فوق أسطح هذا الشارع الصغير.", "انظر إلى رقم 25 في شارع شازيل، وتخيّل عملاقة فوق الأسطح.", "أنت في شارع شازيل، شارع صغير هادئ. ومع ذلك هنا وُلد تمثال الحرية، رمز نيويورك.\n\nكان هدية من فرنسا إلى الولايات المتحدة. بناه النحات الفرنسي أوغست بارتولدي في مشغل في الرقم 25. في داخله هيكل من حديد صمّمه المهندس غوستاف إيفل، صاحب البرج. وحتى سنة 1884 كان التمثال يرتفع فوق الأسطح: كان الجيران يرون رأسه من نوافذهم. ثم فُكّك وشُحن إلى نيويورك في أكثر من 200 صندوق.\n\nانظر فوق الأسطح: تخيّل رأسًا بطول 5 أمتار يطلّ من هناك."], "Le Cours la Reine": ["كور لا رين", "ممشى · ماري دو ميديسيس، 1616", "قبل العدّائين بزمن طويل، كان الناس يأتون إلى هنا للتباهي في عرباتهم.", "انظر إلى الممشى الطويل المستقيم المظلّل بالأشجار على طول السين.", "أنت تجري على طول ممشى واسع بجانب السين. عمره أكثر من 400 سنة.\n\nفي سنة 1616 أمرت الملكة ماري دو ميديسيس، وهي أميرة إيطالية صارت ملكة فرنسا، بغرس ممشى من الأشجار هنا. أرادت مكانًا للتنزه بالعربات، كما في فلورنسا، مدينتها. وسرعان ما صار المكان الأنيق للبلاط: يأتي الناس ليَروا ويُرَوا.\n\nانظر إلى هذا الخط المستقيم الطويل: تغيّرت الأشجار، لكن التخطيط هو تخطيط الملكة."], "Churchill en marche": ["تشرشل ماضيًا إلى الأمام", "برونز · جان كاردو، 1998", "الأسد العجوز يمشي بخطى واسعة، مثلك تمامًا.", "انظر إلى تمثال تشرشل البرونزي وهو في منتصف خطوته، وعصاه في يده.", "أنت تمر أمام تمثال رجل يمشي بخطى واسعة. إنه ونستون تشرشل.\n\nخلال الحرب العالمية الثانية كان رئيس وزراء المملكة المتحدة. في سنة 1940 كانت أوروبا كلها تقريبًا قد سقطت في يد هتلر، لكنه رفض الاستسلام. لقّبوه «الأسد العجوز». يصوّره النحات جان كاردو بزيّه العسكري، وعصاه في يده، متجهًا نحو الشانزليزيه.\n\nانظر إلى القاعدة: عليها كلماته سنة 1940: «لن نستسلم أبدًا»."], "Les jardins de Gilberte": ["حدائق جيلبرت", "ممر مارسيل بروست · حدائق الشانزليزيه", "في هذه الممرات التقى صبي صغير ببطلة روايته العظيمة.", "ابحث عن لافتة ممر مارسيل بروست بجانب المروج.", "أنت في حدائق الشانزليزيه.\n\nفي أواخر القرن التاسع عشر كان صبي صغير يأتي ليلعب هنا: مارسيل بروست. صار فيما بعد كاتبًا كبيرًا، مؤلف «البحث عن الزمن المفقود». في هذه الحدائق التقى بفتاة صغيرة، ماري دو بيناردكي، وأحبّها. وبعد سنوات ألهمته شخصية جيلبرت، أول حب للبطل في روايته.\n\nانظر إلى اسم الممر بجانب المروج: إنه ممر مارسيل بروست."], "La ligne d’arrivée du Tour": ["خط نهاية طواف فرنسا", "جادة · خط النهاية منذ 1975", "أنت تصعد الجادة التي ينتظر درّاجو طواف فرنسا ثلاثة أسابيع للوصول إليها.", "انظر أمامك مباشرة إلى قوس النصر في أعلى الجادة.", "أنت في الشانزليزيه، أشهر جادة في باريس.\n\nطواف فرنسا هو أشهر سباق للدراجات في العالم: ثلاثة أسابيع من السباق عبر البلاد. ومنذ سنة 1975 يقع خط النهاية الأخير هنا. في تلك السنة تغلّب الفرنسي برنار تيفونيه على البطل البلجيكي الكبير إدي ميركس، وفاز بالطواف أمام أهل باريس.\n\nانظر إلى الصعود نحو قوس النصر: هو نفسه لك وللأبطال."], "Les canons du Trocadéro": ["مدافع تروكاديرو", "نافورة وارسو · معرض 1937", "أكبر نافورة في باريس تطلق مياهها أفقيًا، مباشرة نحو برج إيفل.", "انظر إلى المدافع المائية في الحوض الكبير، مواجهةً برج إيفل.", "أنت في حدائق تروكاديرو، مواجهًا برج إيفل.\n\nصُمّمت من أجل المعرض الدولي سنة 1937، وهو معرض ضخم عرضت فيه كل دولة ما تستطيع فعله. في الوسط صفّ من المدافع المائية يطلق نوافير أفقية قوية نحو السين مباشرة. إنها أكبر نافورة في باريس.\n\nانظر إلى الحوض الكبير: عندما تنطلق المدافع، تندفع المياه نحو برج إيفل."], "Le pont qu’on voulait faire sauter": ["الجسر الذي أرادوا تفجيره", "جسر يينا · 1808–1814", "سُمّي هذا الجسر على اسم هزيمة بروسية، والبروسيون لم ينسوا.", "انظر إلى النسور المنحوتة على دعامات جسر يينا.", "أنت على جسر يينا، بين برج إيفل وتروكاديرو.\n\nبناه الإمبراطور نابليون احتفالًا بنصر حققه في يينا سنة 1806 على بروسيا، وهي مملكة ألمانية. لكن في سنة 1815 خسر نابليون معركة واترلو، ودخلت جيوش الأعداء باريس. أراد الجنرال البروسي بلوخر الانتقام: أراد تفجير هذا الجسر. ونجح ملك فرنسا الجديد لويس الثامن عشر في إنقاذه.\n\nانظر إلى النسور على دعامات الجسر: إنها شعار نابليون."], "La tour qui devait disparaître": ["البرج الذي كان يجب أن يختفي", "برج إيفل · 1889", "كان من المفترض أن يبقى عشرين سنة فقط. أنقذه الراديو.", "ارفع عينيك إلى قمة برج إيفل وهوائياته.", "أنت عند قدم برج إيفل. بُني من أجل المعرض العالمي سنة 1889، وهو عرض ضخم أظهرت فيه فرنسا ما تستطيع فعله.\n\nفي ذلك الوقت رأى كثير من الفنانين أنه قبيح جدًا. ولم يُسمح ببقائه إلا عشرين سنة. حاول بانيه، المهندس غوستاف إيفل، أن يجعله مفيدًا: أجرى عليه تجارب عن الرياح والطقس. والأهم أن الجيش وضع هوائي راديو في قمته. فصار البرج أثمن من أن يُهدم.\n\nانظر إلى القمة تمامًا: الهوائيات هي التي أنقذته."], "La fête de la Fédération": ["عيد الاتحاد", "ساحة مارس · 14 يوليو 1790", "عيد 14 يوليو في فرنسا يحتفل أيضًا بالحفل الضخم الذي أقيم على هذا المرج.", "انظر إلى مرج ساحة مارس الكبير الممتد حتى المدرسة العسكرية.", "أنت في ساحة مارس، المرج الطويل عند قدم برج إيفل. لم يكن البرج موجودًا بعد في زمن هذه الحكاية.\n\nفي 14 يوليو 1789 اقتحم الباريسيون سجن الباستيل: كانت بداية الثورة الفرنسية. وبعد سنة أراد الناس احتفالًا ضخمًا هنا. لم يكن هناك عمّال يكفون لتجهيز الأرض. فجاء آلاف الباريسيين يحفرون بأنفسهم، الأغنياء والفقراء جنبًا إلى جنب. وفي 14 يوليو 1790، تحت المطر، احتفل جمهور هائل بالأمة.\n\nانظر إلى هذا المرج: هنا وُلدت روح 14 يوليو، العيد الوطني لفرنسا."], "Victor Hugo, en son avenue": ["فيكتور هوغو في جادته", "آخر بيت · 124 جادة فيكتور هوغو", "كانت الرسائل تصل إلى هنا بعنوان فريد: «إلى السيد فيكتور هوغو، في جادته».", "ابحث عن اللوحة التذكارية في 124 جادة فيكتور هوغو.", "أنت في جادة فيكتور هوغو.\n\nفيكتور هوغو أشهر كاتب في فرنسا، مؤلف «البؤساء» و«أحدب نوتردام». عاش هنا منذ سنة 1878. وفي عيد ميلاده الثمانين سنة 1881 فعلت المدينة شيئًا غير مسبوق: أطلقت اسمه على الجادة وهو ما زال حيًّا. ومرّ مئات الآلاف من الباريسيين في موكب تحت نوافذه. وكانت رسائله تصل بعنوان: «إلى السيد فيكتور هوغو، في جادته». ومات هنا سنة 1885.\n\nانظر إلى اللوحة على الواجهة: هنا كان آخر بيت له."], "Le premier vol humain": ["أول طيران للإنسان", "قصر لا مويت · 21 نوفمبر 1783", "من هنا طار البشر في الهواء لأول مرة على الإطلاق.", "انظر إلى حدائق لا مويت وتخيّل منطادًا يرتفع.", "أنت في لا مويت. كان هنا قصر في الماضي، بحدائق واسعة.\n\nفي 21 نوفمبر 1783، في تلك الحدائق، صعد رجلان إلى منطاد هواء ساخن. كانا بيلاتر دو روزييه، أستاذ علوم شاب، والماركيز دارلاند، ضابط في الجيش. ارتفع المنطاد. فكانا أول إنسانين يطيران في التاريخ. حلّقا فوق باريس 25 دقيقة، وهبطا على الطرف الآخر من المدينة.\n\nانظر إلى السماء فوقك: هنا غادر الإنسان الأرض لأول مرة."], "Le corbeau et le renard": ["الغراب والثعلب", "حديقة رانيلاغ · حفلة راقصة سنة 1774", "حديقة تحمل اسم حفلة إنجليزية، وفيها تمثال من حكاية خرافية.", "ابحث على المروج عن تمثال لافونتين، مع الغراب والثعلب.", "أنت في حديقة رانيلاغ، قرب لا مويت.\n\nاسمها يبدو إنجليزيًا، ولسبب وجيه: في سنة 1774 افتُتحت هنا حفلة رقص في الهواء الطلق، مقتبسة من حديقة رائجة في لندن. وكان الأرستقراطيون يأتون للرقص. اختفت الحفلة وبقي الاسم. وفي وسط المروج تمثال يكرّم جان دو لافونتين، كاتب حكايات على ألسنة الحيوانات في القرن السابع عشر. كل طفل فرنسي يعرف واحدة منها: «الغراب والثعلب».\n\nانظر إلى التمثال: الغراب يمسك قطعة الجبن، والثعلب يتملّقه."], "Impression, soleil levant": ["«انطباع، شروق الشمس»", "متحف مارموتان مونيه · رُسمت سنة 1872", "اللوحة التي أعطت الانطباعية اسمها معلّقة على بعد أمتار.", "ابحث عن متحف مارموتان مونيه، القصر الواقع على طرف الحديقة.", "أنت تمر قرب متحف مارموتان مونيه. في داخله لوحة صغيرة أعطت اسمها لحركة فنية كاملة.\n\nفي سنة 1872 رسم الرسام كلود مونيه ميناء لوهافر عند شروق الشمس. وسمّاها «انطباع، شروق الشمس». وفي سنة 1874 سخر صحفي منه ومن أصدقائه وسمّاهم «الانطباعيين». كانت الكلمة إهانة. فصارت اسم واحدة من أحب الحركات الفنية في العالم.\n\nانظر إلى المتحف على طرف الحديقة: اللوحة خلف هذه الجدران."], "L’avenue des pionniers": ["جادة الروّاد", "جادة الجيش الكبير · الحقبة الجميلة", "قبل السيارات، كانت هذه الجادة تبيع باريس أولى دراجاتها.", "انظر إلى المنحدر الطويل لجادة الجيش الكبير نحو بوابة مايو.", "أنت تنزل جادة الجيش الكبير، التي تبدأ من قوس النصر.\n\nسُمّيت على اسم جيش نابليون. لكن نحو سنة 1900، في «الحقبة الجميلة»، صارت السوق الكبرى للدراجة، الاختراع الجديد تمامًا، ثم للسيارة. اصطفّت على جانبيها المتاجر ومشاغل المصنّعين: معرض سيارات حقيقي في الهواء الطلق.\n\nانظر إلى واجهات المحلات على طول الجادة: ما زالت تبيع الدراجات النارية والسيارات."], "Le pont de Perronet": ["جسر بيرونيه", "جسر نويي · 1772 و1942", "جاء الملك بنفسه ليشاهد إزالة سقالات هذا الجسر.", "انظر إلى جسر نويي، وفي البعيد القوس الكبير في لا ديفانس.", "أنت عند جسر نويي فوق السين.\n\nفي سنة 1772 بنى المهندس جان رودولف بيرونيه هنا جسرًا من الحجر بأقواس منبسطة جدًا، وكان ذلك إنجازًا في زمنه. أخطر لحظة كانت إزالة السقالات الخشبية تحت الأقواس: إما أن يصمد، وإما أن ينهار كل شيء. جاء الملك لويس الخامس عشر بنفسه ليشاهد. وصمد الجسر. ثم استُبدل هذا الجسر الحجري سنة 1942 بالجسر الفولاذي الحالي.\n\nانظر إلى السين تحت الجسر: تخيّل الملك ينتظر حابسًا أنفاسه."], "Un dimanche à la Grande Jatte": ["يوم أحد في لا غراند جات", "جورج سورا · 1884–1886", "هذا الفرع من السين هو مسرح واحدة من أشهر اللوحات في العالم.", "انظر إلى ضفاف جزيرة لا غراند جات والماء المتلألئ.", "أنت تجري بجانب جزيرة لا غراند جات، جزيرة في نهر السين.\n\nفي ثمانينيات القرن التاسع عشر كان الباريسيون يأتون إلى هنا للتنزه يوم الأحد. وجاء رسام شاب، جورج سورا، يراقبهم سنتين كاملتين. ثم رسم لوحة ضخمة، «بعد ظهر يوم أحد في جزيرة لا غراند جات»، بنقاط صغيرة من الألوان فقط. وفي سنة 1886 أثارت فضيحة. واليوم هي من أشهر اللوحات في العالم، في شيكاغو.\n\nانظر إلى ضفاف الجزيرة: إنها مسرح اللوحة."], "La tour est née à Levallois": ["البرج وُلد في لوفالوا", "مشاغل إيفل · 1887–1889", "قطع برج إيفل الـ18000 كلها صُنعت في هذا الحي.", "ابحث عن لافتة شارع غوستاف إيفل القريبة جدًا.", "أنت في لوفالوا، غرب باريس مباشرة.\n\nيتكوّن برج إيفل من 18000 قطعة حديد. كل واحدة منها صُنعت هنا، في مشاغل المهندس غوستاف إيفل. رُسمت كل قطعة وثُقبت وجُهّزت بدقة مذهلة. ثم نُقلت إلى ورشة البناء في ساحة مارس، حيث لم يبقَ إلا تركيبها. لهذا ارتفع البرج في سنتين وبضعة أشهر فقط، من 1887 إلى 1889.\n\nانظر نحو برج إيفل في البعيد: قطعه انطلقت من هنا."], "Les berges rendues aux piétons": ["ضفاف أُعيدت للمشاة", "الضفة اليسرى · بلا سيارات منذ 2013", "أنت تجري على طريق سريع قديم كانت السيارات تنطلق عليه.", "انظر إلى الضفة: حدائق عائمة وألعاب، ولا سيارة واحدة.", "أنت تجري على طول الضفة، بجانب الماء مباشرة. قبل خمس عشرة سنة كانت السيارات تنطلق هنا بسرعة.\n\nفي ستينيات القرن العشرين حُوّلت ضفاف السين هذه إلى طرق سريعة. وفي سنة 2013 أغلقت بلدية باريس 2.3 كيلومتر منها وأعادتها إلى المشاة، مع حدائق عائمة وألعاب ومسارات.\n\nانظر حولك: حيث تجري الآن، كان هناك طريق سريع داخل المدينة."], "Les pierres de la Bastille": ["حجارة الباستيل", "جسر الكونكورد · 1787–1791", "هذا الجسر مبني جزئيًا من السجن الذي هدمه الشعب.", "انظر إلى حجارة جسر الكونكورد تحت قدميك، ثم إلى قصر بوربون المقابل.", "أنت على جسر الكونكورد.\n\nكان الباستيل سجنًا وقلعة، رمزًا لسلطة الملك. في 14 يوليو 1789، في بداية الثورة الفرنسية، اقتحمه الباريسيون. ثم هدموه حجرًا حجرًا. كان هذا الجسر قيد البناء في ذلك الوقت، فأُكمل بحجارة الباستيل. والفكرة، كما تقول الحكاية: أن يدوس الباريسيون السجن القديم كل يوم.\n\nانظر إلى حجارة الجسر: بعضها جاء من الباستيل."], "La pyramide et le chiffre du diable": ["الهرم ورقم الشيطان", "هرم اللوفر · آي. إم. بي، 1989", "لا، ليس في الهرم 666 لوحًا زجاجيًا.", "انظر إلى الهرم الزجاجي في وسط باحة اللوفر.", "أنت أمام اللوفر. كان قصر ملوك فرنسا قبل أن ينتقلوا إلى فرساي. واليوم هو أكبر متحف في العالم.\n\nفي سنة 1989 افتُتح مدخل جديد: هرم من زجاج، صمّمه المهندس الأمريكي الصيني الأصل آي. إم. بي. أثار فضيحة: هرم حديث أمام قصر قديم. بل قالت إشاعة إن فيه 666 لوحًا زجاجيًا، رقم الشيطان. هذا غير صحيح: فيه 673.\n\nانظر إلى الهرم: حاول أن تعدّ الألواح… أو صدّقنا فحسب."], "Le bouquet de la paix": ["باقة السلام", "الأورانجري · «زنابق الماء» لمونيه، 1927", "فور انتهاء الحرب العالمية الأولى، أهدى مونيه فرنسا لوحات «زنابق الماء».", "انظر إلى مبنى الأورانجري في آخر حديقة التويلري، من جهة السين.", "أنت تمر أمام الأورانجري، متحف صغير في آخر حديقة التويلري.\n\nفي 12 نوفمبر 1918 كانت الحرب العالمية الأولى قد انتهت للتو. وأراد الرسام كلود مونيه، وقد صار شيخًا، أن يقدّم لفرنسا هدية. قدّمها لصديقه جورج كليمنصو، رئيس الحكومة. كانت الهدية ثماني لوحات ضخمة لزنابق الماء في بركة حديقته. عُلّقت هنا، في قاعتين بيضاويتين. ومات مونيه سنة 1926، قبل الافتتاح ببضعة أشهر.\n\nانظر إلى المبنى: في داخله تلتفّ زنابق الماء على الجدران كلها."], "La Grande Cascade": ["الشلال الكبير", "غابة بولونيا · خمسينيات القرن التاسع عشر", "هذا الشلال بُني للغابة الجديدة التي أرادها نابليون الثالث، وصخوره كلها مزيّفة.", "انظر إلى الشلال الكبير وأحواضه المتدرّجة.", "أنت في غابة بولونيا، الغابة الكبيرة في غرب باريس. إنها أكبر من سنترال بارك في نيويورك.\n\nفي سنة 1852 أهداها الإمبراطور نابليون الثالث إلى باريس. أرادها جميلة مثل هايد بارك في لندن. فحفر مهندسه أدولف ألفان بحيرات، وشقّ ممرات، وبنى هذا الشلال بارتفاع نحو عشرة أمتار، بصخور… اصطناعية. كل شيء مزيّف، لكن كل شيء يبدو حقيقيًا.\n\nانظر إلى صخور الشلال: صنعها البشر."], "Le moulin de l’abbaye": ["طاحونة الدير", "طاحونة لونشان · أُسّس الدير سنة 1255", "هذه الطاحونة آخر أثر لدير أسّسته أخت ملك قدّيس.", "انظر إلى الطاحونة القديمة، وميدان السباق خلفها مباشرة.", "أنت تمر أمام طاحونة هواء قديمة بجانب ميدان سباق الخيل في لونشان.\n\nفي سنة 1255 أسّست إيزابيل الفرنسية، أخت الملك القديس لويس، ديرًا للراهبات هنا. وبقي أكثر من خمسة قرون. ثم جاءت الثورة الفرنسية سنة 1789: بيع الدير ثم هُدم. ولم يبقَ إلا هذه الطاحونة. وخلفها مباشرة، كل خريف، يستضيف الميدان أعرق سباق خيل في أوروبا، جائزة قوس النصر.\n\nانظر إلى الطاحونة: إنها آخر أثر للدير."], "Le château du pari": ["قصر الرهان", "باغاتيل · 1777", "بُني هذا القصر الصغير في أكثر من شهرين بقليل، للفوز برهان.", "انظر إلى قصر باغاتيل الصغير الأبيض في وسط الحديقة.", "أنت تمر أمام حديقة باغاتيل في غابة بولونيا.\n\nفي سنة 1777 راهن الكونت دارتوا، شقيق الملك لويس السادس عشر، زوجة أخيه الملكة ماري أنطوانيت. زعم أنه يستطيع أن يبني قصرًا صغيرًا في أقل من ثلاثة أشهر. فشغّل مهندسه مئات العمال ليلًا ونهارًا. وكان القصر جاهزًا في 64 يومًا. ربح الرهان.\n\nانظر إلى الحديقة: هي اليوم مشهورة قبل كل شيء بورودها."], "Castor et Pollux": ["كاستور وبولوكس", "حديقة التأقلم · حصار 1870", "خلال حصار باريس، انتهى المطاف بفيلَي هذه الحديقة عند الجزّار.", "انظر إلى مدخل حديقة التأقلم.", "أنت تمر أمام «جاردان داكليماتاسيون»، حديقة للأطفال في غابة بولونيا.\n\nعند افتتاحها سنة 1860 كانت نوعًا من حديقة الحيوانات، فيها حيوانات من كل أنحاء العالم. ونجماها فيلان اسمهما كاستور وبولوكس. في شتاء 1870 حاصر الجيش البروسي القادم من ألمانيا باريس. لم يكن شيء يستطيع دخول المدينة، وكان الباريسيون يتضوّرون جوعًا. وفي أواخر ديسمبر ذُبح كاستور وبولوكس، وبيع لحمهما بثمن باهظ عند جزّار راقٍ.\n\nانظر إلى المدخل: خلفه عاش الفيلان."], "L’île aux Cygnes": ["جزيرة البجع", "جزيرة اصطناعية · 1827", "جزيرة طولها 850 مترًا وعرضها 11 مترًا: الخط المستقيم المثالي.", "انظر إلى الممر الوحيد المظلّل بالأشجار في وسط السين.", "أنت على جزيرة ضيقة في وسط السين. ليس فيها شيء طبيعي: بُنيت سدًّا في أوائل القرن التاسع عشر، قبل نحو 200 سنة.\n\nلاحقًا زُرعت فيها الأشجار وشُقّ فيها ممر واحد. لا سيارات، ولا إشارات مرور، 850 مترًا بخط مستقيم تمامًا. جعلها عدّاؤو الحي مضمارهم المفضّل.\n\nانظر خلفك: برج إيفل يرافقك طوال الطريق."], "La petite sœur de New York": ["الأخت الصغرى لنيويورك", "تمثال الحرية · 1889", "طولها 11.5 مترًا، وتنظر إلى أختها الكبرى عبر الأطلسي.", "انظر إلى تمثال الحرية عند طرف الجزيرة، وشعلته مرفوعة.", "نعم، إنه فعلًا تمثال الحرية، لكنه أصغر. التمثال الكبير في نيويورك هدية من فرنسا إلى الولايات المتحدة سنة 1886، صنعه نحات فرنسي هو أوغست بارتولدي.\n\nفي سنة 1889 احتفلت فرنسا بالذكرى المئوية للثورة. ولقول شكرًا، أهدى الأمريكيون المقيمون في باريس المدينةَ هذه النسخة الصغيرة. على لوحها تاريخان: استقلال أمريكا، واقتحام الباستيل. وفي سنة 1937 أُديرت نحو الغرب، لتنظر إلى أختها الكبرى عبر المحيط.\n\nانظر إلى أين ترفع شعلتها: نحو نيويورك."], "Sous le pont Mirabeau": ["تحت جسر ميرابو", "جسر ميرابو · 1897 · أبولينير، 1912", "قصيدة عن حب ضائع جعلت هذا الجسر مشهورًا في العالم كله.", "انظر إلى التماثيل البرونزية الأربعة الكبيرة على دعامات جسر ميرابو.", "وصلت إلى جسر ميرابو، جسر من حديد بُني سنة 1897.\n\nفي أوائل القرن العشرين كان الشاعر غيوم أبولينير يعبره كثيرًا في طريقه إلى بيته في أوتوي. كان يحب رسّامة اسمها ماري لورانسان. لكنهما افترقا. وفي سنة 1912 كتب قصيدة «جسر ميرابو»: السين يجري تحت الجسر، كما يمضي الزمن ويتلاشى الحب. واليوم يحفظها كل تلميذ فرنسي عن ظهر قلب.\n\nانظر إلى الماء الجاري تحت الجسر: إنه تمامًا ما رآه أبولينير."], "La Maison ronde": ["البيت الدائري", "دار الإذاعة · هنري برنار، 1963", "مبنى مستدير كأسطوانة موسيقية، من أجل الإذاعة الوطنية.", "انظر إلى المبنى الدائري الكبير بجانب السين.", "أنت تمر أمام مبنى دائري ضخم بجانب السين. إنه دار الإذاعة، ويسمّيه الباريسيون «البيت الدائري».\n\nافتتحه سنة 1963 الجنرال ديغول، رئيس فرنسا آنذاك. صمّمه المهندس هنري برنار مثل أسطوانة موسيقية: حلقات من المكاتب والاستوديوهات حول برج مركزي. هنا مقر «راديو فرانس»، الإذاعة الفرنسية العامة.\n\nانظر إلى دوائره الكبيرة: كل الإذاعات العامة في فرنسا تبث من هذا المبنى."], "Le jardin de Shakespeare": ["حديقة شكسبير", "بري كاتلان · 1953", "كل نبتة في هذه الحديقة ذكرها شكسبير.", "ابحث عن مدخل حديقة شكسبير في قلب بري كاتلان.", "أنت في غابة بولونيا، الغابة الكبيرة في غرب باريس، في حديقة اسمها «بري كاتلان».\n\nفي سنة 1953 أُنشئت هنا حديقة خاصة جدًا. لا تضم إلا النباتات المذكورة في مسرحيات شكسبير. كل ركن فيها يشبه ديكورًا مسرحيًا: غابة «حلم ليلة صيف»، وأرض «ماكبث» القاحلة، وجزيرة «العاصفة». وفي الصيف تُقدَّم فيها عروض مسرحية في الهواء الطلق.\n\nانظر إلى الأشجار والزهور: كل واحدة منها آتية من مسرحية لشكسبير."], "L’hippodrome des sauteurs": ["ميدان القفّازين", "ميدان سباق أوتوي · 1873", "هنا لا تكتفي الخيول بالجري: إنها تقفز.", "انظر عبر السياج إلى حواجز ميدان أوتوي.", "أنت تجري بمحاذاة ميدان سباق أوتوي، الذي افتُتح سنة 1873.\n\nهنا لا تكتفي الخيول بالعدو: إنها تقفز فوق الأسيجة النباتية والماء. تُسمّى هذه سباقات الحواجز. ومنذ سنة 1874، كل ربيع، يجري هنا أشهرها في فرنسا: «غران ستيبل شيز دو باري».\n\nانظر عبر السياج: قد ترى الأسيجة على المضمار."], "Un aviateur sur la terre battue": ["طيّار على الملاعب الترابية", "ملعب رولان غاروس · 1928", "أشهر ملعب تنس في العالم يحمل اسم طيّار، لا لاعب.", "انظر إلى جدران ملعب رولان غاروس، بلون ملاعبه الترابية.", "أنت تمر أمام ملعب رولان غاروس، الذي يستضيف كل ربيع أشهر بطولة تنس على الملاعب الترابية في العالم.\n\nلكن رولان غاروس لم يكن لاعب تنس. كان طيّارًا. في سنة 1913 صار أول من عبر البحر الأبيض المتوسط بالطائرة. وقُتل في الحرب العالمية الأولى سنة 1918. وبعد عشر سنوات، في 1928، بُني هذا الملعب لمباراة تنس كبيرة، وسُمّي باسم هذا البطل.\n\nانظر إلى الاسم فوق المدخل: إنه اسم طيّار، لا لاعب."], "Sur les rails de la Petite Ceinture": ["على سكك الحزام الصغير", "خط أوتوي · 1854", "أنت تجري على خط سكة حديد قديم أُعيد إلى الطبيعة.", "انظر إلى الممر الأخضر الذي كانت القطارات تمر فيه، المليء بالسراخس والأشجار.", "أنت في ممر أخضر منخفض في وسط المدينة. كانت القطارات تمر هنا.\n\nفي القرن التاسع عشر كان خط سكة حديد يدور حول باريس كلها، اسمه «الحزام الصغير». هذا الجزء، خط أوتوي، افتُتح سنة 1854. واستخدمه الركاب حتى سنة 1985. ثم توقفت القطارات واستعادت الطبيعة المكان: أشجار وسراخس وزهور برية.\n\nانظر إلى الأرض: في بعض الأماكن ما زلت تميّز مكان السكك."], "Le pont des cadenas": ["جسر الأقفال", "جسر الفنون · 1804", "هذا الجسر الصغير حمل يومًا حتى 45 طنًّا من أقفال الحب.", "انظر إلى الحواجز الزجاجية لجسر الفنون، حيث كانت الأقفال.", "أنت على جسر الفنون، جسر للمشاة بين اللوفر ومعهد فرنسا.\n\nافتُتح سنة 1804، وكان أول جسر من حديد في باريس. في أوائل العقد الثاني من القرن الحادي والعشرين، كان العشّاق من كل أنحاء العالم يعلّقون عليه أقفالًا عليها الحروف الأولى من أسمائهم، ويرمون المفتاح في السين. كانت الأقفال كثيرة إلى حد أن وزنها بلغ 45 طنًّا، فتضرّرت الحواجز. وفي سنة 2015 أزالتها البلدية كلها ووضعت ألواحًا زجاجية.\n\nانظر إلى الألواح الزجاجية على طول الجسر: حلّت محل الأقفال."], "Le Pont-Neuf et le Vert-Galant": ["الجسر الجديد وفير غالان", "الجسر الجديد · 1578–1607", "«الجسر الجديد» هو في الحقيقة أقدم جسر في باريس.", "انظر إلى تمثال هنري الرابع على حصانه في وسط الجسر الجديد.", "وصلت إلى «البون نوف». اسمه يعني «الجسر الجديد»، ومع ذلك هو أقدم جسر في باريس.\n\nاكتمل سنة 1607 في عهد الملك هنري الرابع. كان في وقته ثوريًا: أول جسر في باريس بلا بيوت فوقه، وبأرصفة للمشاة. وكانت باريس كلها تأتي للتنزه عليه. وتحته مباشرة حديقة صغيرة تحمل لقب الملك «فير غالان»، أي العجوز المغازل، لأنه كان له عدد كبير جدًا من العشيقات.\n\nانظر إلى تمثال الملك على حصانه في وسط الجسر: إنه هنري الرابع."], "L’île inventée": ["الجزيرة المخترَعة", "جزيرة سان لويس · 1614–1664", "وُلدت هذه الجزيرة من جزيرتين صغيرتين وصلهما مطوّر عقاري في القرن السابع عشر.", "انظر إلى أرصفة جزيرة سان لويس وواجهات قصورها.", "أنت على جزيرة سان لويس، إحدى الجزيرتين في وسط باريس.\n\nقبل 400 سنة لم يكن هنا إلا جزيرتان صغيرتان ترعى فيهما الأبقار. ونحو سنة 1614 حصل مطوّر عقاري اسمه كريستوف ماري على إذن الملك بوصلهما والبناء عليهما. وفي خمسين سنة ظهرت الأرصفة، والشوارع المستقيمة، وبيوت جميلة للنبلاء. كان أول حي جديد بالكامل في باريس.\n\nانظر إلى الواجهات على طول الرصيف: كلها تقريبًا من ذلك الزمن."], "Les bouquinistes": ["بائعو الكتب القديمة", "أرصفة السين · منذ القرن السادس عشر", "هذه الصناديق الخضراء تشكّل أكبر مكتبة في الهواء الطلق في العالم.", "انظر إلى صناديق الباعة الخضراء المثبّتة على سور النهر.", "أنت تجري على طول السين. على الأسوار المنخفضة صناديق خضراء كبيرة: إنهم «البوكينيست»، باعة الكتب القديمة.\n\nهم هنا منذ القرن السادس عشر، منذ قرابة 500 سنة. طُردوا طويلًا، ثم تُسومح معهم. وفي سنة 1859 منحتهم المدينة أخيرًا أماكن رسمية. واليوم يدير نحو 200 بائع 900 صندوق: أكبر مكتبة في الهواء الطلق في العالم.\n\nانظر إلى الصناديق الخضراء: في المساء تُغلق مثل الخزائن."], "Le Grand Parc des Docks": ["حديقة الأرصفة الكبرى", "سانت أوان · افتُتحت سنة 2013", "حديقة مساحتها 12 هكتارًا نبتت مكان مصانع وأرصفة قديمة.", "انظر إلى مروج الحديقة وبركها على طول السين.", "غادرت باريس، وأنت الآن في سانت أوان، بجانب السين.\n\nأكثر من قرن كانت هنا أرصفة ومصانع ومحطة لتوليد الكهرباء: ضجيج ودخان وفحم. ثم أُغلق كل شيء. وفي مكانها قام حي بيئي حول هذه الحديقة الكبيرة التي تبلغ 12 هكتارًا، وافتُتحت سنة 2013.\n\nانظر إلى المروج والبرك: حلّت محل مداخن المصانع."], "Les Puces de Saint-Ouen": ["سوق البراغيث في سانت أوان", "سوق البراغيث · أواخر القرن التاسع عشر", "أكبر سوق للتحف في العالم نشأ من لُقى جامعي الخِرق.", "انظر إلى ممرات سوق البراغيث في سانت أوان وأكشاكه.", "أنت تمر قرب سوق البراغيث في سانت أوان، شمال باريس مباشرة.\n\nفي أواخر القرن التاسع عشر كان جامعو الخِرق يفتّشون صناديق قمامة باريس بحثًا عن قماش وخردة وأشياء قديمة. ولمّا طُردوا من المدينة، استقرّوا هنا، خلف الأسوار مباشرة، ليبيعوا ما يجدونه. وشيئًا فشيئًا صار المكان سوقًا. واليوم يجتمع فيه أكثر من ألف تاجر كل عطلة أسبوع: إنه أكبر سوق للتحف في العالم.\n\nانظر إلى ممرات السوق: ستجد كل شيء، من الأزرار القديمة إلى ثريات القصور."], "Verlaine et Breton": ["فيرلين وبروتون", "مقبرة باتينيول · 1833", "خلف هذا الجدار يرقد شاعر كبير وأبو السريالية.", "انظر إلى جدار مقبرة باتينيول الصغيرة، الملاصقة للطريق الدائري.", "أنت تمر أمام مقبرة باتينيول، مقبرة صغيرة افتُتحت سنة 1833، وهي اليوم ملاصقة للطريق الدائري.\n\nومع ذلك فيها اسمان كبيران. بول فيرلين، أحد أعظم شعراء فرنسا، دُفن هنا سنة 1896. ولحق به أندريه بروتون سنة 1966: هو مؤسس السريالية، حركة فنية مستوحاة من الأحلام.\n\nانظر إلى جدران المقبرة: خلفها ركن هادئ بجوار ضجيج السيارات مباشرة."], "Le parc des voies ferrées": ["حديقة السكك الحديدية", "حديقة مارتن لوثر كينغ · منذ 2007", "حلّت هذه الحديقة محل امتداد هائل من سكك الحديد.", "انظر إلى برك حديقة مارتن لوثر كينغ وحدائقها.", "أنت في حديقة مارتن لوثر كينغ، في حي باتينيول.\n\nكانت هنا سكك حديد ومستودعات على مدّ البصر، تابعة لمحطة سان لازار القريبة من فندقك. لو فازت باريس بأولمبياد 2012، لبُنيت قرية الرياضيين هنا. لكن لندن فازت. فأُنشئت هنا حديقة منذ سنة 2007، في قلب حي بيئي جديد.\n\nانظر إلى المباني العالية حول الحديقة: هذا الحي كله نما على أراضي السكك القديمة."], "Le méridien de Saint-Sulpice": ["خط الطول في سان سولبيس", "كنيسة سان سولبيس · مزولة 1743", "خط نحاسي يعبر أرضية الكنيسة: إنه أداة فلكية.", "ابحث عن الخط النحاسي على أرضية الكنيسة الذي يقود إلى مسلّة.", "أنت تمر أمام كنيسة سان سولبيس، إحدى أكبر كنائس باريس.\n\nفي داخلها خط نحاسي رفيع يعبر الأرضية حتى مسلّة صغيرة. إنها أداة فلكية رُكّبت سنة 1743. يدخل شعاع من الشمس من ثقب صغير ويسقط على الخط. كان ذلك يُستخدم لتحديد الفصول، وبالتالي لحساب تاريخ عيد الفصح. وقد زعمت رواية «شيفرة دافنشي» أنه خط سرّي: هذا غير صحيح.\n\nانظر إلى برجي الكنيسة: الخط النحاسي خلف الأبواب مباشرة."], "Le palais florentin": ["القصر الفلورنسي", "قصر اللوكسمبورغ · 1615–1631", "ملكة تحنّ إلى بلادها أمرت ببناء هذا القصر.", "انظر إلى واجهة قصر اللوكسمبورغ في نهاية الحوض الكبير.", "أنت أمام قصر اللوكسمبورغ، في آخر الحديقة الكبيرة التي تحمل الاسم نفسه.\n\nفي أوائل القرن السابع عشر كانت ماري دو ميديسيس، الأميرة الإيطالية، ملكة فرنسا. وكان زوجها الملك هنري الرابع قد اغتيل للتو. كانت تحنّ إلى بلادها. فأمرت ببناء هذا القصر ليذكّرها بقصر طفولتها في فلورنسا. استمرت الأشغال من 1615 إلى 1631. ومنذ سنة 1799 يجتمع هنا مجلس الشيوخ، أحد المجلسين اللذين يصوّتان على قوانين فرنسا.\n\nانظر إلى الواجهة: إنها قطعة صغيرة من إيطاليا في وسط باريس."], "Le pendule du Panthéon": ["بندول البانثيون", "البانثيون · ليون فوكو، 1851", "تحت هذه القبة، رأى الناس الأرض تدور.", "ارفع عينيك إلى قبة البانثيون الكبيرة.", "أنت أمام البانثيون، المبنى ذو القبة الكبيرة. هنا تدفن فرنسا أكثر الناس أهمية في تاريخها: الكاتب فيكتور هوغو، والعالمة ماري كوري، والمغنية وبطلة المقاومة جوزفين بيكر.\n\nفي سنة 1851 جرت هنا تجربة شهيرة. علّق الفيزيائي ليون فوكو كرة ثقيلة بسلك طوله 67 مترًا تحت القبة، وجعلها تتأرجح. ومع مرور الساعات، كان اتجاه التأرجح يدور ببطء. لم تكن الكرة هي التي تدور: كانت الأرض تحتها. ولأول مرة رأى الناس بأعينهم أن الأرض تدور.\n\nانظر إلى القبة: البندول ما زال يتأرجح تحتها."], "Les arènes de Lutèce": ["حلبة لوتيس", "مدرّج غالي روماني · القرن الأول", "قبل قرابة ألفي سنة، جلس هنا آلاف المتفرجين.", "انظر إلى المدرّجات الحجرية وساحة الحلبة الدائرية.", "أنت تدخل مدرّجًا رومانيًا قديمًا، مختبئًا خلف المباني.\n\nقبل 2000 سنة كان اسم باريس «لوتيتيا»، وكانت جزءًا من الإمبراطورية الرومانية. وفي القرن الأول بُنيت هنا حلبة، تشبه قليلًا كولوسيوم صغيرًا. كان آلاف المتفرجين يأتون لمشاهدة العروض والمعارك. ثم اختفت تحت الأرض قرونًا. وعُثر عليها مجددًا سنة 1869 أثناء شق شارع، وناضل الكاتب فيكتور هوغو لإنقاذها.\n\nانظر إلى المدرّجات الحجرية: اليوم يلعب الباريسيون هنا لعبة البيتانك."], "Le bassin de Napoléon": ["حوض نابليون", "حوض لا فيليت · 1808", "أكبر بحيرة اصطناعية في باريس حُفرت لتوفير مياه الشرب للباريسيين.", "انظر إلى حوض لا فيليت الطويل الذي تحفّه الأرصفة.", "أنت تجري بجانب حوض طويل جدًا، حوض لا فيليت.\n\nفي أوائل القرن التاسع عشر كانت باريس تفتقر إلى المياه النظيفة. وفي سنة 1802 قرر نابليون جلبها من بعيد، من نهر اسمه «أورك»، وإيصالها إلى هنا عبر قناة. هذا الحوض الذي افتُتح سنة 1808 كان خزّانًا وميناءً في آن واحد. بطول 800 متر، هو أكبر مسطّح مائي اصطناعي في باريس.\n\nانظر إلى الضفتين: هما اليوم مكان النزهات وتراسات المقاهي."], "La Géode": ["لا جيود", "سينما القبة · أدريان فينسيلبير، 1985", "كرة مرآة قطرها 36 مترًا تعكس السماء والعدّائين.", "انظر إلى كرة لا جيود الفضية الكبيرة وانعكاسها في الماء.", "أنت تمر أمام كرة لامعة ضخمة في حديقة لا فيليت. إنها «لا جيود»، افتُتحت سنة 1985.\n\nقطرها 36 مترًا، ومغطاة بأكثر من 6000 مثلث من الفولاذ المصقول، كالمرآة. في داخلها سينما بشاشة عملاقة على شكل قبة: تشعر وكأنك داخل الفيلم.\n\nانظر إلى الكرة وأنت تمر: سترى نفسك تجري فيها."], "La Philharmonie": ["الفيلارموني", "قاعة حفلات · جان نوفيل، 2015", "سفينة فضاء معدنية يحيط فيها الجمهور بالأوركسترا.", "انظر إلى واجهة الفيلارموني المغطاة بصفائح على شكل طيور.", "أنت تمر أمام مبنى معدني رمادي كبير: فيلارموني باريس، قاعة حفلات افتُتحت سنة 2015.\n\nصمّم مهندسها جان نوفيل قاعة لا يجلس فيها الجمهور قبالة الأوركسترا، بل حولها من كل الجهات، على شرفات تبدو وكأنها تطفو. ومن الخارج، الواجهة مغطاة بآلاف الصفائح الألمنيوم على شكل طيور.\n\nانظر إلى الواجهة عن قرب: الصفائح الصغيرة ترسم أشكال طيور."], "La porte du Roi-Soleil": ["بوابة الملك الشمس", "بوابة سان دوني · فرانسوا بلونديل، 1672", "بنى لويس الرابع عشر هذا القوس احتفالًا بانتصاراته.", "ارفع عينيك إلى بوابة سان دوني ومنحوتاتها.", "أنت تمر أمام قوس حجري كبير في وسط الشارع: بوابة سان دوني.\n\nفي القرن السابع عشر كان الملك لويس الرابع عشر، الملقّب بالملك الشمس، قويًا جدًا. فأمر بهدم أسوار باريس القديمة: في رأيه لم تعد المدينة بحاجة إلى أسوار. وفي مكان البوابات القديمة بنى أقواس نصر. هذا القوس بارتفاع 24 مترًا، ويعود إلى سنة 1672، ويحتفل بانتصاراته العسكرية.\n\nانظر إلى المنحوتات على القوس: إنها تروي معارك الملك."], "Face au Mont-Valérien": ["في مواجهة مون فاليريان", "ضفة النهر · إطلالة على النصب التذكاري", "على التلة المقابلة أُعدم رميًا بالرصاص أكثر من ألف مقاوم ورهينة.", "انظر إلى تلة مون فاليريان، على الضفة الأخرى من السين.", "أنت بجانب السين. على التلة المقابلة يقوم حصن: مون فاليريان.\n\nخلال الحرب العالمية الثانية احتل الجيش الألماني فرنسا. ومن 1941 إلى 1944 أعدم رميًا بالرصاص في هذا الحصن أكثر من ألف مقاوم ورهينة. وفي سنة 1960 افتتح هنا الجنرال ديغول، الذي قاد «فرنسا الحرة» من لندن، نصبًا تذكاريًا. وفي 18 يونيو من كل عام يُستعاد هنا نداؤه الإذاعي إلى المقاومة سنة 1940.\n\nانظر إلى التلة المقابلة: إنها مكان للذاكرة لفرنسا كلها."], "Le château disparu": ["القصر المختفي", "شرفة القصر · دُمّر سنة 1870", "على هذه الشرفة الخالية قام قصر استولى فيه بونابرت على السلطة.", "انظر إلى الشرفة الكبيرة الخالية حيث كان القصر.", "أنت على شرفة كبيرة في حديقة سان كلو. كان هنا قصر في الماضي.\n\nفي سنة 1785 اشترته الملكة ماري أنطوانيت. ثم في سنة 1799 وقعت هنا لحظة حاسمة في التاريخ: استولى الجنرال الشاب نابليون بونابرت على السلطة بالقوة. كانت بداية حكمه. ولاحقًا سكن هنا أيضًا ابن أخيه، الإمبراطور نابليون الثالث. وفي سنة 1870، خلال الحرب مع بروسيا، احترق القصر. ولم يُعَد بناؤه أبدًا.\n\nانظر إلى الفراغ أمامك: هنا كان القصر، بالإطلالة نفسها."], "L’autre Trocadéro": ["التروكاديرو الآخر", "حديقة تروكاديرو · إطلالة على باريس", "مثل تلك التي في باريس، تحمل هذه الحديقة اسم حصن إسباني.", "استدر من أعلى الحديقة: باريس كلها أمامك.", "أنت في أعلى حديقة سان كلو، في حديقة تُسمّى أيضًا تروكاديرو، مثل الساحة المقابلة لبرج إيفل.\n\nكلاهما سُمّي على اسم معركة فاز بها الجيش الفرنسي في إسبانيا سنة 1823. لكن الهدية الحقيقية هنا هي الإطلالة: باريس كلها ممتدة أمامك.\n\nانظر إلى الأفق: ترى برج إيفل، وإلى اليسار أبعد قليلًا، أبراج لا ديفانس."], "Le port de l’Arsenal": ["ميناء الأرسنال", "حوض الأرسنال · مرسى للقوارب منذ 1983", "هذه القوارب تطفو في الخندق القديم لأسوار باريس.", "انظر إلى القوارب في مرسى الأرسنال، أسفل ساحة الباستيل.", "أنت تجري بجانب حوض مليء بالقوارب الصغيرة، بين السين وساحة الباستيل.\n\nفي العصور الوسطى كانت باريس محاطة بأسوار، أمامها خنادق مملوءة بالماء لحمايتها. هذا الحوض أحد تلك الخنادق القديمة. وفي القرن التاسع عشر صار ميناءً يصل السين بقناة سان مارتان. ومنذ سنة 1983 صار مرسى للقوارب، تحفّه حديقة.\n\nانظر إلى القوارب الراسية: إنها تطفو في خندق دفاعي قديم."], "Le ministère qui enjambe le quai": ["الوزارة التي تعبر الرصيف", "وزارة المالية · شيميتوف وأويدوبرو، 1989", "هذا المبنى الشبيه بالجسر قدماه في السين، والوزراء يصلون أحيانًا بالقارب.", "انظر إلى مبنى وزارة المالية الضخم الممتد فوق الرصيف.", "أنت تمر تحت مبنى ضخم على شكل جسر. إنه وزارة المالية، التي تدير أموال الدولة الفرنسية.\n\nكانت الوزارة في الماضي داخل جزء من اللوفر. وفي ثمانينيات القرن العشرين أراد الرئيس فرانسوا ميتران اللوفر كله للمتحف. فبُني هذا المبنى الجديد هنا، واكتمل سنة 1989. يمتد طرفه فوق الضفة حتى السين، وفيه رصيف للقوارب: يستطيع الوزراء أن يصلوا بالقارب.\n\nانظر إلى طرف المبنى: قدماه في الماء تقريبًا."], "Quatre livres ouverts": ["أربعة كتب مفتوحة", "المكتبة الوطنية فرانسوا ميتران · دومينيك بيرو، 1996", "أبراج المكتبة الوطنية الأربعة على شكل كتب مفتوحة.", "انظر إلى الأبراج الأربعة على شكل حرف L في زوايا ساحة المكتبة.", "أنت أمام المكتبة الوطنية الفرنسية. إنها تحفظ نسخة من كل ما يُنشر في البلاد.\n\nافتُتح المبنى سنة 1996. تخيّل المهندس دومينيك بيرو أربعة أبراج على شكل حرف L في زوايا ساحة ضخمة، كأربعة كتب مفتوحة واقفة. وفي الوسط، تحت مستوى الأرض، تنمو غابة حقيقية من أشجار الصنوبر العالية، يمكنك أن تنظر إليها لكن لا يمكنك أن تمشي فيها.\n\nانظر إلى الأبراج الأربعة: تخيّلها كتبًا نصف مفتوحة."], "Le musée en plein air": ["المتحف في الهواء الطلق", "حديقة تينو روسي · منذ 1980", "على طول هذا الرصيف تُعرض المنحوتات بلا زجاج ولا تذكرة.", "انظر إلى المنحوتات الموزّعة بين أشجار حديقة تينو روسي.", "أنت في حديقة تينو روسي بجانب السين. إنها متحف مجاني، مفتوح ليلًا ونهارًا.\n\nمنذ سنة 1980 تقف هنا منحوتات حديثة لفناني القرن العشرين بين الأشجار والنهر. وفي أمسيات الصيف تتحوّل المدرّجات الحجرية الصغيرة إلى حلبات رقص: تانغو وسالسا، بجانب الماء.\n\nانظر إلى المنحوتات بين الأشجار: كل واحدة منها قطعة متحفية حقيقية."], "Le cimetière du Montparnasse": ["مقبرة مونبارناس", "مقبرة · 1824", "خلف هذا الجدار يتشارك سارتر وبوفوار قبرًا واحدًا.", "انظر إلى جدار مقبرة مونبارناس وأنت تجري على طول الجادة.", "أنت تجري بمحاذاة مقبرة مونبارناس.\n\nمن نحو 1920 إلى 1950 جذب حي مونبارناس فنانين من كل أنحاء العالم. ويرقد كثير منهم هنا. جان بول سارتر وسيمون دو بوفوار، فيلسوفان وأشهر ثنائي مثقف في فرنسا، مدفونان معًا. والشاعر شارل بودلير قريب منهما. وكذلك المغني سيرج غينسبور.\n\nانظر إلى جدران المقبرة: خلفها يرقد جزء كبير من الثقافة الفرنسية."], "La mire du méridien": ["علامة خط الطول", "حديقة مونسوري · ألفان، 1878", "في هذه الحديقة، علامة حجرية صغيرة تشير إلى خط طول باريس.", "ابحث في الحديقة عن العلامة الحجرية الصغيرة، «علامة الجنوب».", "أنت في حديقة مونسوري، حديقة كبيرة في جنوب باريس افتُتحت سنة 1878.\n\nتخفي كنزًا صغيرًا: علامة حجرية من سنة 1806، اسمها «علامة الجنوب». تقع تمامًا على خط طول باريس، وهو خط وهمي من الشمال إلى الجنوب. قبل أن يختار العالم كله الخط المارّ بغرينتش في لندن، كانت فرنسا تقيس كل شيء انطلاقًا من هذا الخط. وكان علماء الفلك في مرصد باريس يصوّبون نحو هذه العلامة لضبط أدواتهم.\n\nانظر إلى العمود الحجري الصغير: إنه يقع على خط الطول بالضبط."], "Le parc de Brassens": ["حديقة براسنس", "حديقة جورج براسنس · 1985", "الخيول البرونزية عند المدخل تذكّر بسوق الخيل القديم.", "انظر إلى الخيول البرونزية عند المدخل وإلى برج المزادات.", "أنت في حديقة جورج براسنس، في جنوب باريس.\n\nحتى سبعينيات القرن العشرين كانت هنا مسالخ وسوق للخيل. حلّت الحديقة محلها سنة 1985، لكنها احتفظت ببعض الذكريات: أجنحة، وبرج كانت تُعلن منه نتائج البيع، وتماثيل خيول عند المدخل. سُمّيت باسم جورج براسنس، مغنٍّ يعشقه الفرنسيون، وكان يسكن قريبًا.\n\nانظر إلى الخيول البرونزية عند المدخل: إنها تذكّر بالسوق القديم."], "La Petite Ceinture du 15e": ["الحزام الصغير في الدائرة الخامسة عشرة", "سكة قديمة · ممشى منذ 2013", "كيلومتر ونصف من سكة نائمة، سُلّمت للمشاة والعدّائين.", "انظر إلى سكك الحزام الصغير وضفافها المزهرة.", "أنت على خط سكة حديد قديم، بين الأعشاب.\n\nفي القرن التاسع عشر كان خط سكة حديد يدور حول باريس كلها، اسمه «الحزام الصغير». على الضفة اليسرى لم يعد يحمل الركاب منذ سنة 1934. بقيت السكك، ونمت الطبيعة حولها. وفي سنة 2013 افتتحت المدينة هنا ممشى على طول السكك.\n\nانظر إلى الضفاف المزهرة والجسور القديمة: إنه ريف تقريبًا في وسط المدينة."], "L’opéra du Bicentenaire": ["أوبرا المئوية الثانية", "أوبرا الباستيل · كارلوس أوت، 1989", "افتُتحت هذه الأوبرا الزجاجية عشية الذكرى المئتين للثورة.", "انظر إلى واجهة أوبرا الباستيل الزجاجية الكبيرة على الساحة.", "أنت في ساحة الباستيل. هنا كان السجن القلعة الذي اقتحمه الباريسيون في 14 يوليو 1789، في بداية الثورة الفرنسية.\n\nبعد مئتي سنة أراد الرئيس فرانسوا ميتران هنا دار أوبرا حديثة، مفتوحة للجميع، لا للأغنياء فقط. وافتُتح المبنى الكبير من الزجاج والحجر في 13 يوليو 1989، عشية الذكرى المئتين للثورة.\n\nانظر إلى أوبرا الباستيل: قاعتها الرئيسية تتسع لنحو 2700 شخص."], "Le jardin sur le viaduc": ["الحديقة فوق الجسر", "الممر الأخضر رينيه دومون · 1993", "أنت تجري في أول حديقة معلّقة على جسر في العالم.", "انظر تحتك إلى الجسر المبني من الآجر وأقواسه.", "أنت على ممشى مزروع مرتفع فوق الشوارع: «الممر الأخضر».\n\nمن 1859 إلى 1969 كان قطار يسير من الباستيل إلى فانسين على هذا الجسر المبني من الآجر. وعندما أُغلق الخط، كان يمكن أن يُهدم كل شيء. لكن بدلًا من ذلك، في سنة 1993، تحوّل الخط إلى حديقة طولها قرابة 5 كيلومترات. كان أول ممشى من نوعه في العالم. وألهم «الهاي لاين» الشهير في نيويورك.\n\nانظر تحت قدميك: أنت تجري على خط سكة حديد قديم."], "Le palais de 1931": ["قصر 1931", "قصر بورت دوريه · ألبير لابراد، 1931", "واجهته جدارية منحوتة ضخمة، من بقايا معرض مثير للجدل.", "انظر إلى الواجهة المنحوتة الكبيرة لقصر بورت دوريه.", "أنت تمر أمام قصر كبير بأعمدة: قصر بورت دوريه.\n\nبُني سنة 1931 من أجل المعرض الاستعماري. في ذلك الوقت كانت لفرنسا إمبراطورية ضخمة، بمستعمرات في أفريقيا وآسيا، وكان هذا المعرض يهدف إلى الاحتفاء بها. الواجهة مغطاة بالكامل بنحت عملاق يصوّر تلك البلاد البعيدة. ومنذ سنة 2007 يضم القصر متحف تاريخ الهجرة، الذي ينظر إلى ذلك الماضي بعين مختلفة.\n\nانظر إلى الواجهة: النحت يلتف حول المبنى كله."], "Le lac de la Jambe de bois": ["بحيرة «الساق الخشبية»", "بحيرة دوميسنيل · الإمبراطورية الثانية", "تحمل هذه البحيرة اسم جنرال رفض تسليم فانسين.", "انظر إلى جزيرتي البحيرة والمعبد الصغير فوق مغارته.", "وصلت إلى بحيرة دوميسنيل في غابة فانسين، الغابة الكبيرة شرق باريس.\n\nتحمل البحيرة اسم الجنرال دوميسنيل، الذي فقد ساقه في معركة. وكان الناس يسمّونه «الساق الخشبية». في سنة 1814 كان نابليون قد خسر الحرب للتو، وكانت جيوش الأعداء في باريس. وكان دوميسنيل يدافع عن قصر فانسين. طُلب منه الاستسلام. ويقال إنه أجاب: «سأسلّمكم فانسين عندما تعيدون إليّ ساقي».\n\nانظر إلى البحيرة وجزرها: إنها تحمل اسمه."], "Les archives de la planète": ["أرشيف الكوكب", "متحف وحدائق ألبير كان · بولونيا", "مصرفي أرسل مصوّرين ليلتقطوا العالم كله، بالألوان، قبل 1914.", "انظر إلى حدائق متحف ألبير كان، مع ركنها الياباني.", "أنت تمر أمام متحف وحدائق ألبير كان في بولونيا.\n\nكان ألبير كان مصرفيًا ثريًا جدًا له حلم: أن يحفظ صورة للكوكب كله قبل أن يتغيّر. ومنذ سنة 1909 دفع لمصوّرين ليسافروا إلى نحو خمسين بلدًا. فعادوا بـ72000 صورة ملوّنة، من أوائل الصور الملوّنة في التاريخ. وأنشأ حول بيته أيضًا حدائق من كل أنحاء العالم: يابانية وإنجليزية وفرنسية.\n\nانظر فوق الجدران: تلمح أشجار حديقته اليابانية."], "L’île Renault": ["جزيرة رونو", "جزيرة سوغان · مصنع 1929–1992", "كانت هذه الجزيرة كلها مصنع سيارات، «قلعة العمال».", "انظر إلى جزيرة سوغان في وسط السين.", "أنت تجري بجانب جزيرة سوغان، في وسط السين عند بولونيا بيانكور.\n\nهنا وُلدت شركة رونو لصناعة السيارات. منذ سنة 1929 غطّت الشركة الجزيرة كلها بمباني المصانع. وعمل هنا عشرات الآلاف من العمال. واشتهر المصنع بإضراباته الكبرى. وخرجت منه آخر سيارة سنة 1992. واليوم في الجزيرة قاعات حفلات وحدائق.\n\nانظر إلى الجزيرة: تخيّلها مغطاة بالكامل بالمصانع."], "La voile qui suit le soleil": ["الشراع الذي يتبع الشمس", "لا سين ميوزيكال · شيغيرو بان، 2017", "عند طرف الجزيرة، شراع من الألواح الشمسية يدور مع الشمس.", "انظر إلى الشراع الكبير من الألواح الشمسية في «لا سين ميوزيكال».", "وصلت إلى طرف جزيرة في السين. المبنى الكبير هو «لا سين ميوزيكال»، قاعة حفلات افتُتحت سنة 2017.\n\nصمّم مهندساها، الياباني شيغيرو بان والفرنسي جان دو غاستين، قاعة على شكل بيضة مكسوّة بالخشب. وحولها شراع ضخم مغطى بالألواح الشمسية يدور خلال النهار ليتبع الشمس، مثل زهرة عبّاد الشمس.\n\nانظر إلى الشراع الكبير: بحسب ساعة النهار، لن يكون في المكان نفسه."], "La tour aux figures": ["برج الأشكال", "جزيرة سان جيرمان · جان دوبوفيه، 1988", "منحوتة بارتفاع 24 مترًا يمكنك أن تمشي داخلها، مغطاة بخطوط سوداء وحمراء وزرقاء.", "انظر إلى البرج الأبيض العالي بخطوطه السوداء والحمراء والزرقاء.", "وصلت إلى جزيرة سان جيرمان. أمامك برج يشبه رسمة طفل عملاقة.\n\nإنه «برج الأشكال» للفنان الفرنسي جان دوبوفيه، الرسام والنحات. تخيّله في الستينيات بأسلوبه الخاص: أشكال بيضاء محدّدة بالأسود، مع لمسات من الأحمر والأزرق. ولم يُبنَ إلا سنة 1988، بعد وفاته. ارتفاعه 24 مترًا، ويخفي في داخله درجًا حلزونيًا.\n\nانظر إلى خطوطه السوداء: كأنها رسمة واقفة."], "La porte de l'avenue Rapp": ["باب جادة راب", "الفن الحديث · جول لافيروت، 1901", "أجرأ باب في باريس، مع آدم وحواء وسحالٍ.", "قف على الرصيف المقابل وانظر إلى الباب الكبير في 29 جادة راب.", "أنت في جادة راب، قرب برج إيفل. قف على الرصيف المقابل لترى المبنى كاملًا.\n\nبناه نحو سنة 1900 جول لافيروت، مهندس جريء جدًا من أنصار «الفن الحديث»، الأسلوب المليء بانحناءات تشبه النباتات. الواجهة مغطاة بالخزف. ويحيط بالباب آدم وحواء، وعلى ألواح الباب سحالٍ من حديد. وفي سنة 1901 فاز بمسابقة أجمل واجهة في باريس.\n\nانظر إلى الباب: ابحث عن آدم وحواء والسحالي."], "Le Dôme des Invalides": ["قبة الإنفاليد", "كنيسة ملكية · جول أردوان مانسار، 1677", "انتظر نابليون عشرين سنة ليدخل قبره.", "من ساحة فوبان، ارفع عينيك إلى القبة الذهبية للإنفاليد.", "أنت أمام القبة الذهبية للإنفاليد، التي تراها من كل أنحاء باريس.\n\nكان الإنفاليد المستشفى الذي بناه الملك لويس الرابع عشر لجنوده الجرحى. وفي سنة 1677 عهد بالقبة إلى جول أردوان مانسار، مهندس فرساي. نابليون مدفون هنا. بعد هزيمته نُفي إلى سانت هيلانة، جزيرة صغيرة جدًا في وسط الأطلسي، ومات فيها سنة 1821. وفي سنة 1840 أُعيد جثمانه إلى باريس. وهو يرقد تحت هذه القبة.\n\nانظر إلى القبة من ساحة فوبان: إنها أجمل إطلالة."], "Rodin à l'hôtel Biron": ["رودان في قصر بيرون", "قصر · القرن الثامن عشر", "ماتيس وكوكتو وإيزادورا دنكان وريلكه كانوا جيران رودان.", "انظر إلى قصر بيرون وحديقة منحوتاته في شارع فارين.", "أنت أمام قصر بيرون، بيت كبير من القرن الثامن عشر له حديقة. إنه متحف رودان.\n\nأوغست رودان هو نحّات «المفكّر»، الرجل الجالس الغارق في التفكير، وذقنه على يده. في أوائل القرن العشرين كان هذا البيت يؤجَّر غرفةً غرفةً للفنانين. استأجر رودان بضع غرف سنة 1908، ثم البيت كله. وأهدى أعماله إلى الدولة بشرط واحد: أن يصبح البيت متحفه.\n\nانظر إلى الحديقة: «المفكّر» هناك."], "Le Grand Palais": ["القصر الكبير", "المعرض العالمي · 1900", "تحت سقفه الزجاجي العملاق تنافس المبارزون في أولمبياد 2024.", "ارفع عينيك إلى السقف الزجاجي والعربات البرونزية في الزوايا.", "أنت أمام «الغران باليه»، أي القصر الكبير، بسقفه الزجاجي الضخم.\n\nبُني من أجل المعرض العالمي سنة 1900، وهو عرض ضخم جاء فيه العالم كله ليعرض اختراعاته. تحت السقف الزجاجي، القاعة الرئيسية بحجم ملعبي كرة قدم. وخلال ترميمه استضاف منافسات المبارزة في أولمبياد باريس 2024. وأعيد افتتاحه بالكامل سنة 2025.\n\nانظر إلى زوايا السقف: عربات برونزية تجرّها خيول."], "L'avion des Galeries Lafayette": ["طائرة غاليري لافاييت", "مغامرة · جول فيدرين، 1919", "في 19 يناير 1919 هبطت طائرة على سطح هذا المتجر الكبير.", "ارفع عينيك إلى سطح غاليري لافاييت.", "أنت أمام «غاليري لافاييت»، المتجر الكبير في جادة هوسمان.\n\nفي سنة 1919، ولكي يجعل الناس يتحدثون عنه، عرض المتجر جائزة كبيرة لأول طيار يهبط على سطحه. قبِل التحدي جول فيدرين، طيار جريء. وفي 19 يناير 1919 هبط هناك بطائرته الصغيرة وتوقف قبل الحافة بقليل. لكن الطيران فوق باريس كان ممنوعًا: فدفع غرامة صغيرة.\n\nانظر إلى السطح: هبطت عليه طائرة قبل أكثر من مئة سنة."], "La tour Saint-Jacques": ["برج سان جاك", "برج أجراس قوطي · 1509–1523", "آخر ما بقي من كنيسة كان الحجّاج ينطلقون منها إلى كومبوستيلا.", "ارفع عينيك إلى برج سان جاك وتمثال باسكال عند قاعدته.", "أنت أمام برج قوطي عالٍ يقف وحيدًا في حديقة: برج سان جاك، بارتفاع 52 مترًا.\n\nكان برج أجراس كنيسة دُمّرت خلال الثورة. كانت الكنيسة تستقبل الحجّاج المنطلقين سيرًا على الأقدام إلى سانتياغو دي كومبوستيلا في إسبانيا، وهو حجّ مسيحي كبير. ويقال إن العالم بليز باسكال أجرى هنا في القرن السابع عشر تجارب على ضغط الهواء. وتمثاله يقف في الأسفل.\n\nانظر إلى القمة تمامًا: محطة أرصاد صغيرة ما زالت تقيس طقس باريس."], "La fontaine Stravinsky": ["نافورة سترافينسكي", "منحوتات · تينغلي ونيكي دو سان فال، 1983", "ست عشرة منحوتة ترقص على موسيقى سترافينسكي.", "انظر إلى الحوض ومنحوتاته الملوّنة التي تدور وترشّ الماء.", "أنت بجانب مركز بومبيدو، أمام حوض مليء بالمنحوتات المتحركة.\n\nفي سنة 1983 نصبها هنا زوجان فنانان. صنع جان تينغلي آلات سوداء تدور. وصنعت نيكي دو سان فال شخصيات مستديرة ملوّنة. ومعًا كرّما المؤلف الموسيقي إيغور سترافينسكي، بمنحوتات مستوحاة من موسيقاه: طائر النار، وحورية بحر، ومفتاح «صول» الموسيقي.\n\nانظر إلى الآلات السوداء وهي ترشّ المنحوتات الملوّنة."], "Saint-Eustache": ["كنيسة سان أوستاش", "كنيسة · 1532–1640", "هنا عُمّد ريشيليو وموليير ومدام دو بومبادور.", "انظر إلى الواجهة الضخمة لكنيسة سان أوستاش.", "أنت أمام سان أوستاش، كنيسة ضخمة في «لي هال»، سوق باريس الكبير في الماضي.\n\nبُنيت بين 1532 و1640. عُمّد فيها مشاهير: الكاردينال ريشيليو، وزير لويس الثالث عشر، وموليير، الكاتب المسرحي. وفي سنة 1778 أقام فيها المؤلف الموسيقي موزارت، وكان في باريس آنذاك، جنازة أمه. وفي أرغنها قرابة 8000 أنبوب.\n\nانظر إلى الواجهة، ثم ادخل واستمع إن كان الأرغن يعزف."], "La colonne de Catherine de Médicis": ["عمود كاترين دو ميديسيس", "بورصة التجارة · 1574 و2021", "عمود منجّم ملتصق بمبنى دائري لمتحف كبير للفن المعاصر.", "انظر إلى العمود المجوّف الملتصق بمبنى بورصة التجارة الدائري.", "أنت أمام بورصة التجارة، مبنى دائري. وملتصق به عمود غريب.\n\nيعود العمود إلى سنة 1574. إنه كل ما بقي من قصر كاترين دو ميديسيس، ملكة جاءت من إيطاليا، وأمّ ثلاثة ملوك فرنسيين. ويقال إن منجّمها كان يصعده ليقرأ المستقبل في النجوم. ومنذ سنة 2021 صار المبنى الدائري متحفًا للفن المعاصر، هو متحف جامع التحف فرانسوا بينو.\n\nانظر إلى قمة العمود: من هناك كان المنجّم يراقب السماء."], "La Rotonde de la Villette": ["روتوندا لا فيليت", "مركز جباية · كلود نيكولا لودو", "الأخت التوأم لروتوندا حديقة مونسو، في نهاية القناة.", "انظر إلى الروتوندا الكبيرة ذات الأعمدة في نهاية حوض لا فيليت.", "أنت في ساحة ستالينغراد، أمام مبنى دائري بأعمدة: روتوندا لا فيليت.\n\nقبل سنة 1860 كانت باريس محاطة بسور. لم يكن للدفاع، بل لفرض ضريبة على كل ما يدخل المدينة: النبيذ واللحم والخشب. صمّم المهندس كلود نيكولا لودو مراكز الجباية. وكان الباريسيون يكرهون هذا السور. لم يبقَ من مبانيه إلا أربعة، وهذا واحد منها.\n\nانظر إلى الأعمدة: معبد حقيقي، لمجرد مكتب ضرائب."], "Les Buttes-Chaumont": ["تلال شومون", "حديقة · أدولف ألفان، 1867", "مكبّ نفايات قديم تحوّل إلى أروع حديقة في باريس.", "انظر إلى الجرف والبحيرة والمعبد الصغير في أعلى الجزيرة.", "أنت أمام حديقة «بوت شومون»، في الدائرة التاسعة عشرة.\n\nكان هذا المكان كئيبًا في الماضي: مكبّ نفايات، ومقالع، وقريبًا منه موضع قديم كان يُشنق فيه المحكومون. وفي عهد الإمبراطور نابليون الثالث حوّل المهندس أدولف ألفان، الذي أنشأ كثيرًا من حدائق باريس، كل ذلك إلى حديقة. افتُتحت سنة 1867. الجرف والشلال والمغارة والبحيرة كلها تقريبًا من صنع الإنسان.\n\nانظر إلى المعبد الصغير في أعلى الجزيرة. اربط دراجتك: الحديقة أجمل مشيًا."], "L'Hôtel du Nord": ["فندق الشمال", "سينما · مارسيل كارنيه، 1938", "«الجو، الجو...»: أشهر جملة على ضفاف القناة.", "انظر إلى واجهة فندق الشمال، مقابل جسر المشاة على القناة.", "أنت على قناة سان مارتان، أمام «أوتيل دو نور»، أي فندق الشمال.\n\nكان في الماضي فندقًا صغيرًا متواضعًا. وكتب ابن أصحابه، الكاتب أوجين دابيت، رواية عنه. وفي سنة 1938 حوّله المخرج مارسيل كارنيه إلى فيلم شهير. وتقول فيه الممثلة أرليتي أشهر جملة في السينما الفرنسية، عن «الجو». ومع ذلك صُوّر الفيلم كله داخل استوديو.\n\nانظر إلى الواجهة والقناة: هذا هو المشهد الذي أعادوا بناءه من أجل الفيلم."], "Le lac de l'Opéra": ["بحيرة الأوبرا", "دار أوبرا · شارل غارنييه، 1875", "تحت الخشبة بحيرة ربما ألهمت «شبح الأوبرا».", "انظر إلى الواجهة المذهّبة لأوبرا غارنييه.", "أنت أمام أوبرا غارنييه، دار الأوبرا الكبرى في باريس، التي اكتملت سنة 1875.\n\nفي سنة 1861، مع بداية الأشغال، واجه المهندس شارل غارنييه مشكلة: الأرض مليئة بالماء. ولحماية الأساسات بنى خزانًا ضخمًا محكم الإغلاق تحت قاعة الجمهور. إنها «بحيرة» الأوبرا، وما زالت مليئة بالماء حتى اليوم. ويقال إنها ألهمت الكاتب غاستون لورو مخبأ «شبح الأوبرا».\n\nانظر إلى الواجهة الذهبية: تحت قدميك بحيرة."], "La Ruche": ["لا روش، خلية النحل", "مستعمرة فنانين · ألفريد بوشيه، 1902", "شاغال وسوتين وموديلياني عملوا تحت سقف آتٍ من معرض عالمي.", "من ممر دانتزيغ، انظر إلى روتوندا «لا روش» وبوابتها.", "أنت أمام «لا روش»، أي خلية النحل، مبنى دائري مختبئ في آخر حديقة.\n\nفي سنة 1900 أقامت باريس معرضًا عالميًا. وبعده جمع النحات ألفريد بوشيه أجزاء من الأجنحة المفكّكة. وكانت فكرته: أن يؤوي الفنانين الفقراء بثمن زهيد تقريبًا. عاش هنا رسّامون ونحّاتون مفلسون من كل أنحاء أوروبا، مثل مارك شاغال وأميديو موديلياني. وصاروا مشهورين فيما بعد.\n\nانظر إلى الروتوندا: سُمّيت خلية النحل لأن الفنانين كانوا يعملون فيها مثل النحل."], "L'atelier de Bourdelle": ["مرسم بورديل", "متحف فنان · 1885–1929", "مرسم نحّات بقي كما هو، والدخول إليه مجاني.", "انظر إلى التماثيل البرونزية الكبيرة في حديقة متحف بورديل.", "أنت أمام متحف بورديل، في مونبارناس.\n\nكان أنطوان بورديل نحّاتًا. بدأ مساعدًا لرودان، نحّات «المفكّر»، قبل أن يصبح هو نفسه مشهورًا. عمل في هذه المراسم من 1885 حتى وفاته سنة 1929. كل شيء ما زال هنا: تماثيل جصّية عملاقة، وبرونزيات، وكتل من الحجر. إنه متحف منذ سنة 1949، والدخول مجاني.\n\nانظر إلى الحديقة: تماثيله البرونزية الكبيرة تنتظرك."], "La tour Montparnasse": ["برج مونبارناس", "ناطحة سحاب · 1973", "ناطحة السحاب الوحيدة في باريس، وبسببها مُنعت كل الأخريات.", "ارفع عينيك إلى برج مونبارناس الداكن.", "أنت عند قدم برج مونبارناس، الذي اكتمل سنة 1973. ارتفاعه 210 أمتار.\n\nظلّ طويلًا أعلى مبنى في فرنسا. لكن الباريسيين يكرهونه. صدم الناس إلى درجة أنه بعد قليل مُنعت الأبراج في وسط باريس. لهذا يقف وحيدًا. ويحب الباريسيون أن يقولوا إن أجمل إطلالة على باريس هي من أعلى البرج: إنه المكان الوحيد الذي لا تراه منه.\n\nانظر إلى الأعلى تمامًا: هناك شرفة بانورامية في القمة."], "La Closerie des Lilas": ["كلوزري دي ليلا", "مقهى · 1847", "كان همنغواي يكتب هنا صباحًا، تحت أنظار أحد مارشالات نابليون.", "انظر إلى تراس كلوزري دي ليلا وتمثال المارشال ناي أمامه.", "أنت أمام «كلوزري دي ليلا»، مقهى افتُتح سنة 1847.\n\nصار ملتقى للفنانين: الرسام سيزان، والكاتب إميل زولا، ثم بيكاسو لاحقًا. وفي عشرينيات القرن العشرين كان إرنست همنغواي، صحفي أمريكي شاب مفلس، يأتي إلى هنا ليكتب في الصباح. وهو يتحدث عنه في «وليمة متنقلة»، كتابه عن سنواته في باريس. وأمام المقهى تمثال للمارشال ناي، أحد كبار جنرالات نابليون، الذي أُعدم رميًا بالرصاص قريبًا من هنا سنة 1815.\n\nانظر إلى التراس: هناك كان همنغواي يكتب."], "Le pavillon des Indes": ["جناح الهند", "المعرض العالمي · 1878", "قصر هندي من المعرض العالمي سنة 1878، نجا في حديقة في الضواحي.", "انظر إلى الجناح الخشبي المنحوت في حديقة بيكون بجانب السين.", "أنت في كوربفوا، أمام جناح خشبي صغير منحوت يبدو وكأنه جاء من بعيد.\n\nفي سنة 1878 أقامت باريس معرضًا عالميًا، عرضًا ضخمًا قدّمت فيه كل دولة أفضل ما عندها. وأمر أمير ويلز، ملك إنجلترا المستقبلي، ببناء جناحين لتقديم فن الهند، التي كانت آنذاك مستعمرة بريطانية. بعد المعرض دمّرت عاصفة أحدهما. وانتهى الآخر هنا، ونجا.\n\nانظر إلى الخشب المنحوت: قطعة صغيرة من الهند في الضواحي."], "La Grande Arche": ["القوس الكبير", "عمارة · يوهان أوتو فون سبريكلسن، 1989", "مكعب مجوّف طول ضلعه 110 أمتار، مُدار بزاوية 6.33 درجة.", "ارفع عينيك إلى القوس الكبير، ثم استدر نحو قوس النصر في البعيد.", "أنت عند قدم «لا غراند آرش»، أي القوس الكبير، مكعب مجوّف عملاق.\n\nافتُتح سنة 1989، في الذكرى المئتين للثورة الفرنسية. ومهندسه دنماركي، يوهان أوتو فون سبريكلسن. طول كل ضلع 110 أمتار: يمكن أن تتسع له كاتدرائية نوتردام. وهو يكمل خطًا مستقيمًا كبيرًا يمتد من اللوفر عبر الشانزليزيه مرورًا بقوس النصر. وهو مائل قليلًا، جزئيًا لأن محطة وطريقًا سريعًا يمرّان تحته.\n\nاستدر: في النهاية البعيدة ترى قوس النصر."], "Le CNIT": ["مبنى CNIT", "عمارة · كاملو ودو مايي وزيرفوس، 1958", "قبة من الخرسانة ترتكز على ثلاث نقاط فقط، تبعد إحداها عن الأخرى 218 مترًا.", "انظر إلى القبة الثلاثية الضخمة لمبنى CNIT على الساحة.", "أنت أمام مبنى CNIT، المركز الوطني للصناعات والتقنيات، مبنى على شكل شراع مثلث عملاق.\n\nإنه أول مبنى كبير في لا ديفانس. افتتحه الجنرال ديغول سنة 1958. وكان الهدف منه عرض الآلات المصنوعة في فرنسا. يرتكز سقفه الخرساني على ثلاث نقاط فقط، تبعد إحداها عن الأخرى 218 مترًا، من دون أي عمود في الوسط.\n\nانظر إلى السقف: قبة خرسانية ضخمة تقف على ثلاث أقدام."], "La Défense de Paris": ["الدفاع عن باريس", "تمثال · لويس إرنست بارياس، 1883", "تمثال من سنة 1883 أعطى اسمه لأكبر حي أعمال في أوروبا.", "ابحث على الساحة عن التمثال البرونزي «الدفاع عن باريس».", "أنت في لا ديفانس، حي الأعمال، أمام تمثال من البرونز.\n\nلماذا اسم «لا ديفانس»، أي الدفاع؟ في سنة 1870 كانت فرنسا في حرب مع بروسيا، وكانت باريس محاصرة. وقاتل الناس هنا لحماية المدينة. وفي سنة 1883 نُصب هذا التمثال تكريمًا للمدافعين عنها. اسمه «الدفاع عن باريس». فأخذ التقاطع اسمه، وعندما جاءت الأبراج بقي الاسم.\n\nانظر إلى التمثال بين الأبراج: هو الذي أعطى الحي اسمه."], "Le Castel Béranger": ["كاستل بيرانجيه", "الفن الحديث · هيكتور غيمار، 1898", "التحفة الأولى للمهندس الذي صمّم مداخل المترو.", "اقترب من بوابة كاستل بيرانجيه الأمامية، المصنوعة كلها من حديد ملتوٍ.", "أنت في شارع لافونتين، في الدائرة السادسة عشرة، أمام كاستل بيرانجيه.\n\nمهندسه هيكتور غيمار كان سيد «الفن الحديث»، الأسلوب المليء بالانحناءات المستوحاة من النباتات. وهو الذي صمّم مداخل مترو باريس الشهيرة. هنا، نحو سنة 1898، بنى أول عمارة سكنية كبيرة له، وصمّم كل شيء بلا استثناء: الواجهة، والدرابزين، وورق الجدران، حتى مقابض الأبواب.\n\nانظر إلى الباب الأمامي: انحناءاته المعدنية تبشّر بمداخل المترو."], "La piscine Molitor": ["مسبح موليتور", "آرت ديكو · لوسيان بوليه، 1929", "افتتحه طرزان، وظهر فيه البيكيني لأول مرة.", "انظر إلى الواجهة الصفراء على طراز آرت ديكو لمسبح موليتور.", "أنت أمام مسبح موليتور، الذي افتُتح سنة 1929. صُمّم مثل سفينة ركاب كبيرة، بنوافذ دائرية.\n\nفي الافتتاح كان أول من قفز في الماء جوني ويسمولر، بطل السباحة الأولمبي، وطرزان المستقبل في السينما. وفي سنة 1946 عرض هنا مصمم اسمه لويس ريار ثوب سباحة نسائيًا صغيرًا جدًا: البيكيني. أُغلق المسبح سنة 1989، وغطّى فنانو الغرافيتي جدرانه، ثم أعيد افتتاحه سنة 2014.\n\nانظر إلى النوافذ الدائرية والممرات: تشعر وكأنك على متن سفينة."], "Le Corbusier chez lui": ["لو كوربوزييه في بيته", "عمارة موليتور · 1934", "عاش لو كوربوزييه ثلاثين سنة في الطابق الأخير من هذا المبنى الزجاجي.", "ارفع عينيك إلى الطابقين الأخيرين من المبنى الزجاجي في شارع نونجيسير إي كولي.", "أنت أمام عمارة سكنية بواجهات زجاجية، بُنيت سنة 1934.\n\nمهندسها لو كوربوزييه هو أشهر مهندس معماري حديث. كان يحب الجدران البيضاء والنوافذ الكبيرة. بنى هذه العمارة مع ابن عمه، على الحدود تمامًا بين باريس وبولونيا. واحتفظ لنفسه بالطابقين الأخيرين. كان يرسم هناك في الصباح، وعاش فيها حتى وفاته سنة 1965.\n\nانظر إلى أعلى المبنى: هناك كانت شقته."], "La mairie de Tony Garnier": ["بلدية توني غارنييه", "آرت ديكو · توني غارنييه، 1934", "بلدية حديثة جدًا حلم بها عمدة بنّاء.", "انظر إلى الكتلة الخرسانية ذات الخطوط النظيفة لبلدية بولونيا.", "أنت في بولونيا، غرب باريس مباشرة، أمام مبنى البلدية.\n\nفي عشرينيات وثلاثينيات القرن العشرين نمت بولونيا بسرعة، مع مصانع رونو واستوديوهات السينما. وأراد العمدة مدينة حديثة. فطلب من توني غارنييه، مهندس من ليون يحب الخرسانة، أن يصمّم مبنى البلدية الجديد. واكتمل سنة 1934: مبنى بسيط بخطوط مستقيمة، بلا أعمدة ولا تذهيب.\n\nانظر إلى الواجهة البسيطة: بلدية حديثة لمدينة حديثة."], "La place des Vosges": ["ساحة فوج", "ساحة ملكية · 1612", "عاش فيكتور هوغو تحت هذه الأروقة ست عشرة سنة.", "انظر إلى الواجهات من الآجر الأحمر والأروقة حول الساحة.", "أنت في ساحة فوج، أقدم ساحة في باريس صُمّمت دفعة واحدة.\n\nافتُتحت سنة 1612 باسم «الساحة الملكية». كل البيوت متشابهة: آجر أحمر، وحجر أبيض، وأروقة في الأسفل. ولاحقًا سكن الكاتب فيكتور هوغو، مؤلف «البؤساء»، في الرقم 6، من 1832 إلى 1848. وشقته اليوم متحف مجاني.\n\nانظر إلى الواجهات المتطابقة، ثم ابحث عن الرقم 6."], "La girafe du roi": ["زرافة الملك", "حديقة الحيوانات · حديقة النباتات", "أول زرافة في فرنسا مشت إلى هنا، طوال الطريق من مرسيليا.", "انظر إلى مدخل حديقة حيوانات «جاردان دي بلانت».", "أنت في «جاردان دي بلانت»، أي حديقة النباتات، قرب حديقة الحيوانات، أقدم حديقة حيوانات في فرنسا.\n\nفي سنة 1826 أهدى حاكم مصر زرافة إلى ملك فرنسا شارل العاشر. لم يكن أحد في فرنسا قد رأى زرافة من قبل. وصلت بالسفينة إلى مرسيليا. ولأنها كانت أطول من أن تركب عربة تجرّها الخيول، مشت إلى باريس: 900 كيلومتر. كان اسمها «زرافة». استقرت هنا، وجاء أكثر من 100000 باريسي لرؤيتها. وجنّت الموضة: صارت النساء يصففن شعورهن «على طريقة الزرافة».\n\nانظر إلى الحظائر: هنا عاشت زرافة."], "Notre-Dame et le point zéro": ["نوتردام ونقطة الصفر", "كاتدرائية · 1163–2024", "أمام الكاتدرائية، لوحة صغيرة تحدد نقطة الصفر لكل طرق فرنسا.", "من رصيف الضفة اليسرى، انظر إلى ظهر نوتردام وبرجها المدبّب ودعاماتها الطائرة.", "أنت أمام نوتردام دو باري، أشهر كاتدرائية في العالم، بدأ بناؤها سنة 1163.\n\nفي 15 أبريل 2019 دمّر حريق سقفها وانهار برجها المدبّب على الهواء مباشرة. وبعد خمس سنوات من الأشغال أعيد افتتاحها في ديسمبر 2024، ببرج جديد مطابق للقديم. وفي الساحة أمامها لوحة صغيرة تحدد «نقطة الصفر»: منها تُقاس مسافات الطرق انطلاقًا من باريس.\n\nانظر إلى الأرض أمام الكاتدرائية: ابحث عن النجمة البرونزية الصغيرة."], "La fontaine Médicis": ["نافورة ميديسيس", "نافورة · نحو 1630", "نافورة ملكية اضطرت إلى التراجع ثلاثين مترًا لتفسح المجال لشارع.", "انظر إلى النافورة التي على شكل مغارة، والعملاق الذي يتجسس على العاشقين.", "أنت في حدائق اللوكسمبورغ، أمام نافورة على شكل مغارة في آخر حوض طويل.\n\nنحو سنة 1630 أمرت الملكة ماري دو ميديسيس، القادمة من فلورنسا في إيطاليا، ببنائها لتذكّرها بموطنها. وفي القرن التاسع عشر أضيفت تماثيل من أسطورة يونانية: في الأعلى، العملاق بوليفيموس يتجسس على عاشقين، آكيس وغالاتيا. والنهاية سيئة لآكيس.\n\nانظر إلى أعلى المغارة: العملاق يراقبهما. انتبه إلى أن الدراجات ممنوعة في الحدائق."], "L'Arena de la Chapelle": ["أرينا لا شابيل", "قاعة أولمبية · SCAU وNP2F، 2024", "القاعة الجديدة الوحيدة التي بُنيت داخل باريس لألعاب 2024.", "انظر إلى قاعة «أديداس أرينا» الكبيرة عند بوابة لا شابيل.", "أنت أمام «أرينا لا شابيل»، قاعة رياضية افتُتحت سنة 2024.\n\nإنها المنشأة الكبيرة الوحيدة التي بُنيت داخل باريس نفسها لأولمبياد 2024. وخلال الصيف الأولمبي استضافت منافسات الريشة الطائرة والجمباز الإيقاعي. وكانت الفكرة أيضًا إعادة الحياة إلى هذه المنطقة، المعزولة طويلًا عن بقية المدينة بالطريق الدائري وسكك الحديد.\n\nانظر إلى المبنى: قطعة من ألعاب باريس بقيت للحي."], "Le Centre aquatique olympique": ["المركز الأولمبي للرياضات المائية", "منشأة أولمبية · 2024", "المنشأة الأولمبية الدائمة الكبيرة الوحيدة التي بُنيت لألعاب باريس 2024.", "انظر إلى الهيكل الخشبي الضخم والسقف المقوّس للمركز.", "أنت أمام المركز الأولمبي للرياضات المائية، مقابل ملعب فرنسا (ستاد دو فرانس).\n\nبُني لألعاب 2024 الأولمبية، وهو المنشأة الرياضية الدائمة الكبيرة الوحيدة التي شُيّدت لتلك الألعاب. هيكله من الخشب وسقفه كبير ومقوّس، لتقليل التلوث. استضاف مسابقات الغطس وكرة الماء. واليوم يأتي سكان الحي والمدارس للسباحة هنا.\n\nانظر إلى السقف الخشبي: صُمّم ليبقى بعد الألعاب."], "La basilique des rois": ["كاتدرائية الملوك", "كاتدرائية · الأب سوجيه، 1144", "مهد الطراز القوطي، وهنا دُفن ملوك فرنسا.", "انظر إلى واجهة كاتدرائية سان دوني، ثم ادخل لترى نوافذ الزجاج الملوّن الكبيرة.", "أنت أمام كاتدرائية سان دوني، شمال باريس مباشرة.\n\nكان القديس دوني أول أسقف لباريس. تقول الأسطورة إنه قُطع رأسه في مونمارتر نحو سنة 250، ثم مشى حتى هنا حاملًا رأسه بين يديه. بُنيت كنيسة فوق قبره. ونحو سنة 1140 أعاد الأب سوجيه بناءها بأعمدة رشيقة ونوافذ زجاجية ملوّنة ضخمة: هكذا وُلد الطراز القوطي. ودُفن هنا تقريبًا كل ملوك فرنسا.\n\nانظر إلى الواجهة: خلفها ترقد قبور الملوك."], "Le canal Saint-Denis": ["قناة سان دوني", "قناة · 1821", "ستة كيلومترات من الممشى على الماء، من نهر السين إلى لا فيليت.", "انظر إلى القناة وأهوستها والممر المحاذي لها باتجاه باريس.", "أنت على ضفة قناة سان دوني، التي افتُتحت سنة 1821.\n\nتربط نهر السين في سان دوني بحوض لا فيليت في باريس، على مسافة تزيد قليلًا على ستة كيلومترات. ظلّت طويلًا محاطة بالمصانع: كانت المراكب تنقل الفحم والخشب والبضائع، وكانت الخيول تجرّها من الممر المحاذي للماء.\n\nانظر إلى الممر بجانب القناة: حيث كانت الخيول تمشي، يركب الناس اليوم الدراجات."], "La colonne de Juillet": ["عمود يوليو", "نصب تذكاري · 1840", "قبل العمود، كان من المفترض أن يقوم هنا فيل عملاق.", "ارفع عينيك إلى العمود وإلى روح الحرية الذهبية في أعلاه، في ساحة الباستيل.", "أنت في ساحة الباستيل، أمام عمود ارتفاعه 47 مترًا يعلوه تمثال ذهبي.\n\nلا يخلّد ثورة 1789، بل ثورة أخرى. في يوليو 1830، ثار الباريسيون ثلاثة أيام وطردوا الملك شارل العاشر. تُسمّى هذه الأيام «الأيام الثلاثة المجيدة». ويرقد تحت العمود من قُتلوا في المعارك. وقبله، أراد نابليون أن يقيم هنا نافورة على شكل فيل عملاق، لكن لم يُصنع منها سوى نموذج.\n\nانظر إلى التمثال الذهبي في القمة: إنه يحتفي بالحرية."], "Le faubourg des ébénistes": ["حيّ صانعي الأثاث", "حِرَف · منذ القرن الخامس عشر", "هنا عمل النجّارون بلا معلّم يفرض عليهم القواعد.", "ادفع بوابة في شارع فوبور سانت أنطوان وانظر إلى ساحات الحرفيين.", "أنت في شارع فوبور سانت أنطوان، شارع طويل يبدأ من الباستيل.\n\nفي العصور الوسطى، كان على الحرفي في باريس أن يلتزم بقواعد صارمة جدًا لمهنته وأن يدفع الضرائب. لكن في القرن الخامس عشر سمح الملك لويس الحادي عشر للحرفيين المقيمين هنا بالعمل بحرية. فتدفّق النجارون وصانعو الأثاث الفاخر. وطوال قرون صار الحيّ عاصمة الأثاث.\n\nانظر إلى الساحات والممرات: إنها ورش الأمس."], "Le donjon de Vincennes": ["برج فانسين", "قلعة ملكية · 1370", "أعلى برج قلعة في أوروبا، وسُجن فيه فيلسوف كبير.", "ارفع عينيك إلى برج فانسين، البرج المربّع العالي في القلعة.", "أنت أمام قلعة فانسين، شرق باريس. في وسطها يرتفع برج مربّع ضخم: البرج الرئيسي.\n\nاكتمل نحو سنة 1370 في عهد الملك شارل الخامس. ارتفاعه نحو خمسين مترًا، وهو أعلى برج قلعة في أوروبا. ثم صار سجنًا. في سنة 1749 سُجن هنا الفيلسوف دوني ديدرو بسبب أفكاره الحرّة أكثر من اللازم. وكان صديقه جان جاك روسو يأتي مشيًا لزيارته.\n\nانظر إلى البرج: خلف هذه الجدران سُجن ديدرو."], "Le Train Bleu": ["لو ترين بلو", "مطعم محطة · 1900", "مطعم محطة فيه 41 لوحة، بُني لمعرض 1900 العالمي.", "ارفع عينيك على الدرج في محطة ليون نحو النوافذ الكبيرة لمطعم لو ترين بلو.", "أنت في محطة ليون، أمام مطعم «لو ترين بلو» (القطار الأزرق).\n\nافتُتح لمعرض 1900 العالمي. أرادت شركة السكك الحديدية التي تربط باريس بالبحر المتوسط مطعمًا فخمًا: تذهيب وثريات و41 لوحة تصوّر المدن التي تمرّ بها قطاراتها، حتى الريفييرا. واسمه مأخوذ من قطار فاخر شهير كان يذهب إلى نيس وموناكو.\n\nانظر إلى الأسقف المرسومة: تستحق الزيارة ولو لفنجان قهوة."], "Le mariage de Picasso": ["زواج بيكاسو", "كاتدرائية أرثوذكسية · 1861", "يوم تزوّج بيكاسو تحت قباب ذهبية على شكل بصلة.", "ارفع عينيك إلى قباب الكاتدرائية الذهبية في شارع دارو.", "أنت أمام كاتدرائية القديس ألكسندر نيفسكي، بقبابها الذهبية على شكل بصلة. إنها الكنيسة الروسية الكبرى في باريس، افتُتحت سنة 1861.\n\nفي سنة 1918 تزوّج هنا الرسام بابلو بيكاسو من أولغا خوخلوفا، راقصة روسية في «الباليه الروسي»، أحدث فرقة رقص في زمنها. وكان شهوده ثلاثة أصدقاء من الكتّاب والشعراء المشهورين: جان كوكتو وماكس جاكوب وغيوم أبولينير.\n\nانظر إلى القباب الذهبية: تحتها مشى بيكاسو ليتزوّج."], "L'Élysée avant les présidents": ["الإليزيه قبل الرؤساء", "قصر رئاسي · 1718–1722", "محظية ملك، ثم إمبراطور يتنحّى، ثم الرؤساء.", "انظر إلى بوابة قصر الإليزيه المحروسة، دون أن تتوقف.", "أنت في شارع فوبور سانت أونوريه، أمام بوابة تحرسها الشرطة. خلفها قصر الإليزيه.\n\nهنا يعيش رئيس الجمهورية الفرنسية ويعمل. بُني القصر في مطلع القرن الثامن عشر لكونت. وفي سنة 1753 اشترته مدام دو بومبادور، محظية الملك لويس الخامس عشر. وفي سنة 1815، بعد هزيمته في واترلو مباشرة، وقّع نابليون هنا تنازله عن العرش: تخلّى عن السلطة. ومنذ 1873 صار مقرّ الرؤساء.\n\nانظر إلى البوابة، لكن لا تطل الوقوف: الشرطة لا تحب ذلك."], "Le musée d'Ennery": ["متحف دينري", "متحف · مجموعة كليمانس دينري، 1908", "سبعة آلاف قطعة آسيوية مخبّأة في قصر بجادة فوش.", "انظر إلى واجهة متحف دينري في جادة فوش.", "أنت في جادة فوش، أمام متحف صغير جدًا وقليل الشهرة.\n\nنحو سنة 1900، كانت باريس مفتونة بآسيا. جمعت كليمانس دينري، زوجة كاتب مسرحي مشهور، قطعًا من الصين واليابان: نحو 7000 قطعة. كثير منها «نيتسوكي»، تماثيل يابانية صغيرة منحوتة كانت تُعلَّق بالكيمونو. وأوصت بمنزلها ومجموعتها للدولة. افتُتح المتحف سنة 1908.\n\nانظر إلى الواجهة: خلفها آلاف الكنوز الصغيرة من آسيا."], "Le palais d'Iéna": ["قصر إيينا", "عمارة · أوغست بيريه، 1939", "قصر من الخرسانة صُمّم لعرض السدود والجسور.", "انظر إلى أعمدة قصر إيينا، رفيعة في الأسفل وتتّسع في الأعلى.", "أنت أمام قصر إيينا، مبنى كبير من الخرسانة اكتمل سنة 1939.\n\nأثبت مهندسه أوغست بيريه أن الخرسانة يمكن أن تكون جميلة، فلقّبوه «شاعر الخرسانة». كان المبنى مخصّصًا لمتحف للأشغال الكبرى: الجسور والسدود. واليوم يضم المجلس الاقتصادي والاجتماعي والبيئي، وهو مجلس يقدّم المشورة للحكومة.\n\nانظر إلى الأعمدة: رفيعة في الأسفل وأعرض في الأعلى، وفي الخرسانة حصى صغيرة خضراء ووردية."], "Le palais Galliera": ["قصر غالييرا", "قصر · ليون جينان، 1878–1894", "قصر بُني لمجموعة لم تصل أبدًا.", "انظر إلى قصر غالييرا وحديقته، مقابل متحف الفن الحديث.", "أنت أمام قصر غالييرا، قصر حجري وسط حديقة.\n\nكانت دوقة غالييرا أرستقراطية إيطالية فاحشة الثراء. في سنة 1878 بنت هذا القصر لتعرض فيه لوحاتها وتهديها لباريس. لكن في سنة 1886 طرد قانونٌ عائلات ملوك فرنسا السابقين، ومنهم أصدقاؤها. فغضبت واحتفظت بلوحاتها في إيطاليا. وبقي القصر فارغًا. ومنذ 1977 صار متحف الموضة في باريس.\n\nانظر إلى هذا القصر الفخم: بُني للوحات، وانتهى به الأمر يضم الفساتين."], "La maison Yves Saint Laurent": ["دار إيف سان لوران", "متحف · دار أزياء 1974–2002", "طوال ثلاثين سنة تقريبًا، صُمّمت الأزياء الراقية خلف هذه النوافذ.", "انظر إلى نوافذ القصر في 5 جادة مارسو.", "أنت في جادة مارسو، أمام قصر أنيق في المدينة.\n\nكان إيف سان لوران من أعظم مصمّمي الأزياء في القرن العشرين. هو من ألبس النساء بدلة السموكينغ والبنطال. في سنة 1974 أسّس داره هنا. وطوال ثلاثين سنة تقريبًا وُلدت مجموعاته بين هذه الجدران. ومنذ 2017 صار متحفًا: ترى مشغله وكأنه خرج للتو.\n\nانظر إلى النوافذ العليا: هناك كان يرسم."], "Deyrolle": ["ديرول", "متجر علوم طبيعية · منذ 1831", "فراشات وحيوانات محنّطة ولوحات مدرسية، في شارع دو باك منذ 1888.", "انظر إلى واجهة ديرول في 46 شارع دو باك.", "أنت في شارع دو باك، أمام ديرول، متجر لا يشبه أي متجر آخر.\n\nتأسّس سنة 1831 ليبيع المتاحفَ الحيواناتِ المحنّطة والحشرات والأصداف. ولوحاته المصوّرة الكبيرة عن النباتات والحيوانات عُلّقت في فصول أجيال من تلاميذ فرنسا. في سنة 2008 دمّر حريق كل شيء تقريبًا. ثم أُعيد بناء المتجر.\n\nاصعد إلى الطابق العلوي: أسد ودبّ وحمار وحشي في انتظارك."], "Le Lutetia": ["لوتيسيا", "فندق فاخر · 1910", "فندق فاخر لزبائن بون مارشيه، ثم مكان اللقاءات سنة 1945.", "انظر إلى واجهة لوتيسيا على طراز الفن الجديد ولوحتها في جادة راسباي.", "أنت في جادة راسباي، أمام لوتيسيا، فندق كبير افتُتح سنة 1910.\n\nبناه أصحاب «بون مارشيه»، المتجر الكبير المجاور، ليستقبلوا زبائنهم الأثرياء. خلال الحرب العالمية الثانية احتلّ الجيش الألماني باريس واستقرّ في الفندق. وفي سنة 1945، مع نهاية الحرب، استقبل لوتيسيا المرحّلين العائدين من المعسكرات النازية. وكانت العائلات تأتي إلى هنا حاملة صورًا، على أمل أن تجد قريبًا.\n\nانظر إلى اللوحة على الواجهة: إنها تذكّر بتلك اللقاءات."], "La rue Gaston-Gallimard": ["شارع غاستون غاليمار", "دار نشر · هنا منذ 1929", "شارع أُعيدت تسميته باسم ناشره.", "انظر إلى لافتة شارع غاستون غاليمار وباب دار النشر.", "أنت في شارع غاستون غاليمار، شارع صغير في الدائرة السابعة.\n\nغاليمار أشهر دار نشر في فرنسا، أسّسها غاستون غاليمار سنة 1911. انتقلت إلى هنا سنة 1929، ثم سُمّي الشارع باسمه. نشرت لمارسيل بروست وألبير كامو وجان بول سارتر وأنطوان دو سانت إكزوبيري، مؤلف «الأمير الصغير».\n\nانظر إلى الباب: مرّ منه بعض أعظم كتّاب القرن العشرين."], "L'Institut de France": ["معهد فرنسا", "كلية الأمم الأربع · لوي لو فو", "تحت هذه القبة يجلس «الخالدون» بمعاطفهم الخضراء.", "انظر إلى القبة الذهبية لمعهد فرنسا، مقابل جسر الفنون.", "أنت على ضفة نهر السين، أمام مبنى بقبة: معهد فرنسا.\n\nفي سنة 1661 أوصى الكاردينال مازاران، الذي حكم فرنسا حين كان لويس الرابع عشر طفلًا، بثروته لبناء مدرسة. ومنذ 1805 يضم المبنى الأكاديمية الفرنسية، التي ترعى اللغة الفرنسية وتكتب قاموسها. يُلقَّب أعضاؤها الأربعون بـ«الخالدين». وفي المراسم الكبرى يرتدون معطفًا أخضر مطرّزًا ويحملون سيفًا.\n\nانظر إلى القبة: تحتها يجلس الخالدون."], "Les Folies Bergère": ["فولي بيرجير", "قاعة استعراض · 1869", "البار الذي رسمه مانيه، وراقصة منحوتة على الواجهة.", "انظر إلى واجهة فولي بيرجير الذهبية على طراز آرت ديكو وإلى راقصتها.", "أنت أمام «فولي بيرجير»، أشهر قاعة استعراض في باريس، افتُتحت سنة 1869. قاعة الاستعراض مسرح للأغاني والرقص والفقرات المتنوعة.\n\nجعل الرسام إدوار مانيه منها مسرح آخر لوحة كبيرة له، «حانة في فولي بيرجير»: نادلة بنظرة حزينة خلف منضدتها. أما الواجهة الحالية فتعود إلى 1926. والراقصة الذهبية عليها كانت حقيقية: ليلا نيكولسكا، ولا ترتدي شيئًا تقريبًا.\n\nانظر إلى الراقصة الذهبية على الواجهة."], "Le Bouillon Chartier": ["بويون شارتييه", "مطعم شعبي · 1896", "ما زالوا يكتبون الحساب على مفرش الورق.", "انظر إلى لافتة بويون شارتييه في آخر الفناء.", "أنت أمام «بويون شارتييه»، مطعم افتُتح سنة 1896.\n\nفي أواخر القرن التاسع عشر، كان «البويون» مطعمًا بسيطًا ورخيصًا للعمّال. افتتح الأخوان شارتييه هذا المطعم، ولم تتغيّر صالته تقريبًا: مرايا وثريات وسقف زجاجي كبير. وما زالت الأدراج الصغيرة التي كان الزبائن الدائمون يحفظون فيها مناديلهم موجودة. ولا يزال النُدُل يكتبون الحساب على مفرش الطاولة الورقي.\n\nانظر إلى الطابور: بعد 130 سنة، ما زال الناس يأتون للأكل هنا."], "Le Jardin d'acclimatation": ["حديقة التأقلم", "حديقة · نابليون الثالث، 1860", "أقدم مدينة ملاهٍ في باريس بدأت مشروعًا علميًا.", "انظر إلى مدخل حديقة التأقلم على طرف الغابة.", "أنت أمام «جاردان داكليماتاسيون» (حديقة التأقلم)، في غابة بولونيا غرب باريس.\n\nهي اليوم مدينة ملاهٍ للأطفال. لكن الإمبراطور نابليون الثالث افتتحها سنة 1860 بفكرة جدّية: أراد العلماء أن يعرفوا هل تستطيع الحيوانات والنباتات القادمة من أنحاء العالم أن تعتاد مناخ فرنسا، أي أن «تتأقلم». وشيئًا فشيئًا صارت النزهة المفضّلة للعائلات الباريسية.\n\nانظر إلى المدخل: حديقة وُلدت من تجربة علمية."], "La Folie Saint-James": ["فولي سان جيمس", "حديقة ترفيه · فرانسوا جوزيف بيلانجيه، 1777", "صخرة مزيّفة بارتفاع اثني عشر مترًا، نزوة مموّل أفلس.", "انظر إلى الصخرة الكبرى في حديقة فولي سان جيمس.", "أنت في نويي، في «فولي سان جيمس».\n\nفي القرن الثامن عشر، كان الأثرياء جدًا يبنون «الفولي»: حدائق مليئة بمبانٍ صغيرة للمتعة فقط. في سنة 1772 اشترى كلود بودار دو سان جيمس، أمين خزينة البحرية الملكية، هذه الضيعة. أراد حديقة باذخة. وأغرب ما فيها صخرة مزيّفة ضخمة طولها 43 مترًا، فيها حمّامات وشلّال. أفلس سنة 1787.\n\nانظر إلى الصخرة الكبرى: هي التي أفلسته."], "Le cimetière américain de Suresnes": ["المقبرة الأمريكية في سورين", "مقبرة عسكرية · مون فاليريان", "نحو 1600 جندي أمريكي يرقدون هنا، في مواجهة باريس.", "انظر إلى صفوف الصلبان البيضاء والكنيسة الصغيرة على منحدر مون فاليريان.", "أنت في سورين، على تلة مون فاليريان، أمام مقبرة عسكرية أمريكية.\n\nخلال الحرب العالمية الأولى، ومنذ 1917، جاء جنود أمريكيون للقتال في فرنسا. مات كثيرون منهم ولم يعودوا إلى ديارهم. يرقد نحو 1600 منهم في هذه المقبرة، تحت صفوف منتظمة من الصلبان البيضاء. وفي سنة 1919 جاء الرئيس الأمريكي وودرو ويلسون ليلقي خطابًا هنا.\n\nانظر إلى الصلبان البيضاء: إنها تواجه باريس."], "La légende de Piaf": ["أسطورة بياف", "لوحة تذكارية · 72 شارع بيلفيل", "وُلدت على درج هذا البيت؟ أجمل أساطير بيلفيل.", "ابحث عن اللوحة في 72 شارع بيلفيل.", "أنت في شارع بيلفيل، أمام الرقم 72. هنا لوحة تتحدث عن إديت بياف.\n\nبياف هي الصوت الكبير للأغنية الفرنسية، صوت «لا في آن روز». كانت أمها تغنّي في الشوارع، وأبوها بهلوانًا. تقول اللوحة إنها وُلدت هنا على الدرج، سنة 1915. في الحقيقة، تذكر شهادة ميلادها مستشفى تونون القريب. لكن القصة تليق بها كثيرًا فاحتفظ بها الحيّ.\n\nانظر إلى الدرج: من هنا تبدأ أسطورة بياف."], "Le Père-Lachaise": ["مقبرة بير لاشيز", "مقبرة · 1804", "اضطرّوا إلى نقل موليير إليها حتى يرغب الباريسيون في الدفن هنا.", "انظر إلى المدخل الكبير لمقبرة بير لاشيز.", "أنت أمام بير لاشيز، أكثر مقبرة زيارةً في العالم.\n\nحين افتُتحت سنة 1804 لم يرغب فيها أحد: كانت بعيدة جدًا عن الوسط. فخطرت لأحدهم فكرة. في سنة 1817 نُقلت إلى هنا رفات كاتبين مشهورين: موليير، الكاتب المسرحي، ولافونتين، مؤلف الحكايات الخرافية. بعدها صار الباريسيون يريدون أن يُدفنوا بقربهما. واليوم يرقد هنا عازف البيانو شوبان والمغنية إديت بياف وجيم موريسون من فرقة «ذا دورز».\n\nانظر إلى الممرات الصاعدة على التلة: مدينة صغيرة من القبور تحت الأشجار."], "L'Atelier des Lumières": ["أتولييه دي لوميير", "فن رقمي · مسبك قديم، 1835", "مسبك للبحرية تحوّل إلى قاعة عرض ضوئي عملاقة.", "انظر إلى قاعة المسبك القديم في أتولييه دي لوميير.", "أنت أمام «أتولييه دي لوميير» (ورشة الأنوار)، مصنع قديم في الدائرة الحادية عشرة.\n\nفي سنة 1835 افتتح أخوان هنا مسبكًا يصنع قطعًا معدنية ضخمة للسفن والقطارات. أُغلق المصنع في القرن العشرين. وفي سنة 2018 صار مركزًا للفن الرقمي. تُعرض فيه لوحات كبار الفنانين مثل فان غوخ وكليمت بأحجام هائلة على الجدران والأرض، مع الموسيقى.\n\nانظر إلى المبنى القديم من الطوب: في الداخل، تمشي في قلب اللوحات."], "Le Cirque d'Hiver": ["سيرك الشتاء", "سيرك · جاك هيتورف، 1852", "تحت هذا السقف اختُرعت الأرجوحة الطائرة.", "انظر إلى مبنى سيرك الشتاء المستدير ذي الأضلاع العشرين.", "أنت أمام «سيرك الشتاء»، مبنى مستدير له عشرون ضلعًا. إنه سيرك حقيقي مبني من الحجر.\n\nافتتحه الإمبراطور نابليون الثالث سنة 1852. وفي سنة 1859 قدّم هنا لاعب الجمباز جول ليوتار أول عرض على الأرجوحة الطائرة في التاريخ. حتى إنه أعطى اسمه للباس البهلوانيين الضيّق، «الليوتار». ومنذ 1934 تديره عائلة بوغليون، سلالة كبيرة من أهل السيرك.\n\nانظر إلى تماثيل الخيول على الواجهة: تعرف فورًا ما يجري في الداخل."], "Le musée de Cluny": ["متحف كلوني", "المتحف الوطني للعصور الوسطى", "حمّامات رومانية و«السيدة ووحيد القرن» تحت سقف واحد.", "انظر إلى الجدران الرومانية القديمة عند زاوية جادة سان ميشيل، ثم إلى القصر القوطي خلفها.", "أنت أمام متحف كلوني، متحف العصور الوسطى.\n\nيجمع مبنيين قديمين جدًا. أولًا حمّامات رومانية بُنيت نحو سنة 200، حين كانت باريس تُسمّى لوتيس. ثم بيت قوطي من القرن الخامس عشر، كان مقرّ رؤساء دير كلوني. وكنزه مجموعة من ست سجّادات جدارية نُسجت نحو سنة 1500: «السيدة ووحيد القرن».\n\nانظر إلى جدران الطوب القديمة: إنها ما تبقّى من الحمّامات الرومانية."], "Le dôme du Val-de-Grâce": ["قبة فال دو غراس", "كنيسة · فرانسوا مانسار، 1645", "قبة ملكة انتظرت ثلاثًا وعشرين سنة لتُرزق بطفل.", "ارفع عينيك إلى القبة الكبيرة لفال دو غراس.", "أنت أمام فال دو غراس، كنيسة بقبة كبيرة.\n\nكانت آن النمساوية أميرة إسبانية. في سنة 1615 تزوّجت ملك فرنسا لويس الثالث عشر. لكنهما بقيا ثلاثًا وعشرين سنة بلا طفل، وهي كارثة لملكة. فنذرت: إن رُزقت بابن، ستبني كنيسة رائعة. وفي سنة 1638 وُلد لويس الرابع عشر. وفي سنة 1645، وهو في السابعة، وضع الحجر الأول.\n\nانظر إلى القبة: إنها وعد ملكة تحقّق."], "La Grande Mosquée": ["المسجد الكبير", "مسجد · 1926", "تكريم للجنود المسلمين الذين ماتوا من أجل فرنسا.", "انظر إلى المئذنة المربّعة للمسجد الكبير.", "أنت أمام مسجد باريس الكبير، بمئذنته المربّعة التي يبلغ ارتفاعها 33 مترًا.\n\nخلال الحرب العالمية الأولى، مات عشرات الآلاف من الجنود المسلمين من أجل فرنسا، وكان معظمهم من شمال أفريقيا. بُني هذا المسجد تكريمًا لهم، وافتُتح سنة 1926. وعمارته مستوحاة من مساجد المغرب.\n\nانظر إلى المئذنة، ثم ادخل المقهى: شاي بالنعناع وحلويات في فناء من الفسيفساء."], "Les Gobelins": ["الغوبلان", "مصنع ملكي · 1667", "ما زالت السجّادات الجدارية تُنسج هنا يدويًا، كما في عهد لويس الرابع عشر.", "انظر إلى واجهة مصنع الغوبلان في جادة الغوبلان.", "أنت أمام مصنع الغوبلان، في الدائرة الثالثة عشرة.\n\nنحو سنة 1450 أقام صبّاغ اسمه جيهان غوبلان ورشته هنا، بجانب نهر صغير صار اليوم مخفيًا تحت المدينة. وفي سنة 1667 حوّله كولبير، وزير الملك لويس الرابع عشر، إلى مصنع ملكي. نُسجت هنا سجّادات جدارية ضخمة لتزيين قصور الملك، مثل فرساي.\n\nانظر إلى نوافذ الورش الكبيرة: ما زال النسّاجون يعملون هنا يدويًا لحساب الدولة، كما قبل 350 سنة."], "Le cimetière de Levallois": ["مقبرة لوفالوا", "مقبرة · شارع بودان", "ثائرة وغوستاف إيفل وموريس رافيل في المقبرة نفسها.", "انظر إلى مدخل مقبرة لوفالوا في شارع بودان.", "أنت أمام مقبرة لوفالوا، مقبرة صغيرة هادئة.\n\nيرقد هنا أناس مختلفون جدًا. كانت لويز ميشيل معلّمة. في سنة 1871 قاتلت في «الكومونة»، انتفاضة الباريسيين، ثم نُفيت إلى معتقل أشغال شاقة في كاليدونيا الجديدة. وهي مدفونة هنا. وكذلك غوستاف إيفل، مهندس البرج، وموريس رافيل، مؤلف «البوليرو».\n\nانظر إلى الممرات: ثائرة ومهندس وملحّن، جيران إلى الأبد."], "Le cimetière des chiens": ["مقبرة الكلاب", "مقبرة حيوانات أليفة · 1899", "رين تين تين، وباري كلب سان برنار الذي أنقذ أربعين شخصًا.", "انظر إلى نصب الكلب باري قرب المدخل مباشرة.", "أنت أمام مقبرة الكلاب، على جزيرة في نهر السين في أنيير.\n\nافتُتحت سنة 1899، وهي من أوائل مقابر الحيوانات الأليفة في العالم، أسّسها محامٍ وصحفية هي مارغريت دوران. عند المدخل نصب يكرّم باري، كلب سان برنار من جبال الألب. تقول الأسطورة إنه أنقذ أربعين شخصًا تاهوا في الثلج. وفي الداخل يرقد رين تين تين، الكلب نجم الأفلام الأمريكية.\n\nانظر إلى القبور الصغيرة: كلاب وقطط وخيول، مع كلمات محبة من أصحابها."], "Le château d'Asnières": ["قصر أنيير", "قصر · جاك أردوان مانسار دو ساغون، 1750–1752", "قصر ماركيز، بناه أحد أحفاد مهندسي فرساي.", "انظر إلى قصر أنيير المطلّ على البلدة.", "أنت في أنيير، خارج باريس مباشرة، على نهر السين. أمامك قصر من القرن الثامن عشر.\n\nبُني نحو سنة 1750 لماركيز، ابن أحد وزراء الملك لويس الخامس عشر. ومهندسه من أحفاد الرجل الذي بنى فرساي. لاحقًا جذبت ضفاف أنيير الرسامين. رسم جورج سورا المستحمّين هنا سنة 1883، ورسم فنسنت فان غوخ الجسور سنة 1887.\n\nانظر إلى الواجهة: لمسة من فرساي، على طراز بيت ريفي."], "Le stade olympique de Colombes": ["الملعب الأولمبي في كولومب", "ملعب · ألعاب 1924 الأولمبية", "ملعب «عربات النار» عاد إلى الخدمة في ألعاب 2024.", "انظر إلى مدرّجات ملعب إيف دو مانوار في كولومب.", "أنت أمام ملعب كولومب، غرب باريس.\n\nكان الملعب الرئيسي لألعاب 1924 الأولمبية. فاز هنا عدّاءان بريطانيان بالذهب: هارولد أبراهامز في سباق 100 متر، وإريك ليدل في سباق 400 متر. كان ليدل شديد التديّن ورفض الركض يوم الأحد. تُروى قصتهما في فيلم «عربات النار» بموسيقاه الشهيرة. وجُدّد الملعب واستُخدم مجددًا في ألعاب باريس 2024.\n\nانظر إلى المدرّجات: مئة سنة بين دورتين أولمبيتين."], "La Coupole": ["لا كوبول", "مطعم بيرة · 1927", "مطعم آرت ديكو كان يأتيه كل مونبارناس للعشاء والرقص.", "انظر إلى اللافتة الكبيرة لـ«لا كوبول» في جادة مونبارناس.", "أنت في جادة مونبارناس، أمام «لا كوبول»، مطعم ضخم افتُتح سنة 1927.\n\nفي عشرينيات القرن الماضي، كانت مونبارناس مركز الفن الحديث. عاش هنا رسامون وكتّاب من كل أنحاء العالم. وصارت «لا كوبول» ملتقاهم: الرسام بيكاسو والراقصة جوزفين بيكر والكاتب الأمريكي همنغواي. أما أعمدة الصالة فقد رسمها فنانو الحي.\n\nانظر إلى الأعمدة المرسومة في الداخل: الصالة لم تتغيّر تقريبًا."], "Le lion de Denfert": ["أسد دنفير", "منحوتة · أوغست بارتولدي", "أسد بلفور، بحجم مصغّر، في وسط الساحة.", "انظر إلى الأسد البرونزي الرابض في وسط ساحة دنفير روشرو.", "أنت في ساحة دنفير روشرو، أمام أسد كبير من البرونز.\n\nإنه نسخة من أسد عملاق منحوت في الصخر في بلفور، مدينة في شرق فرنسا. في سنة 1870، خلال الحرب ضد بروسيا، صمدت بلفور أمام العدو 103 أيام. وكان يقودها العقيد دنفير روشرو، الذي سُمّيت الساحة باسمه. والنحّات هو أوغست بارتولدي، صانع تمثال الحرية في نيويورك.\n\nانظر إلى الأسد، ثم إلى المبنى الصغير بجانبه: إنه مدخل سراديب الموتى."], "La piscine de la Butte-aux-Cailles": ["مسبح بوت أو كاي", "مسبح · لوي بونييه، 1924", "مسبح وُلد من بئر تجلب ماءً دافئًا من عمق 600 متر.", "انظر إلى واجهة المسبح من الطوب والنافورة في ساحة بول فيرلين.", "أنت في «بوت أو كاي»، حيّ يشبه القرية بشوارعه المرصوفة بالحجارة ومقاهيه الصغيرة.\n\nفي سنة 1893 حُفرت هنا بئر عميقة جدًا، نحو 600 متر. يصعد الماء وحده، وهو دافئ: 25 درجة. وبفضله بُني مسبح افتُتح سنة 1924، بسقف خرساني كبير مقوّس. وفي ساحة بول فيرلين نافورة تعطي الماء نفسه.\n\nانظر إلى النافورة: يأتي سكان الحي ليملؤوا قواريرهم منها."], "L'aqueduc d'Arcueil": ["قناطر أركوي", "قناة مياه · 1613–1623 وستينيات القرن التاسع عشر", "قناتان مائيتان إحداهما فوق الأخرى، فوق آثار قناة ثالثة رومانية.", "انظر إلى الأقواس الكبيرة للقناة وهي تعبر الوادي.", "أنت في أركوي، جنوب باريس، أمام قناة مياه: جسر بُني لنقل الماء.\n\nفي الحقيقة هما اثنتان، واحدة فوق الأخرى. أرادت الملكة ماري دو ميديسيس ماءً لنوافير قصرها في لوكسمبورغ. فأمرت ببناء القناة الأولى، التي اكتملت سنة 1623. وفي ستينيات القرن التاسع عشر بُنيت فوقها قناة ثانية أعلى.\n\nانظر إلى الأقواس: أقواس الملكة في الأسفل، وأقواس القرن التاسع عشر في الأعلى."], "La Naumachie": ["الناوماكيا", "حديقة ترفيه · حديقة دوق شارتر", "بركة تحيط بها أعمدة، يُقال إنها من كنيسة بنتها ملكة لملك.", "اقترب من البركة وانظر إلى هذه الأعمدة نصف المهدّمة.", "هذه البركة المحاطة بالأعمدة من آخر ما تبقّى من حديقة دوق، ابن عمّ الملك لويس السادس عشر، كانت مليئة بأطلال مزيّفة للمتعة فقط.\n\nأغرب ما فيها الأعمدة: يُقال إنها جاءت من كنيسة بنتها الملكة كاترين دو ميديسيس لقبر زوجها الملك هنري الثاني.\n\nانظر إلى الأعمدة: كانت تحرس ملكًا.", "قبل أن تصبح حديقة عامة، كانت هذه الحديقة الخاصة لدوق شارتر، ابن عمّ الملك لويس السادس عشر. في سبعينيات القرن الثامن عشر أراد حديقة تفاجئك عند كل خطوة. فوُضع فيها هرم مصري وطاحونة هولندية وأطلال مزيّفة. وكان الناس يسمّونها «فولي شارتر».\n\nهذه البركة من القطع القليلة المتبقّية. لكن الأعمدة أقدم بكثير من الحديقة.\n\nقبل ذلك بقرنين فقدت الملكة كاترين دو ميديسيس زوجها الملك هنري الثاني. فبنت له كنيسة بجانب كاتدرائية سان دوني، حيث يُدفن ملوك فرنسا. وفي سنة 1719 هُدمت الكنيسة.\n\nيُقال إن أعمدتها انتهت هنا، بجانب الماء. صُنعت لتحرس ملكًا، وصارت اليوم خلفية للبطّ."], "Musée Cernuschi": ["متحف سيرنوشي", "مجموعة فنية · جادة فيلاسكيز", "بوذا برونزي ياباني عملاق عبر نصف العالم ليستقرّ قرب حديقة مونسو.", "انظر إلى البيت خلف السياج: في الداخل، أحدهم ينتظر منذ أكثر من قرن.", "خلف هذا السياج عاش هنري سيرنوشي، مموّل عاشق لآسيا.\n\nفي سنة 1871 وجد في اليابان تمثالًا ضخمًا لبوذا من البرونز نجا من حريق معبده. فاشتراه، وفكّكه قطعة قطعة، وأعاد تركيبه في بيته في باريس.\n\nانظر إلى البيت: ما زال البوذا هناك، والمتحف مجاني.", "هنري سيرنوشي مموّل وُلد في ميلانو واستقرّ في باريس. رجل ثري، وفوق كل شيء فضولي جدًا. في سنة 1871 انطلق في رحلة طويلة إلى آسيا مع صديق ناقد فني. كانت اليابان قد انفتحت على العالم للتو، بعد قرون من الانغلاق على الأجانب.\n\nفي طوكيو، في حيّ ميغورو، صادف تمثالًا عملاقًا: بوذا من البرونز. احترق معبده، ونجا البوذا، وظلّ جالسًا في العراء سنة كاملة تحت المطر.\n\nاشتراه سيرنوشي. وفكّكه قطعة قطعة، وشحنه، وأعاد صنّاع البرونز الباريسيون تركيبه هنا، في بيته.\n\nصار البيت متحفًا، ولم يتحرّك البوذا بعدها أبدًا. عبر نصف العالم لينتهي على بُعد خطوات من حديقة مونسو. وإلقاء التحية عليه مجاني."], "Proust, 45 rue de Courcelles": ["بروست، 45 شارع كورسيل", "عنوان كاتب · شارع كورسيل", "هنا عاش مؤلف واحدة من أشهر الروايات في العالم.", "ابحث عن المبنى الحجري في 45 شارع كورسيل.", "عاش مارسيل بروست، مؤلف «البحث عن الزمن المفقود»، إحدى أشهر الروايات في العالم، في هذا المبنى منذ سنة 1900.\n\nفي طفولته كان يقضي أيام الخميس في حديقة مونسو. وقريبًا من هنا، في صالون رسامة، دخل المجتمع الراقي الذي سيصفه لاحقًا في كتبه.\n\nانظر إلى المبنى: هنا بدأت رواية عظيمة تتشكّل.", "اسمه مارسيل بروست. في طفولته كانت حديقة مونسو ملعبه. يقضي فيها بعد ظهر أيام الخميس، يوم العطلة المدرسية آنذاك.\n\nفي سنة 1900 انتقلت عائلته إلى هذا المبنى الأنيق. كان مارسيل في نحو الثلاثين، ولم يكن مشهورًا بعد. لكنه يملك موهبة: يلاحظ كل شيء.\n\nوقريبًا من هنا، كانت رسامة اسمها مادلين لومير تستقبل في بيتها نخبة المجتمع الباريسي: أرستقراطيين وفنانين وكتّابًا. كان بروست يذهب. يستمع، ويراقب، ويتذكّر كل حركة وكل جملة.\n\nبعد سنوات، صار كل هؤلاء شخصيات «البحث عن الزمن المفقود»، روايته الضخمة. الصبي الصغير من حديقة مونسو وجد موضوعه على بُعد بضعة شوارع من هنا.\n\nهيا، المرحلة الأخيرة: عُد إلى الفندق."]}}, "ru": {"ui": {"homeTitle": "Открой Париж\nвместе с Mayflower", "homeSub": "Кольцевые маршруты от отеля и обратно, с историей в каждой точке.", "start": "Начать", "kicker": "Париж, 8-й округ · Прогулки с гидом", "step1": "Шаг 1 из 3", "step2": "Шаг 2 из 3", "modeQ": "Как ты хочешь гулять?", "walk": "Пешком", "run": "Бег", "bike": "Велосипед", "scoot": "Самокат", "cont": "Дальше", "distQ": "Какое расстояние?", "catTitle": "Выбери маршрут", "mustSee": "Обязательно", "moreIdeas": "Ещё идеи", "byDist": "По расстоянию", "allThemes": "Все", "thArt": "Искусство", "thLit": "Литература", "thBelle": "Прекрасная эпоха и шоу", "thNature": "Парки и леса", "thSeine": "Сена и набережные", "thRoyal": "Короли и история", "thModern": "Современный Париж", "distHint": "Примерное время с остановками на истории.", "seeLoop": "Показать маршрут", "yourLoop": "Шаг 3 из 3 · Твой маршрут", "stories": "истории", "story1": "история", "lookLabel": "Куда смотреть:", "steps": "остановки", "chooseLoop": "Выбери прогулку", "mapAltPre": "Пешая петля от отеля: ", "swipe": "Листай", "readStory": "Читать историю", "zoomIn": "Приблизить", "zoomOut": "Отдалить", "fit": "Весь маршрут", "parisAll": "Весь Париж", "lessStory": "Вернуться к короткой версии", "locMe": "Где я?", "locWait": "Ищу, где ты…", "locFar": "Ты не в Париже: синяя точка показана у отеля", "locDenied": "Геолокация запрещена: синяя точка показана у отеля", "locNone": "Геолокация недоступна: условная позиция", "startWalk": "Начать прогулку", "backMap": "Назад к карте", "navNext": "Следующая остановка", "navGps": "Геолокация включена", "navFar": "Ты в стороне от маршрута · листай вручную", "navManual": "Без геолокации · листай вручную", "navWait": "Ищу, где ты…", "navSim": "Демо-режим", "navSimFar": "Вне маршрута · демо", "navPause": "Пауза", "navPlay": "Продолжить", "navSkip": "Следующая остановка", "navEnd": "Завершить", "navSoon": "Скоро", "navHere": "Ты здесь", "navGoOn": "Идём дальше", "navReadNow": "Слушать историю", "navStop": "остановка", "navRead": "Читать историю", "navLater": "Позже", "navDoneTitle": "Снова у отеля", "navDoneText": "Прогулка окончена. Спасибо, что гулял с нами!", "navRemaining": "осталось", "navRecenter": "Показать, где я", "next": "Следующая история", "foStart": "СТАРТ", "byTheme": "По темам", "otherRoutes": "Другие маршруты", "inKm": "В км", "inTime": "По времени", "allDist": "Все", "catOne": "маршрут", "catMany": "маршрута", "catEmpty": "Для этого фильтра маршрутов нет.", "mustTag": "Обязательно", "withAudio": "текст + аудио", "exLine": "Лондон, Турин, Флоренция: улицы вокруг твоего отеля названы в честь городов Европы. Вот почему.", "exKicker": "Твой отель", "exTitle": "Mayflower, улица Москвы", "exText": "Ты выходишь из отеля на улицу Москвы (rue de Moscou). Посмотри на таблички вокруг: Лондон, Турин, Флоренция, Санкт-Петербург… Эти названия здесь не случайно.\n\nВ начале 1820-х годов двое мужчин придумали здесь новый квартал: Йонас Хагерман, шведский банкир, живший в Париже, и Сильвен Миньон, королевский слесарь, ставший застройщиком. В центре — большая площадь, вокруг — улицы с названиями европейских городов. В 1826 году проект утвердили. Так родился Европейский квартал.\n\nПоэтому, гуляя, представь, как вокруг тебя рисуется карта: каждая улица будто открывает дверь в другой город. Ты всё ещё в Париже, но твой квартал уже зовёт в путешествие.\n\nMayflower, открытый в 2015 году в доме в стиле Османа, — твоя отправная точка для прогулки по воображаемой Европе в самом сердце 8-го округа.", "exListen": "Послушать отрывок", "exRead": "Прочитать историю твоего отеля", "exClose": "Закрыть историю", "startHint": "Ведёт тебя от остановки к остановке и предлагает историю, когда ты на месте. Кнопка «Где я?» просто показывает тебя на карте.", "askKicker": "Перед стартом", "askTitle": "Включить геолокацию?", "askWhy": "Во время прогулки твоя геолокация нужна, чтобы показать тебя на карте и предупредить, когда ты подходишь к остановке. Дальше решаешь ты: послушать историю, прочитать её или оставить на потом.", "askPrivacy": "Твоё местоположение остаётся в телефоне. Оно нигде не сохраняется и никуда не отправляется, а отслеживание заканчивается вместе с прогулкой.", "askYes": "Включить и начать", "askNo": "Начать без геолокации", "askCancel": "Отмена", "locBlocked": "Телефон блокирует геолокацию: переходи дальше кнопкой «Следующая остановка».", "helpKicker": "Геолокация заблокирована", "helpTitle": "Телефон не передаёт местоположение", "helpWhy": "Гид не смог запросить доступ: геолокация выключена для браузера. Чтобы включить:", "helpIos1": "Настройки › Конфиденциальность и безопасность › Службы геолокации: вкл.", "helpIos2": "Ниже: Сайты Safari (или Chrome) › «При использовании».", "helpIos3": "Вернись сюда, нажми «aA» слева от адреса › Настройки веб-сайта › Геопозиция › Спрашивать.", "helpAnd1": "Настройки › Местоположение: вкл.", "helpAnd2": "В Chrome нажми на замок слева от адреса › Разрешения › Местоположение › Разрешить.", "helpRetry": "Попробовать снова", "helpClose": "Продолжить без геолокации", "navReadIt": "Читать", "cardAudio": "Текст + аудио · ", "cardText": "Только текст", "listenDur": "Слушать · ", "mediaBoth": "Читать или слушать · ", "mediaLong": "полная версия ", "mediaText": "Только чтение · аудио недоступно на этом устройстве", "readMore": "Читать дальше · ", "listen": "Слушать", "vPlay": "Слушать", "vStop": "Выключить голос", "vc_butler": "Дворецкий", "vc_titi": "Парижский мальчишка", "vc_diva": "Дива", "vAutoOn": "Автоголос: вкл.", "vAutoOff": "Автоголос: выкл.", "vWho": "Кто рассказывает?", "uMin": "мин", "uH": "ч"}, "modes": {"bike": {"chooseLoop": "Выбери веломаршрут", "startWalk": "Поехали", "mapAltPre": "Велопетля от отеля: ", "navDoneText": "Поездка окончена. Спасибо, что катался с нами!"}, "run": {"chooseLoop": "Выбери пробежку", "startWalk": "Начать пробежку", "mapAltPre": "Беговой маршрут от отеля: ", "navDoneText": "Пробежка окончена. Молодец, хорошего восстановления!"}, "scoot": {"chooseLoop": "Выбери маршрут на самокате", "startWalk": "Поехали", "mapAltPre": "Петля на самокате от отеля: ", "navDoneText": "Поездка окончена. Спасибо, что катался с нами!"}}, "intro": {"butler": "Вот мы и на месте. Устраивайся, я расскажу.", "titi": "Так, стоп! Послушай-ка, это мощная история.", "diva": "Ах, дорогой мой… послушай эту историю."}, "loops": {"parc-monceau": ["Парк Монсо, прогулка среди художников", "Статуи, причуды герцога Шартрского, Камондо и Пруст."], "court-15": ["Пятнадцать минут: мост художников", "Европейский мост, который Кайботт и Моне написали в один и тот же год."], "court-20": ["От площади Клиши до кладбища художников", "Маршал, защищавший Париж, а потом Далида, Дега и Трюффо."], "court-30": ["Железная церковь и мост художников", "Железная церковь, притворяющаяся каменной, и мост Кайботта и Моне."], "court-45": ["Сорок пять минут: от Клиши до Новых Афин", "«Мулен Руж», салон Шопена и Жорж Санд, дом художника и мюзик-холл Жозефины Бейкер."], "court-60": ["Меньше часа: от Троицы до Сент-Огюстена", "Легендарный орган, купол «Прентан», часовня Людовика XVI и железная церковь."], "etoile-secrets": ["Тайны площади Звезды", "Бальзак, куртизанка, музыкальный скандал и самолёт под Аркой."], "plaine-monceau-divas": ["Дивы равнины Монсо", "Сара Бернар, три Дюма и замок, построенный ради бала."], "passy-balzac-eiffel": ["От Бальзака до Эйфелевой башни", "Дворец, вошедший в историю, писатель в бегах и любимый мост кино."], "foch-bois-boulogne": ["Авеню Фош и Булонский лес", "Самая широкая авеню Парижа, последний дом Дебюсси и швейцарское шале на острове."], "montmartre-boheme": ["Богемный Монмартр", "«Мулен Руж», Пикассо, осёл-художник и 311 «я тебя люблю»."], "rive-droite-royale": ["Королевский правый берег", "Мост Александра III, Биржа коммерции, Вандомская колонна и Мадлен."], "course-monceau": ["Круги по парку Монсо", "Два круга мимо позолоченных ворот, пирамиды и огромной статуи."], "course-cours-la-reine": ["От Елисейских Полей до Кур-ла-Рен", "Королевский променад, Черчилль, юный Пруст и финиш «Тур де Франс»."], "course-champ-de-mars": ["Трокадеро и Марсово поле", "Водяные пушки, мост, спасённый в последний момент, и праздник 1790 года."], "course-muette": ["Ла-Мюэтт и Ранела", "Авеню Виктора Гюго, первый полёт человека и импрессионизм."], "course-grande-jatte": ["Гранд-Жатт Сёра", "Вдоль Сены, где Сёра написал своё воскресенье, а Эйфель строил свою башню."], "course-berges-tuileries": ["Набережные и Тюильри", "Автострада, ставшая парком, камни Бастилии и «Кувшинки»."], "course-longchamp": ["Лоншан и Багатель", "Каскад из ненастоящих скал, исчезнувшее аббатство и замок, построенный на спор."], "course-allee-des-cygnes": ["Лебединая аллея и парк Андре-Ситроен", "Длинный узкий остров, маленькая Свобода, Аполлинер и круглый Дом радио."], "course-auteuil": ["Лес: от Отёя до «Ролан Гаррос»", "Сад Шекспира, барьеры Отёя, оранжереи и грунтовые корты."], "course-ile-saint-louis": ["По набережным до острова Сен-Луи", "Мост с замками, самый старый мост, придуманный остров и букинисты."], "course-saint-ouen": ["Доки Сент-Уэна и Батиньоль", "Сена у Леваллуа, блошиный рынок, стальной народный дом и Верлен."], "course-quartier-latin": ["Сен-Жермен, Люксембург и Латинский квартал", "Литературное кафе, меридиан Сен-Сюльпис, маленькая Свобода и римская арена."], "course-villette": ["Ла-Виллет и канал Урк", "Большой бассейн Наполеона, стальная сфера, старые бойни и ворота Короля-Солнца."], "course-saint-cloud": ["Парк Сен-Клу", "Холм казнённых, каскад Месье, исчезнувший замок и Париж у твоих ног."], "course-bercy": ["Берси и восточные набережные", "Порт в королевском рву, министерство с ногами в воде, вино и книги."], "course-montsouris": ["Монсури и юг Парижа", "Сартр и Бовуар, знак меридиана, город мира и парк Брассенса."], "course-vincennes": ["В Венсен по Зелёной аллее", "Виадук, ставший садом, фонтан с газированной водой, дворец 1931 года и озеро генерала."], "course-iles-ouest": ["Острова запада", "Архивы планеты, остров Renault, солнечный парус и башня Дюбюффе."], "velo-rive-gauche": ["Левый берег: от модерна до ампира", "Живая стена, дерзкая дверь, Наполеон и пагода универмага."], "velo-nouvelle-athenes": ["Новые Афины художников", "Кайботт, Шопен у Шеффера, «лоретки» и самолёт на крыше."], "velo-halles-beaubourg": ["От Ле-Аль до Бобура", "Колонна астролога, крещение Мольера и машины Тэнгли."], "velo-canal-buttes": ["Канал Сен-Мартен и Бют-Шомон", "Маршал, египетский храм, Арлетти и тайное озеро Оперы."], "velo-montparnasse": ["Монпарнас художников", "«Улей» Шагала, склеп Пастера и отвергнутый «Бальзак» Родена."], "velo-la-defense": ["До Большой арки", "Часовня в память о принце, индийский дворец и статуя, давшая имя Дефансу."], "velo-annees-30": ["От «безумных» двадцатых к тридцатым", "Гимар, Ле Корбюзье у себя дома, бикини в «Молитор» и «Тур» в Парк-де-Пренс."], "velo-grande-seine": ["Большая петля по Сене", "От Виктора Гюго до королевского жирафа, от Берси до Орсе, вдоль набережных."], "velo-saint-denis": ["Сен-Дени: от королей до Олимпиады", "Арены 2024 года, базилика королей и канал Сен-Дени."], "velo-vincennes": ["Бастилия и Венсенский замок", "Слон Гавроша, мебельщики Предместья и королевский донжон."], "scooter-faubourg": ["Предместье дворцов", "Свадьба Пикассо, президентский дворец и железная церковь."], "scooter-chaillot": ["Шайо, холм музеев", "Нэцкэ, искусство Азии, бетонный дворец и ателье высокой моды."], "scooter-rive-gauche": ["Левый берег издателей", "Бабочки, универмаг, дворец-отель, издатель и академики."], "scooter-music-halls": ["Мюзик-холлы 9-го округа", "Стеклянный купол, орган Мессиана, ревю, восковые фигуры и «бульон»."], "scooter-ouest": ["Нёйи и Сюрен: сады и память", "Императорский парк, причуда финансиста и американское кладбище с видом на Париж."], "scooter-belleville": ["Бельвиль и Менильмонтан", "Госпиталь Генриха IV, легенда Пиаф, Пер-Лашез и императорский цирк."], "scooter-quartier-latin": ["От Латинского квартала до Гобеленов", "Римские термы, купол по королевскому обету, мечеть, больница Шарко и гобелены."], "scooter-asnieres": ["Аньер и Коломб, на том берегу", "Луиза Мишель, Рин Тин Тин, сундуки Vuitton и олимпийский стадион 1924 года."], "scooter-sud": ["На юг, к акведуку", "«Ла Куполь», Бельфорский лев, бассейн с тёплой водой, Бисетр и акведук Марии Медичи."]}, "stops": {"La Rotonde de Chartres": ["Ротонда Шартр", "Архитектура · Леду, 1787", "Этот маленький храм с колоннами похож на садовое украшение. На самом деле это была таможня.", "Посмотри на круглое здание с колоннами у входа в парк.", "Ты у входа в парк Монсо, перед маленьким круглым зданием с колоннами.\n\nОно похоже на украшение сада, но это была налоговая контора. В 1787 году Париж окружил себя стеной, чтобы брать пошлину со всего, что ввозили в город: с вина, мяса, дров. Архитектор Клод-Никола Леду спроектировал для неё таможенные павильоны. Здесь внизу работали сборщики налогов, а наверху была гостиная герцога Шартрского, владельца парка.\n\nПосмотри на верхний этаж: оттуда герцог любовался своим садом."], "Le pont de l'Europe": ["Европейский мост", "Живопись · Кайботт и Моне, 1877", "Два художника-импрессиониста написали этот мост в один и тот же год.", "Посмотри на железные балки моста и на пути вокзала Сен-Лазар внизу.", "Ты стоишь на мосту, а прямо под тобой идут поезда вокзала Сен-Лазар. Когда отсюда в 1837 году отправился первый пассажирский поезд, железная дорога была ещё потрясающей новинкой: паровозы шли на пару, в шуме и дыму.\n\nЧерез несколько десятилетий парижский художник Гюстав Кайботт выбрал этот мост сюжетом картины. Он написал то, что видел: огромные железные балки, прохожих и современный Париж. Картина так и называется — «Европейский мост». В 1877 году его друг Клод Моне написал сам вокзал, с поездами и паром. Моне — это художник «Кувшинок».\n\nПосмотри на балки вокруг: Кайботт написал их 150 лет назад."], "Le maréchal Moncey": ["Маршал Монсей", "Памятник · Амеде Дублемар", "Маршал, которому было почти шестьдесят, защищал эти ворота Парижа.", "Подними глаза на большую статую в центре площади Клиши.", "Ты на площади Клиши. 200 лет назад Париж был окружён стеной, и здесь стояли одни из её ворот.\n\nВ 1814 году император Наполеон проигрывал войну почти всей Европе. Русские войска подошли к Парижу. Эти ворота защищал старый генерал, маршал Монсей, в основном с парижскими добровольцами. 30 марта они держались весь день. Вечером Париж всё же сдался, но их стойкость не забыли.\n\nПосмотри на большую статую в центре площади: это Монсей, а женщина, которую он защищает, — это Париж."], "Le cimetière de Montmartre": ["Кладбище Монмартр", "Место покоя художников · с 1825 года", "Далида, Дега и Трюффо покоятся в старом карьере, под мостом.", "Посмотри на мост улицы Коленкур, который проходит над могилами.", "Ты пришёл на кладбище Монмартр. С 1825 года оно лежит на дне старого карьера, так низко, что улица Коленкур проходит над могилами по мосту.\n\nЗдесь похоронены многие художники. Живописец Эдгар Дега, знаменитый своими балеринами. Писатель Стендаль, автор «Красного и чёрного». Кинорежиссёр Франсуа Трюффо. И певица Далида, одна из главных звёзд французской песни: на её могиле всегда свежие цветы.\n\nПосмотри на мост над кладбищем: машины едут прямо над могилами."], "Saint-Augustin, l'église en fer": ["Сент-Огюстен, железная церковь", "Церковь · Виктор Бальтар, 1860–1871", "Железная церковь, переодетая в камень.", "Посмотри на большой купол Сент-Огюстена в конце бульвара.", "Перед тобой церковь Сент-Огюстен. Снаружи она кажется каменной, но внутри — железо.\n\nЕё построили в 1860–1871 годах по проекту архитектора Виктора Бальтара. До этого он создал огромные железные павильоны Ле-Аль, старого продуктового рынка Парижа. Тогда железо было самым современным материалом. Бальтар поставил купол на тонкие металлические колонны. Это была одна из первых больших церквей Парижа, построенных таким способом.\n\nПосмотри на большой купол: он держится на железном каркасе."], "Le Moulin Rouge": ["«Мулен Руж»", "Кабаре · 6 октября 1889", "В его саду когда-то стоял гигантский слон.", "Посмотри на красные крылья мельницы на бульваре Клиши.", "Перед тобой «Мулен Руж», самое знаменитое кабаре в мире, с мельницей с красными крыльями.\n\nОно открылось 6 октября 1889 года, в тот же год, что и Эйфелева башня. В его саду даже стоял гигантский слон. Именно здесь прославился французский канкан: танцовщицы высоко вскидывают ноги, и разлетаются их нижние юбки. Художник Анри де Тулуз-Лотрек, завсегдатай кабаре, рисовал его афиши и писал его танцовщиц.\n\nПосмотри на крылья мельницы: они до сих пор крутятся."], "Le salon d'Ary Scheffer": ["Салон Ари Шеффера", "Музей романтической жизни · 1830-е", "По пятницам сюда заходили Шопен, Жорж Санд и Делакруа.", "Пройди до конца мощёного переулка, к маленькому дому с садом.", "В конце этого мощёного переулка прячется дом с садом: сегодня это Музей романтической жизни.\n\nВ 1830-е годы он принадлежал художнику Ари Шефферу. По пятницам вечером он принимал друзей-художников: пианиста Фредерика Шопена и его подругу, писательницу Жорж Санд, которая жила неподалёку, художника Эжена Делакруа, композитора Ференца Листа. Звучало фортепиано, говорили о живописи и о страстях.\n\nПосмотри на дом в конце переулка: сюда Шопен приходил играть."], "La maison de Gustave Moreau": ["Дом Гюстава Моро", "Музей художника · 1895", "Художник превратил свой дом в музей ещё при жизни.", "Посмотри на фасад дома Гюстава Моро на улице Ларошфуко.", "Ты проходишь мимо дома художника Гюстава Моро, сегодня это музей.\n\nВ конце XIX века Моро писал мифы, сны и фантастических существ. В 1895 году он принял необычное решение: превратить свой дом в музей ещё при жизни. Он построил две большие мастерские и развесил картины от пола до потолка. Умирая, он оставил всё государству: больше 1000 картин и тысячи рисунков.\n\nПосмотри на большие окна наверху дома: это его мастерские."], "Le Casino de Paris": ["Казино де Пари", "Мюзик-холл · улица Клиши", "Мистенгет, Морис Шевалье, а потом Жозефина Бейкер и «У меня две любви».", "Посмотри на фасад «Казино де Пари» на улице Клиши.", "Ты проходишь мимо «Казино де Пари» на улице Клиши. Несмотря на название, здесь не играют в азартные игры: это мюзик-холл, театр песен, танцовщиц и перьев.\n\nПосле Первой мировой войны здесь блистали главные звёзды того времени, например Мистенгет и Морис Шевалье. В 1931 году американская танцовщица, ставшая кумиром Парижа, Жозефина Бейкер, впервые спела здесь «У меня две любви»: «У меня две любви — моя страна и Париж». Песня стала её гимном.\n\nПосмотри на фасад: здесь родилась эта песня."], "La Trinité de Messiaen": ["Троица Мессиана", "Церковь · Теодор Баллю, 1861–1867", "Великий композитор играл здесь на органе шестьдесят один год.", "Посмотри на церковь Святой Троицы в конце улицы Шоссе-д'Антен.", "Перед тобой церковь Святой Троицы, построенная в 1861–1867 годах.\n\nЕё звезда — музыкант: Оливье Мессиан, один из величайших композиторов XX века, который обожал пение птиц. Он играл на органе этой церкви с 1931 года до своей смерти в 1992-м. Шестьдесят один год! Каждое воскресенье он импровизировал, и музыканты со всего мира приезжали его послушать.\n\nПосмотри на церковь: за её фасадом — орган Мессиана."], "Le Printemps": ["«Прентан»", "Универмаг · 1865", "Под крышей — витражный купол 1923 года.", "Посмотри на фасад «Прентан» и его купола на бульваре Осман.", "Перед тобой «Прентан», один из двух знаменитых универмагов на бульваре Осман, рядом с «Галери Лафайет».\n\nОн открылся в 1865 году и быстро стал храмом моды. Его сокровище спрятано под крышей: огромный купол из цветного стекла, установленный в 1923 году. Во время Второй мировой войны его разобрали, чтобы уберечь от бомбёжек. В 1972 году его вернул на место внук мастера, который его создал.\n\nПосмотри на купола на крыше: стеклянный купол прямо под ними."], "La chapelle expiatoire": ["Искупительная часовня", "Часовня · Пьер Фонтен, 1816–1826", "Здесь сначала были похоронены Людовик XVI и Мария-Антуанетта.", "Посмотри на часовню в глубине сквера Людовика XVI.", "Перед тобой маленькая часовня, спрятанная в саду. Она рассказывает о тёмной странице истории Франции.\n\nВ 1789 году началась Французская революция: народ восстал против короля. В 1793 году король Людовик XVI и его жена, королева Мария-Антуанетта, были гильотинированы на площади Согласия. Их тела бросили на маленьком кладбище — прямо здесь. Через двадцать лет к власти вернулся король: Людовик XVIII, брат Людовика XVI. Он велел выкопать их останки, а потом построил эту часовню, чтобы «искупить», то есть попросить прощения за их смерть.\n\nПосмотри на часовню в конце сада: здесь короля и королеву похоронили впервые."], "La dernière maison de Balzac": ["Последний дом Бальзака", "Писатель · улица Бальзака и улица Беррье", "Здесь Бальзак провёл последние годы, а баронесса снесла его дом... чтобы почтить его.", "Посмотри на особняк в доме 11 по улице Беррье и ротонду в его саду.", "Ты на улице Бальзака. Здесь стоял последний дом Оноре де Бальзака, одного из величайших французских романистов XIX века.\n\nШестнадцать лет Бальзак любил польскую графиню Эвелину Ганскую. Они жили далеко друг от друга и общались почти только письмами. В 1846 году он купил здесь дом и обустроил его для неё. В 1850-м они наконец поженились и поселились здесь. Через пять месяцев Бальзак умер в этом доме.\n\nПосмотри на угол улицы Беррье: там стоял дом Бальзака."], "L'hôtel de la Païva": ["Особняк Паива", "Куртизанка · Елисейские Поля, 25", "Её высадили из кареты на этой авеню, и она поклялась вернуться... и жить здесь.", "Посмотри на особняк в доме 25 на Елисейских Полях.", "Ты проходишь мимо красивого дома 25 на Елисейских Полях: это особняк Паива.\n\nВ XIX веке молодая женщина Эстер Лахман родилась в бедной семье в Москве и приехала в Париж ни с чем. Она стала куртизанкой — женщиной, которая жила за счёт богатых любовников. И стала самой богатой из них, известной как Паива. Рассказывают, что однажды мужчина высадил её из кареты на этой авеню. Она поклялась вернуться и жить здесь. После десяти лет стройки — вот её дом.\n\nПосмотри на фасад: за ним лестница из драгоценного жёлтого камня."], "La Flamme de la Liberté": ["Пламя Свободы", "Памятник · площадь Дианы", "Все думают, что его сделали для леди Дианы. А появилось оно на восемь лет раньше.", "Посмотри на золотое пламя в центре площади, над туннелем.", "Ты на площади Альма. Это большое золотое пламя — точная копия факела, который держит статуя Свободы в Нью-Йорке.\n\nАмериканская газета подарила его Парижу в 1989 году в благодарность французским мастерам, которые реставрировали статую. Через восемь лет, в 1997-м, принцесса Диана, бывшая жена английского принца Чарльза, погибла в автокатастрофе в туннеле прямо под ним. Люди приходили сюда с цветами. Никто этого не решал, но пламя стало её памятником.\n\nПосмотри на основание пламени: там часто лежат цветы и записки для Дианы."], "Un avion sous l'Arc": ["Самолёт под Аркой", "Памятник · Триумфальная арка", "7 августа 1919 года пилот пролетел на самолёте прямо под этой аркой.", "Подними глаза под большой свод Арки, а потом посмотри на огонь на земле.", "Ты перед Триумфальной аркой.\n\nВ 1919 году только что закончилась Первая мировая война. Париж готовил большой парад победы под Аркой. Но лётчикам, которые четыре года рисковали жизнью в небе, предстояло идти пешком. Молодой пилот Шарль Годфруа счёл это несправедливым. 7 августа 1919 года он пролетел на своём маленьком самолёте сквозь арку, едва в два раза шире его крыльев. Отделался простым предупреждением.\n\nПосмотри на проём Арки: представь, как через середину летит самолёт."], "Le Céramic Hôtel": ["Отель «Керамик»", "Модерн · авеню Ваграм, 34", "На авеню Ваграм целый фасад будто вырос, как растение.", "Подними глаза на коричнево-зелёный керамический фасад дома 34 по авеню Ваграм.", "Ты на авеню Ваграм, перед фасадом, покрытым керамическими листьями и цветами.\n\nВ 1904 году в моде был модерн — стиль, который повторяет изгибы растений. Архитектор Жюль Лавиротт построил этот дом, а мастер-керамист покрыл его узорами цвета земли и мха. На следующий год дом победил в конкурсе на самый красивый фасад Парижа.\n\nПосмотри на вход: кажется, будто здание выросло, как растение."], "Chez Sarah Bernhardt": ["У Сары Бернар", "Звезда · бульвар Перейр", "Первая в мире суперзвезда иногда спала в гробу и жила с большими кошками.", "Посмотри на дома вдоль бульвара Перейр, где она провела последние годы.", "Ты на бульваре Перейр, у дома, где Сара Бернар провела последние годы.\n\nСара Бернар была театральной актрисой конца XIX века. Ещё до появления кино она была звездой во всём мире, от Парижа до Нью-Йорка. Она любила шокировать: в её доме жили дикие звери, в спальне стоял скелет, а сама она фотографировалась лёжа в гробу.\n\nПосмотри на окна: за ними жила самая большая звезда своего времени."], "Les lecteurs de Dumas": ["Читатели Дюма", "Памятник · Гюстав Доре, 1883", "У ног Александра Дюма трое парижан с 1883 года читают один из его романов.", "Обойди сидящего Дюма: д'Артаньян на обратной стороне постамента.", "Ты на площади Генерала Катру, перед сидящим человеком: это Александр Дюма.\n\nВ XIX веке Дюма написал «Трёх мушкетёров» и «Графа Монте-Кристо». Его приключенческие романы читали все. Это и показывает статуя: у его ног женщина, рабочий и студент читают одну из его книг. А за спиной стоит на страже д'Артаньян, его мушкетёр.\n\nПосмотри за постамент: там д'Артаньян со шпагой в руке."], "Le château du banquier": ["Замок банкира", "Неоренессанс · особняк Гайяр", "Банкир построил себе копию замка Луары и открыл его балом на 2000 гостей.", "Посмотри на замок из кирпича и камня с остроконечными крышами на площади Генерала Катру.", "Перед тобой настоящий замок посреди Парижа.\n\nЭмиль Гайяр был очень богатым банкиром и обожал Ренессанс — эпоху королей XVI века. Он велел построить копию замка Блуа, знаменитого замка в долине Луары. На открытие в 1885 году он устроил костюмированный бал больше чем на 2000 гостей, а сам нарядился королём Генрихом II.\n\nПосмотри на башенки и острые крыши: замок Луары в двух шагах от парка Монсо."], "Le Majestic": ["«Мажестик»", "Дворец-отель · авеню Клебер, 19", "В этом отеле Пруст ужинал с Джойсом, и здесь закончили войну во Вьетнаме.", "Посмотри на парадный фасад The Peninsula в доме 19 по авеню Клебер.", "Ты проходишь мимо роскошного отеля на авеню Клебер. Сегодня это The Peninsula, а раньше он назывался «Мажестик».\n\nВ 1922 году здесь прошёл ужин с четырьмя гигантами искусства: писателем Марселем Прустом, ирландским писателем Джеймсом Джойсом, композитором Игорем Стравинским и художником Пабло Пикассо. Во время Второй мировой войны здесь был штаб немецкой армии. А в 1973 году здесь подписали мирные соглашения, которые вывели американцев из войны во Вьетнаме.\n\nПосмотри на парадный фасад: это здание видело целый век истории."], "Le parvis des droits de l'homme": ["Площадь Прав человека", "Смотровая площадка · Трокадеро", "На этой террасе сделаны худшее и лучшее фото XX века.", "Выйди на середину террасы, лицом к Эйфелевой башне, между крыльями дворца.", "Ты на широкой площади Трокадеро, между двумя крыльями дворца Шайо. За Сеной стоит Эйфелева башня.\n\n23 июня 1940 года Франция только что проиграла войну Германии. Гитлер был в Париже всего один раз, очень рано утром, и сфотографировался прямо здесь, на фоне Эйфелевой башни. Через восемь лет, в 1948 году, война уже закончилась. В этом же дворце собралась ООН и приняла Всеобщую декларацию прав человека: текст о том, что все люди рождаются свободными и равными.\n\nПосмотри на площадь под ногами: её назвали площадью Прав человека в честь этого текста."], "Le cimetière de Passy": ["Кладбище Пасси", "Место покоя художников · с 1820 года", "Мане, Берта Моризо и Дебюсси покоятся здесь, в тени Эйфелевой башни.", "Найди вход на маленькое кладбище Пасси наверху лестницы.", "Ты проходишь мимо кладбища Пасси, маленького кладбища на холме, одного из самых престижных в Париже.\n\nЗдесь покоятся два великих художника XIX века: Эдуар Мане и рядом с ним Берта Моризо, его невестка, одна из немногих женщин среди импрессионистов. Здесь же похоронен композитор Клод Дебюсси, автор «Лунного света». Он хотел лежать здесь, и через год после смерти его перенесли сюда.\n\nПосмотри на вход на кладбище, прямо рядом с Трокадеро."], "Le pont de Bir-Hakeim": ["Мост Бир-Хакейм", "Мост · 1905, кинозвезда", "Марлон Брандо бродил здесь в «Последнем танго», а Ди Каприо видел, как он складывается, в «Начале».", "Пройди под железной колоннадой моста, лицом к Эйфелевой башне.", "Ты на двухъярусном мосту: наверху идёт метро, внизу — люди и машины.\n\nОн назван в честь Бир-Хакейма, места в Ливийской пустыне. В 1942 году, во время Второй мировой войны, французские солдаты, верные генералу де Голлю, много дней держались там против немецкой армии. Сам мост построен в 1905 году. С его железными колоннами и видом на Эйфелеву башню он стал съёмочной площадкой: его видно в «Последнем танго в Париже» и в «Начале» с Леонардо Ди Каприо.\n\nПосмотри на железные колонны под метро: это любимый кадр режиссёров."], "L'avenue de l'Impératrice": ["Авеню Императрицы", "Авеню · 1854", "120 метров в ширину: Наполеон III хотел авеню, достойную императрицы.", "Оцени ширину авеню с широкими газонами по обеим сторонам.", "Ты на авеню Фош. Вместе с газонами её ширина 120 метров: это самая широкая авеню Парижа.\n\nИмператор Наполеон III открыл её в 1854 году, чтобы она вела к Булонскому лесу. Сначала он назвал её в честь своей жены, императрицы Евгении. Это один из самых дорогих адресов в мире: здесь жили греческий судовладелец Онассис и певец Принс.\n\nПосмотри на парадные фасады: за ними одни из самых роскошных квартир Парижа."], "La dernière maison de Debussy": ["Последний дом Дебюсси", "Музыка · сквер авеню Фош, 24", "Дебюсси умер здесь, когда немецкие пушки обстреливали Париж.", "Загляни в частный сквер в доме 24 сквера авеню Фош.", "Ты проходишь мимо тихого маленького сквера рядом с авеню Фош.\n\nЗдесь с 1905 года жил Клод Дебюсси, французский композитор, автор «Лунного света». Здесь он написал одни из самых исполняемых фортепианных пьес в мире. Он умер здесь в марте 1918 года, во время Первой мировой войны, когда немецкие пушки обстреливали Париж. Из-за войны за его гробом шли совсем немногие.\n\nПосмотри на сквер: здесь жил Дебюсси."], "Le lac et le chalet des Îles": ["Озеро и Шале-дез-Иль", "Булонский лес · Вторая империя", "Это озеро родилось из ошибки в расчётах, а шале приехало из Швейцарии.", "Посмотри на остров на озере и деревянное шале, куда добираются на лодке.", "Ты бежишь вдоль большого озера в Булонском лесу.\n\nИмператор Наполеон III жил в изгнании в Лондоне и полюбил Гайд-парк и его реку. Он захотел такое же здесь. Но первый ландшафтный архитектор ошибся в расчётах: вода не текла. Тогда сделали два озера с двумя островами. На одном из них император поставил настоящее швейцарское шале.\n\nПосмотри на остров: шале до сих пор там, и добираются до него на вёсельной лодке."], "Le vaisseau de Gehry": ["Корабль Гери", "Архитектура · Фонд Louis Vuitton, 2014", "Стеклянное облако приземлилось на краю Булонского леса.", "Посмотри на огромные стеклянные паруса Фонда Louis Vuitton.", "Ты подошёл к зданию, похожему на большой стеклянный парусник: это Фонд Louis Vuitton, музей современного искусства, открытый в 2014 году.\n\nЕго архитектор, американец Фрэнк Гери, один из самых знаменитых в мире. До этого он построил музей Гуггенхайма в Бильбао, в Испании. Здесь он обернул здание двенадцатью большими парусами из изогнутого стекла.\n\nПосмотри на стеклянные паруса: словно корабль, готовый к отплытию."], "Le moulin de la Galette": ["Мулен-де-ла-Галетт", "Танцплощадка · Ренуар, 1876", "По воскресеньям здесь танцевали под деревьями. Ренуар превратил это в шедевр.", "Подними глаза на деревянную мельницу на углу улицы Лепик.", "Ты проходишь мимо ветряной мельницы в самом сердце Монмартра.\n\nКогда-то Монмартр был деревней, покрытой мельницами. Мельникам пришла идея: продавать гуляющим печенье и стакан вина, а потом открыть танцплощадку. В 1876 году художник Огюст Ренуар написал здесь своих друзей, танцующих под деревьями. Эта картина, «Бал в Мулен-де-ла-Галетт», сегодня одна из самых знаменитых в мире.\n\nПосмотри на мельницу над улицей: это та самая, с картины."], "Le Sacré-Cœur": ["Сакре-Кёр", "Базилика · 1875–1919", "Чем больше дождя, тем она белее.", "Подними глаза на белые купола, а потом на квадратную колокольню сзади.", "Ты пришёл к Сакре-Кёр, большой белой базилике, которую видно со всего Парижа.\n\nЕё начали строить в 1875 году, и стройка заняла больше сорока лет: закончили только в 1919-м. Её секрет — в камне: когда идёт дождь, он становится ещё белее. На колокольне висит огромный колокол «Савоярка» весом почти 20 тонн.\n\nОглянись: весь Париж у твоих ног."], "Le Bateau-Lavoir": ["Бато-Лавуар", "Мастерские · площадь Эмиля Гудо", "В этом бараке без отопления Пикассо изобрёл современное искусство.", "Посмотри на застеклённый фасад Бато-Лавуар на площади Эмиля Гудо.", "Ты на маленькой площади Монмартра. Здесь стоял старый деревянный дом с мастерскими без отопления, его прозвали Бато-Лавуар — «корабль-прачечная».\n\nВ 1904 году сюда въехал нищий 23-летний испанский художник — Пабло Пикассо. Здесь в 1907 году он написал «Авиньонских девиц», картину, изменившую историю искусства. Вместе с другом Жоржем Браком он изобрёл кубизм: живопись, которая разбивает формы на геометрические кусочки.\n\nПосмотри на маленький фасад на площади: здесь началось современное искусство."], "Le pont Alexandre-III": ["Мост Александра III", "Мост · 1896–1900", "Царь заложил первый камень, а мост сделали плоским, чтобы он не заслонял Дом инвалидов.", "Посмотри на золотые статуи на опорах, а потом на купол Дома инвалидов вдали.", "Ты на мосту Александра III, самом позолоченном мосту Парижа.\n\nВ конце XIX века Франция и Россия стали союзниками. В честь этого мост назвали именем царя Александра III, императора России. В 1896 году его сын, царь Николай II, заложил первый камень. Под мостом должны были проходить суда, но он не должен был закрывать вид на купол Дома инвалидов. Поэтому инженеры построили одну очень плоскую стальную арку.\n\nПосмотри в сторону Дома инвалидов: мост задумали так, чтобы он не заслонял этот золотой купол."], "La Bourse de Commerce": ["Биржа коммерции", "Музей · 1767 и 2021", "Королева, потом зерно, потом искусство: у этого круглого здания было три жизни.", "Посмотри на колонну, прилепленную к зданию, а потом подними глаза на купол.", "Перед тобой Биржа коммерции, большое круглое здание рядом с Ле-Аль. Больше двух веков здесь торговали зерном, а потом товарами со всего мира.\n\nС 2021 года это музей искусства наших дней. Здесь показывают коллекцию Франсуа Пино — французского бизнесмена, который разбогател на люксовых брендах и уже пятьдесят лет покупает работы живых художников. Чтобы создать музей, японский архитектор Тадао Андо поставил внутрь огромный бетонный цилиндр, не повредив старое здание.\n\nПосмотри на колонну у здания: это всё, что осталось от дворца королевы, построенного больше 450 лет назад."], "La colonne Vendôme": ["Вандомская колонна", "Памятник · свергнута в 1871 году", "Художника заставили платить за восстановление этой колонны.", "Подними глаза на бронзовую колонну и статую Наполеона наверху.", "Ты на Вандомской площади, где обосновались великие ювелиры. В центре — высокая бронзовая колонна.\n\nЕё поставили в честь побед Наполеона, из металла пушек, захваченных у врага. В 1871 году парижане восстали против правительства: это была Коммуна. Они свалили колонну как символ императора. Художник Гюстав Курбе предлагал её разобрать. После восстания его приговорили оплатить её восстановление. Он бежал в Швейцарию и умер, так и не заплатив.\n\nПосмотри наверх: колонну вернули на место, с Наполеоном на вершине."], "La Madeleine": ["Мадлен", "Церковь · прощание с Шопеном", "На похоронах Шопена певиц пришлось спрятать за занавесом.", "Посмотри на огромные колонны Мадлен: она в точности как греческий храм.", "Перед тобой Мадлен. Она похожа на греческий храм, но это церковь.\n\nНаполеон хотел сделать её храмом во славу своей армии. После него она стала церковью. В 1849 году в Париже умер пианист Фредерик Шопен. На его похороны сюда пришли почти 3000 человек. Исполняли «Реквием» Моцарта, как он просил. Но тогда женщинам не разрешалось петь в церкви: певицы пели, спрятавшись за чёрным занавесом.\n\nПосмотри на огромные колонны: вот какой храм задумывал Наполеон."], "Les grilles dorées": ["Золочёные ворота", "Кованые ворота · Габриэль Давиу, 1861", "Эти чёрно-золотые ворота — приветствие элегантного Парижа Наполеона III.", "Посмотри на большие чёрно-золотые ворота у входа в парк.", "Ты подошёл к большим чёрно-золотым воротам парка Монсо.\n\nОколо 1860 года император Наполеон III и его префект барон Осман перестроили весь Париж: широкие бульвары, каменные дома, парки. Город купил это поместье у семьи принцев. Половину продали банкирам, и они построили роскошные особняки. Другая половина стала этим общественным парком, открытым в 1861 году.\n\nПосмотри на золочёные ворота: они приглашают тебя в элегантный Париж Наполеона III."], "La pyramide": ["Пирамида", "Причуда · Кармонтель, 1770-е", "Египетская пирамида посреди Парижа, и ей 250 лет.", "Найди маленькую каменную пирамиду, наполовину скрытую в зелени с северной стороны.", "Ты в парке Монсо. 250 лет назад это был частный сад принца — герцога Шартрского, кузена короля.\n\nВ 1770-е годы художник Кармонтель спроектировал для него сад, полный сюрпризов: голландская мельница, шатёр, разрушенный храм… и маленькая египетская пирамида. С тех пор почти всё исчезло. Но не пирамида.\n\nПосмотри между деревьями: маленькая пирамида всё ещё там."], "La géante de la rue de Chazelles": ["Великанша с улицы Шазель", "Мастерская Гаже-Готье · 1881–1884", "Статуя Свободы сначала возвышалась над крышами этой маленькой улицы.", "Посмотри на дом 25 по улице Шазель и представь великаншу над крышами.", "Ты на улице Шазель, тихой маленькой улочке. Но именно здесь родилась статуя Свободы, символ Нью-Йорка.\n\nЭто был подарок Франции Соединённым Штатам. Французский скульптор Огюст Бартольди строил её в мастерской в доме 25. Внутри у неё железный каркас, который спроектировал инженер Гюстав Эйфель, автор башни. До 1884 года статуя возвышалась над крышами: соседи видели её голову из окон. Потом её разобрали и отправили в Нью-Йорк больше чем в 200 ящиках.\n\nПосмотри поверх крыш: представь, как оттуда торчит голова высотой 5 метров."], "Le Cours la Reine": ["Кур-ла-Рен", "Променад · Мария Медичи, 1616", "Задолго до бегунов сюда приезжали покрасоваться в каретах.", "Посмотри на длинную прямую аллею вдоль Сены.", "Ты бежишь по широкой аллее вдоль Сены. Ей больше 400 лет.\n\nВ 1616 году королева Мария Медичи, итальянская принцесса, ставшая королевой Франции, велела посадить здесь аллею деревьев. Она хотела место для прогулок в каретах, как во Флоренции, своём родном городе. Это быстро стало модным местом двора: сюда приезжали посмотреть на других и показать себя.\n\nПосмотри на эту длинную прямую: деревья сменились, но план остался королевским."], "Churchill en marche": ["Черчилль на ходу", "Бронза · Жан Кардо, 1998", "Старый лев шагает вперёд — прямо как ты.", "Посмотри на бронзовую статую Черчилля на ходу, с тростью в руке.", "Ты проходишь мимо статуи шагающего человека. Это Уинстон Черчилль.\n\nВо время Второй мировой войны он был премьер-министром Великобритании. В 1940 году почти вся Европа пала перед Гитлером, но он отказался сдаваться. Его прозвали Старым львом. Скульптор Жан Кардо изобразил его в военной форме, с тростью, идущим к Елисейским Полям.\n\nПосмотри на постамент: на нём его слова 1940 года — «Мы никогда не сдадимся»."], "Les jardins de Gilberte": ["Сады Жильберты", "Аллея Марселя Пруста · сады Елисейских Полей", "На этих дорожках маленький мальчик встретил героиню своего великого романа.", "Найди табличку аллеи Марселя Пруста вдоль газонов.", "Ты в садах Елисейских Полей.\n\nВ конце XIX века сюда приходил играть маленький мальчик — Марсель Пруст. Позже он станет великим писателем, автором «В поисках утраченного времени». В этих садах он встретил девочку, Мари де Бенардаки, и влюбился в неё. Годы спустя она вдохновила его на образ Жильберты, первой любви героя романа.\n\nПосмотри на название дорожки у газонов: это аллея Марселя Пруста."], "La ligne d’arrivée du Tour": ["Финиш «Тур де Франс»", "Авеню · финиш с 1975 года", "Ты бежишь вверх по авеню, до которой гонщики «Тура» едут три недели.", "Посмотри прямо вперёд, на Триумфальную арку на вершине авеню.", "Ты на Елисейских Полях, самой знаменитой авеню Парижа.\n\n«Тур де Франс» — самая известная велогонка в мире: три недели гонки по всей стране. С 1975 года её финальный финиш здесь. В тот год француз Бернар Тевене обыграл великого бельгийского чемпиона Эдди Меркса и выиграл «Тур» на глазах у парижан.\n\nПосмотри на подъём к Триумфальной арке: он одинаковый и для тебя, и для чемпионов."], "Les canons du Trocadéro": ["Пушки Трокадеро", "Варшавский фонтан · выставка 1937 года", "Самый большой фонтан Парижа бьёт горизонтально, прямо в Эйфелеву башню.", "Посмотри на водяные пушки в большом бассейне, лицом к Эйфелевой башне.", "Ты в садах Трокадеро, лицом к Эйфелевой башне.\n\nИх разбили к Международной выставке 1937 года — огромной ярмарке, где каждая страна показывала, на что способна. В центре ряд водяных пушек бьёт мощными горизонтальными струями прямо к Сене. Это самый большой фонтан Парижа.\n\nПосмотри на большой бассейн: когда пушки стреляют, струи летят к Эйфелевой башне."], "Le pont qu’on voulait faire sauter": ["Мост, который хотели взорвать", "Йенский мост · 1808–1814", "Этот мост назван в честь поражения пруссаков, и пруссаки этого не забыли.", "Посмотри на резных орлов на опорах Йенского моста.", "Ты на Йенском мосту, между Эйфелевой башней и Трокадеро.\n\nИмператор Наполеон построил его в честь победы при Йене в 1806 году над Пруссией, немецким королевством. Но в 1815 году Наполеон проиграл битву при Ватерлоо. Вражеские армии вошли в Париж. Прусский генерал Блюхер жаждал мести: он хотел взорвать этот мост. Новому королю Франции, Людовику XVIII, удалось его спасти.\n\nПосмотри на орлов на опорах моста: это эмблема Наполеона."], "La tour qui devait disparaître": ["Башня, которая должна была исчезнуть", "Эйфелева башня · 1889", "Ей отводили всего двадцать лет. Её спасло радио.", "Подними глаза на верхушку Эйфелевой башни и её антенны.", "Ты у подножия Эйфелевой башни. Её построили к Всемирной выставке 1889 года — огромному шоу, где Франция показывала, на что способна.\n\nТогда многие художники считали её уродливой. Её разрешили оставить только на двадцать лет. Её строитель, инженер Гюстав Эйфель, старался сделать её полезной: проводил на ней опыты с ветром и погодой. А главное, армия поставила на вершине радиоантенну. Башня стала слишком ценной, чтобы её разбирать.\n\nПосмотри на самый верх: её спасли антенны."], "La fête de la Fédération": ["Праздник Федерации", "Марсово поле · 14 июля 1790", "Французское 14 июля празднует и тот огромный праздник на этом газоне.", "Посмотри на большой газон Марсова поля, тянущийся до Военной школы.", "Ты на Марсовом поле, длинном газоне у подножия Эйфелевой башни. Во времена этой истории башни ещё не было.\n\n14 июля 1789 года парижане взяли Бастилию: началась Французская революция. Через год здесь захотели устроить огромный праздник. Рабочих, чтобы подготовить площадку, не хватало. И тысячи парижан пришли копать сами, богатые и бедные бок о бок. 14 июля 1790 года, под дождём, огромная толпа праздновала нацию.\n\nПосмотри на этот газон: здесь родился дух 14 июля, национального праздника Франции."], "Victor Hugo, en son avenue": ["Виктор Гюго на своей авеню", "Последний дом · авеню Виктора Гюго, 124", "Письма приходили сюда с уникальным адресом: «Господину Виктору Гюго, на его авеню».", "Найди мемориальную табличку на доме 124 по авеню Виктора Гюго.", "Ты на авеню Виктора Гюго.\n\nВиктор Гюго — самый знаменитый писатель Франции, автор «Отверженных» и «Собора Парижской Богоматери». Он жил здесь с 1878 года. На его 80-летие в 1881 году город сделал неслыханное: назвал авеню его именем ещё при жизни. Сотни тысяч парижан прошли под его окнами. Письма ему приходили с адресом «Господину Виктору Гюго, на его авеню». Он умер здесь в 1885 году.\n\nПосмотри на табличку на фасаде: здесь был его последний дом."], "Le premier vol humain": ["Первый полёт человека", "Замок Ла-Мюэтт · 21 ноября 1783", "Отсюда люди впервые в истории поднялись в воздух.", "Посмотри на сады Ла-Мюэтт и представь взлетающий шар.", "Ты в Ла-Мюэтт. Когда-то здесь стоял замок с большими садами.\n\n21 ноября 1783 года в этих садах двое мужчин поднялись на борт воздушного шара. Это были Пилатр де Розье, молодой преподаватель естественных наук, и маркиз д'Арланд, армейский офицер. Шар взлетел. Они стали первыми людьми, которые полетели. 25 минут они парили над Парижем и приземлились на другом конце города.\n\nПосмотри на небо над собой: здесь человек впервые оторвался от земли."], "Le corbeau et le renard": ["Ворона и лисица", "Сад Ранела · бал 1774 года", "Сад, названный в честь английского бала, со статуей из басни.", "Найди на газонах статую Лафонтена с вороной и лисицей.", "Ты в саду Ранела, рядом с Ла-Мюэтт.\n\nЕго название звучит по-английски, и не случайно: в 1774 году здесь открылся бал под открытым небом, скопированный с модного лондонского сада. Аристократы приезжали сюда танцевать. Бала больше нет, а название осталось. Посреди газонов стоит статуя Жана де Лафонтена, писателя XVII века, автора басен о животных. Каждый французский ребёнок знает одну из них: «Ворона и лисица».\n\nПосмотри на статую: ворона держит сыр, а лиса ей льстит."], "Impression, soleil levant": ["«Впечатление. Восходящее солнце»", "Музей Мармоттан-Моне · написана в 1872 году", "Картина, давшая имя импрессионизму, висит в нескольких метрах отсюда.", "Найди музей Мармоттан-Моне, особняк на краю сада.", "Ты проходишь рядом с музеем Мармоттан-Моне. Внутри висит небольшая картина, которая дала имя целому направлению.\n\nВ 1872 году художник Клод Моне написал порт Гавра на рассвете. Он назвал картину «Впечатление. Восходящее солнце». В 1874 году журналист насмешливо назвал его и его друзей «импрессионистами», то есть «впечатленцами». Слово задумывалось как оскорбление. А стало названием одного из самых любимых направлений в искусстве.\n\nПосмотри на музей на краю сада: картина за этими стенами."], "L’avenue des pionniers": ["Авеню первопроходцев", "Авеню Великой армии · Прекрасная эпоха", "До автомобилей эта авеню продавала Парижу первые велосипеды.", "Посмотри на длинный спуск авеню Великой армии к Порт-Майо.", "Ты спускаешься по авеню Великой армии, которая начинается у Триумфальной арки.\n\nОна названа в честь армии Наполеона. Но около 1900 года, в Прекрасную эпоху, она стала главным рынком велосипедов — совершенно новое изобретение, — а потом и автомобилей. Вдоль неё тянулись магазины и мастерские производителей: настоящий автосалон под открытым небом.\n\nПосмотри на витрины вдоль авеню: здесь до сих пор продают мотоциклы и машины."], "Le pont de Perronet": ["Мост Перроне", "Мост Нёйи · 1772 и 1942", "Сам король приехал посмотреть, как с этого моста снимают леса.", "Посмотри на мост Нёйи и вдали — на Большую арку Дефанса.", "Ты у моста Нёйи через Сену.\n\nВ 1772 году инженер Жан-Родольф Перроне построил здесь каменный мост с очень плоскими арками — для того времени настоящий подвиг. Самым рискованным было убрать деревянные леса из-под арок: либо выдержит, либо всё рухнет. Король Людовик XV приехал посмотреть лично. Мост выдержал. В 1942 году этот каменный мост заменили нынешним стальным.\n\nПосмотри на Сену под мостом: представь, как король ждёт, затаив дыхание."], "Un dimanche à la Grande Jatte": ["Воскресенье на Гранд-Жатт", "Жорж Сёра · 1884–1886", "Этот рукав Сены — место действия одной из самых знаменитых картин мира.", "Посмотри на берега острова Гранд-Жатт и сверкающую воду.", "Ты бежишь вдоль острова Гранд-Жатт, острова на Сене.\n\nВ 1880-е годы парижане приезжали сюда на воскресные прогулки. Молодой художник Жорж Сёра два года приходил сюда наблюдать за ними. Потом он написал огромную картину «Воскресный день на острове Гранд-Жатт» — только крошечными точками цвета. В 1886 году она вызвала скандал. Сегодня это одна из самых знаменитых картин в мире, она в Чикаго.\n\nПосмотри на берега острова: это место действия картины."], "La tour est née à Levallois": ["Башня родилась в Леваллуа", "Мастерские Эйфеля · 1887–1889", "Все 18 000 деталей Эйфелевой башни сделаны в этом квартале.", "Найди табличку улицы Гюстава Эйфеля совсем рядом.", "Ты в Леваллуа, сразу к западу от Парижа.\n\nЭйфелева башня состоит из 18 000 железных деталей. Каждую сделали здесь, в мастерских инженера Гюстава Эйфеля. Каждую деталь чертили, сверлили и готовили с невероятной точностью. Потом её везли на стройку на Марсовом поле, где оставалось только собрать. Поэтому башню построили всего за два с небольшим года, с 1887 по 1889-й.\n\nПосмотри в сторону Эйфелевой башни вдали: её детали отправились отсюда."], "Les berges rendues aux piétons": ["Набережные, возвращённые пешеходам", "Левый берег · без машин с 2013 года", "Ты бежишь по бывшей скоростной трассе, где носились машины.", "Посмотри на набережную: плавучие сады, игры и ни одной машины.", "Ты бежишь по набережной, у самой воды. Пятнадцать лет назад здесь неслись машины.\n\nВ 1960-е годы эти набережные Сены превратили в скоростные дороги. В 2013 году мэрия Парижа закрыла 2,3 километра и вернула их пешеходам, с плавучими садами, играми и дорожками.\n\nОглянись: там, где ты бежишь, раньше была городская автострада."], "Les pierres de la Bastille": ["Камни Бастилии", "Мост Согласия · 1787–1791", "Этот мост отчасти построен из тюрьмы, которую разрушил народ.", "Посмотри на камни моста Согласия под ногами, а потом на Бурбонский дворец напротив.", "Ты на мосту Согласия.\n\nБастилия была тюрьмой-крепостью, символом королевской власти. 14 июля 1789 года, в начале Французской революции, парижане взяли её штурмом. А потом разобрали камень за камнем. Этот мост тогда как раз строили. Его достроили из камней Бастилии. Идея, как говорят, была такая: чтобы парижане каждый день ходили по старой тюрьме.\n\nПосмотри на камни моста: некоторые из них из Бастилии."], "La pyramide et le chiffre du diable": ["Пирамида и число дьявола", "Пирамида Лувра · Бэй Юймин, 1989", "Нет, в пирамиде не 666 стёкол.", "Посмотри на стеклянную пирамиду в центре двора Лувра.", "Ты перед Лувром. Это был дворец французских королей, пока они не переехали в Версаль. Сегодня это самый большой музей в мире.\n\nВ 1989 году открылся новый вход: стеклянная пирамида по проекту американского архитектора китайского происхождения Бэй Юймина. Это был скандал: современная пирамида перед старинным дворцом. Ходил даже слух, что в ней 666 стёкол — число дьявола. Неправда: их 673.\n\nПосмотри на пирамиду: попробуй сосчитать стёкла… или просто поверь нам."], "Le bouquet de la paix": ["Букет мира", "Оранжери · «Кувшинки» Моне, 1927", "Сразу после Первой мировой войны Моне подарил Франции свои «Кувшинки».", "Посмотри на здание Оранжери в конце сада Тюильри, со стороны Сены.", "Ты проходишь мимо Оранжери, небольшого музея в конце сада Тюильри.\n\n12 ноября 1918 года Первая мировая война только что закончилась. Художник Клод Моне, уже старик, захотел сделать Франции подарок. Он вручил его своему другу Жоржу Клемансо, главе правительства. Подарком стали восемь огромных полотен с кувшинками из пруда в его саду. Их повесили здесь, в двух овальных залах. Моне умер в 1926 году, за несколько месяцев до открытия.\n\nПосмотри на здание: внутри кувшинки опоясывают все стены."], "La Grande Cascade": ["Большой каскад", "Булонский лес · 1850-е", "Этот водопад построили для нового леса Наполеона III, и все скалы в нём ненастоящие.", "Посмотри на большой каскад и его ступенчатые бассейны.", "Ты в Булонском лесу, большом лесу на западе Парижа. Он больше Центрального парка в Нью-Йорке.\n\nВ 1852 году император Наполеон III подарил его Парижу. Он хотел, чтобы лес был так же красив, как Гайд-парк в Лондоне. Его инженер Адольф Альфан выкопал озёра, проложил дорожки и построил этот водопад высотой около десяти метров, со скалами… искусственными. Всё ненастоящее, но всё выглядит как настоящее.\n\nПосмотри на скалы водопада: их сделали люди."], "Le moulin de l’abbaye": ["Мельница аббатства", "Мельница Лоншан · аббатство основано в 1255 году", "Эта мельница — последний след аббатства, основанного сестрой короля-святого.", "Посмотри на старую мельницу, а прямо за ней — ипподром.", "Ты проходишь мимо старой ветряной мельницы у ипподрома Лоншан.\n\nВ 1255 году Изабелла Французская, сестра короля Людовика Святого, основала здесь женский монастырь. Он простоял больше пяти веков. Потом в 1789 году пришла Французская революция: монастырь продали, а потом снесли. Осталась только эта мельница. Прямо за ней каждую осень ипподром принимает самые престижные скачки Европы — Приз Триумфальной арки.\n\nПосмотри на мельницу: это последний след монастыря."], "Le château du pari": ["Замок на спор", "Багатель · 1777", "Этот маленький замок построили чуть больше чем за два месяца — чтобы выиграть пари.", "Посмотри на маленький белый замок Багатель в центре парка.", "Ты проходишь мимо парка Багатель в Булонском лесу.\n\nВ 1777 году граф д'Артуа, брат короля Людовика XVI, поспорил со своей невесткой, королевой Марией-Антуанеттой. Он утверждал, что сможет построить маленький замок меньше чем за три месяца. Его архитектор заставил сотни рабочих трудиться день и ночь. Замок был готов за 64 дня. Пари выиграно.\n\nПосмотри на парк: сегодня он знаменит прежде всего розами."], "Castor et Pollux": ["Кастор и Поллукс", "Сад акклиматизации · осада 1870 года", "Во время осады Парижа слоны из этого сада оказались у мясника.", "Посмотри на вход в Сад акклиматизации.", "Ты проходишь мимо Сада акклиматизации, детского парка в Булонском лесу.\n\nКогда он открылся в 1860 году, это было что-то вроде зоопарка, с животными со всего света. Его звёздами были два слона, Кастор и Поллукс. Зимой 1870 года Париж окружила прусская армия из Германии. В город ничего не могло попасть, парижане голодали. В конце декабря Кастора и Поллукса забили, а их мясо продала за бешеные деньги модная мясная лавка.\n\nПосмотри на вход: за ним жили два слона."], "L’île aux Cygnes": ["Лебединый остров", "Искусственный остров · 1827", "Остров длиной 850 метров и шириной 11: идеальная прямая.", "Посмотри на единственную аллею посреди Сены.", "Ты на узком острове посреди Сены. Ничего природного в нём нет: его построили как дамбу в начале XIX века, около 200 лет назад.\n\nПозже здесь посадили деревья и проложили одну-единственную дорожку. Ни машин, ни светофоров, 850 метров идеально прямо. Местные бегуны сделали её своей любимой трассой.\n\nОглянись: Эйфелева башня сопровождает тебя всю дорогу."], "La petite sœur de New York": ["Младшая сестра Нью-Йорка", "Статуя Свободы · 1889", "Её рост 11,5 метра, и она смотрит на старшую сестру через Атлантику.", "Посмотри на статую Свободы на краю острова, с поднятым факелом.", "Да, это правда статуя Свободы, только поменьше. Большая, в Нью-Йорке, была подарком Франции Соединённым Штатам в 1886 году. Её создал французский скульптор Огюст Бартольди.\n\nВ 1889 году Франция праздновала столетие Революции. В благодарность американцы, жившие в Париже, подарили городу эту маленькую копию. На её табличке две даты: независимость Америки и взятие Бастилии. В 1937 году её повернули на запад, чтобы она смотрела на старшую сестру за океаном.\n\nПосмотри, куда она держит факел: в сторону Нью-Йорка."], "Sous le pont Mirabeau": ["Под мостом Мирабо", "Мост Мирабо · 1897 · Аполлинер, 1912", "Стихотворение об ушедшей любви прославило этот мост на весь мир.", "Посмотри на четыре большие бронзовые статуи на опорах моста Мирабо.", "Ты подошёл к мосту Мирабо, железному мосту 1897 года.\n\nВ начале XX века поэт Гийом Аполлинер часто переходил его по дороге домой в Отёй. Он был влюблён в художницу Мари Лорансен. Но они расстались. В 1912 году он написал стихотворение «Мост Мирабо»: Сена течёт под мостом, как уходит время и угасает любовь. Сегодня его учит наизусть каждый французский школьник.\n\nПосмотри на воду под мостом: это именно то, что видел Аполлинер."], "La Maison ronde": ["Круглый дом", "Дом радио · Анри Бернар, 1963", "Здание, круглое, как пластинка, для национального радио.", "Посмотри на большое круглое здание у Сены.", "Ты проходишь мимо огромного круглого здания у Сены. Это Дом радио, парижане зовут его «Круглым домом».\n\nЕго открыл в 1963 году генерал де Голль, тогдашний президент Франции. Архитектор Анри Бернар задумал его как пластинку: кольца офисов и студий вокруг центральной башни. Здесь находится Radio France, французское общественное радио.\n\nПосмотри на его большие круги: все общественные радиостанции Франции вещают из этого здания."], "Le jardin de Shakespeare": ["Сад Шекспира", "Пре-Катлан · 1953", "Каждое растение в этом саду упоминается у Шекспира.", "Найди вход в Сад Шекспира в самом сердце Пре-Катлан.", "Ты в Булонском лесу, большом лесу на западе Парижа, в парке под названием Пре-Катлан.\n\nВ 1953 году здесь создали совершенно особенный сад. В нём растут только растения, упомянутые в пьесах Шекспира. Каждый уголок похож на театральную декорацию: лес «Сна в летнюю ночь», пустошь «Макбета», остров «Бури». Летом здесь даже играют спектакли под открытым небом.\n\nПосмотри на деревья и цветы: каждое из них — из пьесы Шекспира."], "L’hippodrome des sauteurs": ["Ипподром прыгунов", "Ипподром Отёй · 1873", "Здесь лошади не только бегут: они прыгают.", "Посмотри сквозь ограду на препятствия ипподрома Отёй.", "Ты бежишь вдоль ипподрома Отёй, открытого в 1873 году.\n\nЗдесь лошади не просто скачут: они прыгают через живые изгороди и воду. Это называется стипль-чез. С 1874 года каждую весну здесь проходит самый знаменитый из них во Франции — Большой парижский стипль-чез.\n\nПосмотри сквозь ограду: может, увидишь изгороди на дорожке."], "Un aviateur sur la terre battue": ["Лётчик на грунтовом корте", "Стадион «Ролан Гаррос» · 1928", "Самый знаменитый теннисный стадион мира назван в честь лётчика, а не теннисиста.", "Посмотри на стены стадиона «Ролан Гаррос», цвета его грунтовых кортов.", "Ты проходишь мимо стадиона «Ролан Гаррос», где каждую весну проходит самый знаменитый в мире турнир на грунте.\n\nНо Ролан Гаррос не был теннисистом. Он был лётчиком. В 1913 году он первым перелетел Средиземное море. Он погиб в Первую мировую войну, в 1918 году. Через десять лет, в 1928-м, этот стадион построили для большого теннисного матча и назвали в честь героя.\n\nПосмотри на имя над входом: оно принадлежит лётчику, а не игроку."], "Sur les rails de la Petite Ceinture": ["По рельсам Птит-Сентюр", "Линия Отёй · 1854", "Ты бежишь по старой железной дороге, отданной природе.", "Посмотри на зелёную выемку, где когда-то ходили поезда, полную папоротников и деревьев.", "Ты в зелёной выемке посреди города. Здесь раньше ходили поезда.\n\nВ XIX веке вокруг всего Парижа шла железная дорога под названием Птит-Сентюр — «малый пояс». Этот участок, линия Отёй, открылся в 1854 году. Пассажиры ездили по нему до 1985 года. Потом поезда остановились, и природа взяла своё: деревья, папоротники, полевые цветы.\n\nПосмотри под ноги: местами ещё видно, где лежали рельсы."], "Le pont des cadenas": ["Мост с замками", "Мост Искусств · 1804", "Этот маленький мост когда-то нёс до 45 тонн «замков любви».", "Посмотри на стеклянные перила моста Искусств, где раньше висели замки.", "Ты на мосту Искусств, пешеходном мосту между Лувром и Институтом Франции.\n\nОн открылся в 1804 году и был первым железным мостом Парижа. В начале 2010-х пары со всего мира вешали на него замки со своими инициалами, а ключ бросали в Сену. Замков стало так много, до 45 тонн, что перила повредились. В 2015 году город снял их все и поставил стеклянные панели.\n\nПосмотри на стеклянные панели вдоль моста: они заменили замки."], "Le Pont-Neuf et le Vert-Galant": ["Новый мост и Вер-Галан", "Новый мост · 1578–1607", "«Новый мост» на самом деле — самый старый мост Парижа.", "Посмотри на конную статую Генриха IV посреди Нового моста.", "Ты дошёл до Нового моста. Его название значит «новый мост», и всё же это самый старый мост Парижа.\n\nЕго закончили в 1607 году при короле Генрихе IV. Для своего времени он был революционным: первый мост Парижа без домов и с тротуарами. Весь Париж приходил сюда гулять. Прямо внизу маленький сад носит прозвище короля — «Вер-Галан», старый дамский угодник: у него было очень много любовниц.\n\nПосмотри на конную статую короля посреди моста: это Генрих IV."], "L’île inventée": ["Придуманный остров", "Остров Сен-Луи · 1614–1664", "Этот остров появился из двух островков, которые соединил застройщик XVII века.", "Посмотри на набережные и фасады особняков острова Сен-Луи.", "Ты на острове Сен-Луи, одном из двух островов в центре Парижа.\n\n400 лет назад здесь было лишь два островка, где паслись коровы. Около 1614 года застройщик Кристоф Мари получил разрешение короля соединить их и застроить. За пятьдесят лет появились набережные, прямые улицы и красивые дома знати. Это был первый совершенно новый квартал Парижа.\n\nПосмотри на фасады вдоль набережной: почти все они того времени."], "Les bouquinistes": ["Букинисты", "Набережные Сены · с XVI века", "Эти зелёные ящики — самый большой книжный магазин под открытым небом в мире.", "Посмотри на зелёные ящики букинистов на парапете.", "Ты бежишь вдоль Сены. На парапетах большие зелёные ящики: это букинисты, продавцы старых книг.\n\nОни здесь с XVI века, почти 500 лет. Долго их прогоняли, потом терпели. В 1859 году город наконец выделил им официальные места. Сегодня около 200 букинистов держат 900 ящиков: это самый большой книжный магазин под открытым небом в мире.\n\nПосмотри на зелёные ящики: вечером они закрываются, как сундуки."], "Le Grand Parc des Docks": ["Большой парк Доков", "Сент-Уэн · открыт в 2013 году", "Парк в 12 гектаров вырос на месте бывших заводов и доков.", "Посмотри на луга и пруды парка вдоль Сены.", "Ты выехал из Парижа и оказался в Сент-Уэне, у Сены.\n\nБольше века здесь были доки, заводы и электростанция: шум, дым и уголь. Потом всё закрылось. На их месте построили экоквартал вокруг этого большого парка в 12 гектаров, открытого в 2013 году.\n\nПосмотри на луга и пруды: они заменили заводские трубы."], "Les Puces de Saint-Ouen": ["Блошиный рынок Сент-Уэн", "Блошиный рынок · конец XIX века", "Крупнейший антикварный рынок мира вырос из находок старьёвщиков.", "Посмотри на проходы и лавки блошиного рынка Сент-Уэн.", "Ты проходишь рядом с блошиным рынком Сент-Уэн, сразу к северу от Парижа.\n\nВ конце XIX века старьёвщики перебирали парижские мусорные баки в поисках ткани, металлолома и старых вещей. Их выгнали из города, и они обосновались здесь, сразу за стенами, чтобы продавать свои находки. Постепенно это стало рынком. Сегодня каждые выходные здесь собирается больше тысячи торговцев: это самый большой антикварный рынок в мире.\n\nЗагляни в проходы рынка: тут есть всё, от старых пуговиц до люстр из замков."], "Verlaine et Breton": ["Верлен и Бретон", "Кладбище Батиньоль · 1833", "За этой стеной лежат великий поэт и отец сюрреализма.", "Посмотри на стену маленького кладбища Батиньоль, прижатого к окружной дороге.", "Ты проходишь мимо кладбища Батиньоль, маленького кладбища, открытого в 1833 году. Сегодня оно вплотную прижато к окружной дороге.\n\nНо здесь лежат два великих имени. Поль Верлен, один из величайших поэтов Франции, похоронен здесь в 1896 году. В 1966 году к нему присоединился Андре Бретон: он основал сюрреализм, направление в искусстве, вдохновлённое снами.\n\nПосмотри на стены кладбища: за ними тихий уголок прямо рядом с рёвом машин."], "Le parc des voies ferrées": ["Парк на месте путей", "Парк Мартина Лютера Кинга · с 2007 года", "Этот парк заменил огромное поле железнодорожных путей.", "Посмотри на пруды и сады парка Мартина Лютера Кинга.", "Ты в парке Мартина Лютера Кинга, в квартале Батиньоль.\n\nЗдесь насколько хватало глаз тянулись пути и склады вокзала Сен-Лазар, который совсем рядом с твоим отелем. Если бы Париж выиграл Олимпиаду 2012 года, здесь построили бы олимпийскую деревню. Выиграл Лондон. И с 2007 года здесь создали парк, в центре нового экоквартала.\n\nПосмотри на высокие дома вокруг парка: весь квартал вырос на старой железнодорожной земле."], "Le méridien de Saint-Sulpice": ["Меридиан Сен-Сюльпис", "Церковь Сен-Сюльпис · гномон 1743 года", "По полу церкви идёт латунная линия: это астрономический прибор.", "Найди на полу церкви латунную линию, ведущую к обелиску.", "Ты проходишь мимо церкви Сен-Сюльпис, одной из самых больших в Париже.\n\nВнутри тонкая латунная линия пересекает пол и ведёт к маленькому обелиску. Это астрономический прибор, установленный в 1743 году. Солнечный луч проходит через маленькое отверстие и падает на линию. Так отмечали времена года и вычисляли дату Пасхи. Роман «Код да Винчи» утверждал, что это тайная линия: это не так.\n\nПосмотри на две башни церкви: латунная линия сразу за дверями."], "Le palais florentin": ["Флорентийский дворец", "Люксембургский дворец · 1615–1631", "Этот дворец построила королева, тосковавшая по родине.", "Посмотри на фасад Люксембургского дворца в конце большого пруда.", "Перед тобой Люксембургский дворец, в конце большого одноимённого сада.\n\nВ начале XVII века итальянская принцесса Мария Медичи была королевой Франции. Её мужа, короля Генриха IV, только что убили. Она тосковала по родине и велела построить этот дворец, чтобы он напоминал ей дворец её детства во Флоренции. Работы шли с 1615 по 1631 год. С 1799 года здесь заседает Сенат, одна из двух палат, которые принимают законы Франции.\n\nПосмотри на фасад: это кусочек Италии посреди Парижа."], "Le pendule du Panthéon": ["Маятник Пантеона", "Пантеон · Леон Фуко, 1851", "Под этим куполом люди увидели, как вращается Земля.", "Подними глаза на большой купол Пантеона.", "Перед тобой Пантеон, большое здание с куполом. Здесь Франция хоронит самых важных для неё людей: писателя Виктора Гюго, учёную Марию Кюри, певицу и героиню Сопротивления Жозефину Бейкер.\n\nВ 1851 году здесь прошёл знаменитый опыт. Физик Леон Фуко подвесил под куполом тяжёлый шар на тросе длиной 67 метров и раскачал его. За несколько часов направление качания медленно поворачивалось. Поворачивался не шар, а Земля под ним. Впервые люди своими глазами увидели, что Земля вращается.\n\nПосмотри на купол: маятник до сих пор качается под ним."], "Les arènes de Lutèce": ["Арены Лютеции", "Галло-римский амфитеатр · I век", "Почти две тысячи лет назад здесь сидели тысячи зрителей.", "Посмотри на каменные ступени трибун и круглую арену.", "Ты входишь в старый римский амфитеатр, спрятанный за домами.\n\n2000 лет назад Париж назывался Лютецией и входил в Римскую империю. В I веке здесь построили арену, немного похожую на маленький Колизей. Тысячи зрителей приходили смотреть представления и бои. Потом она на века исчезла под землёй. Её снова нашли в 1869 году, когда прокладывали улицу, и писатель Виктор Гюго боролся за её спасение.\n\nПосмотри на каменные трибуны: сегодня парижане играют здесь в петанк."], "Le bassin de Napoléon": ["Бассейн Наполеона", "Бассейн Ла-Виллет · 1808", "Самое большое искусственное озеро Парижа выкопали, чтобы дать парижанам питьевую воду.", "Посмотри на длинный бассейн Ла-Виллет с набережными.", "Ты бежишь вдоль очень длинного бассейна — бассейна Ла-Виллет.\n\nВ начале XIX века Парижу не хватало чистой воды. В 1802 году Наполеон решил привести её издалека, из реки Урк, и доставить сюда по каналу. Этот бассейн, открытый в 1808 году, был и водохранилищем, и портом. Длиной 800 метров, это самая большая искусственная водная гладь Парижа.\n\nПосмотри на оба берега: сегодня это место пикников и уличных кафе."], "La Géode": ["Жеод", "Купольный кинотеатр · Адриен Фенсильбер, 1985", "Зеркальный шар диаметром 36 метров отражает небо и бегунов.", "Посмотри на большой серебряный шар Жеода и его отражение в воде.", "Ты проходишь мимо огромного блестящего шара в парке Ла-Виллет. Это Жеод, открытый в 1985 году.\n\nЕго диаметр 36 метров, и он покрыт больше чем 6000 полированных стальных треугольников, как зеркало. Внутри — кинотеатр с гигантским экраном-куполом: кажется, будто ты внутри фильма.\n\nПосмотри на шар, пробегая мимо: ты увидишь в нём себя."], "La Philharmonie": ["Филармония", "Концертный зал · Жан Нувель, 2015", "Металлический космический корабль, где публика сидит вокруг оркестра.", "Посмотри на фасад Филармонии, покрытый пластинами в форме птиц.", "Ты проходишь мимо большого серого металлического здания: это Парижская филармония, концертный зал, открытый в 2015 году.\n\nЕё архитектор Жан Нувель придумал зал, где публика сидит не напротив оркестра, а со всех сторон вокруг него, на балконах, которые будто парят в воздухе. Снаружи фасад покрыт тысячами алюминиевых пластин в форме птиц.\n\nПрисмотрись к фасаду: маленькие пластины складываются в силуэты птиц."], "La porte du Roi-Soleil": ["Ворота Короля-Солнца", "Ворота Сен-Дени · Франсуа Блондель, 1672", "Людовик XIV построил эту арку в честь своих побед.", "Подними глаза на ворота Сен-Дени и их скульптуры.", "Ты проходишь мимо большой каменной арки посреди улицы: это ворота Сен-Дени.\n\nВ XVII веке король Людовик XIV, прозванный Королём-Солнцем, был очень могущественным. Он велел снести старые стены Парижа: по его мнению, городу они больше не были нужны. На месте старых ворот он построил триумфальные арки. Эта, высотой 24 метра, построена в 1672 году и прославляет его военные победы.\n\nПосмотри на рельефы арки: они рассказывают о битвах короля."], "Face au Mont-Valérien": ["Напротив Мон-Валерьен", "Берег реки · вид на мемориал", "На холме напротив расстреляли больше тысячи участников Сопротивления и заложников.", "Посмотри на холм Мон-Валерьен за Сеной.", "Ты у Сены. На холме напротив стоит форт: Мон-Валерьен.\n\nВо время Второй мировой войны немецкая армия оккупировала Францию. С 1941 по 1944 год в этом форте расстреляли больше тысячи участников Сопротивления и заложников. В 1960 году генерал де Голль, руководивший Свободной Францией из Лондона, открыл здесь мемориал. Каждое 18 июня здесь вспоминают его радиопризыв к сопротивлению 1940 года.\n\nПосмотри на холм напротив: это место памяти для всей Франции."], "Le château disparu": ["Исчезнувший замок", "Терраса замка · уничтожен в 1870 году", "На этой пустой террасе стоял замок, где Бонапарт захватил власть.", "Посмотри на большую пустую террасу, где когда-то стоял замок.", "Ты на большой террасе в парке Сен-Клу. Здесь раньше стоял замок.\n\nВ 1785 году его купила королева Мария-Антуанетта. А в 1799 году здесь случился ключевой момент истории: молодой генерал Наполеон Бонапарт силой захватил власть. Это было началом его правления. Позже здесь жил и его племянник, император Наполеон III. В 1870 году, во время войны с Пруссией, замок сгорел. Его так и не восстановили.\n\nПосмотри на пустое место перед собой: здесь стоял замок, с тем же видом."], "L’autre Trocadéro": ["Другое Трокадеро", "Сад Трокадеро · вид на Париж", "Как и парижский, этот сад назван в честь испанского форта.", "Обернись с вершины сада: весь Париж перед тобой.", "Ты на вершине парка Сен-Клу, в саду, который тоже называется Трокадеро, как площадь напротив Эйфелевой башни.\n\nОба названы в честь битвы, которую французская армия выиграла в Испании в 1823 году. Но главный подарок здесь — вид: весь Париж раскинулся перед тобой.\n\nПосмотри на горизонт: видна Эйфелева башня, а левее — башни Дефанса."], "Le port de l’Arsenal": ["Порт Арсенала", "Бассейн Арсенала · марина с 1983 года", "Эти лодки плавают в старом рву парижских укреплений.", "Посмотри на лодки в марине Арсенала, ниже площади Бастилии.", "Ты бежишь вдоль бассейна, полного маленьких лодок, между Сеной и площадью Бастилии.\n\nВ Средние века Париж был окружён стенами, а перед ними для защиты были рвы с водой. Этот бассейн — один из тех старых рвов. В XIX веке он стал портом, соединяющим Сену с каналом Сен-Мартен. С 1983 года это марина, вдоль которой разбит сад.\n\nПосмотри на пришвартованные лодки: они плавают в старом оборонительном рву."], "Le ministère qui enjambe le quai": ["Министерство над набережной", "Министерство финансов · Шеметов и Уидобро, 1989", "Это здание-мост стоит ногами в Сене, и министры иногда приплывают на лодке.", "Посмотри на огромное здание Министерства финансов, нависающее над набережной.", "Ты проходишь под огромным зданием в форме моста. Это Министерство финансов, которое управляет деньгами французского государства.\n\nРаньше министерство занимало часть Лувра. В 1980-е годы президент Франсуа Миттеран захотел отдать музею весь Лувр. Поэтому здесь построили новое здание, законченное в 1989 году. Его конец выходит за набережную к самой Сене, с причалом: министры могут приплыть на лодке.\n\nПосмотри на край здания: его ноги почти в воде."], "Quatre livres ouverts": ["Четыре раскрытые книги", "Национальная библиотека им. Миттерана · Доминик Перро, 1996", "Четыре башни Национальной библиотеки похожи на раскрытые книги.", "Посмотри на четыре Г-образные башни по углам площади библиотеки.", "Перед тобой Национальная библиотека Франции. В ней хранится экземпляр всего, что издаётся в стране.\n\nЗдание открылось в 1996 году. Архитектор Доминик Перро придумал четыре Г-образные башни по углам огромной площади, как четыре раскрытые книги, поставленные стоймя. В центре, ниже уровня земли, растёт настоящий лес высоких сосен: на него можно смотреть, но гулять там нельзя.\n\nПосмотри на четыре башни: представь их полураскрытыми книгами."], "Le musée en plein air": ["Музей под открытым небом", "Сад Тино Росси · с 1980 года", "Вдоль этой набережной скульптуры выставлены без стекла и без билета.", "Посмотри на скульптуры среди деревьев сада Тино Росси.", "Ты в саду Тино Росси у Сены. Это бесплатный музей, открытый днём и ночью.\n\nС 1980 года здесь, между деревьями и рекой, стоят современные скульптуры художников XX века. А летними вечерами маленькие каменные амфитеатры превращаются в танцплощадки: танго, сальса, у самой воды.\n\nПосмотри на скульптуры среди деревьев: каждая — настоящий музейный экспонат."], "Le cimetière du Montparnasse": ["Кладбище Монпарнас", "Кладбище · 1824", "За этой стеной Сартр и Бовуар делят одну могилу.", "Посмотри на стену кладбища Монпарнас, пробегая по авеню.", "Ты бежишь вдоль кладбища Монпарнас.\n\nПримерно с 1920 по 1950 год квартал Монпарнас притягивал художников со всего мира. Многие из них покоятся здесь. Жан-Поль Сартр и Симона де Бовуар, два философа и самая знаменитая интеллектуальная пара Франции, похоронены вместе. Неподалёку поэт Шарль Бодлер. И певец Серж Генсбур тоже здесь.\n\nПосмотри на стены кладбища: за ними покоится добрая часть французской культуры."], "La mire du méridien": ["Знак меридиана", "Парк Монсури · Альфан, 1878", "В этом парке маленький каменный знак отмечает Парижский меридиан.", "Найди в парке маленький каменный знак — «южную миру».", "Ты в парке Монсури, большом саду на юге Парижа, открытом в 1878 году.\n\nОн прячет маленькое сокровище: каменный знак 1806 года, «южную миру». Он стоит точно на Парижском меридиане, воображаемой линии с севера на юг. Пока весь мир не выбрал меридиан, проходящий через Гринвич в Лондоне, Франция всё измеряла от этой линии. Астрономы Парижской обсерватории наводили на этот знак свои инструменты.\n\nПосмотри на маленькую каменную колонну: она стоит точно на меридиане."], "Le parc de Brassens": ["Парк Брассенса", "Парк Жоржа Брассенса · 1985", "Бронзовые лошади у входа напоминают о старом конском рынке.", "Посмотри на бронзовых лошадей у входа и башню аукциона.", "Ты в парке Жоржа Брассенса на юге Парижа.\n\nДо 1970-х годов здесь были бойни и конский рынок. В 1985 году их заменил парк, но кое-что оставили на память: павильоны, башню, с которой объявляли продажи, и статуи лошадей у входа. Парк назван в честь Жоржа Брассенса, певца, которого французы обожают; он жил неподалёку.\n\nПосмотри на бронзовых лошадей у входа: они напоминают о старом рынке."], "La Petite Ceinture du 15e": ["Птит-Сентюр в 15-м округе", "Старая железная дорога · прогулочная тропа с 2013 года", "Полтора километра спящей железной дороги, отданные пешеходам и бегунам.", "Посмотри на рельсы и цветущие насыпи Птит-Сентюр.", "Ты на старой железной дороге, среди травы.\n\nВ XIX веке вокруг всего Парижа шла железная дорога под названием Птит-Сентюр — «малый пояс». На Левом берегу пассажиров по ней не возят с 1934 года. Рельсы остались, а вокруг выросла природа. В 2013 году город открыл здесь тропу вдоль путей.\n\nПосмотри на цветущие откосы и старые мосты: почти деревня посреди города."], "L’opéra du Bicentenaire": ["Опера двухсотлетия", "Опера Бастилия · Карлос Отт, 1989", "Эта стеклянная опера открылась накануне 200-летия Революции.", "Посмотри на большой стеклянный фасад Оперы Бастилии на площади.", "Ты на площади Бастилии. Здесь стояла тюрьма-крепость, которую парижане взяли штурмом 14 июля 1789 года, в начале Французской революции.\n\nЧерез двести лет президент Франсуа Миттеран захотел построить здесь современную оперу, открытую для всех, а не только для богатых. Большое здание из стекла и камня открылось 13 июля 1989 года, накануне 200-летия Революции.\n\nПосмотри на Оперу Бастилию: её главный зал вмещает около 2700 человек."], "Le jardin sur le viaduc": ["Сад на виадуке", "Зелёная аллея Рене Дюмона · 1993", "Ты бежишь по самому первому в мире парку на виадуке.", "Посмотри вниз на кирпичный виадук и его арки.", "Ты на озеленённой дорожке, поднятой над улицами: это Зелёная аллея.\n\nС 1859 по 1969 год по этому кирпичному виадуку ходил поезд от Бастилии до Венсена. Когда линию закрыли, всё могли снести. Но в 1993 году путь превратили в сад длиной почти 5 километров. Это была первая такая прогулочная дорожка в мире. Она вдохновила знаменитый нью-йоркский Хай-Лайн.\n\nПосмотри под ноги: ты бежишь по старой железной дороге."], "Le palais de 1931": ["Дворец 1931 года", "Дворец Порт-Доре · Альбер Лапрад, 1931", "Его фасад — огромная резная фреска, след спорной выставки.", "Посмотри на большой резной фасад дворца Порт-Доре.", "Ты проходишь мимо большого дворца с колоннами — дворца Порт-Доре.\n\nЕго построили в 1931 году для Колониальной выставки. Тогда у Франции была огромная империя с колониями в Африке и Азии, и выставка должна была её прославить. Весь фасад покрыт гигантским рельефом с изображением этих далёких земель. С 2007 года во дворце находится Музей истории иммиграции, который смотрит на это прошлое по-другому.\n\nПосмотри на фасад: рельеф опоясывает всё здание."], "Le lac de la Jambe de bois": ["Озеро Деревянной Ноги", "Озеро Домениль · Вторая империя", "Это озеро названо в честь генерала, который отказался сдать Венсен.", "Посмотри на два острова озера и маленький храм над гротом.", "Ты дошёл до озера Домениль в Венсенском лесу, большом лесу к востоку от Парижа.\n\nОзеро названо в честь генерала Домениля, который потерял ногу в бою. Его прозвали «Деревянной Ногой». В 1814 году Наполеон только что проиграл войну, вражеские армии были в Париже. Домениль защищал Венсенский замок. Ему велели сдаться. Говорят, он ответил: «Я сдам Венсен, когда вы вернёте мне мою ногу».\n\nПосмотри на озеро и его острова: они носят его имя."], "Les archives de la planète": ["Архивы планеты", "Музей и сады Альбера Кана · Булонь", "Ещё до 1914 года банкир отправил фотографов снимать весь мир — в цвете.", "Посмотри на сады музея Альбера Кана с японским уголком.", "Ты проходишь мимо музея и садов Альбера Кана в Булони.\n\nАльбер Кан был очень богатым банкиром с мечтой: сохранить облик всей планеты, пока она не изменилась. С 1909 года он платил фотографам, чтобы они ездили примерно в пятьдесят стран. Они привезли 72 000 цветных фотографий, одних из самых первых в истории. Вокруг своего дома он также разбил сады со всего мира: японский, английский, французский.\n\nЗагляни за стены: видны деревья его японского сада."], "L’île Renault": ["Остров Renault", "Остров Сеген · завод 1929–1992", "Весь этот остров был автозаводом, «крепостью рабочих».", "Посмотри на остров Сеген посреди Сены.", "Ты бежишь вдоль острова Сеген, посреди Сены в Булонь-Бийанкуре.\n\nЗдесь родился автопроизводитель Renault. С 1929 года компания застроила заводскими корпусами весь остров. Здесь работали десятки тысяч рабочих. Завод прославился большими забастовками. Последняя машина сошла с конвейера в 1992 году. Сегодня на острове концертные залы и сады.\n\nПосмотри на остров: представь, что он целиком покрыт заводами."], "La voile qui suit le soleil": ["Парус, который следует за солнцем", "Сен-Мюзикаль · Сигэру Бан, 2017", "На оконечности острова парус из солнечных панелей поворачивается за солнцем.", "Посмотри на большой парус из солнечных панелей Сен-Мюзикаль.", "Ты на оконечности острова на Сене. Большое здание — это Сен-Мюзикаль, концертная площадка, открытая в 2017 году.\n\nЕё архитекторы, японец Сигэру Бан и француз Жан де Гастин, придумали зал в форме яйца, облицованный деревом. Вокруг него огромный парус, покрытый солнечными панелями, днём поворачивается вслед за солнцем, как подсолнух.\n\nПосмотри на большой парус: в зависимости от времени дня он будет в разных местах."], "La tour aux figures": ["Башня фигур", "Остров Сен-Жермен · Жан Дюбюффе, 1988", "Скульптура высотой 24 метра, внутрь которой можно войти, вся в чёрных, красных и синих линиях.", "Посмотри на высокую белую башню с чёрными, красными и синими линиями.", "Ты на острове Сен-Жермен. Перед тобой башня, похожая на гигантский детский рисунок.\n\nЭто «Башня фигур» французского художника и скульптора Жана Дюбюффе. Он придумал её в 1960-е годы в своём стиле: белые формы, обведённые чёрным, с пятнами красного и синего. Построили её только в 1988 году, после его смерти. Её высота 24 метра, а внутри спрятана винтовая лестница.\n\nПосмотри на её чёрные линии: словно рисунок, вставший на ноги."], "La porte de l'avenue Rapp": ["Дверь на авеню Рапп", "Модерн · Жюль Лавиротт, 1901", "Самая дерзкая дверь Парижа — с Адамом, Евой и ящерицами.", "Встань на противоположный тротуар и посмотри на большую дверь дома 29 по авеню Рапп.", "Ты на авеню Рапп, рядом с Эйфелевой башней. Встань на противоположный тротуар, чтобы увидеть дом целиком.\n\nЕго построил около 1900 года Жюль Лавиротт, очень смелый архитектор модерна — стиля, полного растительных изгибов. Фасад покрыт керамикой. Дверь обрамляют Адам и Ева, а на створках — железные ящерицы. В 1901 году дом победил в конкурсе на самый красивый фасад Парижа.\n\nПосмотри на дверь: найди Адама, Еву и ящериц."], "Le Dôme des Invalides": ["Купол Дома инвалидов", "Королевская капелла · Жюль Ардуэн-Мансар, 1677", "Наполеон двадцать лет ждал, чтобы попасть в свою гробницу.", "С площади Вобан подними глаза на золотой купол Дома инвалидов.", "Перед тобой золотой купол Дома инвалидов, его видно со всего Парижа.\n\nДом инвалидов — это госпиталь, который король Людовик XIV построил для своих раненых солдат. В 1677 году он поручил купол Жюлю Ардуэн-Мансару, архитектору Версаля. Здесь похоронен Наполеон. После поражения его сослали на остров Святой Елены, крошечный остров посреди Атлантики, где он умер в 1821 году. В 1840 году его тело вернули в Париж. Он покоится под этим куполом.\n\nПосмотри на купол с площади Вобан: оттуда лучший вид."], "Rodin à l'hôtel Biron": ["Роден в особняке Бирон", "Особняк · XVIII век", "Соседями Родена были Матисс, Кокто, Айседора Дункан и Рильке.", "Посмотри на особняк Бирон и его сад скульптур на улице Варенн.", "Ты у особняка Бирон, большого дома XVIII века с садом. Это музей Родена.\n\nОгюст Роден — скульптор «Мыслителя», сидящего человека, погружённого в раздумья, подперев подбородок рукой. В начале XX века этот дом сдавали художникам по комнатам. В 1908 году Роден снял несколько комнат, а потом весь дом. Он подарил свои работы государству с одним условием: чтобы здесь был его музей.\n\nЗагляни в сад: «Мыслитель» там."], "Le Grand Palais": ["Гран-Пале", "Всемирная выставка · 1900", "Под его гигантской стеклянной крышей фехтовальщики соревновались на Олимпиаде 2024 года.", "Подними глаза на стеклянную крышу и бронзовые колесницы по углам.", "Перед тобой Гран-Пале с огромной стеклянной крышей.\n\nЕго построили к Всемирной выставке 1900 года — огромному шоу, куда весь мир приезжал показать свои изобретения. Главный зал под стеклянной крышей размером с два футбольных поля. Во время реконструкции здесь проходило фехтование Олимпиады Париж-2024. Полностью он вновь открылся в 2025 году.\n\nПосмотри на углы крыши: бронзовые колесницы, запряжённые лошадьми."], "L'avion des Galeries Lafayette": ["Самолёт «Галери Лафайет»", "Подвиг · Жюль Ведрин, 1919", "19 января 1919 года на крышу этого универмага приземлился самолёт.", "Подними глаза на крышу «Галери Лафайет».", "Ты у «Галери Лафайет», универмага на бульваре Осман.\n\nВ 1919 году, чтобы о нём заговорили, магазин пообещал большую премию первому пилоту, который сядет на его крышу. Жюль Ведрин, отчаянный лётчик, принял вызов. 19 января 1919 года он посадил там свой маленький самолёт и остановился в двух шагах от края. Но летать над Парижем было запрещено: ему выписали небольшой штраф.\n\nПосмотри на крышу: больше ста лет назад туда сел самолёт."], "La tour Saint-Jacques": ["Башня Сен-Жак", "Готическая колокольня · 1509–1523", "Последний остаток церкви, откуда паломники отправлялись в Компостелу.", "Подними глаза на башню Сен-Жак и статую Паскаля у её подножия.", "Перед тобой высокая готическая башня, одиноко стоящая в саду: башня Сен-Жак, высотой 52 метра.\n\nЭто была колокольня церкви, разрушенной во время Революции. Церковь принимала паломников, отправлявшихся пешком в Сантьяго-де-Компостела в Испании — великое христианское паломничество. Говорят, что в XVII веке учёный Блез Паскаль проводил здесь опыты с атмосферным давлением. Его статуя стоит внизу.\n\nПосмотри на самый верх: маленькая метеостанция до сих пор измеряет парижскую погоду."], "La fontaine Stravinsky": ["Фонтан Стравинского", "Скульптура · Тэнгли и Ники де Сен-Фалль, 1983", "Шестнадцать скульптур танцуют под музыку Стравинского.", "Посмотри на бассейн и его яркие скульптуры, которые крутятся и брызгают водой.", "Ты рядом с Центром Помпиду, перед бассейном, полным движущихся скульптур.\n\nВ 1983 году их установила здесь пара художников. Жан Тэнгли сделал крутящиеся чёрные машины. Ники де Сен-Фалль — круглые разноцветные фигуры. Вместе они отдали дань композитору Игорю Стравинскому: скульптуры вдохновлены его музыкой — жар-птица, русалка, скрипичный ключ.\n\nПосмотри, как чёрные машины брызгают на разноцветные скульптуры."], "Saint-Eustache": ["Сент-Эсташ", "Церковь · 1532–1640", "Здесь крестили Ришельё, Мольера и мадам де Помпадур.", "Посмотри на огромный фасад церкви Сент-Эсташ.", "Перед тобой Сент-Эсташ, огромная церковь в Ле-Аль, когда-то главном рынке Парижа.\n\nЕё строили с 1532 по 1640 год. Здесь крестили знаменитостей: кардинала Ришельё, министра Людовика XIII, и Мольера, драматурга. В 1778 году композитор Моцарт, бывший тогда в Париже, отпевал здесь свою мать. В её органе почти 8000 труб.\n\nПосмотри на фасад, а потом зайди и послушай, не играет ли орган."], "La colonne de Catherine de Médicis": ["Колонна Екатерины Медичи", "Биржа коммерции · 1574 и 2021", "Колонна астролога, прилепленная к ротонде большого музея современного искусства.", "Посмотри на полую колонну, прикреплённую к ротонде Биржи коммерции.", "Ты у Биржи коммерции, круглого здания. К нему прижата странная колонна.\n\nКолонна 1574 года. Это всё, что осталось от дворца Екатерины Медичи, королевы родом из Италии и матери трёх французских королей. Говорят, её астролог поднимался на колонну, чтобы читать будущее по звёздам. С 2021 года круглое здание стало музеем современного искусства коллекционера Франсуа Пино.\n\nПосмотри на верх колонны: оттуда астролог наблюдал небо."], "La Rotonde de la Villette": ["Ротонда Ла-Виллет", "Таможенный павильон · Клод-Никола Леду", "Сестра-близнец ротонды парка Монсо, в конце канала.", "Посмотри на большую ротонду с колоннами в конце бассейна Ла-Виллет.", "Ты на площади Сталинграда, перед круглым зданием с колоннами: это ротонда Ла-Виллет.\n\nДо 1860 года Париж был окружён стеной. Она была не для обороны, а чтобы брать пошлину со всего, что ввозили в город: с вина, мяса, дров. Архитектор Клод-Никола Леду спроектировал таможенные павильоны. Парижане ненавидели эту стену. Из её зданий сохранились лишь четыре, и это одно из них.\n\nПосмотри на колонны: настоящий храм для простой налоговой конторы."], "Les Buttes-Chaumont": ["Бют-Шомон", "Парк · Адольф Альфан, 1867", "Старая свалка, превращённая в самый эффектный парк Парижа.", "Посмотри на скалу, озеро и маленький храм на вершине острова.", "Ты у парка Бют-Шомон, в 19-м округе.\n\nРаньше это было мрачное место: свалка, карьеры, а рядом — старое место, где вешали осуждённых. При императоре Наполеоне III инженер Адольф Альфан, создавший многие парки Парижа, превратил всё это в парк. Он открылся в 1867 году. Скала, водопад, грот и озеро почти полностью рукотворные.\n\nПосмотри на маленький храм на вершине острова. Пристегни велосипед: парк лучше всего смотреть пешком."], "L'Hôtel du Nord": ["«Отель дю Нор»", "Кино · Марсель Карне, 1938", "«Атмосфера, атмосфера...» — самая знаменитая фраза канала.", "Посмотри на фасад «Отеля дю Нор» напротив пешеходного мостика через канал.", "Ты на канале Сен-Мартен, у «Отеля дю Нор» — «Северного отеля».\n\nРаньше это была маленькая скромная гостиница. Сын хозяев, писатель Эжен Даби, написал о ней роман. В 1938 году режиссёр Марсель Карне снял по нему культовый фильм. Актриса Арлетти произносит там самую знаменитую фразу французского кино — про «атмосферу». При этом фильм целиком сняли в студии.\n\nПосмотри на фасад и канал: именно эту сцену заново построили для фильма."], "Le lac de l'Opéra": ["Озеро Оперы", "Оперный театр · Шарль Гарнье, 1875", "Под сценой есть озеро, которое, возможно, вдохновило «Призрака Оперы».", "Посмотри на позолоченный фасад Оперы Гарнье.", "Перед тобой Опера Гарнье, большой оперный театр Парижа, достроенный в 1875 году.\n\nВ 1861 году, в начале стройки, у архитектора Шарля Гарнье возникла проблема: земля была полна воды. Чтобы защитить фундамент, он построил под зрительным залом огромный водонепроницаемый резервуар. Это «озеро» Оперы, и оно до сих пор полно воды. Говорят, оно подсказало писателю Гастону Леру убежище Призрака Оперы.\n\nПосмотри на золотой фасад: у тебя под ногами озеро."], "La Ruche": ["Улей", "Колония художников · Альфред Буше, 1902", "Шагал, Сутин и Модильяни работали под крышей павильона Всемирной выставки.", "С прохода Данциг посмотри на ротонду «Улья» и её ворота.", "Ты у «Улья», круглого здания, спрятанного в глубине сада.\n\nВ 1900 году в Париже прошла Всемирная выставка. После неё скульптор Альфред Буше собрал части разобранных павильонов. Его идея: селить бедных художников почти бесплатно. Здесь жили нищие художники и скульпторы со всей Европы, например Марк Шагал и Амедео Модильяни. Знаменитыми они стали позже.\n\nПосмотри на ротонду: её прозвали «Ульем», потому что художники работали здесь, как пчёлы."], "L'atelier de Bourdelle": ["Мастерская Бурделя", "Музей художника · 1885–1929", "Мастерская скульптора, оставленная как была, и вход бесплатный.", "Посмотри на большие бронзовые статуи в саду музея Бурделя.", "Ты у музея Бурделя на Монпарнасе.\n\nАнтуан Бурдель был скульптором. Он начинал помощником Родена, автора «Мыслителя», а потом прославился сам. Он работал в этих мастерских с 1885 года до своей смерти в 1929-м. Всё на месте: гигантские гипсовые фигуры, бронза, каменные блоки. С 1949 года это музей, и вход бесплатный.\n\nЗагляни в сад: тебя ждут его большие бронзовые статуи."], "La tour Montparnasse": ["Башня Монпарнас", "Небоскрёб · 1973", "Единственный небоскрёб Парижа — и из-за него запретили все остальные.", "Подними глаза на тёмную башню Монпарнас.", "Ты у подножия башни Монпарнас, достроенной в 1973 году. Её высота 210 метров.\n\nДолгое время это было самое высокое здание Франции. Но парижане её ненавидят. Она так шокировала людей, что вскоре в центре Парижа запретили строить башни. Поэтому она стоит одна. Парижане любят говорить, что лучший вид на Париж — с этой башни: это единственное место, откуда её не видно.\n\nПосмотри на самый верх: там панорамная терраса."], "La Closerie des Lilas": ["«Клозери де Лила»", "Кафе · 1847", "Хемингуэй писал здесь по утрам под присмотром одного из маршалов Наполеона.", "Посмотри на террасу «Клозери де Лила» и статую маршала Нея перед ней.", "Ты у «Клозери де Лила», кафе, открытого в 1847 году.\n\nОно стало местом встреч художников: здесь бывали живописец Сезанн, писатель Эмиль Золя, позже Пикассо. В 1920-е годы Эрнест Хемингуэй, молодой и бедный американский журналист, приходил сюда писать по утрам. Он рассказывает об этом в книге «Праздник, который всегда с тобой» о своих парижских годах. Перед кафе стоит статуя маршала Нея, одного из лучших генералов Наполеона, расстрелянного неподалёку в 1815 году.\n\nПосмотри на террасу: там писал Хемингуэй."], "Le pavillon des Indes": ["Индийский павильон", "Всемирная выставка · 1878", "Индийский дворец со Всемирной выставки 1878 года, уцелевший в пригородном парке.", "Посмотри на резной деревянный павильон в парке Бекон у Сены.", "Ты в Курбевуа, перед маленьким резным деревянным павильоном, который будто приехал издалека.\n\nВ 1878 году в Париже прошла Всемирная выставка — огромное шоу, где каждая страна показывала лучшее. Принц Уэльский, будущий король Англии, велел построить два павильона, чтобы представить искусство Индии, тогда британской колонии. После выставки один разрушила буря. Другой оказался здесь и уцелел.\n\nПосмотри на резное дерево: кусочек Индии в пригороде."], "La Grande Arche": ["Большая арка", "Архитектура · Йохан Отто фон Спрекельсен, 1989", "Полый куб со стороной 110 метров, повёрнутый на 6,33 градуса.", "Подними глаза на Большую арку, а потом обернись к Триумфальной арке вдали.", "Ты у подножия Большой арки — гигантского полого куба.\n\nОна открылась в 1989 году, к 200-летию Французской революции. Её архитектор — датчанин Йохан Отто фон Спрекельсен. Каждая сторона — 110 метров: внутри поместился бы Нотр-Дам. Она завершает большую прямую, которая идёт от Лувра по Елисейским Полям через Триумфальную арку. Она немного повёрнута, отчасти потому, что под ней проходят вокзал и автострада.\n\nОбернись: в самом конце видна Триумфальная арка."], "Le CNIT": ["CNIT", "Архитектура · Камело, де Майи, Зерфюсс, 1958", "Бетонный свод опирается всего на три точки в 218 метрах друг от друга.", "Посмотри на огромный треугольный свод CNIT на площади.", "Перед тобой CNIT, Национальный центр промышленности и техники, — здание в форме гигантского треугольного паруса.\n\nЭто самое первое большое здание Дефанса. Его открыл генерал де Голль в 1958 году. Здесь собирались показывать машины, сделанные во Франции. Его бетонная крыша опирается всего на три точки, в 218 метрах друг от друга, без единой колонны посередине.\n\nПосмотри на крышу: огромный бетонный свод на трёх ногах."], "La Défense de Paris": ["Защита Парижа", "Статуя · Луи-Эрнест Барриас, 1883", "Статуя 1883 года дала имя крупнейшему деловому кварталу Европы.", "Найди на площади бронзовую статую «Защита Парижа».", "Ты в Дефансе, деловом квартале, перед бронзовой статуей.\n\nПочему «Дефанс», то есть «защита»? В 1870 году Франция воевала с Пруссией, и Париж был окружён. Здесь сражались, чтобы защитить город. В 1883 году в честь защитников поставили эту статую. Она называется «Защита Парижа». Перекрёсток получил её имя, а когда появились башни, имя осталось.\n\nПосмотри на статую среди башен: это она дала имя кварталу."], "Le Castel Béranger": ["Кастель Беранже", "Модерн · Эктор Гимар, 1898", "Ранний шедевр архитектора, создавшего входы в метро.", "Подойди поближе к входной решётке Кастель Беранже — сплошь завитки железа.", "Ты на улице Лафонтена, в 16-м округе, у Кастель Беранже.\n\nЕго архитектор Эктор Гимар был мастером модерна — стиля, полного изгибов, вдохновлённых растениями. Это он придумал знаменитые входы в парижское метро. Здесь около 1898 года он построил свой первый большой жилой дом и придумал абсолютно всё: фасад, ограды, обои, даже дверные ручки.\n\nПосмотри на входную дверь: её металлические изгибы уже предвещают входы в метро."], "La piscine Molitor": ["Бассейн «Молитор»", "Ар-деко · Люсьен Полле, 1929", "Его открывал Тарзан, и здесь впервые показали бикини.", "Посмотри на жёлтый фасад бассейна «Молитор» в стиле ар-деко.", "Ты у бассейна «Молитор», открытого в 1929 году. Его задумали как большой океанский лайнер, с иллюминаторами.\n\nНа открытии первым нырнул Джонни Вайсмюллер, олимпийский чемпион по плаванию и будущий Тарзан в кино. В 1946 году дизайнер Луи Реар показал здесь крошечный женский купальник: бикини. Бассейн закрыли в 1989 году, граффитисты расписали его стены, а в 2014-м он снова открылся.\n\nПосмотри на иллюминаторы и трапы: будто ты на корабле."], "Le Corbusier chez lui": ["Ле Корбюзье у себя дома", "Дом «Молитор» · 1934", "Ле Корбюзье тридцать лет жил на верхнем этаже этого стеклянного дома.", "Подними глаза на два верхних этажа стеклянного дома на улице Нунжессер-э-Коли.", "Перед тобой жилой дом со стеклянными фасадами, построенный в 1934 году.\n\nЕго архитектор Ле Корбюзье — самый знаменитый архитектор-модернист. Он любил белые стены и большие окна. Он построил этот дом вместе с кузеном, прямо на границе Парижа и Булони. Два верхних этажа он оставил себе. По утрам он там рисовал и жил там до своей смерти в 1965 году.\n\nПосмотри на верх дома: там была его квартира."], "La mairie de Tony Garnier": ["Мэрия Тони Гарнье", "Ар-деко · Тони Гарнье, 1934", "Ультрасовременная мэрия, задуманная мэром-строителем.", "Посмотри на строгий бетонный объём мэрии Булони.", "Ты в Булони, сразу к западу от Парижа, у мэрии.\n\nВ 1920–30-е годы Булонь быстро росла: заводы Renault, киностудии. Мэр хотел современный город. Он попросил Тони Гарнье, архитектора из Лиона, влюблённого в бетон, спроектировать новую мэрию. Её закончили в 1934 году: простое здание с прямыми линиями, без колонн и позолоты.\n\nПосмотри на строгий фасад: современная мэрия для современного города."], "La place des Vosges": ["Площадь Вогезов", "Королевская площадь · 1612", "Виктор Гюго шестнадцать лет жил под этими аркадами.", "Посмотри на фасады из красного кирпича и аркады вокруг площади.", "Ты на площади Вогезов, самой старой площади Парижа, спланированной целиком.\n\nОна открылась в 1612 году под названием Королевская площадь. Все дома одинаковые: красный кирпич, белый камень, внизу аркады. Позже писатель Виктор Гюго, автор «Отверженных», жил в доме номер 6, с 1832 по 1848 год. Его квартира сегодня — бесплатный музей.\n\nПосмотри на одинаковые фасады, а потом найди дом номер 6."], "La girafe du roi": ["Королевский жираф", "Зверинец · Ботанический сад", "Первый жираф Франции пришёл сюда пешком из самого Марселя.", "Посмотри на вход в зверинец Ботанического сада.", "Ты в Ботаническом саду, рядом со зверинцем, старейшим зоопарком Франции.\n\nВ 1826 году правитель Египта подарил французскому королю Карлу X жирафа. Во Франции никто никогда не видел жирафов. Она прибыла на корабле в Марсель. Для конной повозки она была слишком высокой, поэтому шла до Парижа пешком: 900 километров. Её звали Зарафа. Она поселилась здесь, и больше 100 000 парижан пришли на неё посмотреть. Мода сошла с ума: женщины носили причёски «а-ля жираф».\n\nПосмотри на вольеры: здесь жила Зарафа."], "Notre-Dame et le point zéro": ["Нотр-Дам и нулевой километр", "Собор · 1163–2024", "Перед собором маленькая табличка отмечает нулевую точку всех дорог Франции.", "С набережной Левого берега посмотри на заднюю часть Нотр-Дама, его шпиль и аркбутаны.", "Перед тобой Нотр-Дам-де-Пари, самый знаменитый собор в мире, начатый в 1163 году.\n\n15 апреля 2019 года пожар уничтожил его крышу, а шпиль рухнул в прямом эфире. После пяти лет работ собор снова открылся в декабре 2024 года, с новым точно таким же шпилем. На площади перед ним маленькая табличка отмечает нулевую точку: от неё отсчитывают расстояния по дорогам от Парижа.\n\nПосмотри на землю перед собором: найди маленькую бронзовую звезду."], "La fontaine Médicis": ["Фонтан Медичи", "Фонтан · около 1630", "Королевский фонтан, которому пришлось отступить на тридцать метров, чтобы освободить место для улицы.", "Посмотри на фонтан в виде грота и великана, подглядывающего за влюблёнными.", "Ты в Люксембургском саду, перед фонтаном в виде грота в конце длинного бассейна.\n\nОколо 1630 года королева Мария Медичи, родом из Флоренции, велела построить его, чтобы он напоминал ей о доме. В XIX веке добавили статуи из греческого мифа: наверху великан Полифем подглядывает за двумя влюблёнными, Акидом и Галатеей. Для Акида всё кончается плохо.\n\nПосмотри на верх грота: великан следит за ними. Учти, что в саду нельзя ездить на велосипеде."], "L'Arena de la Chapelle": ["Арена Ла-Шапель", "Олимпийская арена · SCAU и NP2F, 2024", "Единственная новая арена, построенная в самом Париже к Играм 2024 года.", "Посмотри на большую «Адидас Арену» у Порт-де-ла-Шапель.", "Ты у Арены Ла-Шапель, спортивного зала, открытого в 2024 году.\n\nЭто единственный большой объект, построенный в самом Париже к Олимпиаде 2024 года. Олимпийским летом здесь проходили бадминтон и художественная гимнастика. Идея была ещё и в том, чтобы оживить этот район, долго отрезанный от остального города окружной дорогой и железнодорожными путями.\n\nПосмотри на здание: кусочек парижских Игр, оставленный кварталу."], "Le Centre aquatique olympique": ["Олимпийский центр водных видов спорта", "Олимпийский объект · 2024", "Единственный большой постоянный объект, построенный для Игр Париж-2024.", "Посмотри на огромный деревянный каркас и изогнутую крышу центра.", "Ты у Олимпийского центра водных видов спорта, напротив «Стад де Франс».\n\nЕго построили к Олимпийским играм 2024 года. Это единственный большой постоянный спортивный объект, возведённый для этих Игр. Каркас сделан из дерева, крыша большая и изогнутая — чтобы меньше загрязнять природу. Здесь проходили прыжки в воду и водное поло. Сегодня сюда приходят плавать местные жители и школьники.\n\nПосмотри на деревянную крышу: её задумали так, чтобы она служила и после Игр."], "La basilique des rois": ["Базилика королей", "Базилика · аббат Сугерий, 1144", "Здесь родилась готика и здесь похоронены короли Франции.", "Посмотри на фасад базилики Сен-Дени, а потом зайди внутрь к большим витражам.", "Ты перед базиликой Сен-Дени, сразу к северу от Парижа.\n\nСвятой Дионисий был первым епископом Парижа. По легенде, около 250 года ему отрубили голову на Монмартре, и он дошёл сюда, неся свою голову в руках. На его могиле построили церковь. Около 1140 года аббат Сугерий перестроил её — с тонкими колоннами и огромными витражами. Так родилась готика. Здесь похоронены почти все короли Франции.\n\nПосмотри на фасад: за ним лежат гробницы королей."], "Le canal Saint-Denis": ["Канал Сен-Дени", "Канал · 1821", "Шесть километров вдоль воды — от Сены до Ла-Виллет.", "Посмотри на канал, шлюзы и бечевник, уходящий в Париж.", "Ты на берегу канала Сен-Дени, открытого в 1821 году.\n\nОн соединяет Сену в Сен-Дени с бассейном Ла-Виллет в Париже — чуть больше шести километров. Долгое время вдоль него стояли заводы: баржи везли уголь, дерево и товары. Их тянули лошади, шагая по дорожке вдоль воды.\n\nПосмотри на дорожку у канала: где раньше шли лошади, теперь катаются на велосипедах."], "La colonne de Juillet": ["Июльская колонна", "Памятник · 1840", "До колонны здесь собирались поставить гигантского слона.", "Подними глаза на колонну и золотого Гения свободы на площади Бастилии.", "Ты на площади Бастилии, перед 47-метровой колонной с золотой фигурой наверху.\n\nОна посвящена не революции 1789 года, а другой. В июле 1830 года парижане три дня бунтовали и прогнали короля Карла X. Эти дни называют «Три славных дня». Погибшие в боях покоятся под колонной. А до неё Наполеон хотел поставить здесь фонтан в виде гигантского слона. Сделали только макет.\n\nПосмотри на золотую фигуру наверху: она прославляет свободу."], "Le faubourg des ébénistes": ["Предместье краснодеревщиков", "Ремесло · с XV века", "Здесь столяры работали без хозяев и без цеховых правил.", "Толкни ворота на улице Фобур-Сент-Антуан и загляни во дворы мастеров.", "Ты на улице Фобур-Сент-Антуан — длинной улице, уходящей от Бастилии.\n\nВ Средние века, чтобы быть ремесленником в Париже, нужно было соблюдать очень строгие правила своего цеха и платить налоги. Но в XV веке король Людовик XI разрешил ремесленникам, поселившимся здесь, работать свободно. Сюда хлынули столяры и краснодеревщики, которые делают дорогую мебель. На века квартал стал столицей мебели.\n\nПосмотри на дворы и проходы: это старые мастерские."], "Le donjon de Vincennes": ["Донжон Венсена", "Королевский замок · 1370", "Самый высокий донжон Европы, где сидел в заключении великий философ.", "Подними глаза на донжон Венсена — высокую квадратную башню замка.", "Ты у Венсенского замка, к востоку от Парижа. В центре стоит огромная квадратная башня — донжон.\n\nЕго достроили около 1370 года, при короле Карле V. Высотой около пятидесяти метров, это самый высокий донжон Европы. Позже он стал тюрьмой. В 1749 году здесь заперли философа Дени Дидро за слишком свободные идеи. Его друг Жан-Жак Руссо ходил к нему пешком.\n\nПосмотри на донжон: за этими стенами сидел Дидро."], "Le Train Bleu": ["«Голубой экспресс»", "Вокзальный ресторан · 1900", "Вокзальный ресторан с 41 картиной, построенный к Всемирной выставке 1900 года.", "Посмотри вверх по лестнице на Лионском вокзале — на большие окна «Голубого экспресса».", "Ты на Лионском вокзале, у ресторана Le Train Bleu — «Голубой экспресс».\n\nЕго открыли к Всемирной выставке 1900 года. Железнодорожная компания, возившая пассажиров из Парижа к Средиземному морю, хотела роскошный ресторан: позолота, люстры и 41 картина с городами, через которые шли её поезда, вплоть до Лазурного берега. Название — в честь знаменитого роскошного поезда в Ниццу и Монако.\n\nПосмотри на расписные потолки: ради них стоит зайти хотя бы на кофе."], "Le mariage de Picasso": ["Свадьба Пикассо", "Православный собор · 1861", "День, когда Пикассо женился под золотыми луковками куполов.", "Подними глаза на золотые купола собора на улице Дарю.", "Ты у собора Святого Александра Невского с золотыми куполами-луковками. Это главная русская церковь Парижа, освящённая в 1861 году.\n\nВ 1918 году художник Пабло Пикассо обвенчался здесь с Ольгой Хохловой — балериной «Русских балетов», самой современной труппы того времени. Свидетелями были три его знаменитых друга, писатели и поэты: Жан Кокто, Макс Жакоб и Гийом Аполлинер.\n\nПосмотри на золотые купола: под ними Пикассо шёл к венцу."], "L'Élysée avant les présidents": ["Елисейский дворец до президентов", "Президентский дворец · 1718–1722", "Фаворитка короля, отрёкшийся император — и только потом президенты.", "Посмотри на охраняемые ворота Елисейского дворца, не останавливаясь.", "Ты на улице Фобур-Сент-Оноре, у ворот, которые охраняет полиция. За ними — Елисейский дворец.\n\nЗдесь живёт и работает президент Франции. Дворец построили в начале XVIII века для одного графа. В 1753 году его купила мадам де Помпадур, фаворитка короля Людовика XV. В 1815 году, сразу после поражения при Ватерлоо, Наполеон подписал здесь отречение — отказался от власти. С 1873 года это резиденция президентов.\n\nПосмотри на ворота, но не задерживайся: полиция этого не любит."], "Le musée d'Ennery": ["Музей д'Эннери", "Музей · коллекция Клеманс д'Эннери, 1908", "Семь тысяч азиатских вещиц, спрятанных в особняке на авеню Фош.", "Посмотри на фасад музея д'Эннери на авеню Фош.", "Ты на авеню Фош, у крошечного и почти неизвестного музея.\n\nОколо 1900 года Париж был очарован Азией. Клеманс д'Эннери, жена известного драматурга, собирала предметы из Китая и Японии — около 7000. Многие из них — нэцкэ, маленькие резные японские фигурки, которые подвешивали к кимоно. Она завещала дом и коллекцию государству. Музей открылся в 1908 году.\n\nПосмотри на фасад: за ним тысячи маленьких сокровищ Азии."], "Le palais d'Iéna": ["Йенский дворец", "Архитектура · Огюст Перре, 1939", "Бетонный дворец, задуманный для показа плотин и мостов.", "Посмотри на колонны Йенского дворца — тонкие внизу и расширяющиеся кверху.", "Ты перед Йенским дворцом — большим бетонным зданием, достроенным в 1939 году.\n\nЕго архитектор Огюст Перре доказал, что бетон может быть красивым. Его называют поэтом бетона. Здание строили для музея великих инженерных сооружений — мостов, плотин. Сегодня здесь заседает Экономический, социальный и экологический совет — собрание, которое даёт советы правительству.\n\nПосмотри на колонны: тонкие внизу, шире наверху, а в бетоне — зелёные и розовые камешки."], "Le palais Galliera": ["Дворец Гальера", "Дворец · Леон Жинен, 1878–1894", "Дворец, построенный для коллекции, которая так и не приехала.", "Посмотри на дворец Гальера и его сад напротив Музея современного искусства.", "Ты у дворца Гальера — каменного дворца посреди сада.\n\nГерцогиня Гальера была невероятно богатой итальянской аристократкой. В 1878 году она построила этот дворец, чтобы показывать свои картины и подарить их Парижу. Но в 1886 году закон изгнал из Франции семьи бывших королей, среди них её друзей. Обидевшись, она оставила картины в Италии. Дворец остался пустым. С 1977 года здесь Музей моды Парижа.\n\nПосмотри на этот роскошный дворец: строили для картин, а в итоге в нём платья."], "La maison Yves Saint Laurent": ["Дом Ив Сен-Лорана", "Музей · дом моды 1974–2002", "Почти тридцать лет за этими окнами рождалась высокая мода.", "Посмотри на окна особняка на авеню Марсо, 5.", "Ты на авеню Марсо, у элегантного городского особняка.\n\nИв Сен-Лоран — один из величайших модельеров XX века. Это он одел женщин в смокинг и брюки. В 1974 году он устроил здесь свой дом моды. Почти тридцать лет его коллекции рождались в этих стенах. С 2017 года здесь музей: его мастерскую можно увидеть так, будто он только что вышел.\n\nПосмотри на верхние окна: там он рисовал."], "Deyrolle": ["Деироль", "Лавка натуралиста · с 1831 года", "Бабочки, чучела и школьные таблицы — на улице Бак с 1888 года.", "Посмотри на витрину Deyrolle на улице Бак, 46.", "Ты на улице Бак, у Deyrolle — лавки, не похожей ни на одну другую.\n\nЕё основали в 1831 году, чтобы продавать музеям чучела животных, насекомых и ракушки. Её большие иллюстрированные таблицы с растениями и животными висели в классах у поколений французских школьников. В 2008 году пожар уничтожил почти всё. Лавку отстроили заново.\n\nПоднимись на второй этаж: там тебя ждут лев, медведь и зебра."], "Le Lutetia": ["«Лютеция»", "Роскошный отель · 1910", "Отель для покупателей «Бон Марше», а в 1945-м — место встреч.", "Посмотри на фасад «Лютеции» в стиле модерн и мемориальную доску на бульваре Распай.", "Ты на бульваре Распай, у «Лютеции» — большого отеля, открытого в 1910 году.\n\nЕго построили владельцы соседнего универмага «Бон Марше», чтобы селить богатых покупателей. Во время Второй мировой войны немецкая армия оккупировала Париж и заняла отель. В 1945 году, в конце войны, «Лютеция» принимала депортированных, возвращавшихся из нацистских лагерей. Семьи приходили сюда с фотографиями в надежде найти близких.\n\nПосмотри на доску на фасаде: она напоминает об этих встречах."], "La rue Gaston-Gallimard": ["Улица Гастона Галлимара", "Издательство · здесь с 1929 года", "Улица, названная в честь своего издателя.", "Посмотри на табличку улицы Гастон-Галлимар и дверь издательства.", "Ты на улице Гастон-Галлимар — маленькой улочке в 7-м округе.\n\n«Галлимар» — самое известное издательство Франции. Его основал Гастон Галлимар в 1911 году. Сюда оно переехало в 1929-м, а позже улицу назвали его именем. Здесь печатали Марселя Пруста, Альбера Камю, Жан-Поля Сартра и Антуана де Сент-Экзюпери, автора «Маленького принца».\n\nПосмотри на дверь: через неё проходили величайшие писатели XX века."], "L'Institut de France": ["Институт Франции", "Коллеж Четырёх наций · Луи Лево", "Под этим куполом заседают «бессмертные» в зелёных мундирах.", "Посмотри на золотой купол Института Франции напротив моста Искусств.", "Ты на берегу Сены, перед зданием с куполом — Институтом Франции.\n\nВ 1661 году кардинал Мазарини, правивший Францией, пока Людовик XIV был ребёнком, завещал своё состояние на строительство школы. С 1805 года здесь находится Французская академия. Она оберегает французский язык и составляет его словарь. Её сорок членов прозвали «бессмертными». На торжественные церемонии они надевают зелёный мундир с вышивкой и шпагу.\n\nПосмотри на купол: под ним заседают бессмертные."], "Les Folies Bergère": ["«Фоли-Бержер»", "Мюзик-холл · 1869", "Бар, который написал Мане, и танцовщица на фасаде.", "Посмотри на позолоченный фасад «Фоли-Бержер» в стиле ар-деко и его танцовщицу.", "Ты у «Фоли-Бержер» — самого знаменитого мюзик-холла Парижа, открытого в 1869 году. Мюзик-холл — это театр песен, танцев и эстрадных номеров.\n\nХудожник Эдуар Мане поместил сюда свою последнюю большую картину, «Бар в Фоли-Бержер»: барменша с грустным взглядом за стойкой. Нынешний фасад сделан в 1926 году. Золотая танцовщица на нём существовала на самом деле: Лила Никольская. На ней почти ничего нет.\n\nПосмотри на золотую танцовщицу на фасаде."], "Le Bouillon Chartier": ["«Буйон Шартье»", "Бульонная · 1896", "Счёт здесь до сих пор пишут прямо на бумажной скатерти.", "Посмотри на вывеску «Буйон Шартье» в глубине двора.", "Ты у «Буйон Шартье» — ресторана, открытого в 1896 году.\n\nВ конце XIX века «бульонной» называли простой дешёвый ресторан для рабочих. Братья Шартье открыли этот, и зал с тех пор почти не изменился: зеркала, люстры, большая стеклянная крыша. Сохранились даже ящички, где постоянные посетители хранили свои салфетки. Официанты по-прежнему пишут счёт на бумажной скатерти.\n\nПосмотри на очередь: через 130 лет люди всё так же приходят сюда поесть."], "Le Jardin d'acclimatation": ["Сад акклиматизации", "Парк · Наполеон III, 1860", "Старейший парк развлечений Парижа начинался как научный проект.", "Посмотри на вход в Сад акклиматизации на краю леса.", "Ты у Сада акклиматизации, в Булонском лесу, на западе Парижа.\n\nСегодня это парк развлечений для детей. Но император Наполеон III открыл его в 1860 году с серьёзной целью. Учёные хотели проверить, смогут ли животные и растения со всего мира привыкнуть к французскому климату — «акклиматизироваться». Постепенно он стал любимым местом прогулок парижских семей.\n\nПосмотри на вход: этот парк родился из научного эксперимента."], "La Folie Saint-James": ["Фоли Сен-Джеймс", "Садовая причуда · Франсуа-Жозеф Беланже, 1777", "Двенадцатиметровая искусственная скала — прихоть разорившегося финансиста.", "Посмотри на Большую скалу в парке Фоли Сен-Джеймс.", "Ты в Нёйи, в парке Фоли Сен-Джеймс.\n\nВ XVIII веке очень богатые люди строили «фоли» — сады с маленькими павильонами просто для удовольствия. В 1772 году Клод Бодар де Сен-Джеймс, казначей королевского флота, купил это поместье. Он хотел сумасшедший сад. Самое безумное в нём — огромная искусственная скала длиной 43 метра, с купальнями и водопадом. В 1787 году он разорился.\n\nПосмотри на большую скалу: именно она его разорила."], "Le cimetière américain de Suresnes": ["Американское кладбище в Сюрене", "Военное кладбище · Мон-Валерьен", "Почти 1600 американских солдат покоятся здесь лицом к Парижу.", "Посмотри на ряды белых крестов и часовню на склоне Мон-Валерьен.", "Ты в Сюрене, на холме Мон-Валерьен, у американского военного кладбища.\n\nВ Первую мировую войну, с 1917 года, американские солдаты приехали воевать во Францию. Многие погибли и так и не вернулись домой. Почти 1600 из них лежат на этом кладбище под ровными рядами белых крестов. В 1919 году американский президент Вудро Вильсон выступил здесь с речью.\n\nПосмотри на белые кресты: они обращены к Парижу."], "La légende de Piaf": ["Легенда о Пиаф", "Мемориальная доска · улица Бельвиль, 72", "Родилась на ступеньках этого дома? Лучшая легенда Бельвиля.", "Найди мемориальную доску у дома 72 на улице Бельвиль.", "Ты на улице Бельвиль, у дома номер 72. Здесь висит доска об Эдит Пиаф.\n\nПиаф — великий голос французской песни, голос «La Vie en rose». Её мать пела на улицах, отец был акробатом. На доске написано, что она родилась прямо здесь, на ступеньках, в 1915 году. На самом деле в её свидетельстве о рождении указана соседняя больница Тенон. Но эта история так ей подходит, что квартал её сохранил.\n\nПосмотри на ступеньки: здесь начинается легенда о Пиаф."], "Le Père-Lachaise": ["Пер-Лашез", "Кладбище · 1804", "Пришлось перенести сюда Мольера, чтобы парижане захотели здесь лежать.", "Посмотри на парадный вход кладбища Пер-Лашез.", "Ты у Пер-Лашез — самого посещаемого кладбища в мире.\n\nКогда его открыли в 1804 году, оно никому не было нужно: слишком далеко от центра. И тогда кому-то пришла идея. В 1817 году сюда перенесли останки двух знаменитых писателей: драматурга Мольера и Лафонтена, автора басен. После этого парижане захотели лежать рядом с ними. Сегодня здесь покоятся пианист Шопен, певица Эдит Пиаф и Джим Моррисон из The Doors.\n\nПосмотри на аллеи, поднимающиеся на холм: маленький город из надгробий под деревьями."], "L'Atelier des Lumières": ["«Ателье огней»", "Цифровое искусство · бывший литейный завод, 1835", "Литейный завод для флота превратился в гигантский проекционный зал.", "Посмотри на старый цех литейного завода «Ателье огней».", "Ты у «Ателье огней» — старой фабрики в 11-м округе.\n\nВ 1835 году два брата открыли здесь литейный завод, который делал огромные металлические детали для кораблей и поездов. В XX веке завод закрылся. В 2018 году здесь открыли центр цифрового искусства. Картины великих художников, например Ван Гога или Климта, проецируют огромными на стены и пол, под музыку.\n\nПосмотри на старое кирпичное здание: внутри ты буквально идёшь сквозь картины."], "Le Cirque d'Hiver": ["Зимний цирк", "Цирк · Жак Хитторф, 1852", "Под этой крышей придумали воздушную трапецию.", "Посмотри на круглое двадцатигранное здание Зимнего цирка.", "Ты у Зимнего цирка — круглого здания с двадцатью гранями. Это настоящий цирк, построенный из камня.\n\nЕго открыл император Наполеон III в 1852 году. В 1859 году гимнаст Жюль Леотар впервые в истории показал здесь номер на летающей трапеции. Он даже дал своё имя трико акробатов — «леотард». С 1934 года цирком управляет семья Бульоне, великая цирковая династия.\n\nПосмотри на статуи лошадей на фасаде: сразу понятно, что происходит внутри."], "Le musée de Cluny": ["Музей Клюни", "Национальный музей Средневековья", "Римские термы и «Дама с единорогом» под одной крышей.", "Посмотри на древние римские стены на углу бульвара Сен-Мишель, а потом на готический особняк за ними.", "Ты у музея Клюни — музея Средневековья.\n\nОн объединяет два очень старых здания. Сначала римские термы, построенные около 200 года, когда Париж назывался Лютецией. Потом готический дом XV века — резиденция аббатов Клюни. Его главное сокровище — шесть шпалер, сотканных около 1500 года: «Дама с единорогом».\n\nПосмотри на старые кирпичные стены: это остатки римских терм."], "Le dôme du Val-de-Grâce": ["Купол Валь-де-Грас", "Церковь · Франсуа Мансар, 1645", "Купол королевы, которая двадцать три года ждала ребёнка.", "Подними глаза на большой купол Валь-де-Грас.", "Ты перед Валь-де-Грас — церковью с большим куполом.\n\nАнна Австрийская была испанской принцессой. В 1615 году она вышла замуж за французского короля Людовика XIII. Но двадцать три года у них не было детей — для королевы это катастрофа. Она дала обет: если родится сын, она построит великолепную церковь. В 1638 году родился будущий Людовик XIV. В 1645 году семилетним он заложил первый камень.\n\nПосмотри на купол: это исполненный обет королевы."], "La Grande Mosquée": ["Большая мечеть", "Мечеть · 1926", "Дань памяти мусульманским солдатам, погибшим за Францию.", "Посмотри на квадратный минарет Большой мечети.", "Ты у Большой мечети Парижа с квадратным минаретом высотой 33 метра.\n\nВ Первую мировую войну десятки тысяч мусульманских солдат, в основном из Северной Африки, погибли за Францию. Эту мечеть построили в их честь. Она открылась в 1926 году. Её архитектура вдохновлена мечетями Марокко.\n\nПосмотри на минарет, а потом зайди в чайную: мятный чай и сладости во дворике с мозаикой."], "Les Gobelins": ["Гобелены", "Королевская мануфактура · 1667", "Здесь до сих пор ткут шпалеры вручную, как при Людовике XIV.", "Посмотри на фасад мануфактуры Гобеленов на авеню Гобелен.", "Ты у мануфактуры Гобеленов, в 13-м округе.\n\nОколо 1450 года красильщик Жеан Гобелен устроил здесь мастерскую у маленькой речки, которая теперь спрятана под городом. В 1667 году Кольбер, министр короля Людовика XIV, превратил её в королевскую мануфактуру. Здесь ткали огромные шпалеры для украшения королевских дворцов, например Версаля.\n\nПосмотри на большие окна мастерских: ткачи до сих пор работают здесь вручную для государства, как 350 лет назад."], "Le cimetière de Levallois": ["Кладбище Леваллуа", "Кладбище · улица Боден", "Революционерка, Гюстав Эйфель и Морис Равель на одном кладбище.", "Посмотри на вход кладбища Леваллуа на улице Боден.", "Ты у кладбища Леваллуа — маленького тихого кладбища.\n\nЗдесь покоятся очень разные люди. Луиза Мишель была учительницей. В 1871 году она сражалась за Коммуну — восстание парижан, а потом её сослали на каторгу в Новую Каледонию. Она похоронена здесь. Как и Гюстав Эйфель, инженер башни, и Морис Равель, автор «Болеро».\n\nПосмотри на аллеи: революционерка, инженер и композитор — соседи навсегда."], "Le cimetière des chiens": ["Кладбище собак", "Кладбище домашних животных · 1899", "Рин Тин Тин и Барри — сенбернар, спасший сорок человек.", "Посмотри на памятник псу Барри прямо у входа.", "Ты у кладбища собак, на острове посреди Сены в Аньере.\n\nОно открылось в 1899 году. Это одно из первых в мире кладбищ домашних животных; его основали юрист и журналистка Маргерит Дюран. У входа стоит памятник Барри — сенбернару из Альп. По легенде, он спас сорок человек, заблудившихся в снегу. Дальше лежит Рин Тин Тин, пёс — звезда американского кино.\n\nПосмотри на маленькие могилы: собаки, кошки, лошади и нежные слова их хозяев."], "Le château d'Asnières": ["Замок Аньер", "Замок · Жак Ардуэн-Мансар де Саньон, 1750–1752", "Замок маркиза, построенный потомком архитекторов Версаля.", "Посмотри на замок Аньер, возвышающийся над городом.", "Ты в Аньере, сразу за Парижем, на Сене. Перед тобой замок XVIII века.\n\nЕго построили около 1750 года для маркиза — сына одного из министров короля Людовика XV. Архитектор был потомком человека, построившего Версаль. Позже берега Аньера привлекли художников. Жорж Сёра написал здесь купальщиков в 1883 году, а Винсент Ван Гог — мосты в 1887-м.\n\nПосмотри на фасад: немного Версаля в загородном стиле."], "Le stade olympique de Colombes": ["Олимпийский стадион Коломба", "Стадион · Олимпийские игры 1924", "Стадион из «Огненных колесниц» снова в деле на Играх 2024.", "Посмотри на трибуны стадиона Ив-дю-Мануар в Коломбе.", "Ты у стадиона в Коломбе, к западу от Парижа.\n\nЭто был главный стадион Олимпийских игр 1924 года. Здесь два британских бегуна выиграли золото: Гарольд Абрахамс на 100 метрах и Эрик Лидделл на 400. Лидделл был глубоко верующим и отказался бежать в воскресенье. Их историю рассказывает фильм «Огненные колесницы» со знаменитой музыкой. Стадион отреставрировали, и он снова принимал Игры Париж-2024.\n\nПосмотри на трибуны: сто лет между двумя Олимпиадами."], "La Coupole": ["«Ла Куполь»", "Брассери · 1927", "Брассери в стиле ар-деко, где ужинал и танцевал весь Монпарнас.", "Посмотри на большую вывеску «Ла Куполь» на бульваре Монпарнас.", "Ты на бульваре Монпарнас, у «Ла Куполь» — огромного брассери, открытого в 1927 году.\n\nВ 1920-е годы Монпарнас был центром современного искусства. Здесь жили художники и писатели со всего мира. «Ла Куполь» стала местом их встреч: художник Пикассо, танцовщица Жозефина Бейкер, американский писатель Хемингуэй. Колонны в зале расписали местные художники.\n\nПосмотри на расписные колонны внутри: зал почти не изменился."], "Le lion de Denfert": ["Лев на Данфер", "Скульптура · Огюст Бартольди", "Бельфорский лев в миниатюре посреди площади.", "Посмотри на лежащего бронзового льва посреди площади Данфер-Рошро.", "Ты на площади Данфер-Рошро, перед большим бронзовым львом.\n\nЭто копия гигантского льва, высеченного в скале в Бельфоре — городе на востоке Франции. В 1870 году, во время войны с Пруссией, Бельфор 103 дня держался против врага. Им командовал полковник Данфер-Рошро, давший имя площади. Скульптор — Огюст Бартольди, автор статуи Свободы в Нью-Йорке.\n\nПосмотри на льва, а потом на маленькое здание рядом: это вход в катакомбы."], "La piscine de la Butte-aux-Cailles": ["Бассейн Бют-о-Кай", "Бассейн · Луи Боннье, 1924", "Бассейн, рождённый из скважины с тёплой водой с глубины 600 метров.", "Посмотри на кирпичный фасад бассейна и фонтанчик на площади Поль-Верлен.", "Ты на Бют-о-Кай — квартале, похожем на деревню, с булыжными улочками и бистро.\n\nВ 1893 году здесь пробурили очень глубокую скважину — около 600 метров. Вода поднимается сама, и она тёплая: 25 градусов. Благодаря ей построили бассейн, открытый в 1924 году, с большой изогнутой бетонной крышей. На площади Поль-Верлен фонтанчик даёт ту же воду.\n\nПосмотри на фонтанчик: местные приходят сюда наполнять бутылки."], "L'aqueduc d'Arcueil": ["Акведук Аркёя", "Акведук · 1613–1623 и 1860-е", "Два акведука друг на друге, над следами третьего, римского.", "Посмотри на большие арки акведука, пересекающие долину.", "Ты в Аркёе, к югу от Парижа, перед акведуком — мостом, построенным, чтобы нести воду.\n\nНа самом деле их два, один над другим. Королева Мария Медичи хотела воды для фонтанов своего Люксембургского дворца. Она велела построить первый акведук, законченный в 1623 году. В 1860-х годах поверх него построили второй, более высокий.\n\nПосмотри на арки: внизу — королевы, наверху — XIX века."], "La Naumachie": ["Навмахия", "Садовая причуда · сад герцога Шартрского", "Пруд с колоннадой, которая, говорят, пришла из часовни королевы для короля.", "Подойди к пруду и посмотри на эти полуразрушенные колонны.", "Этот пруд с колоннами — один из последних уголков сада герцога, кузена короля Людовика XVI. Сад был полон ненастоящих руин, построенных просто для забавы.\n\nСамое удивительное — колонны. Говорят, они из часовни, которую королева Екатерина Медичи построила для гробницы своего мужа, короля Генриха II.\n\nПосмотри на колонны: когда-то они охраняли короля.", "До того как стать общественным парком, здесь был частный сад герцога Шартрского, кузена короля Людовика XVI. В 1770-х годах он захотел сад, который удивлял бы на каждом шагу. Здесь появились египетская пирамида, голландская мельница, ненастоящие руины. Его прозвали «шартрской причудой».\n\nЭтот пруд — один из немногих уцелевших уголков. Но колонны гораздо старше сада.\n\nЗа два века до этого королева Екатерина Медичи потеряла мужа, короля Генриха II. Она построила для него часовню рядом с базиликой Сен-Дени, где хоронят королей Франции. В 1719 году часовню снесли.\n\nГоворят, её колонны оказались здесь, у воды. Их создали, чтобы охранять короля, а теперь они служат фоном для уток."], "Musée Cernuschi": ["Музей Чернуски", "Коллекция · авеню Веласкес", "Огромный японский бронзовый Будда, переплывший полмира к парку Монсо.", "Посмотри на дом за оградой: внутри кое-кто ждёт уже больше века.", "За этой оградой жил Анри Чернуски — финансист, влюблённый в Азию.\n\nВ 1871 году в Японии он нашёл огромного бронзового Будду, уцелевшего при пожаре в своём храме. Он купил его, разобрал по частям и собрал заново у себя дома в Париже.\n\nПосмотри на дом: Будда до сих пор там, а вход в музей бесплатный.", "Анри Чернуски — финансист, родившийся в Милане и обосновавшийся в Париже. Богатый человек, а главное — очень любопытный. В 1871 году он отправляется в долгое путешествие по Азии с другом-искусствоведом. Япония только что открылась миру после веков закрытости для иностранцев.\n\nВ Токио, в районе Мегуро, он натыкается на гигантскую статую — бронзового Будду. Его храм сгорел. Будда уцелел и уже год сидит под открытым небом, под дождём.\n\nЧернуски покупает его. Он велит разобрать статую по частям, отправить в Париж, и здесь, в его доме, парижские литейщики собирают её заново.\n\nДом стал музеем, и Будда больше никуда не двигался. Он пересёк полмира, чтобы оказаться в двух шагах от парка Монсо. И поздороваться с ним можно бесплатно."], "Proust, 45 rue de Courcelles": ["Пруст, улица Курсель, 45", "Адрес писателя · улица Курсель", "Здесь жил автор одного из самых знаменитых романов в мире.", "Найди каменный дом на улице Курсель, 45.", "Марсель Пруст, автор «В поисках утраченного времени», одного из самых знаменитых романов в мире, жил в этом доме с 1900 года.\n\nМальчиком он проводил четверги в парке Монсо. А совсем рядом, в салоне одной художницы, он вошёл в высший свет, который потом опишет в своих книгах.\n\nПосмотри на дом: здесь потихоньку рождался великий роман.", "Его зовут Марсель Пруст. В детстве парк Монсо — его площадка для игр. Он проводит там вечера четвергов: тогда в этот день не учились.\n\nВ 1900 году его семья переезжает в этот респектабельный дом. Марселю почти тридцать. Он ещё не знаменит. Но у него есть дар: он замечает всё.\n\nСовсем рядом художница Мадлен Лемер принимает у себя сливки парижского общества: аристократов, артистов, писателей. Пруст бывает там. Он слушает, смотрит, запоминает каждый жест, каждую фразу.\n\nЧерез много лет все эти люди станут героями «В поисках утраченного времени», его огромного романа. Мальчик из парка Монсо нашёл свою тему в нескольких улицах отсюда.\n\nНу что, последний отрезок: возвращаемся в отель."]}}};
